const SHOP_PATH_PLACEHOLDER = "active";
const THEME_KEY = "shopee_theme_mode";

function applyTheme(theme) {
  const normalized = theme === "light" ? "light" : "dark";
  document.body.classList.toggle("theme-light", normalized === "light");
  document.body.classList.toggle("theme-dark", normalized !== "light");
  localStorage.setItem(THEME_KEY, normalized);

  const btn = document.getElementById("btn-theme-toggle");
  if (btn) {
    btn.textContent = normalized === "light" ? "Dark Mode" : "White Mode";
  }

  if (window.Chart && window.Chart.defaults) {
    const isLight = normalized === "light";
    window.Chart.defaults.color = isLight ? "#334155" : "#e2e8f0";
    window.Chart.defaults.borderColor = isLight
      ? "rgba(148, 163, 184, 0.28)"
      : "rgba(148, 163, 184, 0.34)";
  }

  if (CONTROL_PANEL_DATA && document.getElementById("tab-control-panel")?.classList.contains("active")) {
    renderControlPanelTrendChart(CONTROL_PANEL_DATA.dailyBars30d || []);
  }

  refreshSeoChartsTheme();
  refreshInMemoryChartsTheme();
}

function applyThemeToChartInstance(chart, chartTheme) {
  if (!chart) return;
  try {
    chart.update("none");
  } catch (error) {
    console.warn("[theme] applyThemeToChartInstance skipped (safe-guard):", error);
  }
}

function refreshInMemoryChartsTheme() {
  const knownCharts = [
    DASH_CHART_MONTH,
    DASH_CHART_TODAY,
    DASH_CHART_MONTH_RATIO,
    DASH_ADS_COMPARE_CHART,
    CONTROL_PANEL_CHART,
    SALES_SHARE_MOM_CHART,
    PRODUCT_RANKING_EVOLUTION_CHART,
    PRODUCT_RANKING_DISTRIBUTION_CHART,
    LAUNCHES_CHART,
    LAUNCHES_MOM_CHART,
  ];

  knownCharts.forEach((chart) => applyThemeToChartInstance(chart));
}

function initThemeToggle() {
  const saved = localStorage.getItem(THEME_KEY) || "dark";
  applyTheme(saved);
  document.getElementById("btn-theme-toggle")?.addEventListener("click", () => {
    applyTheme(document.body.classList.contains("theme-light") ? "dark" : "light");
  });
}

function formatBRLFixed90(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return n.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function formatBRLCents(cents) {
  const n = Number(cents || 0) / 100;
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function formatBRL(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function getShopeeSellerOrderUrl(orderRef) {
  const normalized = String(orderRef || "").trim();
  if (!normalized) return "";
  return `https://seller.shopee.com.br/portal/sale/order/${encodeURIComponent(normalized)}`;
}

function resolveShopeePortalOrderRef(orderLike, fallbackOrderSn = "") {
  const candidates = [
    orderLike?.portalOrderRef,
    orderLike?.portal_order_ref,
    orderLike?.orderNumber,
    orderLike?.order_number,
    orderLike?.shopeeOrderId,
    orderLike?.shopee_order_id,
    orderLike?.orderId,
    orderLike?.order_id,
    orderLike?.platformOrderId,
    orderLike?.platform_order_id,
  ];

  for (const raw of candidates) {
    const value = String(raw ?? "").trim();
    if (/^\d{10,20}$/.test(value)) return value;
  }

  return String(fallbackOrderSn || "").trim();
}

async function resolveShopeePortalOrderRefOnline({
  orderSn = "",
  fallbackRef = "",
}) {
  const fallback = String(fallbackRef || "").trim();
  if (/^\d{10,20}$/.test(fallback)) return fallback;

  const normalizedOrderSn = String(orderSn || "").trim();
  if (!normalizedOrderSn) return fallback;

  try {
    const payload = await apiGet(
      `/shops/${SHOP_PATH_PLACEHOLDER}/orders/${encodeURIComponent(
        normalizedOrderSn,
      )}/portal-ref`,
    );
    return resolveShopeePortalOrderRef(
      payload || {},
      fallback || normalizedOrderSn,
    );
  } catch (_error) {
    return fallback || normalizedOrderSn;
  }
}

function getShopeeSellerProductUrl(itemId) {
  const normalized = String(itemId || "").trim();
  if (!normalized) return "";
  const activeShop = getActiveShopFromMe();
  const shopShopeeId = String(activeShop?.shopId || "").trim();
  if (/^\d+$/.test(shopShopeeId) && /^\d+$/.test(normalized)) {
    return `https://shopee.com.br/product/${encodeURIComponent(shopShopeeId)}/${encodeURIComponent(normalized)}`;
  }
  return `https://seller.shopee.com.br/portal/product/${encodeURIComponent(normalized)}`;
}

function getShopeeSellerProductEditUrl(itemId) {
  const normalized = String(itemId || "").trim();
  if (!normalized) return "";
  return `https://seller.shopee.com.br/portal/product/${encodeURIComponent(normalized)}`;
}

function translateFeatureName(value) {
  const label = String(value || "").trim();
  if (!label) return "";
  const key = label.toLowerCase();
  const dict = {
    brand: "Marca",
    model: "Modelo",
    material: "Material",
    color: "Cor",
    style: "Estilo",
    type: "Tipo",
    width: "Largura",
    height: "Altura",
    length: "Comprimento",
    depth: "Profundidade",
    weight: "Peso",
    package_weight: "Peso da embalagem",
    package_length: "Comprimento da embalagem",
    package_width: "Largura da embalagem",
    package_height: "Altura da embalagem",
    warranty: "Garantia",
    origin: "Origem",
    quantity: "Quantidade",
    capacity: "Capacidade",
    size: "Tamanho",
    pattern: "Estampa",
    voltage: "Voltagem",
    power: "Potência",
    assembly_required: "Necessita montagem",
  };
  return dict[key] || label;
}

function openExternalUrl(url) {
  if (!url) return;
  window.open(url, "_blank", "noopener,noreferrer");
}

function parseCsvValues(raw) {
  return Array.from(
    new Set(
      String(raw || "")
        .split(",")
        .map((token) => String(token || "").trim())
        .filter(Boolean),
    ),
  );
}

function parseCsvItemIds(raw) {
  return parseCsvValues(raw).filter((token) => /^\d+$/.test(token));
}

function $(sel) {
  return document.querySelector(sel);
}
function $all(sel) {
  return Array.from(document.querySelectorAll(sel));
}

function setAppBootLoader(visible, message = "") {
  const loader = document.getElementById("appBootLoader");
  if (!loader) return;
  loader.classList.toggle("is-hidden", !visible);
  const msg = document.getElementById("appBootLoaderMessage");
  if (msg && message) msg.textContent = message;
}

function getUiStateTypeFromText(text) {
  const value = String(text || "").trim().toLowerCase();
  if (!value) return null;

  if (
    value.includes("carregando") ||
    value.includes("loading") ||
    value.includes("sincronizando")
  ) {
    return "loading";
  }

  if (value.includes("erro") || value.includes("falha")) {
    return "error";
  }

  if (
    value.includes("nenhum") ||
    value.includes("nenhuma") ||
    value.includes("sem dados") ||
    value.includes("sem ")
  ) {
    return "empty";
  }

  return null;
}

function applyUiStateClass(el, forcedType = null) {
  if (!el) return;

  const text = el.textContent || "";
  const type = forcedType || getUiStateTypeFromText(text);
  if (!type) return;

  el.classList.add("ui-state", `ui-state--${type}`);
}

function enhanceUiStates(root = document) {
  const nodes = root.querySelectorAll(".muted");
  nodes.forEach((el) => {
    if (el.children.length > 0) return;
    applyUiStateClass(el);
  });
}

function createNotificationId() {
  return `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function formatNotificationDate(value) {
  try {
    return new Intl.DateTimeFormat("pt-BR", {
      dateStyle: "short",
      timeStyle: "short",
    }).format(new Date(value));
  } catch (_error) {
    return String(value || "");
  }
}

function normalizeNotificationChannel(value) {
  return String(value || "").trim().toLowerCase() === "informative"
    ? "informative"
    : "general";
}

function normalizeUserVisibleNotificationKind(value) {
  const kind = String(value || "").trim().toLowerCase();
  return USER_VISIBLE_NOTIFICATION_KINDS.has(kind) ? kind : "";
}

function isRelevantUserNotification(raw) {
  const kind = normalizeUserVisibleNotificationKind(raw?.kind);
  if (!kind) return false;
  if (kind === "daily_roas") return true;

  const text = [raw?.title, raw?.message]
    .map((value) => String(value || "").toLowerCase())
    .join(" ");
  return !/(audit|tab access|select shop|consulta:|auth - select)/.test(text);
}

function parseNotificationTimestamp(value) {
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? ms : Date.now();
}

function parseOptionalTimestamp(value) {
  if (!value) return null;
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? ms : null;
}

function pruneGlobalNotifications() {
  const now = Date.now();
  const sanitized = Array.isArray(GLOBAL_NOTIFICATIONS)
    ? GLOBAL_NOTIFICATIONS
      .map((raw) => {
        const kind = normalizeUserVisibleNotificationKind(raw?.kind);
        if (!kind || !isRelevantUserNotification(raw)) return null;
        const channel = normalizeNotificationChannel(raw?.channel);
        const createdAt = raw?.createdAt || new Date().toISOString();
        const timestamp = parseNotificationTimestamp(createdAt);
        const informativeEndsAtMs = parseOptionalTimestamp(
          raw?.noticeSnapshot?.endsAt || raw?.actionPayload?.endsAt,
        );
        if (
          channel === "general" &&
          now - timestamp > GLOBAL_NOTIFICATIONS_GENERAL_TTL_MS
        ) {
          return null;
        }
        if (
          channel === "informative" &&
          informativeEndsAtMs != null &&
          now > informativeEndsAtMs
        ) {
          return null;
        }
        return {
          id: String(raw?.id || createNotificationId()),
          title: String(raw?.title || "Notificação"),
          message: String(raw?.message || ""),
          type: String(raw?.type || "info"),
          actionLabel: String(raw?.actionLabel || "").trim(),
          actionUrl: String(raw?.actionUrl || "").trim(),
          actionKind: String(raw?.actionKind || "").trim(),
          actionPayload:
            raw?.actionPayload && typeof raw.actionPayload === "object"
              ? raw.actionPayload
              : null,
          noticeSnapshot:
            raw?.noticeSnapshot && typeof raw.noticeSnapshot === "object"
              ? raw.noticeSnapshot
              : null,
          createdAt: new Date(timestamp).toISOString(),
          read: Boolean(raw?.read),
          channel,
          kind,
        };
      })
      .filter(Boolean)
    : [];
  GLOBAL_NOTIFICATIONS = sanitized.slice(0, GLOBAL_NOTIFICATIONS_MAX_ITEMS);
}

function saveGlobalNotificationsToStorage() {
  pruneGlobalNotifications();
  try {
    localStorage.setItem(
      GLOBAL_NOTIFICATIONS_STORAGE_KEY,
      JSON.stringify(GLOBAL_NOTIFICATIONS),
    );
  } catch (_error) {
    // ignore storage errors
  }
}

function loadGlobalNotificationsFromStorage() {
  try {
    const raw = localStorage.getItem(GLOBAL_NOTIFICATIONS_STORAGE_KEY);
    if (!raw) {
      GLOBAL_NOTIFICATIONS = [];
      return;
    }
    const parsed = JSON.parse(raw);
    GLOBAL_NOTIFICATIONS = Array.isArray(parsed) ? parsed : [];
  } catch (_error) {
    GLOBAL_NOTIFICATIONS = [];
  }
  pruneGlobalNotifications();
}

function getGlobalNotificationById(notificationId) {
  const id = String(notificationId || "").trim();
  if (!id) return null;
  return GLOBAL_NOTIFICATIONS.find((item) => item.id === id) || null;
}

function reopenInformativeNotification(notification) {
  const payloadId = String(notification?.actionPayload?.noticeId || "").trim();
  const sourceList = Array.isArray(GLOBAL_INFORMATIVE_POPUP_NOTICES)
    ? GLOBAL_INFORMATIVE_POPUP_NOTICES
    : [];
  const liveNotice = payloadId
    ? sourceList.find((item) => String(item?.id || "") === payloadId) || null
    : null;
  const fallbackNotice =
    notification?.noticeSnapshot && typeof notification.noticeSnapshot === "object"
      ? notification.noticeSnapshot
      : null;
  const notice = liveNotice || fallbackNotice;
  if (!notice) {
    alert("Este informativo não está mais disponível.");
    return;
  }
  openGlobalInformativePopup(notice);
}

function handleGlobalNotificationAction(notificationId) {
  const notification = getGlobalNotificationById(notificationId);
  if (!notification) return;
  const actionKind = String(notification.actionKind || "").trim().toLowerCase();
  if (actionKind === "reopen_informative_popup") {
    reopenInformativeNotification(notification);
  } else if (actionKind === "open_tab") {
    const tab = String(notification.actionPayload?.tab || "").trim();
    if (tab) void showTab(tab);
  } else if (notification.actionUrl) {
    window.open(notification.actionUrl, "_blank", "noopener,noreferrer");
  }
}

function setGlobalNotificationsTab(channel) {
  GLOBAL_NOTIFICATIONS_ACTIVE_TAB =
    normalizeNotificationChannel(channel) === "informative"
      ? "informative"
      : "general";
  const generalButton = document.getElementById("btnGlobalNotificationsTabGeneral");
  const informativeButton = document.getElementById(
    "btnGlobalNotificationsTabInformative",
  );
  const generalList = document.getElementById("globalNotificationsGeneralList");
  const informativeList = document.getElementById("globalNotificationsInformativeList");
  generalButton?.classList.toggle("is-active", GLOBAL_NOTIFICATIONS_ACTIVE_TAB === "general");
  informativeButton?.classList.toggle(
    "is-active",
    GLOBAL_NOTIFICATIONS_ACTIVE_TAB === "informative",
  );
  if (generalList) {
    generalList.classList.toggle("is-hidden", GLOBAL_NOTIFICATIONS_ACTIVE_TAB !== "general");
  }
  if (informativeList) {
    informativeList.classList.toggle(
      "is-hidden",
      GLOBAL_NOTIFICATIONS_ACTIVE_TAB !== "informative",
    );
  }
}

function renderGlobalNotifications() {
  const countEl = document.getElementById("globalNotificationsCount");
  const generalListEl = document.getElementById("globalNotificationsGeneralList");
  const informativeListEl = document.getElementById("globalNotificationsInformativeList");
  if (!countEl || !generalListEl || !informativeListEl) return;

  pruneGlobalNotifications();
  saveGlobalNotificationsToStorage();

  const unread = GLOBAL_NOTIFICATIONS.filter((item) => !item.read).length;
  countEl.textContent = String(unread);
  countEl.classList.toggle("is-empty", unread === 0);

  const renderItems = (channel, listEl) => {
    const channelItems = GLOBAL_NOTIFICATIONS.filter(
      (item) => normalizeNotificationChannel(item?.channel) === channel,
    );
    if (!channelItems.length) {
      listEl.innerHTML = '<div class="muted ui-state ui-state--empty">Nenhuma notificação ainda.</div>';
      return;
    }
    listEl.innerHTML = channelItems.map((item) => `
      <article class="global-notification-item ${item.read ? "" : "is-unread"}">
        <div><strong>${escapeHtml(item.title || "Notificação")}</strong></div>
        <div class="muted">${escapeHtml(item.message || "")}</div>
        <div class="global-notification-item__meta">${escapeHtml(formatNotificationDate(item.createdAt))}</div>
        ${
          item.read && !item.actionUrl && !item.actionKind
            ? ""
            : `<div class="global-notification-item__actions">
                 ${
                   item.actionUrl
                     ? `<a class="btn btn-ghost" href="${escapeHtml(item.actionUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(item.actionLabel || "Abrir")}</a>`
                     : ""
                 }
                 ${
                   item.actionKind
                     ? `<button class="btn btn-ghost" type="button" data-notification-action="${escapeHtml(item.id)}">${escapeHtml(item.actionLabel || "Abrir")}</button>`
                     : ""
                 }
                 ${
                   item.read
                     ? ""
                     : `<button class="btn btn-ghost" type="button" data-mark-notification-read="${escapeHtml(item.id)}">Marcar como lido</button>`
                 }
               </div>`
        }
      </article>
    `).join("");
  };

  renderItems("general", generalListEl);
  renderItems("informative", informativeListEl);
  setGlobalNotificationsTab(GLOBAL_NOTIFICATIONS_ACTIVE_TAB);

  document
    .querySelectorAll(
      "#globalNotificationsGeneralList [data-mark-notification-read], #globalNotificationsInformativeList [data-mark-notification-read]",
    )
    .forEach((button) => {
    button.addEventListener("click", () => {
      const notificationId = button.getAttribute("data-mark-notification-read");
      GLOBAL_NOTIFICATIONS = GLOBAL_NOTIFICATIONS.map((item) =>
        item.id === notificationId ? { ...item, read: true } : item,
      );
      saveGlobalNotificationsToStorage();
      renderGlobalNotifications();
    });
  });

  document
    .querySelectorAll(
      "#globalNotificationsGeneralList [data-notification-action], #globalNotificationsInformativeList [data-notification-action]",
    )
    .forEach((button) => {
      button.addEventListener("click", () => {
        const notificationId = button.getAttribute("data-notification-action");
        handleGlobalNotificationAction(notificationId);
      });
    });
}

function closeNotificationToast(notificationId) {
  const container = document.getElementById("globalNotificationToasts");
  if (!container) return;
  const node = container.querySelector(`[data-notification-toast="${notificationId}"]`);
  if (node) node.remove();
  const timer = GLOBAL_NOTIFICATIONS_TOAST_TIMERS.get(notificationId);
  if (timer) {
    clearTimeout(timer);
    GLOBAL_NOTIFICATIONS_TOAST_TIMERS.delete(notificationId);
  }
}

function showNotificationToast(notification) {
  const container = document.getElementById("globalNotificationToasts");
  if (!container || !notification?.id) return;
  const toast = document.createElement("article");
  toast.className = "global-notification-toast";
  toast.dataset.notificationToast = notification.id;
  toast.innerHTML = `
    <div class="global-notification-toast__head">
      <strong>${escapeHtml(notification.title || "Notificação")}</strong>
      <button class="global-notification-toast__close" type="button" data-close-toast>&times;</button>
    </div>
    <div class="muted">${escapeHtml(notification.message || "")}</div>
    <div class="global-notification-toast__meta">${escapeHtml(formatNotificationDate(notification.createdAt))}</div>
  `;
  container.prepend(toast);
  toast.querySelector("[data-close-toast]")?.addEventListener("click", () => {
    closeNotificationToast(notification.id);
  });

  const timer = setTimeout(() => {
    closeNotificationToast(notification.id);
  }, 15000);
  GLOBAL_NOTIFICATIONS_TOAST_TIMERS.set(notification.id, timer);
}

function pushGlobalNotification({
  title = "Notificação",
  message = "",
  type = "info",
  showToast = true,
  actionLabel = "",
  actionUrl = "",
  actionKind = "",
  actionPayload = null,
  noticeSnapshot = null,
  channel = "general",
  kind = "",
} = {}) {
  const normalizedKind = normalizeUserVisibleNotificationKind(kind);
  if (!normalizedKind) return null;
  pruneGlobalNotifications();
  const notification = {
    id: createNotificationId(),
    title: String(title || "Notificação"),
    message: String(message || ""),
    type: String(type || "info"),
    actionLabel: String(actionLabel || "").trim(),
    actionUrl: String(actionUrl || "").trim(),
    actionKind: String(actionKind || "").trim(),
    actionPayload:
      actionPayload && typeof actionPayload === "object" ? actionPayload : null,
    noticeSnapshot:
      noticeSnapshot && typeof noticeSnapshot === "object" ? noticeSnapshot : null,
    createdAt: new Date().toISOString(),
    read: false,
    channel: normalizeNotificationChannel(channel),
    kind: normalizedKind,
  };
  GLOBAL_NOTIFICATIONS = [notification, ...GLOBAL_NOTIFICATIONS].slice(
    0,
    GLOBAL_NOTIFICATIONS_MAX_ITEMS,
  );
  saveGlobalNotificationsToStorage();
  renderGlobalNotifications();
  if (showToast) showNotificationToast(notification);
  return notification;
}

function initGlobalNotifications() {
  const bellButton = document.getElementById("btn-global-notifications");
  const panel = document.getElementById("globalNotificationsPanel");
  const markAllButton = document.getElementById("btnGlobalNotificationsMarkAll");
  const tabGeneralButton = document.getElementById("btnGlobalNotificationsTabGeneral");
  const tabInformativeButton = document.getElementById(
    "btnGlobalNotificationsTabInformative",
  );

  if (!bellButton || !panel) return;

  loadGlobalNotificationsFromStorage();

  bellButton.addEventListener("click", (event) => {
    event.stopPropagation();
    const open = panel.style.display !== "none";
    panel.style.display = open ? "none" : "block";
  });

  markAllButton?.addEventListener("click", () => {
    GLOBAL_NOTIFICATIONS = GLOBAL_NOTIFICATIONS.map((item) => ({ ...item, read: true }));
    saveGlobalNotificationsToStorage();
    renderGlobalNotifications();
  });

  tabGeneralButton?.addEventListener("click", () => {
    setGlobalNotificationsTab("general");
  });
  tabInformativeButton?.addEventListener("click", () => {
    setGlobalNotificationsTab("informative");
  });

  document.addEventListener("click", (event) => {
    if (panel.style.display === "none") return;
    if (panel.contains(event.target) || bellButton.contains(event.target)) return;
    panel.style.display = "none";
  });

  setGlobalNotificationsTab("general");
  renderGlobalNotifications();
  window.shopeeNotify = (payload = {}) => pushGlobalNotification(payload);
}

function loadProcessNotificationSeenIds() {
  try {
    const raw = localStorage.getItem(PROCESS_NOTIFICATIONS_SEEN_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    const items = Array.isArray(parsed) ? parsed : [];
    PROCESS_NOTIFICATION_SEEN_IDS = new Set(
      items.map((value) => String(value || "").trim()).filter(Boolean),
    );
  } catch (_error) {
    PROCESS_NOTIFICATION_SEEN_IDS = new Set();
  }
}

function saveProcessNotificationSeenIds() {
  try {
    const ids = Array.from(PROCESS_NOTIFICATION_SEEN_IDS).slice(
      -PROCESS_NOTIFICATIONS_MAX_SEEN,
    );
    localStorage.setItem(PROCESS_NOTIFICATIONS_SEEN_STORAGE_KEY, JSON.stringify(ids));
  } catch (_error) {
    // ignore storage errors
  }
}

function markProcessNotificationSeen(processId) {
  const key = String(processId || "").trim();
  if (!key) return;
  PROCESS_NOTIFICATION_SEEN_IDS.add(key);
  if (PROCESS_NOTIFICATION_SEEN_IDS.size > PROCESS_NOTIFICATIONS_MAX_SEEN) {
    const trimmed = Array.from(PROCESS_NOTIFICATION_SEEN_IDS).slice(
      -PROCESS_NOTIFICATIONS_MAX_SEEN,
    );
    PROCESS_NOTIFICATION_SEEN_IDS = new Set(trimmed);
  }
  saveProcessNotificationSeenIds();
}

function shouldNotifyProcessId(processId) {
  const key = String(processId || "").trim();
  if (!key) return false;
  return !PROCESS_NOTIFICATION_SEEN_IDS.has(key);
}

function resolveFriendlyProcessName({
  displayName = "",
  method = "",
  path = "",
  requestBody = null,
} = {}) {
  const providedName = String(displayName || "").trim();
  if (providedName) return providedName;
  const normalizedMethod = String(method || "").trim().toUpperCase();
  const rawPath = String(path || "").trim();
  const lowerPath = rawPath.toLowerCase();
  const routePath = lowerPath.includes("#")
    ? lowerPath.slice(0, lowerPath.indexOf("#"))
    : lowerPath;
  const actionTag = lowerPath.includes("#")
    ? lowerPath.slice(lowerPath.indexOf("#") + 1)
    : String(requestBody?.action || "").trim().toLowerCase();

  const actionLabelByTag = {
    "logistics.spx.enable": "Alteração de logística (habilitar Shopee Xpress)",
    "logistics.spx.disable": "Alteração de logística (desabilitar Shopee Xpress)",
    "logistics.seller.enable": "Alteração de logística (habilitar Logística do vendedor)",
    "logistics.seller.disable": "Alteração de logística (desabilitar Logística do vendedor)",
    "logistics.conflicts.keep_spx": "Correção de conflitos de logística (manter Shopee Xpress)",
    "logistics.conflicts.keep_seller": "Correção de conflitos de logística (manter Logística do vendedor)",
    "logistics.mapping.apply": "Mapeamento automático de logística",
    "logistics.configure": "Configuracao guiada de logistica",
    "products.deadline.apply": "Alteração de prazo sob encomenda",
    "products.relaunch.pause": "Pausa de anúncios",
    "products.relaunch.delete": "Exclusão de anúncios",
    "products.status.bulk": "Alteração massiva de status de anúncios",
  };
  if (actionTag && actionLabelByTag[actionTag]) {
    return actionLabelByTag[actionTag];
  }

  const routeMatchers = [
    [new RegExp("/shops/active/logistics/configure$"), "Configuracao guiada de logistica"],
    [/\/shops\/active\/dashboard\/stock-alert\/sync-stock$/, "Sincronismo de loja"],
    [/\/shops\/active\/products\/sync$/, "Sincronismo de produtos"],
    [/\/shops\/active\/orders\/sync$/, "Sincronismo de pedidos"],
    [/\/shops\/active\/logistics\/spx\/enable$/, "Alteração de logística (habilitar Shopee Xpress)"],
    [/\/shops\/active\/logistics\/spx\/disable$/, "Alteração de logística (desabilitar Shopee Xpress)"],
    [/\/shops\/active\/logistics\/seller\/enable$/, "Alteração de logística (habilitar Logística do vendedor)"],
    [/\/shops\/active\/logistics\/seller\/disable$/, "Alteração de logística (desabilitar Logística do vendedor)"],
    [/\/shops\/active\/logistics\/conflicts\/keep-spx$/, "Correção de conflitos de logística (manter Shopee Xpress)"],
    [/\/shops\/active\/logistics\/conflicts\/keep-seller$/, "Correção de conflitos de logística (manter Logística do vendedor)"],
    [/\/shops\/active\/products\/deadline-control\/apply$/, "Alteração de prazo sob encomenda"],
    [/\/shops\/active\/products\/relaunch\/pause$/, "Pausa de anúncios"],
    [/\/shops\/active\/products\/relaunch\/delete$/, "Exclusão de anúncios"],
    [/\/shops\/active\/products\/status\/bulk$/, "Alteração massiva de status de anúncios"],
    [/\/shops\/active\/products\/update-price$/, "Alteração de preço de produto"],
    [/\/shops\/active\/products\/update-stock$/, "Alteração de estoque de produto"],
  ];
  for (const [pattern, label] of routeMatchers) {
    if (pattern.test(routePath)) return label;
  }

  if (normalizedMethod === "PATCH" || normalizedMethod === "PUT") {
    return "Alteração de cadastro";
  }
  if (normalizedMethod === "DELETE") {
    return "Remoção de cadastro";
  }
  const tokenMap = {
    ads: "anúncios",
    async: "assíncrono",
    bulk: "em massa",
    conflicts: "conflitos",
    dashboard: "dashboard",
    deadline: "prazo",
    delete: "exclusão",
    disable: "desabilitação",
    enable: "habilitação",
    export: "exportação",
    import: "importação",
    jobs: "jobs",
    logistics: "logística",
    mapping: "mapeamento",
    orders: "pedidos",
    price: "preço",
    process: "processo",
    products: "produtos",
    relaunch: "relançamento",
    seller: "logística do vendedor",
    spx: "Shopee Xpress",
    status: "status",
    stock: "estoque",
    sync: "sincronismo",
    update: "atualização",
  };
  const humanizeToken = (value) => {
    const normalized = String(value || "").trim().toLowerCase().replace(/_/g, "-");
    return tokenMap[normalized] || normalized.split("-").filter(Boolean).join(" ");
  };
  const titleCase = (value) => String(value || "")
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => `${word.charAt(0).toUpperCase()}${word.slice(1)}`)
    .join(" ");
  if (actionTag) {
    return titleCase(actionTag.split(".").map(humanizeToken).filter(Boolean).join(" - "));
  }
  const routeSegments = routePath
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean)
    .filter((segment) => !["shopee", "shops", "active", "admin-global", "master"].includes(segment))
    .filter((segment) => !/^\d+$/.test(segment))
    .map(humanizeToken)
    .filter(Boolean);
  const routeName = routeSegments.length ? titleCase(routeSegments.join(" - ")) : "";
  if (normalizedMethod === "POST" || normalizedMethod === "JOB") {
    return routeName ? `Execução: ${routeName}` : "Execução de processo";
  }
  if (normalizedMethod === "GET") {
    return routeName ? `Consulta: ${routeName}` : "Consulta de processo";
  }
  return routeName || "Processo nomeado";
}

function isUserRequestedProcessNotification(item) {
  const method = String(item?.method || "").trim().toUpperCase();
  const text = [item?.displayName, item?.path, item?.method]
    .map((value) => String(value || "").toLowerCase())
    .join(" ");

  if (method === "GET" || /(audit|tab-access|select-shop|auth - select)/.test(text)) {
    return false;
  }
  return ["POST", "PUT", "PATCH", "DELETE", "JOB"].includes(method);
}

async function pollProcessNotificationsFromBackend({ silent = true } = {}) {
  try {
    const data = await apiGet("/processes/notifications?lookbackHours=168&limit=120");
    const items = Array.isArray(data?.items) ? data.items : [];
    if (!items.length) return;

    items
      .slice()
      .sort((a, b) => Number(a?.id || 0) - Number(b?.id || 0))
      .forEach((item) => {
        const processId = String(item?.id || "").trim();
        if (!processId) return;
        if (!shouldNotifyProcessId(processId)) return;
        if (!isUserRequestedProcessNotification(item)) {
          markProcessNotificationSeen(processId);
          return;
        }
        const success = Boolean(item?.success);
        const processName = resolveFriendlyProcessName(item);
        const message = success
          ? `${processName} concluído com sucesso.`
          : `${processName} finalizado com falhas${item?.errorMessage ? `: ${item.errorMessage}` : "."}`;
        pushGlobalNotification({
          title: `${processName} #${processId}`,
          message,
          type: success ? "success" : "warning",
          showToast: !silent,
          actionLabel: "Baixar logs",
          actionUrl: normalizeApiPath(
            `/processes/${encodeURIComponent(processId)}/logs.txt`,
          ),
          kind: "user_action",
        });
        markProcessNotificationSeen(processId);
      });
  } catch (error) {
    if (!silent) {
      console.warn("[process-notifications] poll failed", error?.message || error);
    }
  }
}

function startProcessNotificationsPolling() {
  loadProcessNotificationSeenIds();
  void pollProcessNotificationsFromBackend({ silent: true });

  if (PROCESS_NOTIFICATIONS_POLL_TIMER) {
    clearInterval(PROCESS_NOTIFICATIONS_POLL_TIMER);
  }
  PROCESS_NOTIFICATIONS_POLL_TIMER = setInterval(() => {
    void pollProcessNotificationsFromBackend({ silent: true });
  }, 45000);

  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      void pollProcessNotificationsFromBackend({ silent: true });
    }
  });
}

function formatSignedPercent(value, digits = 2) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return `${n >= 0 ? "+" : ""}${n.toFixed(digits)}%`;
}

function getDailyInsightSentStorageKey(now = new Date()) {
  const dayIso = isoLocalDate(now);
  const shopKey = String(ME?.activeShopId || ACTIVE_SHOP_ID || "active");
  return `${DAILY_INSIGHT_SENT_STORAGE_PREFIX}_${shopKey}_${dayIso}`;
}

async function buildDailyInsightPayload() {
  if (!ME) {
    await loadMe();
  }
  const shops = Array.isArray(ME?.shops) ? ME.shops : [];
  if (!shops.length) return null;
  if (!ME?.activeShopId && shops.length > 1) return null;
  if (!ME?.activeShopId && shops.length === 1) {
    await ensureShopSelected();
  }

  const now = new Date();
  const yesterday = new Date(now);
  yesterday.setDate(yesterday.getDate() - 1);
  const dayBeforeYesterday = new Date(now);
  dayBeforeYesterday.setDate(dayBeforeYesterday.getDate() - 2);

  const yesterdayIso = isoLocalDate(yesterday);
  const dayBeforeYesterdayIso = isoLocalDate(dayBeforeYesterday);

  const [todaySales, monthlySales, roasYesterday, roasDayBefore] = await Promise.all([
    apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/dashboard/today-sales`),
    apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/dashboard/monthly-sales`),
    loadAdsRoasApprox({ dateFrom: yesterdayIso, dateTo: yesterdayIso }),
    loadAdsRoasApprox({
      dateFrom: dayBeforeYesterdayIso,
      dateTo: dayBeforeYesterdayIso,
    }),
  ]);

  const roasCurrent = Number(roasYesterday?.metrics?.roas);
  const roasPrevious = Number(roasDayBefore?.metrics?.roas);
  const roasDeltaPct =
    Number.isFinite(roasCurrent) &&
    Number.isFinite(roasPrevious) &&
    Math.abs(roasPrevious) > 0
      ? ((roasCurrent - roasPrevious) / Math.abs(roasPrevious)) * 100
      : null;

  const gmvMtdCents = Number(monthlySales?.metrics?.gmvMtdCents || 0);
  const prevFullMonthGmvCents = Number(
    monthlySales?.compare?.prevFullMonth?.gmvMtdCents || 0,
  );
  const dayOfMonth = Number(monthlySales?.period?.dayOfMonth || 1);
  const daysInMonth = Number(monthlySales?.period?.daysInMonth || 30);
  const elapsedMonthPct =
    daysInMonth > 0 ? (dayOfMonth / Math.max(1, daysInMonth)) * 100 : 0;
  const currentVsLastMonthPct =
    prevFullMonthGmvCents > 0
      ? (gmvMtdCents / prevFullMonthGmvCents) * 100
      : null;
  const paceDeltaPct =
    currentVsLastMonthPct == null
      ? null
      : currentVsLastMonthPct - elapsedMonthPct;

  const gmvYesterdayCents = Number(todaySales?.metrics?.gmvYesterdayCents || 0);
  const ordersCountYesterday = Number(todaySales?.metrics?.ordersCountYesterday || 0);

  const roasArrow = roasDeltaPct == null ? "⚪" : roasDeltaPct >= 0 ? "📈" : "📉";
  const paceArrow = paceDeltaPct == null ? "⚪" : paceDeltaPct >= 0 ? "📈" : "📉";
  const roasText =
    roasDeltaPct == null
      ? "ROAS sem base comparativa"
      : `ROAS ${formatSignedPercent(roasDeltaPct)} vs dia anterior`;
  const paceText =
    paceDeltaPct == null
      ? "Ritmo sem base do mês anterior"
      : `Ritmo ${formatSignedPercent(paceDeltaPct)} para bater o mês anterior`;

  return {
    title: "Insight diário 08:00",
    message:
      `${roasArrow} ${roasText} | ` +
      `${paceArrow} ${paceText} | ` +
      `🛒 Vendas ontem (${yesterdayIso}): ${formatBRLCents(gmvYesterdayCents)} em ${ordersCountYesterday} pedido(s).`,
  };
}

async function maybeSendDailyInsightNotification() {
  const now = new Date();
  if (now.getHours() < 8) return;

  const sentKey = getDailyInsightSentStorageKey(now);
  try {
    if (localStorage.getItem(sentKey)) return;
  } catch (_error) {
    // ignore read errors
  }

  try {
    const payload = await buildDailyInsightPayload();
    if (!payload) return;
    pushGlobalNotification({
      ...payload,
      type: "info",
      channel: "general",
      showToast: true,
      kind: "daily_roas",
    });
    try {
      localStorage.setItem(sentKey, new Date().toISOString());
    } catch (_error) {
      // ignore write errors
    }
  } catch (error) {
    console.warn("[notifications.daily-insight] failed", error?.message || error);
  }
}

function startDailyInsightNotifications() {
  if (DAILY_INSIGHT_TIMER) {
    clearInterval(DAILY_INSIGHT_TIMER);
    DAILY_INSIGHT_TIMER = null;
  }

  void maybeSendDailyInsightNotification();
  DAILY_INSIGHT_TIMER = setInterval(() => {
    void maybeSendDailyInsightNotification();
  }, 15 * 60 * 1000);
}

function normalizeInformativeLinkUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith("/")) return raw;
  return "";
}

function normalizeInformativeNoticeType(value) {
  const raw = String(value || "").trim().toUpperCase();
  return raw === "POPUP" ? "POPUP" : "TAG";
}

function loadGlobalInformativePopupDismissState() {
  try {
    const raw = localStorage.getItem(GLOBAL_INFORMATIVE_POPUP_DISMISS_STORAGE_KEY);
    if (!raw) {
      GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE = {};
      return;
    }
    const parsed = JSON.parse(raw);
    GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE =
      parsed && typeof parsed === "object" ? parsed : {};
  } catch (_error) {
    GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE = {};
  }
}

function saveGlobalInformativePopupDismissState() {
  try {
    localStorage.setItem(
      GLOBAL_INFORMATIVE_POPUP_DISMISS_STORAGE_KEY,
      JSON.stringify(GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE || {}),
    );
  } catch (_error) {
    // ignore localStorage failures
  }
}

function isPopupDismissedForever(noticeId) {
  const key = String(noticeId || "").trim();
  if (!key) return false;
  return GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE?.[key] === false;
}

function setPopupDismissPreference(noticeId, shouldShowAgain) {
  const key = String(noticeId || "").trim();
  if (!key) return;
  GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE = {
    ...(GLOBAL_INFORMATIVE_POPUP_DISMISS_STATE || {}),
    [key]: Boolean(shouldShowAgain),
  };
  saveGlobalInformativePopupDismissState();
}

function ensureGlobalInformativePopup() {
  let overlay = document.getElementById("globalInformativePopupOverlay");
  if (overlay) return overlay;
  overlay = document.createElement("div");
  overlay.id = "globalInformativePopupOverlay";
  overlay.className = "global-informative-popup-overlay is-hidden";
  overlay.innerHTML = `
    <div class="global-informative-popup-modal">
      <button id="globalInformativePopupClose" type="button" class="global-informative-popup-close" aria-label="Fechar aviso">×</button>
      <a id="globalInformativePopupLink" class="global-informative-popup-link" href="#" target="_blank" rel="noopener noreferrer">
        <img id="globalInformativePopupImage" class="global-informative-popup-image" alt="Comunicado" />
      </a>
      <div id="globalInformativePopupMessage" class="global-informative-popup-message"></div>
    </div>
  `;
  document.body.appendChild(overlay);

  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) {
      const closeBtn = document.getElementById("globalInformativePopupClose");
      if (closeBtn) closeBtn.click();
    }
  });

  return overlay;
}

function hideGlobalInformativePopup() {
  const overlay = document.getElementById("globalInformativePopupOverlay");
  if (overlay) overlay.classList.add("is-hidden");
}

function askPopupShowAgain(noticeId) {
  openModal(
    "Comunicado",
    `
      <div class="muted">Deseja ser informado novamente depois?</div>
      <div class="toolbar" style="margin-top:12px; justify-content:flex-end; gap:8px;">
        <button id="btnInformativePopupAskYes" class="btn btn-primary" type="button">Sim</button>
        <button id="btnInformativePopupAskNo" class="btn btn-ghost" type="button">Não</button>
      </div>
    `,
  );

  document.getElementById("btnInformativePopupAskYes")?.addEventListener("click", () => {
    setPopupDismissPreference(noticeId, true);
    closeModal();
  });
  document.getElementById("btnInformativePopupAskNo")?.addEventListener("click", () => {
    setPopupDismissPreference(noticeId, false);
    closeModal();
  });
}

function ensureInformativePopupNotification(notice) {
  const noticeId = String(notice?.id || "").trim();
  if (!noticeId) return;
  const alreadyExists = GLOBAL_NOTIFICATIONS.some(
    (item) =>
      normalizeNotificationChannel(item?.channel) === "informative" &&
      String(item?.actionPayload?.noticeId || "").trim() === noticeId,
  );
  if (alreadyExists) return;
  const title = String(notice?.title || "Informativo").trim() || "Informativo";
  const message = String(notice?.message || "").trim();
  pushGlobalNotification({
    title,
    message: message || "Comunicado disponível para visualização.",
    type: "info",
    showToast: false,
    channel: "informative",
    actionLabel: "Abrir novamente",
    actionKind: "reopen_informative_popup",
    actionPayload: {
      noticeId,
      endsAt: notice?.endsAt || notice?.ends_at || null,
    },
    noticeSnapshot: {
      id: noticeId,
      title,
      message,
      imageUrl: String(notice?.imageUrl || notice?.image_url || "").trim(),
      linkUrl: normalizeInformativeLinkUrl(notice?.linkUrl || notice?.link_url || ""),
      color: String(notice?.color || "").trim(),
      noticeType: "POPUP",
      startsAt: notice?.startsAt || notice?.starts_at || null,
      endsAt: notice?.endsAt || notice?.ends_at || null,
    },
  });
}

function openGlobalInformativePopup(notice) {
  const overlay = ensureGlobalInformativePopup();
  const linkEl = document.getElementById("globalInformativePopupLink");
  const imageEl = document.getElementById("globalInformativePopupImage");
  const messageEl = document.getElementById("globalInformativePopupMessage");
  const closeBtn = document.getElementById("globalInformativePopupClose");
  if (!overlay || !linkEl || !imageEl || !messageEl || !closeBtn || !notice) return;
  ensureInformativePopupNotification(notice);

  const noticeId = String(notice?.id || "").trim();
  const linkUrl = normalizeInformativeLinkUrl(notice?.linkUrl || notice?.link_url || "");
  const imageUrl = String(notice?.imageUrl || notice?.image_url || "").trim();
  const title = String(notice?.title || "").trim();
  const message = String(notice?.message || "").trim();
  const payload = [title, message].filter(Boolean).join(" • ");

  imageEl.src = imageUrl;
  imageEl.alt = title || "Comunicado";
  messageEl.textContent = payload;
  if (linkUrl) {
    linkEl.style.display = "";
    linkEl.setAttribute("href", linkUrl);
    linkEl.style.pointerEvents = "";
  } else {
    linkEl.removeAttribute("href");
    linkEl.style.pointerEvents = "none";
  }
  overlay.classList.remove("is-hidden");

  closeBtn.onclick = () => {
    hideGlobalInformativePopup();
    askPopupShowAgain(noticeId);
  };
}

function tryShowGlobalInformativePopup() {
  if (GLOBAL_INFORMATIVE_POPUP_SHOWN_ONCE) return;
  const popupNotices = Array.isArray(GLOBAL_INFORMATIVE_POPUP_NOTICES)
    ? GLOBAL_INFORMATIVE_POPUP_NOTICES
    : [];
  if (!popupNotices.length) {
    hideGlobalInformativePopup();
    return;
  }
  const candidate = popupNotices.find(
    (notice) => !isPopupDismissedForever(notice?.id),
  );
  if (!candidate) {
    hideGlobalInformativePopup();
    return;
  }
  const imageUrl = String(candidate?.imageUrl || candidate?.image_url || "").trim();
  if (!imageUrl) return;
  GLOBAL_INFORMATIVE_POPUP_SHOWN_ONCE = true;
  ensureInformativePopupNotification(candidate);
  hideGlobalInformativePopup();
}

function ensureGlobalInformativeBar() {
  let bar = document.getElementById("globalInformativeBar");
  if (bar) return bar;
  bar = document.createElement("div");
  bar.id = "globalInformativeBar";
  bar.className = "global-informative-bar is-hidden";
  bar.innerHTML = `
    <div class="global-informative-bar__inner">
      <div id="globalInformativeBarTextViewport" class="global-informative-bar__text-viewport">
        <span id="globalInformativeBarTextTrack" class="global-informative-bar__text-track"></span>
      </div>
      <a id="globalInformativeBarLink" class="global-informative-bar__link" href="#" target="_blank" rel="noopener noreferrer" style="display:none;">Saiba mais</a>
    </div>
  `;
  const appBootLoader = document.getElementById("appBootLoader");
  if (appBootLoader?.parentNode) {
    appBootLoader.parentNode.insertBefore(bar, appBootLoader.nextSibling);
  } else {
    document.body.insertBefore(bar, document.body.firstChild);
  }
  return bar;
}

function syncGlobalInformativeBarText(payloadText) {
  const viewportEl = document.getElementById("globalInformativeBarTextViewport");
  const trackEl = document.getElementById("globalInformativeBarTextTrack");
  if (!viewportEl || !trackEl) return;

  const baseText = String(payloadText || "").trim() || "Aviso importante";
  trackEl.classList.remove("is-scrolling");
  trackEl.style.removeProperty("--marquee-duration");
  trackEl.textContent = baseText;
  viewportEl.setAttribute("title", baseText);

  window.requestAnimationFrame(() => {
    const viewportWidth = Number(viewportEl.clientWidth || 0);
    const textWidth = Number(trackEl.scrollWidth || 0);
    if (viewportWidth <= 0 || textWidth <= viewportWidth + 8) return;

    const separator = "      •      ";
    trackEl.textContent = `${baseText}${separator}${baseText}`;
    const totalWidth = Number(trackEl.scrollWidth || 0);
    const loopDistance = totalWidth / 2;
    const pxPerSecond = 70;
    const durationSeconds = Math.max(
      14,
      Math.min(70, loopDistance / Math.max(30, pxPerSecond)),
    );
    trackEl.style.setProperty("--marquee-duration", `${durationSeconds}s`);
    trackEl.classList.add("is-scrolling");
  });
}

function renderGlobalInformativeBarCurrent() {
  const bar = ensureGlobalInformativeBar();
  const viewportEl = document.getElementById("globalInformativeBarTextViewport");
  const linkEl = document.getElementById("globalInformativeBarLink");
  if (!bar || !viewportEl || !linkEl) return;

  if (!Array.isArray(GLOBAL_INFORMATIVE_TAG_NOTICES) || !GLOBAL_INFORMATIVE_TAG_NOTICES.length) {
    bar.classList.add("is-hidden");
    viewportEl.removeAttribute("title");
    linkEl.style.display = "none";
    linkEl.removeAttribute("href");
    return;
  }

  const safeIndex =
    ((Number(GLOBAL_INFORMATIVE_ACTIVE_INDEX) % GLOBAL_INFORMATIVE_TAG_NOTICES.length) +
      GLOBAL_INFORMATIVE_TAG_NOTICES.length) %
    GLOBAL_INFORMATIVE_TAG_NOTICES.length;
  const notice = GLOBAL_INFORMATIVE_TAG_NOTICES[safeIndex] || null;
  if (!notice) {
    bar.classList.add("is-hidden");
    return;
  }

  const color = /^#[0-9a-fA-F]{6}$/.test(String(notice?.color || ""))
    ? String(notice.color).toUpperCase()
    : "#FF5A00";
  const title = String(notice?.title || "").trim();
  const message = String(notice?.message || "").trim();
  const payload = [title, message].filter(Boolean).join(" • ");
  const linkUrl = normalizeInformativeLinkUrl(notice?.linkUrl || notice?.link_url || "");

  syncGlobalInformativeBarText(payload);
  bar.style.setProperty("--informative-color", color);
  bar.classList.remove("is-hidden");

  if (linkUrl) {
    linkEl.style.display = "";
    linkEl.setAttribute("href", linkUrl);
  } else {
    linkEl.style.display = "none";
    linkEl.removeAttribute("href");
  }
}

async function refreshGlobalInformativeNotices() {
  try {
    const data = await apiGet("/informativos/active");
    const notices = Array.isArray(data?.notices) ? data.notices : [];
    GLOBAL_INFORMATIVE_TAG_NOTICES = notices.filter(
      (notice) => normalizeInformativeNoticeType(notice?.noticeType || notice?.notice_type) === "TAG",
    );
    GLOBAL_INFORMATIVE_POPUP_NOTICES = notices.filter(
      (notice) =>
        normalizeInformativeNoticeType(notice?.noticeType || notice?.notice_type) === "POPUP",
    );
    if (
      !Number.isFinite(Number(GLOBAL_INFORMATIVE_ACTIVE_INDEX)) ||
      GLOBAL_INFORMATIVE_ACTIVE_INDEX < 0 ||
      GLOBAL_INFORMATIVE_ACTIVE_INDEX >= GLOBAL_INFORMATIVE_TAG_NOTICES.length
    ) {
      GLOBAL_INFORMATIVE_ACTIVE_INDEX = 0;
    }
    renderGlobalInformativeBarCurrent();
    tryShowGlobalInformativePopup();
  } catch (_error) {
    GLOBAL_INFORMATIVE_TAG_NOTICES = [];
    GLOBAL_INFORMATIVE_POPUP_NOTICES = [];
    GLOBAL_INFORMATIVE_ACTIVE_INDEX = 0;
    renderGlobalInformativeBarCurrent();
    hideGlobalInformativePopup();
  }
}

function startGlobalInformativeBanner() {
  if (GLOBAL_INFORMATIVE_ROTATE_TIMER) {
    clearInterval(GLOBAL_INFORMATIVE_ROTATE_TIMER);
    GLOBAL_INFORMATIVE_ROTATE_TIMER = null;
  }
  if (GLOBAL_INFORMATIVE_REFRESH_TIMER) {
    clearInterval(GLOBAL_INFORMATIVE_REFRESH_TIMER);
    GLOBAL_INFORMATIVE_REFRESH_TIMER = null;
  }

  GLOBAL_INFORMATIVE_ROTATE_TIMER = setInterval(() => {
    if (!Array.isArray(GLOBAL_INFORMATIVE_TAG_NOTICES) || GLOBAL_INFORMATIVE_TAG_NOTICES.length <= 1) {
      return;
    }
    GLOBAL_INFORMATIVE_ACTIVE_INDEX =
      (GLOBAL_INFORMATIVE_ACTIVE_INDEX + 1) % GLOBAL_INFORMATIVE_TAG_NOTICES.length;
    renderGlobalInformativeBarCurrent();
  }, 30000);

  GLOBAL_INFORMATIVE_REFRESH_TIMER = setInterval(() => {
    void refreshGlobalInformativeNotices();
  }, 120000);

  loadGlobalInformativePopupDismissState();
  GLOBAL_INFORMATIVE_POPUP_SHOWN_ONCE = false;
  ensureGlobalInformativePopup();
  void refreshGlobalInformativeNotices();
}

function getGlobalProcessDockElements() {
  let panel = document.getElementById("globalProcessDock");
  if (!panel) {
    panel = document.createElement("aside");
    panel.id = "globalProcessDock";
    panel.className = "global-process-dock is-hidden";
    document.body.appendChild(panel);
  }

  let handle = document.getElementById("globalProcessDockHandle");
  if (!handle) {
    handle = document.createElement("button");
    handle.id = "globalProcessDockHandle";
    handle.className = "global-process-dock-handle is-hidden";
    handle.type = "button";
    document.body.appendChild(handle);
  }

  return { panel, handle };
}

function normalizeGlobalProcessEntry(raw = {}) {
  const logs = Array.isArray(raw?.logs)
    ? raw.logs.map((line) => String(line || "")).filter(Boolean)
    : [];
  return {
    id: String(raw?.id || createNotificationId()),
    source: String(raw?.source || "processo"),
    title: String(raw?.title || "Processo"),
    startedAt: String(raw?.startedAt || new Date().toISOString()),
    finishedAt: raw?.finishedAt ? String(raw.finishedAt) : "",
    status: String(raw?.status || "running"),
    total: Math.max(0, Number(raw?.total || 0)),
    done: Math.max(0, Number(raw?.done || 0)),
    success: Math.max(0, Number(raw?.success || 0)),
    failed: Math.max(0, Number(raw?.failed || 0)),
    finished: Boolean(raw?.finished),
    notified: Boolean(raw?.notified),
    queueState: String(raw?.queueState || ""),
    queueWaitingSince: raw?.queueWaitingSince ? String(raw.queueWaitingSince) : "",
    queueWaitingAlerted: Boolean(raw?.queueWaitingAlerted),
    updatedAt: String(raw?.updatedAt || new Date().toISOString()),
    logs: logs.slice(-GLOBAL_PROCESS_DOCK_MAX_LOGS),
  };
}

function formatQueueWaitingLabel(startedAtIso) {
  const startedMs = new Date(startedAtIso || "").getTime();
  if (!Number.isFinite(startedMs) || startedMs <= 0) return "há alguns segundos";
  const elapsedSec = Math.max(0, Math.floor((Date.now() - startedMs) / 1000));
  if (elapsedSec < 60) return `há ${elapsedSec}s`;
  const elapsedMin = Math.floor(elapsedSec / 60);
  const remainingSec = elapsedSec % 60;
  return `há ${elapsedMin}m${remainingSec}s`;
}

function pruneGlobalProcessDockState() {
  if (!GLOBAL_PROCESS_DOCK_STATE || typeof GLOBAL_PROCESS_DOCK_STATE !== "object") {
    GLOBAL_PROCESS_DOCK_STATE = { collapsed: false, processes: [] };
  }
  GLOBAL_PROCESS_DOCK_STATE.collapsed = Boolean(GLOBAL_PROCESS_DOCK_STATE.collapsed);
  GLOBAL_PROCESS_DOCK_STATE.processes = (Array.isArray(GLOBAL_PROCESS_DOCK_STATE.processes)
    ? GLOBAL_PROCESS_DOCK_STATE.processes
    : []
  )
    .map((entry) => normalizeGlobalProcessEntry(entry))
    .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
    .slice(0, GLOBAL_PROCESS_DOCK_MAX_PROCESSES);
}

function saveGlobalProcessDockState() {
  pruneGlobalProcessDockState();
  try {
    localStorage.setItem(
      GLOBAL_PROCESS_DOCK_STORAGE_KEY,
      JSON.stringify(GLOBAL_PROCESS_DOCK_STATE),
    );
  } catch (_error) {
    // ignore localStorage failures
  }
}

function loadGlobalProcessDockState() {
  try {
    const raw = localStorage.getItem(GLOBAL_PROCESS_DOCK_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    GLOBAL_PROCESS_DOCK_STATE = {
      collapsed: Boolean(parsed?.collapsed),
      processes: Array.isArray(parsed?.processes) ? parsed.processes : [],
    };
    pruneGlobalProcessDockState();
  } catch (_error) {
    GLOBAL_PROCESS_DOCK_STATE = { collapsed: false, processes: [] };
  }
}

function setGlobalProcessDockCollapsed(collapsed) {
  GLOBAL_PROCESS_DOCK_STATE.collapsed = Boolean(collapsed);
  saveGlobalProcessDockState();
  renderGlobalProcessDock();
}

function downloadGlobalProcessEntryLogs(processId) {
  const process = (GLOBAL_PROCESS_DOCK_STATE.processes || []).find(
    (entry) => entry.id === processId,
  );
  if (!process) return;
  const safeName = String(process.title || "processo")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  const lines = [
    `Processo: ${process.title}`,
    `Origem: ${process.source}`,
    `Inicio: ${process.startedAt || "-"}`,
    `Fim: ${process.finishedAt || "-"}`,
    `Status: ${process.status}`,
    `Progresso: ${Number(process.done || 0)}/${Number(process.total || 0)}`,
    `Sucesso: ${Number(process.success || 0)}`,
    `Falhas: ${Number(process.failed || 0)}`,
    "",
    ...(Array.isArray(process.logs) ? process.logs : []),
  ];
  const blob = new Blob([lines.join("\n")], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${safeName || "processo"}_${Date.now()}_logs.txt`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function renderGlobalProcessDock() {
  const { panel, handle } = getGlobalProcessDockElements();
  pruneGlobalProcessDockState();

  const processes = GLOBAL_PROCESS_DOCK_STATE.processes;
  const runningCount = processes.filter((entry) => !entry.finished).length;
  const hasAny = processes.length > 0;

  panel.classList.toggle("is-hidden", !hasAny || GLOBAL_PROCESS_DOCK_STATE.collapsed);
  handle.classList.toggle("is-hidden", !hasAny || !GLOBAL_PROCESS_DOCK_STATE.collapsed);

  if (!hasAny) {
    panel.innerHTML = "";
    handle.textContent = "";
    return;
  }

  handle.textContent =
    runningCount > 0 ? `Processos (${runningCount} em andamento)` : "Processos (concluídos)";

  panel.innerHTML = `
    <div class="global-process-dock__header">
      <div>
        <strong>Processos</strong>
        <div class="muted">
          ${runningCount > 0 ? `${runningCount} em andamento` : "Sem processos em andamento"}
        </div>
      </div>
      <div class="global-process-dock__actions">
        <button class="btn btn-ghost" type="button" data-gpd-refresh>Sincronizar agora</button>
        <button class="btn btn-ghost" type="button" data-gpd-clear-finished>Limpar concluídos</button>
        <button class="btn btn-ghost" type="button" data-gpd-collapse>Recolher</button>
      </div>
    </div>
    <div class="global-process-dock__list">
      ${processes
        .map((entry) => {
          const total = Math.max(0, Number(entry.total || 0));
          const done = Math.max(0, Number(entry.done || 0));
          const pct = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : 0;
          const jobId = extractJobIdFromProcessEntry(entry);
          const waitingSince = entry?.queueWaitingSince
            ? new Date(entry.queueWaitingSince).getTime()
            : 0;
          const waitingAgeMs = waitingSince > 0 ? Date.now() - waitingSince : 0;
          const isQueueWaitingAlert =
            !entry.finished &&
            String(entry.queueState || "").toLowerCase() === "waiting" &&
            waitingAgeMs >= 15000;
          const tone =
            entry.status === "success"
              ? "is-success"
              : entry.status === "warning"
                ? "is-warning"
                : entry.status === "error"
                  ? "is-error"
                  : "is-running";
          const logs = Array.isArray(entry.logs) ? entry.logs.slice(-10) : [];
          const finishedLabel = entry.finishedAt
            ? `Finalizado em ${formatNotificationDate(entry.finishedAt)}`
            : `Atualizado em ${formatNotificationDate(entry.updatedAt)}`;

          return `
            <article class="global-process-card ${tone}">
              <div class="global-process-card__head">
                <div>
                  <div><strong>${escapeHtml(entry.title)}</strong></div>
                  <div class="muted">${escapeHtml(entry.source)} • ${escapeHtml(
                    formatNotificationDate(entry.startedAt),
                  )}</div>
                </div>
                <span class="badge">${escapeHtml(
                  entry.finished
                    ? entry.status === "warning"
                      ? "Concluído c/ alertas"
                      : entry.status === "error"
                        ? "Concluído com erro"
                        : "Concluído"
                    : "Em andamento",
                )}</span>
              </div>
              <div class="global-process-card__progress">
                <div class="global-process-card__track">
                  <div class="global-process-card__bar" style="width:${pct}%"></div>
                </div>
                <div class="muted">${done}/${total} • ${pct}% • sucesso ${Number(
                  entry.success || 0,
                )} • falhas ${Number(entry.failed || 0)}</div>
                <div class="muted">${escapeHtml(finishedLabel)}</div>
                ${
                  isQueueWaitingAlert
                    ? `<div class="badge badge--yellow" style="margin-top:6px;">Fila aguardando consumo ${escapeHtml(
                      formatQueueWaitingLabel(entry.queueWaitingSince),
                    )}. Verifique worker/fila.</div>`
                    : ""
                }
              </div>
              <div class="global-process-card__logs">
                ${
                  logs.length
                    ? logs
                        .map(
                          (line) =>
                            `<div class="global-process-card__log">${escapeHtml(String(line || ""))}</div>`,
                        )
                        .join("")
                    : '<div class="muted">Sem logs.</div>'
                }
              </div>
              <div class="global-process-card__actions">
                <button class="btn btn-ghost" type="button" data-gpd-download="${escapeHtml(
                  entry.id,
                )}">Baixar logs</button>
                ${
                  !entry.finished && jobId
                    ? `<button class="btn btn-ghost" type="button" data-gpd-cancel="${escapeHtml(
                      entry.id,
                    )}" data-gpd-job-id="${escapeHtml(jobId)}">Cancelar processo</button>`
                    : ""
                }
                ${
                  entry.finished
                    ? `<button class="btn btn-ghost" type="button" data-gpd-dismiss="${escapeHtml(entry.id)}">Remover</button>`
                    : ""
                }
              </div>
            </article>
          `;
        })
        .join("")}
    </div>
  `;

  if (panel.dataset.bound !== "1") {
    panel.dataset.bound = "1";
    panel.addEventListener("click", (event) => {
      const refreshBtn = event.target.closest("[data-gpd-refresh]");
      if (refreshBtn) {
        const originalText = refreshBtn.textContent;
        refreshBtn.disabled = true;
        refreshBtn.textContent = "Sincronizando...";
        Promise.resolve(reconcileGlobalProcessDockJobs())
          .catch(() => {})
          .finally(() => {
            refreshBtn.disabled = false;
            refreshBtn.textContent = originalText || "Sincronizar agora";
          });
        return;
      }

      const collapseBtn = event.target.closest("[data-gpd-collapse]");
      if (collapseBtn) {
        setGlobalProcessDockCollapsed(true);
        return;
      }

      const clearFinishedBtn = event.target.closest("[data-gpd-clear-finished]");
      if (clearFinishedBtn) {
        GLOBAL_PROCESS_DOCK_STATE.processes = GLOBAL_PROCESS_DOCK_STATE.processes.filter(
          (entry) => !entry.finished,
        );
        saveGlobalProcessDockState();
        renderGlobalProcessDock();
        return;
      }

      const downloadBtn = event.target.closest("[data-gpd-download]");
      if (downloadBtn) {
        downloadGlobalProcessEntryLogs(downloadBtn.getAttribute("data-gpd-download"));
        return;
      }

      const cancelBtn = event.target.closest("[data-gpd-cancel]");
      if (cancelBtn) {
        const processId = String(cancelBtn.getAttribute("data-gpd-cancel") || "").trim();
        const jobId = String(cancelBtn.getAttribute("data-gpd-job-id") || "").trim();
        if (!processId || !jobId) return;
        const confirmed = window.confirm(
          "Cancelar este processo em fila? Essa ação remove o job pendente.",
        );
        if (!confirmed) return;
        const originalText = cancelBtn.textContent;
        cancelBtn.disabled = true;
        cancelBtn.textContent = "Cancelando...";
        Promise.resolve(cancelAsyncProcessJob(jobId))
          .then((result) => {
            if (result?.cancelled) {
              appendGlobalTrackedProcessLog(
                processId,
                `Processo cancelado manualmente (jobId: ${jobId}).`,
                "warning",
              );
              finishGlobalTrackedProcess(processId, {
                summaryMessage: "Processo cancelado manualmente.",
                hasWarning: true,
              });
              return;
            }
            appendGlobalTrackedProcessLog(
              processId,
              `Não foi possível cancelar: estado atual ${String(result?.state || "desconhecido")}.`,
              "warning",
            );
          })
          .catch((error) => {
            appendGlobalTrackedProcessLog(
              processId,
              `Falha ao cancelar processo: ${String(error?.message || "erro desconhecido")}`,
              "error",
            );
          })
          .finally(() => {
            cancelBtn.disabled = false;
            cancelBtn.textContent = originalText || "Cancelar processo";
          });
        return;
      }

      const dismissBtn = event.target.closest("[data-gpd-dismiss]");
      if (dismissBtn) {
        const id = dismissBtn.getAttribute("data-gpd-dismiss");
        GLOBAL_PROCESS_DOCK_STATE.processes = GLOBAL_PROCESS_DOCK_STATE.processes.filter(
          (entry) => entry.id !== id,
        );
        saveGlobalProcessDockState();
        renderGlobalProcessDock();
      }
    });
  }

  if (handle.dataset.bound !== "1") {
    handle.dataset.bound = "1";
    handle.addEventListener("click", () => {
      setGlobalProcessDockCollapsed(false);
    });
  }
}

function getGlobalTrackedProcess(processId) {
  if (!processId) return null;
  return (GLOBAL_PROCESS_DOCK_STATE.processes || []).find(
    (entry) => entry.id === String(processId),
  );
}

function extractJobIdFromProcessEntry(entry = {}) {
  const logs = Array.isArray(entry?.logs) ? entry.logs : [];
  for (let i = logs.length - 1; i >= 0; i -= 1) {
    const line = String(logs[i] || "");
    const match = line.match(/jobId:\s*([a-zA-Z0-9_.-]+)/);
    if (match?.[1]) return String(match[1]).trim();
  }
  return "";
}

async function reconcileGlobalProcessDockJobs() {
  const running = (GLOBAL_PROCESS_DOCK_STATE.processes || []).filter(
    (entry) => entry && !entry.finished,
  );
  if (!running.length) return;
  const staleWaitingCutoffMs = 30 * 60 * 1000;

  for (const entry of running) {
    const jobId = extractJobIdFromProcessEntry(entry);
    if (!jobId) continue;
    try {
      // eslint-disable-next-line no-await-in-loop
      const status = await getAsyncProcessJobStatus(jobId);
      const state = String(status?.status || "").toLowerCase();
      entry.queueState = state;
      if (state === "waiting") {
        if (!entry.queueWaitingSince) {
          entry.queueWaitingSince = new Date().toISOString();
        }
        const waitingMs =
          Date.now() - new Date(entry.queueWaitingSince || new Date().toISOString()).getTime();
        if (waitingMs >= staleWaitingCutoffMs) {
          const total = Math.max(0, Number(entry.total || 0));
          syncGlobalTrackedProcessProgress(entry.id, {
            done: total,
            total,
            success: 0,
            failed: total || 1,
          });
          appendGlobalTrackedProcessLog(
            entry.id,
            "Processo encerrado automaticamente: job ficou em WAITING por mais de 30 minutos sem consumo.",
            "warning",
          );
          finishGlobalTrackedProcess(entry.id, {
            summaryMessage:
              "Processo expirado na fila. Reexecute a ação; o sistema usará fallback direto se a fila não iniciar.",
            hasWarning: true,
          });
          continue;
        }
        if (waitingMs >= 15000 && !entry.queueWaitingAlerted) {
          entry.queueWaitingAlerted = true;
          entry.logs = [...(Array.isArray(entry.logs) ? entry.logs : []), "Alerta: job em WAITING por mais de 15s. Verifique worker/fila ou cancele o processo."].slice(
            -GLOBAL_PROCESS_DOCK_MAX_LOGS,
          );
        }
      } else {
        entry.queueWaitingSince = "";
        entry.queueWaitingAlerted = false;
      }
      if (state === "completed") {
        const payload = status?.result && typeof status.result === "object"
          ? status.result
          : {};
        const nested = payload?.result && typeof payload.result === "object"
          ? payload.result
          : payload;
        const total = Math.max(0, Number(entry.total || 0));
        const success = Number.isFinite(Number(nested?.success))
          ? Number(nested.success)
          : Number.isFinite(Number(nested?.paused))
            ? Number(nested.paused)
            : Number.isFinite(Number(nested?.deleted))
              ? Number(nested.deleted)
              : total;
        const failed = Number.isFinite(Number(nested?.failed))
          ? Number(nested.failed)
          : Math.max(0, total - success);
        syncGlobalTrackedProcessProgress(entry.id, {
          done: total,
          total,
          success: Math.max(0, success),
          failed: Math.max(0, failed),
        });
        finishGlobalTrackedProcess(entry.id, {
          summaryMessage: "Job assíncrono concluído.",
          hasWarning: Math.max(0, failed) > 0,
        });
      } else if (state === "failed") {
        const total = Math.max(0, Number(entry.total || 0));
        syncGlobalTrackedProcessProgress(entry.id, {
          done: total,
          total,
          success: 0,
          failed: total || 1,
        });
        finishGlobalTrackedProcess(entry.id, {
          summaryMessage: String(status?.failedReason || "Job assíncrono falhou."),
          hasError: true,
        });
      }
    } catch (error) {
      const message = String(error?.message || "");
      const missingJob = message.includes("Job não encontrado") || message.includes("job_not_found") || message.includes("404");
      const waitingSince = entry?.queueWaitingSince
        ? new Date(entry.queueWaitingSince).getTime()
        : 0;
      const waitingAgeMs = waitingSince > 0 ? Date.now() - waitingSince : 0;
      if (missingJob && waitingAgeMs >= staleWaitingCutoffMs) {
        const total = Math.max(0, Number(entry.total || 0));
        syncGlobalTrackedProcessProgress(entry.id, {
          done: total,
          total,
          success: 0,
          failed: total || 1,
        });
        appendGlobalTrackedProcessLog(
          entry.id,
          "Processo encerrado automaticamente: job não existe mais na fila.",
          "warning",
        );
        finishGlobalTrackedProcess(entry.id, {
          summaryMessage:
            "Processo antigo removido/expirado na fila. Reexecute se ainda precisar aplicar a ação.",
          hasWarning: true,
        });
      }
    }
  }
  saveGlobalProcessDockState();
  renderGlobalProcessDock();
}

function beginGlobalTrackedProcess(source, title, total = 0) {
  const entry = normalizeGlobalProcessEntry({
    id: createNotificationId(),
    source: String(source || "processo"),
    title: String(title || "Processo"),
    startedAt: new Date().toISOString(),
    finishedAt: "",
    status: "running",
    total: Number(total || 0),
    done: 0,
    success: 0,
    failed: 0,
    finished: false,
    notified: false,
    updatedAt: new Date().toISOString(),
    logs: [],
  });
  GLOBAL_PROCESS_DOCK_STATE.processes = [
    entry,
    ...(GLOBAL_PROCESS_DOCK_STATE.processes || []),
  ].slice(0, GLOBAL_PROCESS_DOCK_MAX_PROCESSES);
  saveGlobalProcessDockState();
  renderGlobalProcessDock();
  return entry.id;
}

function appendGlobalTrackedProcessLog(processId, message, tone = "info") {
  const entry = getGlobalTrackedProcess(processId);
  if (!entry) return;
  const line = String(message || "").trim();
  if (!line) return;
  entry.logs = [...(Array.isArray(entry.logs) ? entry.logs : []), line].slice(
    -GLOBAL_PROCESS_DOCK_MAX_LOGS,
  );
  if (tone === "error" && !entry.finished) {
    entry.status = "running";
  }
  entry.updatedAt = new Date().toISOString();
  saveGlobalProcessDockState();
  renderGlobalProcessDock();
}

function syncGlobalTrackedProcessProgress(
  processId,
  { done = 0, total = 0, success = 0, failed = 0 } = {},
) {
  const entry = getGlobalTrackedProcess(processId);
  if (!entry) return;
  entry.total = Math.max(0, Number(total || 0));
  entry.done = Math.max(0, Number(done || 0));
  entry.success = Math.max(0, Number(success || 0));
  entry.failed = Math.max(0, Number(failed || 0));
  entry.updatedAt = new Date().toISOString();
  saveGlobalProcessDockState();
  renderGlobalProcessDock();
}

function finishGlobalTrackedProcess(
  processId,
  { summaryMessage = "", hasWarning = false, hasError = false } = {},
) {
  const entry = getGlobalTrackedProcess(processId);
  if (!entry) return;
  entry.finished = true;
  entry.finishedAt = new Date().toISOString();
  entry.updatedAt = entry.finishedAt;
  if (hasError) entry.status = "error";
  else if (hasWarning) entry.status = "warning";
  else entry.status = "success";
  if (summaryMessage) {
    entry.logs = [...(Array.isArray(entry.logs) ? entry.logs : []), summaryMessage].slice(
      -GLOBAL_PROCESS_DOCK_MAX_LOGS,
    );
  }
  entry.notified = true;

  saveGlobalProcessDockState();
  renderGlobalProcessDock();
  void pollProcessNotificationsFromBackend({ silent: true });
}

function initGlobalProcessDock() {
  loadGlobalProcessDockState();
  renderGlobalProcessDock();
  void reconcileGlobalProcessDockJobs();
  setInterval(() => {
    void reconcileGlobalProcessDockJobs();
  }, 60000);
  window.shopeeProcessDock = {
    start: (source, title, total) => beginGlobalTrackedProcess(source, title, total),
    log: (processId, message, tone) =>
      appendGlobalTrackedProcessLog(processId, message, tone),
    progress: (processId, payload = {}) =>
      syncGlobalTrackedProcessProgress(processId, payload),
    finish: (processId, payload = {}) => finishGlobalTrackedProcess(processId, payload),
    collapse: () => setGlobalProcessDockCollapsed(true),
    expand: () => setGlobalProcessDockCollapsed(false),
    getState: () => JSON.parse(JSON.stringify(GLOBAL_PROCESS_DOCK_STATE || {})),
  };
}

function getActiveShopFromMe() {
  const shops = Array.isArray(ME?.shops) ? ME.shops : [];
  const activeShopId = ME?.activeShopId ?? null;
  return (
    shops.find((shop) => Number(shop?.id) === Number(activeShopId)) ||
    shops[0] ||
    null
  );
}

function getControlPanelCacheKey() {
  const shop = getActiveShopFromMe();
  const shopDbId = String(shop?.id ?? ME?.activeShopId ?? ACTIVE_SHOP_ID ?? "").trim();
  if (!shopDbId) return "";
  return `${CONTROL_PANEL_CACHE_STORAGE_PREFIX}:${shopDbId}`;
}

function readControlPanelCache({ ignoreTtl = false } = {}) {
  const cacheKey = getControlPanelCacheKey();
  if (!cacheKey) return null;

  try {
    const raw = localStorage.getItem(cacheKey);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const savedAt = Number(parsed?.savedAt || 0);
    const data = parsed?.data || null;
    if (!savedAt || !data) return null;
    const ageMs = Date.now() - savedAt;
    const isFresh = ageMs >= 0 && ageMs <= CONTROL_PANEL_CACHE_TTL_MS;
    if (!isFresh && !ignoreTtl) return null;
    return { data, savedAt, ageMs, isFresh };
  } catch (_error) {
    return null;
  }
}

function writeControlPanelCache(data) {
  const cacheKey = getControlPanelCacheKey();
  if (!cacheKey || !data) return;

  try {
    localStorage.setItem(
      cacheKey,
      JSON.stringify({
        savedAt: Date.now(),
        data,
      }),
    );
  } catch (_error) {}
}

function clearControlPanelCache() {
  const cacheKey = getControlPanelCacheKey();
  if (!cacheKey) return;
  try {
    localStorage.removeItem(cacheKey);
  } catch (_error) {}
}

function requestControlPanelData({ force = false } = {}) {
  if (!force && CONTROL_PANEL_FETCH_PROMISE) return CONTROL_PANEL_FETCH_PROMISE;
  const query = force ? "?force=1" : "";
  const promise = apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/dashboard/control-panel${query}`);
  if (!force) {
    CONTROL_PANEL_FETCH_PROMISE = promise.finally(() => {
      CONTROL_PANEL_FETCH_PROMISE = null;
    });
    return CONTROL_PANEL_FETCH_PROMISE;
  }
  return promise;
}

function formatSupportShopLabel(shop) {
  if (!shop) return "Nenhuma loja ativa";

  const parts = [];
  if (shop.shopId != null) parts.push(`Shop ${shop.shopId}`);
  if (shop.name) parts.push(String(shop.name));
  if (shop.region) parts.push(String(shop.region));
  if (!parts.length && shop.id != null) parts.push(`Loja ${shop.id}`);

  return parts.join(" • ");
}

function setSupportFormStatus(text, type = "info") {
  const el = document.getElementById("supportFormStatus");
  if (!el) return;

  el.textContent = String(text || "");
  el.classList.remove("ui-state", "ui-state--loading", "ui-state--empty", "ui-state--error");

  if (type === "loading") {
    el.classList.add("ui-state", "ui-state--loading");
  }

  if (type === "error") {
    el.classList.add("ui-state", "ui-state--error");
  }
}

function syncSupportReplyChoice() {
  const choices = document.querySelectorAll("#supportReplyChoice .support-choice");
  choices.forEach((choice) => {
    const input = choice.querySelector("input");
    choice.classList.toggle("is-selected", Boolean(input?.checked));
  });
}

function setSupportView(view = "contact") {
  const normalized = view === "manual" ? "manual" : "contact";

  const options = document.querySelectorAll("[data-support-view]");
  options.forEach((option) => {
    option.classList.toggle(
      "is-active",
      String(option.dataset.supportView || "") === normalized,
    );
  });

  const views = document.querySelectorAll(".support-view");
  views.forEach((panel) => panel.classList.remove("is-active"));

  const activePanel = document.getElementById(`support-view-${normalized}`);
  activePanel?.classList.add("is-active");
}

function renderSupportContext() {
  const accountName = ME?.account?.name ? String(ME.account.name) : "—";
  const email = ME?.user?.email ? String(ME.user.email) : "—";
  const userName =
    ME?.user?.name || ME?.user?.fullName || ME?.account?.name || "—";
  const activeShop = getActiveShopFromMe();
  const shopLabel = formatSupportShopLabel(activeShop);

  setText("supportContextEmail", email);
  setText("supportContextName", String(userName));
  setText("supportContextAccount", accountName);
  setText("supportContextShop", shopLabel);
  setText("supportAccountBadge", activeShop?.shopId ? `Conta: ${activeShop.shopId}` : accountName);
}

async function submitSupportRequest() {
  if (!ME) {
    await loadMe();
  }

  const subject = String(document.getElementById("supportSubject")?.value || "Duvidas");
  const replyMode =
    document.querySelector('input[name="supportReplyMode"]:checked')?.value ||
    "email";
  const phone = String(document.getElementById("supportPhone")?.value || "").trim();
  const message = String(document.getElementById("supportMessage")?.value || "").trim();

  if (!message) {
    setSupportFormStatus("Descreva sua mensagem antes de abrir o suporte.", "error");
    return;
  }

  if (replyMode === "phone" && !phone) {
    setSupportFormStatus("Preencha um celular para retorno quando escolher resposta por celular.", "error");
    return;
  }

  const accountName = ME?.account?.name ? String(ME.account.name) : "Conta sem nome";
  const activeShop = getActiveShopFromMe();
  const shopLabel = formatSupportShopLabel(activeShop);
  const btn = document.getElementById("btnSupportSend");
  const meta = document.getElementById("supportFormMeta");

  if (btn) {
    btn.disabled = true;
    btn.textContent = "Enviando...";
  }
  if (meta) {
    meta.textContent =
      "Sua mensagem está sendo enviada automaticamente ao suporte via Brevo.";
  }

  setSupportFormStatus("Enviando solicitação ao suporte...", "loading");

  try {
    await apiPost("/support/request", {
      subject,
      replyMode,
      phone,
      message,
    });

    setSupportFormStatus(
      `Solicitação enviada com sucesso. Nossa equipe vai analisar o contexto da conta ${accountName}${shopLabel ? ` (${shopLabel})` : ""}.`,
    );

    const messageEl = document.getElementById("supportMessage");
    const phoneEl = document.getElementById("supportPhone");
    if (messageEl) messageEl.value = "";
    if (replyMode === "phone" && phoneEl) phoneEl.value = "";
  } catch (e) {
    let errorMessage = String(e?.message || e);
    try {
      const parsed = JSON.parse(errorMessage);
      errorMessage =
        parsed?.message || parsed?.error?.message || parsed?.error || errorMessage;
    } catch (_) {}

    setSupportFormStatus(
      `Não foi possível enviar a solicitação automaticamente. ${errorMessage}`,
      "error",
    );
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = "Enviar mensagem";
    }
    if (meta) {
      meta.textContent =
        "A mensagem será enviada automaticamente com o contexto da conta já preenchido.";
    }
  }
}

async function openSupportTab(view = "contact") {
  await showTab("support");
  setSupportView(view);
}

function animateTabPanel(panel) {
  if (!panel) return;
  panel.classList.remove("is-entering");
  void panel.offsetWidth;
  panel.classList.add("is-entering");
  setTimeout(() => panel.classList.remove("is-entering"), 320);
}

function setText(id, text) {
  const el = document.getElementById(id);
  if (el) {
    el.textContent = String(text ?? "");
    el.classList.remove("ui-state", "ui-state--loading", "ui-state--empty", "ui-state--error");
  }
}

const SEO_REF_KEY = "seo_ref_product";

function getSeoRefProduct() {
  try {
    const raw = localStorage.getItem(SEO_REF_KEY);
    if (!raw) return null;
    const obj = JSON.parse(raw);
    if (!obj?.itemId) return null;
    return obj;
  } catch {
    return null;
  }
}

function setSeoRefProduct(p) {
  if (!p) {
    localStorage.removeItem(SEO_REF_KEY);
    return;
  }
  localStorage.setItem(
    SEO_REF_KEY,
    JSON.stringify({
      itemId: String(p.itemId),
      title: p.title || null,
      imageUrl: p.imageUrl || null,
    }),
  );
}

function initProductsSort() {
  if (PRODUCTS_SORT_BOUND) return;
  PRODUCTS_SORT_BOUND = true;

  const sel = document.getElementById("products-sort");
  if (!sel) return;

  // valor inicial (respeita estado atual)
  sel.value = `${PRODUCTS_SORT_BY}:${PRODUCTS_SORT_DIR}`;

  sel.addEventListener("change", async () => {
    const [by, dir] = String(sel.value || "updatedAt:desc").split(":");
    PRODUCTS_SORT_BY = by || "updatedAt";
    PRODUCTS_SORT_DIR = dir === "asc" ? "asc" : "desc";
    PRODUCTS_PAGE = 1;
    await loadProducts();
  });
}

function normalizeApiPath(path) {
  let normalized = String(path || "").trim();
  if (!normalized) return "/shopee";
  if (/^https?:\/\//i.test(normalized)) return normalized;
  if (!normalized.startsWith("/")) normalized = `/${normalized}`;
  if (!normalized.startsWith("/shopee")) normalized = `/shopee${normalized}`;
  return normalized;
}

async function apiGet(path) {
  path = normalizeApiPath(path);
  const r = await fetch(path, { credentials: "include" });
  const text = await r.text();
  if (!r.ok) throw new Error(text || `HTTP ${r.status}`);
  return text ? JSON.parse(text) : null;
}

async function apiPost(path, body) {
  path = normalizeApiPath(path);
  const r = await fetch(path, {
    method: "POST",
    credentials: "include",
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await r.text();
  if (!r.ok) throw new Error(text || `HTTP ${r.status}`);
  return text ? JSON.parse(text) : null;
}

async function apiPut(path, body) {
  path = normalizeApiPath(path);
  const r = await fetch(path, {
    method: "PUT",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body || {}),
  });
  const text = await r.text();
  if (!r.ok) throw new Error(text || `HTTP ${r.status}`);
  return text ? JSON.parse(text) : null;
}

function markUserActivity() {
  if (INACTIVITY_LOGOUT_IN_PROGRESS) return;
  const inactiveMs = Date.now() - Number(LAST_USER_ACTIVITY_AT || 0);
  if (inactiveMs >= INACTIVITY_LOGOUT_MS && !hasActiveProcessInProgress()) {
    logoutByInactivity();
    return;
  }
  LAST_USER_ACTIVITY_AT = Date.now();
}

function hasActiveProcessInProgress() {
  const dockHasRunningProcess = (GLOBAL_PROCESS_DOCK_STATE?.processes || []).some(
    (entry) => entry && !entry.finished,
  );

  return Boolean(
    PRODUCTS_SYNC_IN_PROGRESS ||
      ORDERS_SYNC_IN_PROGRESS ||
      CONTROL_PANEL_SYNC_IN_PROGRESS ||
      dockHasRunningProcess,
  );
}

async function logoutByInactivity() {
  if (INACTIVITY_LOGOUT_IN_PROGRESS) return;
  if (hasActiveProcessInProgress()) return;

  INACTIVITY_LOGOUT_IN_PROGRESS = true;
  const message = "Voce foi deslogado por inatividade.";

  if (typeof window.shopeeNotify === "function") {
    window.shopeeNotify({
      title: "Sessao encerrada",
      message,
      type: "warning",
    });
  } else {
    window.alert(message);
  }

  try {
    await apiPost("/auth/logout");
  } catch (_error) {}

  window.setTimeout(() => {
    window.location.href = "/selecao-plataforma?reason=inactive";
  }, 1200);
}

function checkInactivityLogout() {
  if (INACTIVITY_LOGOUT_IN_PROGRESS) return;
  if (hasActiveProcessInProgress()) return;

  const inactiveMs = Date.now() - Number(LAST_USER_ACTIVITY_AT || 0);
  if (inactiveMs >= INACTIVITY_LOGOUT_MS) {
    logoutByInactivity();
  }
}

function initInactivityLogout() {
  if (INACTIVITY_LOGOUT_BOUND) return;
  INACTIVITY_LOGOUT_BOUND = true;
  LAST_USER_ACTIVITY_AT = Date.now();

  ["click", "keydown", "mousemove", "scroll", "touchstart", "pointerdown"].forEach(
    (eventName) => {
      window.addEventListener(eventName, markUserActivity, {
        passive: true,
        capture: true,
      });
    },
  );
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) return;
    checkInactivityLogout();
    if (!INACTIVITY_LOGOUT_IN_PROGRESS) markUserActivity();
  });

  INACTIVITY_LOGOUT_HANDLE = window.setInterval(checkInactivityLogout, 60 * 1000);
}

function auditTabAccess(tab) {
  // Trocar de tela é navegação, não um processo solicitado pelo usuário.
  // Mantemos o histórico de trabalho para ações que de fato alteram a operação.
  LAST_TAB_ACCESS_AUDIT = { tab: String(tab || "").trim(), at: Date.now() };
}

function initSeoGoogleCompare() {
  document
    .getElementById("btnSeoCmp")
    ?.addEventListener("click", runSeoCompare);
  document.getElementById("seoCmpTerms")?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") runSeoCompare();
  });
}

async function runSeoCompare() {
  const termsRaw = String(
    document.getElementById("seoCmpTerms")?.value || "",
  ).trim();
  const period = String(document.getElementById("seoPeriod")?.value || "30d"); // reaproveita período do Google
  const msg = document.getElementById("seoCmpMsg");

  if (!termsRaw) {
    if (msg) msg.textContent = "Digite 2 a 4 palavras separadas por vírgula.";
    return;
  }

  if (msg) msg.textContent = "Carregando comparação…";

  try {
    const data = await apiGet(
      `/seo/compare?terms=${encodeURIComponent(termsRaw)}&period=${encodeURIComponent(period)}`,
    );
    if (data?.trends?.ok === false) {
      if (msg)
        msg.textContent =
          data?.message || "Google Trends indisponível no momento.";
      if (SEO_GOOGLE_CMP_CHART) {
        SEO_GOOGLE_CMP_CHART.destroy();
        SEO_GOOGLE_CMP_CHART = null;
      }
      if (SEO_GOOGLE_CMP_BARS) {
        SEO_GOOGLE_CMP_BARS.destroy();
        SEO_GOOGLE_CMP_BARS = null;
      }
      const b = document.getElementById("seoCmpWinner");
      if (b) {
        b.className = "badge badge--gray";
        b.textContent = "Indisponível";
      }
      return;
    }
    const terms = data?.terms || [];
    const series = data?.series || [];
    if (!terms.length || !series.length) {
      if (msg) msg.textContent = "Sem dados para comparar.";
      if (SEO_GOOGLE_CMP_CHART) {
        SEO_GOOGLE_CMP_CHART.destroy();
        SEO_GOOGLE_CMP_CHART = null;
      }
      if (SEO_GOOGLE_CMP_BARS) {
        SEO_GOOGLE_CMP_BARS.destroy();
        SEO_GOOGLE_CMP_BARS = null;
      }
      const b = document.getElementById("seoCmpWinner");
      if (b) {
        b.className = "badge badge--gray";
        b.textContent = "—";
      }
      return;
    }

    // labels = datas (usa a 1ª série como referência)
    const points0 = series[0]?.points || [];
    const labels = points0.map((p) => {
      const d = new Date(Number(p.time || 0));
      return d.toLocaleDateString("pt-BR", {
        day: "2-digit",
        month: "2-digit",
      });
    });

    const palette = ["#60a5fa", "#f97316", "#34d399", "#f472b6"];

    const datasets = series.map((s, i) => ({
      label: s.term,
      data: (s.points || []).map((p) => Number(p.value || 0)),
      borderColor: palette[i % palette.length],
      backgroundColor: palette[i % palette.length] + "33",
      tension: 0.25,
      pointRadius: 0,
      borderWidth: 2,
      fill: false,
    }));

    // mensagem-resumo: quem tem maior média (mais “relevante” no período)
    const summary = data?.summary || {};

    // pesos do score (ajuste aqui)
    const W_AVG = 0.7;
    const W_MAX = 0.3;

    const scored = terms
      .map((t) => {
        const avg = Number(summary?.[t]?.avg ?? 0);
        const max = Number(summary?.[t]?.max ?? 0);
        const score = Math.round((W_AVG * avg + W_MAX * max) * 10) / 10; // 0–100
        return { term: t, avg, max, score };
      })
      .sort((a, b) => b.score - a.score);

    const winner = scored[0] || null;

    // Mensagem-resumo
    if (msg) {
      msg.textContent = winner
        ? `Melhor score no período: "${winner.term}" (score ${winner.score} = ${W_AVG}×avg + ${W_MAX}×max).`
        : "Sem dados para comparar.";
    }

    // Badge do vencedor
    const winnerEl = document.getElementById("seoCmpWinner");
    if (winnerEl) {
      winnerEl.className = "badge badge--top";
      winnerEl.textContent = winner
        ? `Top: ${winner.term} (${winner.score})`
        : "—";
    }
    // --- gráfico 2: barras avg e max ---
    const labels2 = terms.map((t) => wrapChartLabel(t, 16));
    const avgData = terms.map((t) => Number(summary?.[t]?.avg ?? 0));
    const maxData = terms.map((t) => Number(summary?.[t]?.max ?? 0));
    const chartTheme = getUiChartThemeColors();
    const isLight = document.body.classList.contains("theme-light");

    const ctx2 = document.getElementById("seoCmpBars")?.getContext("2d");
    if (ctx2) {
      if (SEO_GOOGLE_CMP_BARS) SEO_GOOGLE_CMP_BARS.destroy();

      SEO_GOOGLE_CMP_BARS = new Chart(ctx2, {
        type: "bar",
        data: {
          labels: labels2,
          datasets: [
            {
              label: "Média (avg)",
              data: avgData,
              backgroundColor: isLight
                ? "rgba(59,130,246,0.30)"
                : "rgba(96,165,250,0.22)",
              borderColor: isLight
                ? "rgba(59,130,246,0.52)"
                : "rgba(96,165,250,0.45)",
              borderWidth: 1,
              borderRadius: 8,
            },
            {
              label: "Pico (max)",
              data: maxData,
              backgroundColor: isLight
                ? "rgba(249,115,22,0.30)"
                : "rgba(249,115,22,0.22)",
              borderColor: isLight
                ? "rgba(249,115,22,0.52)"
                : "rgba(249,115,22,0.45)",
              borderWidth: 1,
              borderRadius: 8,
            },
          ],
        },
        options: {
          responsive: true,
          plugins: {
            legend: { labels: { color: chartTheme.legend } },
            tooltip: {
              backgroundColor: chartTheme.tooltipBg,
              borderColor: chartTheme.tooltipBorder,
              borderWidth: 1,
              titleColor: chartTheme.tooltipTitle,
              bodyColor: chartTheme.tooltipBody,
              callbacks: {
                label: (ctx) =>
                  `${ctx.dataset.label}: ${Number(ctx.raw || 0).toFixed(1)}`,
              },
            },
          },
          scales: {
            x: {
              ticks: { color: chartTheme.axis, maxRotation: 0 },
              grid: { display: false },
            },
            y: {
              ticks: { color: chartTheme.axis },
              grid: { color: chartTheme.grid },
              suggestedMin: 0,
              suggestedMax: 100,
            },
          },
        },
      });
    }
    const ctx = document.getElementById("seoCmpChart")?.getContext("2d");
    if (!ctx) return;

    if (SEO_GOOGLE_CMP_CHART) SEO_GOOGLE_CMP_CHART.destroy();
    SEO_GOOGLE_CMP_CHART = new Chart(ctx, {
      type: "line",
      data: { labels, datasets },
      options: {
        responsive: true,
        plugins: {
          legend: { labels: { color: chartTheme.legend } },
          tooltip: {
            backgroundColor: chartTheme.tooltipBg,
            borderColor: chartTheme.tooltipBorder,
            borderWidth: 1,
            titleColor: chartTheme.tooltipTitle,
            bodyColor: chartTheme.tooltipBody,
          },
        },
        scales: {
          x: {
            ticks: { color: chartTheme.axis, maxRotation: 0 },
            grid: { display: false },
          },
          y: {
            ticks: { color: chartTheme.axis },
            grid: { color: chartTheme.grid },
            suggestedMin: 0,
            suggestedMax: 100,
          },
        },
      },
    });
  } catch (e) {
    if (msg) msg.textContent = `Erro: ${String(e?.message || e)}`;
  }
}

const GIFT_CAMPAIGN_STATE = { mainKeys: new Set(), giftKeys: new Set(), mainRows: [], giftRows: [], mainSelected: new Map(), giftSelected: new Map(), campaignId: null, preview: null, logistics: null, logisticsResolution: null, initialized: false };
function giftCampaignMoney(cents) { return Number(cents || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }
function giftCampaignNumber(value) { const normalized = String(value || "").trim().replace(/\./g, "").replace(",", "."); const parsed = Number(normalized); return Number.isFinite(parsed) ? parsed : 0; }
function giftCampaignItems(kind) { const selected = kind === "main" ? GIFT_CAMPAIGN_STATE.mainSelected : GIFT_CAMPAIGN_STATE.giftSelected; return [...selected.values()].map((row) => ({ key: row.key, productId: row.productId, itemId: row.itemId, modelId: row.modelId, title: row.title, sku: row.sku, costCents: Math.round(Number(row.costCents || 0)), priceCents: Math.round(Number(row.currentPriceCents || 0)), quantity: 1 })); }
function giftCampaignPayload() { const value = (id) => String(document.getElementById(id)?.value || "").trim(); const margin = value("giftCampaignMargin"); return { name: value("giftCampaignName"), startAt: value("giftCampaignStart"), endAt: value("giftCampaignEnd"), minSpendCents: Math.max(0, Math.round(giftCampaignNumber(value("giftCampaignMinSpend")) * 100)), targetMarginRate: margin ? giftCampaignNumber(margin) / 100 : null, useMaxDuration: false, conflictPolicy: "skip", mainItems: giftCampaignItems("main"), giftItems: giftCampaignItems("gift") }; }
function renderGiftCampaignRows(kind) {
  const isMain = kind === "main"; const root = document.getElementById(isMain ? "giftMainResults" : "giftItemResults"); const rows = isMain ? GIFT_CAMPAIGN_STATE.mainRows : GIFT_CAMPAIGN_STATE.giftRows; const selected = isMain ? GIFT_CAMPAIGN_STATE.mainSelected : GIFT_CAMPAIGN_STATE.giftSelected;
  if (!root) return;
  root.innerHTML = rows.length ? rows.map((row) => '<label class="gift-campaign-row"><input type="checkbox" data-gift-key="' + pricingV6Esc(row.key) + '" ' + (selected.has(row.key) ? "checked" : "") + '/><span class="gift-campaign-row__main"><strong>' + pricingV6Esc(row.title) + '</strong><span>' + pricingV6Esc(row.itemId) + (row.modelId ? " / " + pricingV6Esc(row.modelId) : "") + (row.sku ? " | " + pricingV6Esc(row.sku) : "") + '</span></span><em>' + (row.costCents > 0 ? "CMV " + giftCampaignMoney(row.costCents) : "Sem CMV") + '</em></label>').join("") : '<span class="muted">Nenhum produto ativo encontrado.</span>';
  root.querySelectorAll("[data-gift-key]").forEach((input) => input.addEventListener("change", () => { const key = input.getAttribute("data-gift-key"); const row = rows.find((candidate) => candidate.key === key); if (input.checked && row) selected.set(key, row); else selected.delete(key); GIFT_CAMPAIGN_STATE.preview = null; GIFT_CAMPAIGN_STATE.campaignId = null; document.getElementById("btnGiftPublish").disabled = true; }));
}
async function searchGiftCampaignProducts(kind) { const isMain = kind === "main"; const input = document.getElementById(isMain ? "giftMainSearch" : "giftItemSearch"); const root = document.getElementById(isMain ? "giftMainResults" : "giftItemResults"); if (root) root.innerHTML = '<span class="muted">Buscando produtos ativos...</span>'; const result = await apiGet("/shops/active/pricing/products?page=1&pageSize=100&q=" + encodeURIComponent(String(input?.value || "").trim())); if (isMain) GIFT_CAMPAIGN_STATE.mainRows = Array.isArray(result?.items) ? result.items : []; else GIFT_CAMPAIGN_STATE.giftRows = Array.isArray(result?.items) ? result.items : []; renderGiftCampaignRows(kind); }
function renderGiftCampaignPreview(preview, logistics) { const root = document.getElementById("giftCampaignPreview"); const status = document.getElementById("giftCampaignStatus"); const publish = document.getElementById("btnGiftPublish"); if (!root) return; const lines = Array.isArray(preview?.lines) ? preview.lines : []; const options = Array.isArray(logistics?.options) ? logistics.options : []; const selected = options.find((option) => option.id === GIFT_CAMPAIGN_STATE.logisticsResolution); const rows = lines.map((row) => '<tr><td>' + pricingV6Esc(row.key) + '</td><td>' + giftCampaignMoney(row.costCents) + '</td><td>' + giftCampaignMoney(row.costWithGiftCents) + '</td><td><strong>' + giftCampaignMoney(row.suggestedPriceCents) + '</strong></td><td>' + (row.marginRate == null ? "-" : pricingV6Percent(row.marginRate)) + '</td></tr>').join(""); const logisticText = selected ? selected.label : "Nenhuma alternativa logística viável"; root.innerHTML = '<div class="gift-campaign-summary"><strong>Maior CMV de brinde: ' + giftCampaignMoney(preview?.giftProvisionCents) + '</strong><span>Logística: ' + pricingV6Esc(logisticText) + '</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Principal</th><th>CMV principal</th><th>CMV com brinde</th><th>Preço recomendado</th><th>Margem</th></tr></thead><tbody>' + rows + '</tbody></table></div>' + (options.length ? '<div class="gift-campaign-warn">' + options.map((option) => (option.feasible ? "" : pricingV6Esc(option.label + ": " + (option.reason || "não disponível")))).filter(Boolean).join("<br>") + '</div>' : ""); const ready = Boolean(GIFT_CAMPAIGN_STATE.campaignId && selected && selected.feasible && lines.length); if (status) status.textContent = ready ? "Prévia salva e logística validada. A publicação será processada em fila." : "A prévia exige uma alternativa logística viável."; if (publish) publish.disabled = !ready; }
async function previewGiftCampaign() { const status = document.getElementById("giftCampaignStatus"); if (status) status.textContent = "Criando rascunho e validando campanha..."; const payload = giftCampaignPayload(); const draft = await apiPost("/shops/active/gift-campaigns/drafts", payload); GIFT_CAMPAIGN_STATE.campaignId = draft?.id; if (!GIFT_CAMPAIGN_STATE.campaignId) throw new Error("A campanha não retornou identificador."); const preview = await apiPost("/shops/active/gift-campaigns/" + encodeURIComponent(GIFT_CAMPAIGN_STATE.campaignId) + "/preview", {}); const suggestedSpend = Math.min(...(preview?.lines || []).map((line) => Number(line?.suggestedPriceCents || 0)).filter((price) => price > 0)); if (payload.minSpendCents <= 0 && Number.isFinite(suggestedSpend)) { document.getElementById("giftCampaignMinSpend").value = (suggestedSpend / 100).toFixed(2).replace(".", ","); await apiPut("/shops/active/gift-campaigns/" + encodeURIComponent(GIFT_CAMPAIGN_STATE.campaignId) + "/drafts", { ...giftCampaignPayload() }); } const logistics = await apiGet("/shops/active/gift-campaigns/" + encodeURIComponent(GIFT_CAMPAIGN_STATE.campaignId) + "/logistics-options"); GIFT_CAMPAIGN_STATE.preview = preview; GIFT_CAMPAIGN_STATE.logistics = logistics; GIFT_CAMPAIGN_STATE.logisticsResolution = (logistics?.options || []).find((option) => option.id !== "edit_selection" && option.feasible)?.id || null; renderGiftCampaignPreview(preview, logistics); }
async function monitorGiftCampaign(campaignId) { const status = document.getElementById("giftCampaignStatus"); for (let attempt = 0; attempt < 60; attempt += 1) { await new Promise((resolve) => window.setTimeout(resolve, 2500)); const campaign = await apiGet("/shops/active/gift-campaigns/" + encodeURIComponent(campaignId)); const last = Array.isArray(campaign?.actions) ? campaign.actions[campaign.actions.length - 1] : null; const message = last?.payload?.message ? " " + last.payload.message : ""; if (status) status.textContent = "Campanha: " + String(campaign?.status || "em processamento") + "." + message; if (["published", "failed", "partial_failed", "cancelled"].includes(String(campaign?.status))) return campaign; } return null; }
async function publishGiftCampaign() { if (!GIFT_CAMPAIGN_STATE.campaignId || !GIFT_CAMPAIGN_STATE.preview) return; const choice = await openPricingV6DecisionModal({ title: "Confirmar campanha de brindes", message: "Os preços recomendados e a logística serão revalidados na Shopee. A publicação será enviada para a fila com registro de cada etapa.", actions: [{ value: "cancel", label: "Cancelar", className: "btn btn-ghost" }, { value: "confirm", label: "Confirmar e enfileirar", className: "btn btn-primary" }] }); if (choice !== "confirm") return; const button = document.getElementById("btnGiftPublish"); button.disabled = true; button.textContent = "Enfileirando..."; try { const id = encodeURIComponent(GIFT_CAMPAIGN_STATE.campaignId); await apiPost("/shops/active/gift-campaigns/" + id + "/confirm", { logisticsResolution: GIFT_CAMPAIGN_STATE.logisticsResolution, approvedPriceKeys: (GIFT_CAMPAIGN_STATE.preview.lines || []).map((line) => line.key), conflictPolicy: "skip" }); const queued = await apiPost("/shops/active/gift-campaigns/" + id + "/publish", {}); document.getElementById("giftCampaignStatus").textContent = "Campanha enviada para a fila da Shopee: " + (queued?.id || GIFT_CAMPAIGN_STATE.campaignId) + "."; void monitorGiftCampaign(GIFT_CAMPAIGN_STATE.campaignId).catch((error) => { const status = document.getElementById("giftCampaignStatus"); if (status) status.textContent = "Não foi possível atualizar o status: " + String(error?.message || error); }); } finally { button.textContent = "Publicar na Shopee"; button.disabled = false; } }
function initGiftCampaign() { if (GIFT_CAMPAIGN_STATE.initialized) return; GIFT_CAMPAIGN_STATE.initialized = true; const format = (date) => { date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); }; const start = new Date(Date.now() + 65 * 60 * 1000); const end = new Date(start.getTime() + 30 * 24 * 60 * 60 * 1000); document.getElementById("giftCampaignStart").value = format(start); document.getElementById("giftCampaignEnd").value = format(end); document.getElementById("btnGiftSearchMain")?.addEventListener("click", () => searchGiftCampaignProducts("main").catch((error) => { document.getElementById("giftMainResults").textContent = String(error?.message || error); })); document.getElementById("btnGiftSearchItems")?.addEventListener("click", () => searchGiftCampaignProducts("item").catch((error) => { document.getElementById("giftItemResults").textContent = String(error?.message || error); })); document.getElementById("btnGiftPreview")?.addEventListener("click", () => previewGiftCampaign().catch((error) => { document.getElementById("giftCampaignStatus").textContent = String(error?.message || error); })); document.getElementById("btnGiftPublish")?.addEventListener("click", () => publishGiftCampaign().catch((error) => { document.getElementById("giftCampaignStatus").textContent = String(error?.message || error); })); }/* ---------------- Tabs ---------------- */
const SIDEBAR_CATEGORY_STATE_KEY = "sidebar_category_state_v4";
const SIDEBAR_COLLAPSED_KEY = "sidebar_collapsed_v1";

function sidebarCategoryIcon(type) {
  const iconByCategory = {
    overview: "i-grid",
    ads: "i-megaphone",
    promotions: "i-tag",
    analytics: "i-chart",
    operations: "i-box",
    advanced: "i-sliders",
    account: "i-shield-user",
    support: "i-help-circle",
  };
  return iconByCategory[type] || "i-grid";
}

function sidebarTabIconSymbol(tab) {
  const map = {
    "control-panel": "i-grid",
    dashboard: "i-trend",
    "stock-alert": "i-alert",
    "price-increase": "i-tag",
    "shopee-notices": "i-alert",
    "latest-updates": "i-refresh",
    metrics: "i-chart",
    "catalog-quality": "i-shield-user",
    auth: "i-shield-user",
    admin: "i-sliders",
    support: "i-help-circle",
    products: "i-box",
    "listing-status": "i-sliders",
    "listing-clone": "i-copy",
    "gift-campaign": "i-tag",
    "curve-abc": "i-chart",
    relaunch: "i-refresh",
    launches: "i-rocket",
    "analytics-ai": "i-chart",
    "ads-ranking": "i-trophy",
    "sales-control": "i-sliders",
    "deadline-control": "i-calendar",
    "sales-share": "i-chart",
    orders: "i-receipt",
    ads: "i-megaphone",
    boost: "i-zap",
    margin: "i-percent",
    seo: "i-trend",
    costs: "i-percent",
    promotions: "i-tag",
    "flash-sale": "i-zap",
    logistics: "i-box",
    clips: "i-share",
    "bulk-specs": "i-sliders",
    "geo-sales": "i-share",
    "patch-notes": "i-receipt",
  };
  return map[String(tab || "").trim()] || "i-grid";
}

function renderSpriteIcon(symbolId, className = "") {
  const safeId = escapeHtml(String(symbolId || "i-grid"));
  const safeClass = escapeHtml(String(className || "").trim());
  const classAttr = safeClass ? ` class="${safeClass}"` : "";
  return `<svg${classAttr} viewBox="0 0 24 24" fill="none" stroke="currentColor"><use href="#${safeId}"></use></svg>`;
}

function alignSidebarNavIconsToSemanticMap() {
  const buttons = document.querySelectorAll(".ml-sidebar__section > .ml-nav-item");
  if (!buttons.length) return;

  buttons.forEach((button) => {
    const tab = String(button.dataset.tab || "").trim();
    if (!tab) return;

    const symbolId = sidebarTabIconSymbol(tab);
    const currentIcon = button.querySelector(".ml-nav-icon");
    const nextIconMarkup = renderSpriteIcon(symbolId, "ml-nav-icon");

    if (!currentIcon) {
      const content = button.querySelector(".ml-nav-item__content");
      if (content) {
        content.insertAdjacentHTML("beforebegin", nextIconMarkup);
      } else {
        button.insertAdjacentHTML("afterbegin", nextIconMarkup);
      }
      return;
    }

    const currentUse = currentIcon.querySelector("use");
    const currentHref = String(
      currentUse?.getAttribute("href") ||
        currentUse?.getAttribute("xlink:href") ||
        "",
    );
    const expectedHref = `#${symbolId}`;
    if (currentHref === expectedHref) return;

    currentIcon.outerHTML = nextIconMarkup;
  });
}

function readSidebarCategoryState() {
  try {
    return JSON.parse(localStorage.getItem(SIDEBAR_CATEGORY_STATE_KEY) || "{}");
  } catch {
    return {};
  }
}

function writeSidebarCategoryState(state) {
  localStorage.setItem(SIDEBAR_CATEGORY_STATE_KEY, JSON.stringify(state));
}

function readSidebarCollapsedState() {
  try {
    return localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === "1";
  } catch {
    return false;
  }
}

function ensureTopbarSidebarToggleButton() {
  let btn = document.getElementById("btn-sidebar-toggle-topbar");
  const topbar = document.querySelector(".ml-topbar");
  if (!topbar) return null;

  const rightCluster = topbar.querySelector(".ml-topbar__right");

  if (!btn) {
    btn = document.createElement("button");
    btn.type = "button";
    btn.id = "btn-sidebar-toggle-topbar";
    btn.className = "ml-sidebar__collapse ml-sidebar__collapse--topbar";
    btn.setAttribute("aria-label", "Expandir barra lateral");
    btn.setAttribute("title", "Expandir barra lateral");
    btn.innerHTML = `
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      stroke-width="1.8"
      stroke-linecap="round"
      stroke-linejoin="round"
    >
      <path d="M9 6l6 6-6 6"></path>
    </svg>
  `;
  }

  // Guarantee left placement even if the button already existed in the wrong container.
  if (rightCluster && rightCluster.parentNode === topbar) {
    topbar.insertBefore(btn, rightCluster);
  } else {
    topbar.prepend(btn);
  }
  return btn;
}

function applySidebarCollapsedState(collapsed) {
  const app = document.querySelector(".ml-app");
  const topbarButton = ensureTopbarSidebarToggleButton();
  const buttons = document.querySelectorAll(
    "#btn-sidebar-toggle-legacy, #btn-sidebar-toggle-topbar",
  );
  if (!app) return;

  const next = Boolean(collapsed);
  app.classList.toggle("is-sidebar-collapsed", next);
  document.body.classList.toggle("sidebar-collapsed", next);

  const wrappers = document.querySelectorAll(".sidebar-category");
  if (wrappers.length) {
    const activeTab =
      document.querySelector(".ml-sidebar .ml-nav-item.active")?.dataset.tab ||
      document.querySelector(".workspace-pill.active")?.dataset.tab ||
      "control-panel";

    wrappers.forEach((wrapper) => {
      if (next) {
        setSidebarCategoryOpen(wrapper, false, false);
        return;
      }

      const hasActive = [...wrapper.querySelectorAll(".ml-nav-item")].some(
        (button) => button.dataset.tab === activeTab,
      );
      const shouldOpen = hasActive;
      setSidebarCategoryOpen(wrapper, shouldOpen, false);
    });

    if (!next) {
      const activeWrapper = [...wrappers].find((wrapper) =>
        [...wrapper.querySelectorAll(".ml-nav-item")].some(
          (button) => button.dataset.tab === activeTab,
        ),
      );
      if (activeWrapper) {
        closeOtherSidebarCategories(activeWrapper);
        setSidebarCategoryOpen(activeWrapper, true, true);
      }
    }
  }

  buttons.forEach((btn) => {
    btn.setAttribute(
      "aria-label",
      next ? "Expandir barra lateral" : "Recolher barra lateral",
    );
    btn.setAttribute(
      "title",
      next ? "Expandir barra lateral" : "Recolher barra lateral",
    );
  });

  if (topbarButton) {
    topbarButton.style.display = next ? "inline-flex" : "none";
  }

  try {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, next ? "1" : "0");
  } catch {}
}

function initSidebarCollapse() {
  ensureTopbarSidebarToggleButton();
  const buttons = Array.from(
    document.querySelectorAll(
      "#btn-sidebar-toggle-legacy, #btn-sidebar-toggle-topbar",
    ),
  );
  if (!buttons.length) return;

  applySidebarCollapsedState(readSidebarCollapsedState());

  buttons.forEach((btn) => {
    if (btn.dataset.bound === "1") return;
    btn.dataset.bound = "1";

    btn.addEventListener("click", () => {
      const app = document.querySelector(".ml-app");
      const next = !app?.classList.contains("is-sidebar-collapsed");
      applySidebarCollapsedState(next);
    });
  });
}

