function setSidebarCategoryOpen(wrapper, open, save = true) {
  if (!wrapper) return;
  wrapper.classList.toggle("is-open", Boolean(open));
  const toggle = wrapper.querySelector(".sidebar-category__toggle");
  if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");

  if (!save) return;
  const state = readSidebarCategoryState();
  state[wrapper.dataset.category] = Boolean(open);
  writeSidebarCategoryState(state);
}

function closeOtherSidebarCategories(targetWrapper) {
  const wrappers = document.querySelectorAll(".sidebar-category");
  wrappers.forEach((wrapper) => {
    if (wrapper === targetWrapper) return;
    if (wrapper.classList.contains("is-open")) {
      setSidebarCategoryOpen(wrapper, false, true);
    }
  });
}

function syncSidebarCategories(activeTab) {
  const wrappers = document.querySelectorAll(".sidebar-category");
  if (!wrappers.length) return;
  const isCollapsed = document
    .querySelector(".ml-app")
    ?.classList.contains("is-sidebar-collapsed");
  let activeWrapper = null;

  wrappers.forEach((wrapper) => {
    const hasActive = [...wrapper.querySelectorAll(".ml-nav-item")].some(
      (button) => button.dataset.tab === activeTab,
    );
    wrapper.classList.toggle("is-active-category", hasActive);
    if (hasActive) {
      activeWrapper = wrapper;
    }
  });

  if (!isCollapsed && activeWrapper) {
    closeOtherSidebarCategories(activeWrapper);
    setSidebarCategoryOpen(activeWrapper, true, true);
  }
}

function updateShellContext(activeTab) {
  const categories = getSidebarCategoryConfig();
  const category = categories.find((entry) => entry.tabs.includes(activeTab));
  const eyebrowMap = {
    overview: "Vis\u00e3o geral",
    ads: "An\u00fancios",
    promotions: "Promo\u00e7\u00f5es",
    analytics: "Analytics",
    operations: "Opera\u00e7\u00e3o",
    account: "Conta",
    support: "Suporte",
  };
  const activeButton = document.querySelector(
    `.ml-nav-item[data-tab="${activeTab}"] .ml-nav-item__label`,
  );
  const workspaceButton = document.querySelector(
    `.workspace-pill[data-tab="${activeTab}"]`,
  );
  const title =
    activeButton?.textContent?.trim() ||
    workspaceButton?.textContent?.trim() ||
    "Painel de Controle";
  const eyebrow = eyebrowMap[category?.key] || "Vis\u00e3o geral";

  setText("shell-page-title", title);
  setText("shell-page-eyebrow", eyebrow);
  const quickJump = document.getElementById("workspaceQuickJump");
  if (quickJump && quickJump.value !== activeTab) quickJump.value = activeTab;
}

function initWorkspaceQuickJump() {
  const select = document.getElementById("workspaceQuickJump");
  if (!select || select.dataset.bound === "1") return;

  const buttons = $all(".ml-sidebar__section > .ml-nav-item");
  const options = buttons
    .map((button) => ({
      tab: String(button.dataset.tab || "").trim(),
      label: String(button.querySelector(".ml-nav-item__label")?.textContent || button.textContent || "")
        .replace(/\s+/g, " ")
        .replace(/\bBeta\b/gi, "")
        .trim(),
    }))
    .filter((item) => item.tab && item.label);

  select.innerHTML = options
    .map((item) => `<option value="${escapeHtml(item.tab)}">${escapeHtml(item.label)}</option>`)
    .join("");
  select.dataset.bound = "1";
  select.addEventListener("change", () => {
    if (select.value) void showTab(select.value);
  });
}

function applyActionHierarchy(root = document) {
  const destructivePattern = /^(Excluir|Encerrar|Desativar|Apagar|Remover)/i;
  root.querySelectorAll("button").forEach((button) => {
    const label = String(button.textContent || "").trim().replace(/\s+/g, " ");
    if (!destructivePattern.test(label)) return;
    button.classList.add("btn-danger", "ux-danger-action");
    button.setAttribute("data-ux-danger-action", "true");
    if (!button.title) button.title = "Ação que altera ou remove dados";
  });
}

function initControlPanelFocus() {
  const panel = document.getElementById("tab-control-panel");
  const topProducts = document.getElementById("controlPanelTopProducts");
  const section = topProducts?.closest(".control-panel-products");
  if (!panel || !section || section.dataset.uxFocusBound === "1") return;

  section.dataset.uxFocusBound = "1";
  section.classList.add("ux-control-panel-secondary");

  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "btn btn-ghost ux-control-panel-secondary-toggle";
  toggle.setAttribute("aria-expanded", "false");
  toggle.textContent = "Ver produtos em destaque";
  toggle.addEventListener("click", () => {
    const expanded = section.classList.toggle("is-expanded");
    toggle.setAttribute("aria-expanded", String(expanded));
    toggle.textContent = expanded
      ? "Ocultar produtos em destaque"
      : "Ver produtos em destaque";
  });
  section.before(toggle);
}

function initSidebarCategories() {
  const section = document.querySelector(".ml-sidebar__section");
  if (!section || section.dataset.categorized === "1") return;

  alignSidebarNavIconsToSemanticMap();

  const buttonMap = new Map(
    $all(".ml-sidebar__section > .ml-nav-item").map((button) => [
      button.dataset.tab,
      button,
    ]),
  );
  const title = section.querySelector(".ml-sidebar__title");
  if (title) title.textContent = "Categorias";

  section
    .querySelectorAll(".ml-sidebar__group-title")
    .forEach((element) => element.remove());

  const categories = getSidebarCategoryConfig();
  const fragment = document.createDocumentFragment();

  for (const category of categories) {
    const buttons = category.tabs
      .map((tab) => buttonMap.get(tab))
      .filter(Boolean)
      .filter((button) => button.style.display !== "none");
    if (!buttons.length) continue;

    const wrapper = document.createElement("section");
    wrapper.className = "sidebar-category";
    wrapper.dataset.category = category.key;

    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "sidebar-category__toggle";
    toggle.setAttribute("aria-expanded", "false");
    toggle.innerHTML = `
      <span class="sidebar-category__icon">${renderSpriteIcon(sidebarCategoryIcon(category.key), "ml-nav-icon")}</span>
      <span class="sidebar-category__meta">
        <strong>${escapeHtml(category.label)}</strong>
        <small>${escapeHtml(category.hint)}</small>
      </span>
      <span class="sidebar-category__chevron" aria-hidden="true">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
          <path d="M9 6l6 6-6 6"></path>
        </svg>
      </span>
    `;

    const body = document.createElement("div");
    body.className = "sidebar-category__body";

    const inner = document.createElement("div");
    inner.className = "sidebar-category__inner";

    buttons.forEach((button) => {
      button.classList.add("ml-nav-item--sub");
      const label =
        button.querySelector(".ml-nav-item__label")?.textContent?.trim() ||
        button.dataset.tab ||
        "Aba";
      button.setAttribute("title", label);
      button.setAttribute("aria-label", label);
      inner.appendChild(button);
    });

    body.appendChild(inner);
    wrapper.append(toggle, body);

    const hasActive = buttons.some((button) =>
      button.classList.contains("active"),
    );
    const isInitiallyOpen = hasActive;

    setSidebarCategoryOpen(wrapper, isInitiallyOpen, false);

    toggle.addEventListener("click", () => {
      const shouldOpen = !wrapper.classList.contains("is-open");
      if (shouldOpen) {
        closeOtherSidebarCategories(wrapper);
      }
      setSidebarCategoryOpen(wrapper, shouldOpen, true);
    });

    fragment.appendChild(wrapper);
  }

  section.appendChild(fragment);
  section.dataset.categorized = "1";

  const activeTab =
    document.querySelector(".ml-sidebar .ml-nav-item.active")?.dataset.tab ||
    document.querySelector(".workspace-pill.active")?.dataset.tab ||
    "control-panel";
  syncSidebarCategories(activeTab);
  updateShellContext(activeTab);
}

async function showTab(tab) {
  const resolvedTab = tab;
  auditTabAccess(resolvedTab);
  const tabs = $all(".tab");
  const panels = $all(".tab-panel");

  tabs.forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  syncSidebarCategories(tab);
  updateShellContext(tab);
  panels.forEach((p) => {
    const isActive = p.id === `tab-${resolvedTab}`;
    p.classList.toggle("active", isActive);
    if (isActive) animateTabPanel(p);
  });

  if (
    tab === "control-panel" ||
    tab === "stock-alert" ||
    tab === "price-increase" ||
    tab === "shopee-notices" ||
    tab === "products" ||
    tab === "listing-status" ||
    tab === "listing-clone" ||
    tab === "gift-campaign" ||
    tab === "curve-abc" ||
    tab === "relaunch" ||
    tab === "launches" ||
    tab === "analytics-ai" ||
    tab === "ads-ranking" ||
    tab === "sales-control" ||
    tab === "sales-share" ||
    tab === "metrics" ||
    tab === "ads" ||
    tab === "boost" ||
    tab === "catalog-quality" ||
    tab === "orders" ||
    tab === "deadline-control" ||
    tab === "geo-sales" ||
    tab === "costs" ||
    tab === "intelligent-pricing" ||
    tab === "margin" ||
    tab === "promotions" ||
    tab === "flash-sale" ||
    tab === "logistics" ||
    tab === "clips" ||
    tab === "bulk-specs"
  ) {
    await ensureShopSelected();
  }

  if (tab === "products") {
    initProductsSort();
    loadProducts();
  }
  if (tab === "listing-status") initListingStatusTab();
  if (tab === "deadline-control") loadDeadlineControlPanel();
  if (tab === "gift-campaign") initGiftCampaign();
  if (tab === "listing-clone" && window.listingCloneManager) {
    window.listingCloneManager.load();
  }
  if (tab === "curve-abc") await loadProductsCurvesAbc();
  if (tab === "relaunch") await loadProductsRelaunch();
  if (tab === "launches") await loadLaunches();
  if (tab === "analytics-ai") await loadAnalyticsAi();
  if (tab === "sales-control") await loadSalesControl();
  if (tab === "sales-share") await loadSalesShare();
  if (tab === "control-panel") loadControlPanel();
  if (tab === "stock-alert" && window.stockAlertManager) {
    await window.stockAlertManager.load();
  }
  if (tab === "price-increase") await loadPriceIncreaseTab();
  if (tab === "shopee-notices") await loadShopeeNoticeTab();
  if (tab === "orders") loadOrders();
  if (tab === "admin") loadAdmin();
  if (tab === "billing-credits") await loadBillingCreditsTab();
  if (tab === "patch-notes") loadPatchNotes();
  if (tab === "latest-updates") loadLatestUpdates();
  if (tab === "geo-sales") loadGeoSales();
  if (tab === "dashboard") loadDashboard();
  if (tab === "ads" && typeof window.loadAdsAll === "function") {
    await window.loadAdsAll();
  }
  if (tab === "ads-ranking" && typeof loadProductsRanking === "function") {
    await loadProductsRanking();
  }
  if (tab === "boost" && window.adsBoostManager) {
    await window.adsBoostManager.load();
  }
  if (tab === "metrics" && window.metricsManager) {
    window.metricsManager.load();
  }
  if (tab === "catalog-quality" && window.catalogQualityManager) {
    window.catalogQualityManager.load();
  }
  if (tab === "seo") openSeoHome();
  if (tab === "costs") loadCosts();
  if (tab === "intelligent-pricing") loadIntelligentPricingTab();
  if (tab === "margin") loadMargin();
  if (tab === "promotions" && window.promotionManager) {
    window.promotionManager.setupEventListeners?.();
  }
  if (tab === "flash-sale" && window.flashSaleManager) {
    window.flashSaleManager.init();
  }
  if (tab === "logistics") {
    if (LOGISTICS_DATA) {
      renderLogisticsTables(LOGISTICS_DATA);
    } else {
      await loadLogistics({ forceSync: true });
    }
  }
  if (tab === "clips") loadBulkClipsPanel();
  if (tab === "bulk-specs") loadBulkSpecsPanel();
  if (tab === "support") {
    if (!ME) await loadMe();
    renderSupportContext();
    if (!document.querySelector(".support-view.is-active")) {
      setSupportView("contact");
    }
  }

  enhanceUiStates(document.getElementById(`tab-${resolvedTab}`) || document);
  applyActionHierarchy(document.getElementById(`tab-${resolvedTab}`) || document);
}

function initTabs() {
  const tabs = $all(".tab");
  tabs.forEach((btn) => {
    btn.addEventListener("click", async () => {
      await showTab(btn.dataset.tab);
    });
  });
}

function applyBetaTags() {
  const betaTabs = ["margin", "launches"];
  betaTabs.forEach((tab) => {
    document.querySelectorAll(`.tab[data-tab="${tab}"]`).forEach((button) => {
      if (button.querySelector(".ml-beta-tag")) return;
      const badge = document.createElement("span");
      badge.className = "ml-beta-tag";
      badge.textContent = "Beta";
      const labelTarget =
        button.querySelector(".ml-nav-item__label") || button;
      labelTarget.appendChild(document.createTextNode(" "));
      labelTarget.appendChild(badge);
    });
  });
}

function renderSeoList(rootId, rows, { rightLabelFn, barPctFn } = {}) {
  const root = document.getElementById(rootId);
  if (!root) return;

  if (!rows?.length) {
    root.innerHTML = `<div class="muted ui-state ui-state--empty">Sem dados.</div>`;
    return;
  }

  root.innerHTML = rows
    .slice(0, 20)
    .map((r) => {
      const term = escapeHtml(r.term || r.uf || r.text || "—");
      const sub = r.sub ? escapeHtml(r.sub) : "";
      const right = rightLabelFn ? escapeHtml(rightLabelFn(r)) : "";
      const pct = barPctFn
        ? Math.max(0, Math.min(100, Number(barPctFn(r) || 0)))
        : null;

      return `
        <div class="seo-row">
          <div class="seo-row__left" style="min-width:0;">
            <div class="seo-row__term">${term}</div>
            ${sub ? `<div class="seo-row__sub">${sub}</div>` : ""}
            ${
              pct != null
                ? `<div class="seo-bar"><div style="width:${pct.toFixed(1)}%"></div></div>`
                : ""
            }
          </div>
          <div class="seo-row__right">${right}</div>
        </div>
      `;
    })
    .join("");
}

async function loadSeoKeywords() {
  const q = String(document.getElementById("seoQ")?.value || "").trim();
  const period = String(document.getElementById("seoPeriod")?.value || "30d");
  const msg = document.getElementById("seoMsg");

  if (!q) {
    if (msg) msg.textContent = "Digite uma palavra para buscar.";
    return;
  }

  if (msg) msg.textContent = "Carregando…";

  try {
    const data = await apiGet(
      `/seo/keywords?q=${encodeURIComponent(q)}&period=${encodeURIComponent(period)}`,
    );

    if (msg) {
      msg.textContent =
        data?.trends?.ok === false
          ? "Trends indisponível no momento (bloqueio/consent). Exibindo sugestões do Google."
          : "";
    }

    renderSeoList(
      "seoTopList",
      (data?.related?.top || []).map((x) => ({
        term: x.term,
        score: Number(x.score || 0),
        sub: "Trends • Top",
      })),
      {
        rightLabelFn: (r) => String(r.score || 0),
        barPctFn: (r) => (Number(r.score || 0) / 100) * 100,
      },
    );

    renderSeoList(
      "seoRisingList",
      (data?.related?.rising || []).map((x) => ({
        term: x.term,
        growthPct: x.growthPct,
        sub: "Trends • Rising",
      })),
      {
        rightLabelFn: (r) =>
          r.growthPct == null
            ? "—"
            : Number(r.growthPct) >= 9999
              ? "Breakout"
              : `${r.growthPct}%`,
      },
    );

    renderSeoList(
      "seoUfList",
      (data?.byUf || []).map((x) => ({
        uf: x.uf,
        interest: Number(x.interest || 0),
        sub: "BR • UF",
      })),
      {
        rightLabelFn: (r) => `${r.interest}`,
        barPctFn: (r) => (Number(r.interest || 0) / 100) * 100,
      },
    );

    renderSeoList(
      "seoSuggestList",
      (data?.suggestions || []).map((t) => ({
        text: t,
        sub: "Autocomplete",
      })),
      {
        rightLabelFn: () => "",
      },
    );

    if (msg && data?.trends?.ok !== false) msg.textContent = "";
  } catch (e) {
    if (msg) msg.textContent = `Erro: ${String(e?.message || e)}`;
  }
}

function showSeoView(view) {
  const home = document.getElementById("seoHome");
  const g = document.getElementById("seoGoogleView");
  const s = document.getElementById("seoShopeeView");

  if (home) home.style.display = view === "home" ? "" : "none";
  if (g) g.style.display = view === "google" ? "" : "none";
  if (s) s.style.display = view === "shopee" ? "" : "none";
}

function openSeoHome() {
  showSeoView("home");
}

function openSeoGoogle() {
  showSeoView("google");
}

function openSeoShopee() {
  showSeoView("shopee");
  ensureShopeeTrendsUi(); // cria UI dentro de seoShopeeRoot (abaixo)
  // opcional: se já tiver produto ref, carregar automático
  const ref = getSeoRefProduct();
  if (ref?.itemId) loadSeoShopeeRecommendations({ ref, q: "" });
}

function initSeo() {
  document
    .getElementById("btnSeoOpenGoogle")
    ?.addEventListener("click", openSeoGoogle);
  document
    .getElementById("btnSeoOpenShopee")
    ?.addEventListener("click", openSeoShopee);

  document
    .getElementById("btnSeoBackFromGoogle")
    ?.addEventListener("click", openSeoHome);
  document
    .getElementById("btnSeoBackFromShopee")
    ?.addEventListener("click", openSeoHome);

  // Google (continua igual)
  document
    .getElementById("btnSeoSearch")
    ?.addEventListener("click", loadSeoKeywords);
  document.getElementById("seoQ")?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") loadSeoKeywords();
  });
  initSeoGoogleCompare();
}

