function setWidthPct(id, pct) {
  const el = document.getElementById(id);
  if (!el) return;
  const x = Number(pct);
  const safe = Number.isFinite(x) ? Math.max(0, Math.min(100, x)) : 0;
  el.style.width = `${safe}%`;
}

function formatCount(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) ? n.toLocaleString("pt-BR") : "0";
}

function formatPctText(value, digits = 1) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return `${n.toFixed(digits).replace(".", ",")}%`;
}

function clampPct(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(100, n));
}

function getScoreLabel(scorePct) {
  const pct = clampPct(scorePct);
  if (pct >= 85) return "Operacao muito saudavel";
  if (pct >= 70) return "Operacao consistente";
  if (pct >= 55) return "Operacao em atencao";
  return "Operacao critica";
}

function getSacToneKey(scorePct) {
  const pct = clampPct(scorePct);
  if (pct >= 95) return "excellent";
  if (pct >= 85) return "good";
  if (pct >= 70) return "warning";
  return "critical";
}

function renderControlPanelStars(rating, totalRatings) {
  const safeRating = Math.max(0, Math.min(5, Number(rating)));
  if (!Number.isFinite(safeRating) || safeRating <= 0) {
    return `<span class="muted">Sem avaliacoes suficientes.</span>`;
  }

  const stars = [];
  for (let index = 0; index < 5; index += 1) {
    const fillPct = Math.max(0, Math.min(100, (safeRating - index) * 100));
    stars.push(`
      <span class="control-panel-stars__item" aria-hidden="true">
        <span class="control-panel-stars__base">★</span>
        <span class="control-panel-stars__fill" style="width:${fillPct}%;">★</span>
      </span>
    `);
  }

  const ratingsLabel = Number(totalRatings || 0) > 0
    ? `${formatCount(totalRatings)} avaliacoes`
    : "Sem volume suficiente";

  return `${stars.join("")}<span class="control-panel-stars__meta">${escapeHtml(ratingsLabel)}</span>`;
}

