function parseRelaunchProcessError(err) {
  let raw = String(err?.message || err || "Erro desconhecido");
  try {
    const parsed = JSON.parse(raw);
    raw = parsed?.message || parsed?.error?.message || parsed?.error || raw;
  } catch (_) {}
  return String(raw || "Erro desconhecido");
}

function extractAsyncProcessPayload(statusPayload = {}) {
  const level1 =
    statusPayload?.result && typeof statusPayload.result === "object"
      ? statusPayload.result
      : null;
  if (level1?.result && typeof level1.result === "object") {
    return level1.result;
  }
  return level1 || {};
}

async function enqueueAsyncProcessJob(action, payload = {}) {
  return apiPost("/shops/active/process-jobs", {
    action: String(action || "").trim(),
    payload: payload && typeof payload === "object" ? payload : {},
  });
}

async function getAsyncProcessJobStatus(jobId) {
  return apiGet(
    `/shops/active/process-jobs/${encodeURIComponent(String(jobId || "").trim())}`,
  );
}

async function cancelAsyncProcessJob(jobId) {
  return apiDelete(
    `/shops/active/process-jobs/${encodeURIComponent(String(jobId || "").trim())}`,
  );
}

async function waitForAsyncProcessJob(
  jobId,
  { pollMs = 2200, timeoutMs = 20 * 60 * 1000, onUpdate = null } = {},
) {
  const startedAt = Date.now();
  let previousState = "";

  while (Date.now() - startedAt < timeoutMs) {
    // eslint-disable-next-line no-await-in-loop
    const status = await getAsyncProcessJobStatus(jobId);
    const currentState = String(status?.status || status?.state || "").toLowerCase();

    if (typeof onUpdate === "function" && currentState !== previousState) {
      onUpdate(status, previousState);
      previousState = currentState;
    }

    if (currentState === "completed") {
      return status;
    }
    if (currentState === "failed") {
      throw new Error(
        String(status?.failedReason || "Processo assíncrono concluído com erro."),
      );
    }

    // eslint-disable-next-line no-await-in-loop
    await new Promise((resolve) => setTimeout(resolve, pollMs));
  }

  throw new Error("Tempo limite excedido aguardando conclusão do processo assíncrono.");
}

async function waitForAsyncProcessJobStart(
  jobId,
  { pollMs = 1200, timeoutMs = 15000 } = {},
) {
  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    // eslint-disable-next-line no-await-in-loop
    const status = await getAsyncProcessJobStatus(jobId);
    const currentState = String(status?.status || status?.state || "").toLowerCase();
    if (["active", "completed", "failed", "delayed"].includes(currentState)) {
      return status;
    }
    // eslint-disable-next-line no-await-in-loop
    await new Promise((resolve) => setTimeout(resolve, pollMs));
  }
  return null;
}

function normalizeListingStatusText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function splitListingStatusCsv(value) {
  return Array.from(
    new Set(
      String(value || "")
        .split(/[\n,;]+/g)
        .map((token) => token.trim())
        .filter(Boolean),
    ),
  );
}

function getListingStatusAction() {
  return String(
    document.querySelector('input[name="listingStatusAction"]:checked')?.value ||
      "activate",
  );
}

function getListingStatusActionLabel(action = getListingStatusAction()) {
  const labels = {
    activate: "Ativação/Publicação de anúncios",
    deactivate: "Desativação/Pausa de anúncios",
    delete: "Exclusão de anúncios",
  };
  return labels[String(action || "").trim()] || "Alteração de status de anúncios";
}

function getListingStatusInputs() {
  const manualIds = splitListingStatusCsv(
    document.getElementById("listingStatusIdsInput")?.value,
  );
  const manualSkus = splitListingStatusCsv(
    document.getElementById("listingStatusSkusInput")?.value,
  );
  const fileIds = Array.isArray(LISTING_STATUS_FILE_IDS)
    ? LISTING_STATUS_FILE_IDS
    : [];
  const itemIds = Array.from(
    new Set([...manualIds, ...fileIds].map((value) => String(value || "").trim()).filter(Boolean)),
  );
  const skus = Array.from(
    new Set(manualSkus.map((value) => String(value || "").trim()).filter(Boolean)),
  );
  return { itemIds, skus };
}

function renderListingStatusSummary() {
  const summary = document.getElementById("listingStatusSummary");
  if (!summary) return;
  const { itemIds, skus } = getListingStatusInputs();
  const action = getListingStatusActionLabel();
  summary.textContent =
    `${action}: ${itemIds.length} ID(s) e ${skus.length} SKU(s) prontos para processar.`;
}

function renderListingStatusPreview() {
  const preview = document.getElementById("listingStatusPreview");
  const meta = document.getElementById("listingStatusFileMeta");
  if (!preview || !meta) return;
  const ids = Array.isArray(LISTING_STATUS_FILE_IDS) ? LISTING_STATUS_FILE_IDS : [];
  meta.textContent = ids.length
    ? `${ids.length} ID(s) carregado(s) da planilha.`
    : "Nenhuma planilha carregada.";
  if (!ids.length) {
    preview.innerHTML = "";
    renderListingStatusSummary();
    return;
  }
  preview.innerHTML = ids
    .slice(0, 20)
    .map(
      (id, index) => `
        <div class="listing-status-preview__row">
          <span>${index + 1}</span>
          <strong>${escapeHtml(String(id))}</strong>
        </div>
      `,
    )
    .join("");
  if (ids.length > 20) {
    preview.insertAdjacentHTML(
      "beforeend",
      `<div class="muted">+ ${ids.length - 20} ID(s) adicionais.</div>`,
    );
  }
  renderListingStatusSummary();
}

function downloadListingStatusTemplate() {
  const headers = ["ID DO PRODUTO"];
  const rows = [["1861418518"], ["1861418519"], ["1861418520"]];
  if (window.XLSX?.utils?.aoa_to_sheet) {
    const worksheet = window.XLSX.utils.aoa_to_sheet([headers, ...rows]);
    worksheet["!cols"] = [{ wch: 22 }];
    const workbook = window.XLSX.utils.book_new();
    window.XLSX.utils.book_append_sheet(workbook, worksheet, "Status");
    window.XLSX.writeFile(workbook, "modelo_status_anuncios.xlsx", {
      compression: true,
    });
    return;
  }
  downloadLogisticsCsvUtf8("modelo_status_anuncios.csv", headers, rows);
}

async function parseListingStatusFile(file) {
  if (!file) return [];
  if (!window.XLSX?.read) {
    throw new Error("A biblioteca XLSX nao carregou no navegador.");
  }
  const isCsv = String(file.name || "").toLowerCase().endsWith(".csv");
  const workbook = window.XLSX.read(await file.arrayBuffer(), {
    type: "array",
    raw: false,
    codepage: isCsv ? 65001 : undefined,
  });
  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  if (!sheet) throw new Error("Nao foi possivel ler a primeira aba da planilha.");
  const matrix = window.XLSX.utils.sheet_to_json(sheet, {
    header: 1,
    defval: "",
    blankrows: false,
  });
  if (!Array.isArray(matrix) || !matrix.length) {
    throw new Error("A planilha esta vazia.");
  }

  const header = Array.isArray(matrix[0]) ? matrix[0] : [];
  const columnIndex = header.findIndex(
    (cell) => normalizeListingStatusText(cell) === "id do produto",
  );
  const idIndex = columnIndex >= 0 ? columnIndex : 0;
  const ids = [];
  for (let i = 1; i < matrix.length; i += 1) {
    const row = Array.isArray(matrix[i]) ? matrix[i] : [];
    const raw = String(row[idIndex] || "").trim();
    if (!raw) continue;
    if (/^\d+$/.test(raw)) ids.push(raw);
  }
  return Array.from(new Set(ids));
}

function setListingStatusProgress(status, text) {
  const badge = document.getElementById("listingStatusProgressBadge");
  const label = document.getElementById("listingStatusProgressText");
  if (badge) {
    badge.className = "badge";
    if (status === "running") badge.classList.add("badge--yellow");
    else if (status === "success") badge.classList.add("badge--green");
    else if (status === "error") badge.classList.add("badge--red");
    else badge.classList.add("badge--gray");
    badge.textContent =
      status === "running"
        ? "Em andamento"
        : status === "success"
          ? "Concluido"
          : status === "error"
            ? "Erro"
            : "Aguardando";
  }
  if (label) label.textContent = text || "";
}

function appendListingStatusLog(message, tone = "info") {
  const logBox = document.getElementById("listingStatusLogs");
  const stamp = new Date().toLocaleTimeString("pt-BR", { hour12: false });
  const line = `[${stamp}] ${String(message || "")}`;
  if (LISTING_STATUS_PROCESS_STATE) {
    LISTING_STATUS_PROCESS_STATE.logs.push(line);
    appendGlobalTrackedProcessLog(
      LISTING_STATUS_PROCESS_STATE.globalProcessId,
      line,
      tone,
    );
  }
  if (!logBox) return;
  if (logBox.querySelector(".muted")) logBox.innerHTML = "";
  const row = document.createElement("div");
  row.className = `listing-status-log--${tone}`;
  row.textContent = line;
  logBox.appendChild(row);
  logBox.scrollTop = logBox.scrollHeight;
}

function exportListingStatusLogs() {
  if (!LISTING_STATUS_PROCESS_STATE?.logs?.length) return;
  const lines = [
    `Processo: ${LISTING_STATUS_PROCESS_STATE.actionLabel || "-"}`,
    `Inicio: ${LISTING_STATUS_PROCESS_STATE.startedAt || "-"}`,
    `Fim: ${new Date().toLocaleString("pt-BR")}`,
    `Sucesso: ${Number(LISTING_STATUS_PROCESS_STATE.success || 0)}`,
    `Falhas: ${Number(LISTING_STATUS_PROCESS_STATE.failed || 0)}`,
    "",
    ...LISTING_STATUS_PROCESS_STATE.logs,
  ];
  const blob = new Blob([lines.join("\n")], {
    type: "text/plain;charset=utf-8",
  });
  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  link.href = url;
  link.download = `status_anuncios_${Date.now()}_logs.txt`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

async function runListingStatusProcess() {
  const btn = document.getElementById("btnListingStatusRun");
  const exportBtn = document.getElementById("btnListingStatusExportLogs");
  const action = getListingStatusAction();
  const { itemIds, skus } = getListingStatusInputs();
  const total = itemIds.length + skus.length;
  if (!total) {
    openModal(
      "Status de anúncios",
      '<div class="muted">Informe ao menos um ID, SKU ou planilha para processar.</div>',
    );
    return;
  }
  if (
    action === "delete" &&
    !window.confirm(
      `Excluir ${total} anuncio(s)? Esta acao nao pode ser desfeita.`,
    )
  ) {
    return;
  }

  const actionLabel = getListingStatusActionLabel(action);
  const globalProcessId = beginGlobalTrackedProcess("Status de anúncios", actionLabel, total);
  LISTING_STATUS_PROCESS_STATE = {
    actionLabel,
    startedAt: new Date().toLocaleString("pt-BR"),
    total,
    success: 0,
    failed: 0,
    logs: [],
    globalProcessId,
  };

  if (btn) {
    btn.disabled = true;
    btn.textContent = "Processando...";
  }
  if (exportBtn) exportBtn.disabled = true;
  const logBox = document.getElementById("listingStatusLogs");
  if (logBox) logBox.innerHTML = "";
  setListingStatusProgress("running", `Enfileirando ${total} item(ns)...`);
  appendListingStatusLog(`Processo iniciado para ${total} item(ns).`, "info");

  try {
    await ensureShopSelected();
    const enqueueResult = await enqueueAsyncProcessJob("products.status.bulk", {
      action,
      itemIds,
      skus,
      concurrency: 5,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendListingStatusLog(`Job enfileirado com sucesso (jobId: ${jobId || "-"})`, "info");
    const startStatus = await waitForAsyncProcessJobStart(jobId);
    let response = null;
    if (!startStatus) {
      appendListingStatusLog(
        "Job ficou em WAITING por mais de 15s. Executando fallback direto (sem fila).",
        "warning",
      );
      try {
        const cancelStatus = await cancelAsyncProcessJob(jobId);
        if (cancelStatus?.cancelled) {
          appendListingStatusLog(
            `Job em fila removido com sucesso (${jobId}).`,
            "info",
          );
        } else {
          appendListingStatusLog(
            `Job não removido (${jobId}) - estado atual: ${String(cancelStatus?.state || "desconhecido")}.`,
            "warning",
          );
        }
      } catch (cancelError) {
        appendListingStatusLog(
          `Não foi possível remover job da fila: ${String(cancelError?.message || "erro desconhecido")}`,
          "warning",
        );
      }
      response = await apiPost("/shops/active/products/status/bulk", {
        action,
        itemIds,
        skus,
        concurrency: 5,
      });
    } else {
      const status = await waitForAsyncProcessJob(jobId, {
        onUpdate: (snapshot) => {
          const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
          appendListingStatusLog(`Status do job: ${stateLabel}`, "info");
        },
      });
      response = extractAsyncProcessPayload(status);
    }
    const logs = Array.isArray(response?.logs) ? response.logs : [];
    logs.forEach((entry) => {
      const itemId = String(entry?.itemId || "").trim();
      const sku = String(entry?.sku || "").trim();
      const message = String(entry?.message || "").trim();
      const label = [itemId ? `Item ${itemId}` : "", sku ? `SKU ${sku}` : ""]
        .filter(Boolean)
        .join(" / ") || "Item sem identificacao";
      appendListingStatusLog(
        `${entry?.ok ? "Sucesso" : "Falha"} - ${label}${message ? ` - ${message}` : ""}`,
        entry?.ok ? "success" : "error",
      );
    });

    const success = Math.max(0, Number(response?.success || 0));
    const failed = Math.max(0, Number(response?.failed || 0));
    LISTING_STATUS_PROCESS_STATE.success = success;
    LISTING_STATUS_PROCESS_STATE.failed = failed;
    syncGlobalTrackedProcessProgress(globalProcessId, {
      done: total,
      total,
      success,
      failed,
    });
    const summary = `Resumo final: ${success} sucesso(s) e ${failed} falha(s).`;
    appendListingStatusLog(summary, failed > 0 ? "error" : "success");
    setListingStatusProgress(
      failed > 0 ? "error" : "success",
      summary,
    );
    finishGlobalTrackedProcess(globalProcessId, {
      summaryMessage: summary,
      hasWarning: failed > 0,
    });
    if (exportBtn) exportBtn.disabled = false;
  } catch (error) {
    const message = parseRelaunchProcessError(error);
    appendListingStatusLog(`Falha geral no processo: ${message}`, "error");
    setListingStatusProgress("error", "Processo encerrado com erro.");
    finishGlobalTrackedProcess(globalProcessId, {
      summaryMessage: `Falha geral: ${message}`,
      hasError: true,
    });
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = "Executar processo";
    }
  }
}

function clearListingStatusForm() {
  const idsInput = document.getElementById("listingStatusIdsInput");
  const skusInput = document.getElementById("listingStatusSkusInput");
  const fileInput = document.getElementById("listingStatusFileInput");
  if (idsInput) idsInput.value = "";
  if (skusInput) skusInput.value = "";
  if (fileInput) fileInput.value = "";
  LISTING_STATUS_FILE_IDS = [];
  renderListingStatusPreview();
  setListingStatusProgress("idle", "Nenhum processo iniciado.");
  const logBox = document.getElementById("listingStatusLogs");
  if (logBox) logBox.innerHTML = '<div class="muted">Os logs do processo aparecerão aqui.</div>';
  const exportBtn = document.getElementById("btnListingStatusExportLogs");
  if (exportBtn) exportBtn.disabled = true;
}

