function getRelaunchProcessUi() {
  let panel = document.getElementById("relaunchProcessPanel");
  if (!panel) {
    panel = document.createElement("aside");
    panel.id = "relaunchProcessPanel";
    panel.className = "relaunch-process-panel is-hidden";
    panel.innerHTML = `
      <div class="relaunch-process-panel__header">
        <div>
          <div id="relaunchProcessTitle" class="relaunch-process-panel__title">Processo</div>
          <div id="relaunchProcessMeta" class="relaunch-process-panel__meta">Aguardando execucao...</div>
        </div>
        <span id="relaunchProcessBadge" class="relaunch-process-badge">Parado</span>
      </div>
      <div class="relaunch-process-progress-track">
        <div id="relaunchProcessBar" class="relaunch-process-progress-bar"></div>
      </div>
      <div class="relaunch-process-progress-meta">
        <span id="relaunchProcessCounter">0/0</span>
        <span id="relaunchProcessPercent">0%</span>
      </div>
      <div id="relaunchProcessLogs" class="relaunch-process-logs"></div>
      <div class="relaunch-process-actions">
        <button id="btnRelaunchProcessExport" class="btn btn-ghost" type="button" disabled>Exportar logs.txt</button>
        <button id="btnRelaunchProcessClose" class="btn btn-ghost" type="button">Fechar</button>
      </div>
    `;
    document.body.appendChild(panel);

    panel
      .querySelector("#btnRelaunchProcessClose")
      ?.addEventListener("click", () => {
        panel.classList.add("is-hidden");
      });
    panel
      .querySelector("#btnRelaunchProcessExport")
      ?.addEventListener("click", () => {
        if (!RELAUNCH_PROCESS_STATE?.logs?.length) return;
        const safeAction = String(
          RELAUNCH_PROCESS_STATE.actionLabel || "processo",
        )
          .toLowerCase()
          .replace(/\s+/g, "_")
          .replace(/[^a-z0-9_]/g, "");
        const lines = [
          `Processo: ${RELAUNCH_PROCESS_STATE.actionLabel || "-"}`,
          `Inicio: ${RELAUNCH_PROCESS_STATE.startedAt || "-"}`,
          `Fim: ${new Date().toLocaleString("pt-BR")}`,
          `Sucesso: ${Number(RELAUNCH_PROCESS_STATE.success || 0)}`,
          `Falhas: ${Number(RELAUNCH_PROCESS_STATE.failed || 0)}`,
          "",
          ...RELAUNCH_PROCESS_STATE.logs,
        ];
        const blob = new Blob([lines.join("\n")], {
          type: "text/plain;charset=utf-8",
        });
        const link = document.createElement("a");
        const url = URL.createObjectURL(blob);
        link.href = url;
        link.download = `relaunch_${safeAction}_${Date.now()}_logs.txt`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      });
  }

  return {
    panel,
    title: panel.querySelector("#relaunchProcessTitle"),
    meta: panel.querySelector("#relaunchProcessMeta"),
    badge: panel.querySelector("#relaunchProcessBadge"),
    bar: panel.querySelector("#relaunchProcessBar"),
    counter: panel.querySelector("#relaunchProcessCounter"),
    percent: panel.querySelector("#relaunchProcessPercent"),
    logs: panel.querySelector("#relaunchProcessLogs"),
    exportBtn: panel.querySelector("#btnRelaunchProcessExport"),
  };
}

function updateRelaunchProcessProgress(done, total, success, failed) {
  const ui = getRelaunchProcessUi();
  const safeTotal = Math.max(0, Number(total || 0));
  const safeDone = Math.max(0, Number(done || 0));
  const pct = safeTotal > 0 ? Math.round((safeDone / safeTotal) * 100) : 0;
  if (ui.counter) ui.counter.textContent = `${safeDone}/${safeTotal}`;
  if (ui.percent) ui.percent.textContent = `${pct}%`;
  if (ui.bar) ui.bar.style.width = `${pct}%`;
  if (ui.meta) {
    ui.meta.textContent =
      `Concluidos ${safeDone}/${safeTotal} - sucesso ${Number(success || 0)} - falhas ${Number(failed || 0)}`;
  }
  syncGlobalTrackedProcessProgress(RELAUNCH_PROCESS_STATE?.globalProcessId, {
    done: safeDone,
    total: safeTotal,
    success: Number(success || 0),
    failed: Number(failed || 0),
  });
}

function appendRelaunchProcessLog(message, tone = "info") {
  if (!RELAUNCH_PROCESS_STATE) return;
  const ui = getRelaunchProcessUi();
  const stamp = new Date().toLocaleTimeString("pt-BR", { hour12: false });
  const line = `[${stamp}] ${String(message || "")}`;
  RELAUNCH_PROCESS_STATE.logs.push(line);
  appendGlobalTrackedProcessLog(RELAUNCH_PROCESS_STATE.globalProcessId, line, tone);
  if (!ui.logs) return;

  const row = document.createElement("div");
  row.className = `relaunch-process-log relaunch-process-log--${tone}`;
  row.textContent = line;
  ui.logs.appendChild(row);
  ui.logs.scrollTop = ui.logs.scrollHeight;
}

function startRelaunchProcess(actionLabel, total) {
  const processId = beginGlobalTrackedProcess("Relançamento", actionLabel, total);
  RELAUNCH_PROCESS_STATE = {
    actionLabel: String(actionLabel || "Processo"),
    startedAt: new Date().toLocaleString("pt-BR"),
    total: Number(total || 0),
    done: 0,
    success: 0,
    failed: 0,
    logs: [],
    finished: false,
    globalProcessId: processId,
  };

  const ui = getRelaunchProcessUi();
  ui.panel.classList.remove("is-hidden");
  if (ui.title) ui.title.textContent = RELAUNCH_PROCESS_STATE.actionLabel;
  if (ui.badge) {
    ui.badge.textContent = "Em andamento";
    ui.badge.classList.remove("is-success", "is-warning");
    ui.badge.classList.add("is-running");
  }
  if (ui.logs) ui.logs.innerHTML = "";
  if (ui.exportBtn) ui.exportBtn.disabled = true;
  updateRelaunchProcessProgress(0, RELAUNCH_PROCESS_STATE.total, 0, 0);
  appendRelaunchProcessLog(
    `Processo iniciado para ${RELAUNCH_PROCESS_STATE.total} anuncio(s).`,
    "info",
  );
}

function finishRelaunchProcess(summaryMessage) {
  if (!RELAUNCH_PROCESS_STATE) return;
  RELAUNCH_PROCESS_STATE.finished = true;
  appendRelaunchProcessLog(summaryMessage, "info");
  const ui = getRelaunchProcessUi();
  if (ui.exportBtn) ui.exportBtn.disabled = false;
  if (ui.badge) {
    const hasFailure = Number(RELAUNCH_PROCESS_STATE.failed || 0) > 0;
    ui.badge.textContent = hasFailure ? "Concluido com alertas" : "Concluido";
    ui.badge.classList.remove("is-running");
    ui.badge.classList.toggle("is-warning", hasFailure);
    ui.badge.classList.toggle("is-success", !hasFailure);
  }
  finishGlobalTrackedProcess(RELAUNCH_PROCESS_STATE.globalProcessId, {
    summaryMessage: String(summaryMessage || ""),
    hasWarning: Number(RELAUNCH_PROCESS_STATE.failed || 0) > 0,
  });
}

async function relaunchPauseSelected(btn) {
  if (RELAUNCH_SELECTED_IDS.size === 0) {
    alert("Selecione pelo menos um produto.");
    return;
  }

  const selectedIds = Array.from(RELAUNCH_SELECTED_IDS);
  if (!confirm(`Pausar ${selectedIds.length} anuncios?`)) {
    return;
  }

  btn.disabled = true;
  btn.textContent = "Pausando...";
  startRelaunchProcess("Processo de pausa de anuncios", selectedIds.length);

  try {
    await ensureShopSelected();
    const enqueueResult = await enqueueAsyncProcessJob("products.relaunch.pause", {
      productIds: selectedIds,
      concurrency: 5,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendRelaunchProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendRelaunchProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const response = extractAsyncProcessPayload(status);
    const logs = Array.isArray(response?.logs) ? response.logs : [];
    if (!logs.length) {
      appendRelaunchProcessLog(
        "Processo concluido sem retorno detalhado de logs por item.",
        "info",
      );
    } else {
      logs.forEach((entry) => {
        const itemId = String(entry?.itemId || "").trim();
        const message = String(entry?.message || "").trim();
        const label = itemId
          ? `Item ${itemId}${message ? ` - ${message}` : ""}`
          : message || "Item sem identificacao";
        appendRelaunchProcessLog(
          `${entry?.ok ? "Pausa concluida para" : "Falha ao pausar"} ${label}.`,
          entry?.ok ? "success" : "error",
        );
      });
    }

    RELAUNCH_PROCESS_STATE.success = Math.max(0, Number(response?.paused || 0));
    RELAUNCH_PROCESS_STATE.failed = Math.max(0, Number(response?.failed || 0));
    RELAUNCH_PROCESS_STATE.done = Number(RELAUNCH_PROCESS_STATE.total || selectedIds.length);
    updateRelaunchProcessProgress(
      RELAUNCH_PROCESS_STATE.done,
      RELAUNCH_PROCESS_STATE.total,
      RELAUNCH_PROCESS_STATE.success,
      RELAUNCH_PROCESS_STATE.failed,
    );

    finishRelaunchProcess(
      `Resumo final: ${RELAUNCH_PROCESS_STATE.success} pausado(s) e ${RELAUNCH_PROCESS_STATE.failed} falha(s).`,
    );

    RELAUNCH_SELECTED_IDS.clear();
    await loadProductsRelaunch();
  } catch (error) {
    appendRelaunchProcessLog(
      `Falha geral no processo: ${parseRelaunchProcessError(error)}`,
      "error",
    );
    finishRelaunchProcess("Resumo final: processo encerrado com erro.");
    alert(`Erro ao pausar: ${escapeHtml(parseRelaunchProcessError(error))}`);
  } finally {
    btn.disabled = false;
    btn.textContent = "Pausar selecionados";
  }
}

async function relaunchDeleteSelected(btn) {
  if (RELAUNCH_SELECTED_IDS.size === 0) {
    alert("Selecione pelo menos um produto.");
    return;
  }

  const selectedIds = Array.from(RELAUNCH_SELECTED_IDS);
  if (
    !confirm(
      `Voce tem certeza que deseja excluir ${selectedIds.length} anuncio${selectedIds.length !== 1 ? "s" : ""}? Esta acao nao pode ser desfeita.`,
    )
  ) {
    return;
  }

  btn.disabled = true;
  btn.textContent = "Excluindo...";
  startRelaunchProcess("Processo de exclusao de anuncios", selectedIds.length);

  const deletedIds = [];
  try {
    await ensureShopSelected();
    const enqueueResult = await enqueueAsyncProcessJob("products.relaunch.delete", {
      productIds: selectedIds,
      concurrency: 5,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendRelaunchProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendRelaunchProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const response = extractAsyncProcessPayload(status);
    const logs = Array.isArray(response?.logs) ? response.logs : [];
    if (!logs.length) {
      appendRelaunchProcessLog(
        "Processo concluido sem retorno detalhado de logs por item.",
        "info",
      );
    } else {
      logs.forEach((entry) => {
        const itemId = String(entry?.itemId || "").trim();
        const message = String(entry?.message || "").trim();
        const label = itemId
          ? `Item ${itemId}${message ? ` - ${message}` : ""}`
          : message || "Item sem identificacao";
        if (entry?.ok && itemId) deletedIds.push(itemId);
        appendRelaunchProcessLog(
          `${entry?.ok ? "Exclusao concluida para" : "Falha ao excluir"} ${label}.`,
          entry?.ok ? "success" : "error",
        );
      });
    }

    RELAUNCH_PROCESS_STATE.success = Math.max(0, Number(response?.deleted || 0));
    RELAUNCH_PROCESS_STATE.failed = Math.max(0, Number(response?.failed || 0));
    RELAUNCH_PROCESS_STATE.done = Number(RELAUNCH_PROCESS_STATE.total || selectedIds.length);
    updateRelaunchProcessProgress(
      RELAUNCH_PROCESS_STATE.done,
      RELAUNCH_PROCESS_STATE.total,
      RELAUNCH_PROCESS_STATE.success,
      RELAUNCH_PROCESS_STATE.failed,
    );

    if (deletedIds.length > 0) {
      const rows = deletedIds
        .map((id) => {
          if (RELAUNCH_ALL_PRODUCTS[id]) return RELAUNCH_ALL_PRODUCTS[id];
          return Object.values(RELAUNCH_ALL_PRODUCTS).find(
            (product) => String(product?.itemId || "") === String(id),
          );
        })
        .filter(Boolean)
        .map((product) => [
          product.title || "",
          product.sku || product.itemSku || "",
          String(product.itemId || ""),
        ]);
      downloadSheetWithFallback(
        `relaunch_deletados_${new Date().getTime()}`,
        ["nome_produto", "sku", "item_id"],
        rows,
      );
      appendRelaunchProcessLog(
        `Planilha de deletados exportada (${deletedIds.length} item(ns)).`,
        "info",
      );
    }

    finishRelaunchProcess(
      `Resumo final: ${RELAUNCH_PROCESS_STATE.success} excluido(s) e ${RELAUNCH_PROCESS_STATE.failed} falha(s).`,
    );

    RELAUNCH_SELECTED_IDS.clear();
    await loadProductsRelaunch();
  } catch (error) {
    appendRelaunchProcessLog(
      `Falha geral no processo: ${parseRelaunchProcessError(error)}`,
      "error",
    );
    finishRelaunchProcess("Resumo final: processo encerrado com erro.");
    alert(`Erro ao excluir: ${escapeHtml(parseRelaunchProcessError(error))}`);
  } finally {
    btn.disabled = false;
    btn.textContent = "Excluir anuncios";
  }
}

/* ===== Sub-abas de Produtos ===== */
function initProductsSubTabs() {
  const tabs = $all(".products-sub-tab");
  const contents = $all(".products-tab-content");

  tabs.forEach((btn) => {
    // Remove old listeners to prevent duplicates
    const newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);

    // Re-query after replacement
    const updatedBtn = document.querySelector(
      `.products-sub-tab[data-products-tab="${newBtn.dataset.productsTab}"]`,
    );

    updatedBtn.addEventListener("click", async () => {
      const tab = updatedBtn.dataset.productsTab;

      // Atualizar abas ativas
      const allTabs = $all(".products-sub-tab");
      const allContents = $all(".products-tab-content");

      allTabs.forEach((b) => b.classList.toggle("active", b === updatedBtn));
      allContents.forEach((c) => {
        const shouldShow = c.id === `products-tab-${tab}`;
        c.style.display = shouldShow ? "block" : "none";
      });

      // Carregar dados
      if (tab === "abc") {
        await loadProductsCurvesAbc();
      } else if (tab === "relaunch") {
        await loadProductsRelaunch();
      }
    });
  });
}

/* ---------------- Sync Buttons ---------------- */

function updateProductsSyncProgress({ percent = 0, status = "", detail = "", tone = "" } = {}) {
  const wrap = document.getElementById("products-sync-progress");
  const bar = document.getElementById("products-sync-progress-bar");
  const value = document.getElementById("products-sync-progress-value");
  const text = document.getElementById("products-sync-progress-text");
  const detailEl = document.getElementById("products-sync-progress-detail");
  const normalizedPercent = Math.max(0, Math.min(100, Math.round(Number(percent || 0))));

  if (wrap) {
    wrap.hidden = false;
    wrap.classList.toggle("is-error", tone === "error");
    wrap.classList.toggle("is-success", tone === "success");
  }
  if (bar) bar.style.width = `${normalizedPercent}%`;
  if (value) value.textContent = `${normalizedPercent}%`;
  if (text) text.textContent = status || "";
  if (detailEl) detailEl.textContent = detail || "";
}

function startProductsSyncProgress() {
  window.clearInterval(PRODUCTS_SYNC_PROGRESS_TIMER);
  PRODUCTS_SYNC_PROGRESS_VALUE = 4;
  updateProductsSyncProgress({
    percent: PRODUCTS_SYNC_PROGRESS_VALUE,
    status: "Preparando sincronizacao leve...",
    detail: "Precos existentes serao preservados; estoque, visitas e avaliacoes seguem seus ciclos.",
  });

  PRODUCTS_SYNC_PROGRESS_TIMER = window.setInterval(() => {
    if (!PRODUCTS_SYNC_IN_PROGRESS) return;
    PRODUCTS_SYNC_PROGRESS_VALUE = Math.min(
      94,
      PRODUCTS_SYNC_PROGRESS_VALUE + (PRODUCTS_SYNC_PROGRESS_VALUE < 45 ? 4 : 2),
    );
    const status =
      PRODUCTS_SYNC_PROGRESS_VALUE < 28
        ? "Buscando IDs ativos e pausados..."
        : PRODUCTS_SYNC_PROGRESS_VALUE < 58
          ? "Atualizando cadastro essencial..."
          : PRODUCTS_SYNC_PROGRESS_VALUE < 82
            ? "Aplicando ciclos de estoque, visitas e avaliacoes..."
            : "Finalizando gravacao local...";
    updateProductsSyncProgress({
      percent: PRODUCTS_SYNC_PROGRESS_VALUE,
      status,
      detail: "O tempo pode variar conforme o volume de anuncios da loja.",
    });
  }, 900);
}

function stopProductsSyncProgress() {
  window.clearInterval(PRODUCTS_SYNC_PROGRESS_TIMER);
  PRODUCTS_SYNC_PROGRESS_TIMER = null;
}

function buildProductsSyncSummary(summary = {}) {
  const cycles = summary?.cycles || {};
  const stockText = cycles.stockRefreshed
    ? "estoque atualizado"
    : "estoque preservado ate o ciclo 5";
  const ratingsText = cycles.ratingsRefreshed
    ? "avaliacoes/visitas atualizadas"
    : "avaliacoes/visitas preservadas ate o ciclo 10";
  return [
    `${summary?.upserted ?? 0} produtos`,
    `${summary?.pricesPreserved ?? 0} precos preservados`,
    `${summary?.imagesCreated ?? 0} imagens novas`,
    stockText,
    ratingsText,
  ].join(" | ");
}

function finishProductsSyncProgress(summary = {}) {
  stopProductsSyncProgress();
  updateProductsSyncProgress({
    percent: 100,
    status: "Sincronizacao concluida.",
    detail: buildProductsSyncSummary(summary),
    tone: "success",
  });
}

function failProductsSyncProgress(message) {
  stopProductsSyncProgress();
  updateProductsSyncProgress({
    percent: Math.max(12, PRODUCTS_SYNC_PROGRESS_VALUE || 12),
    status: "Falha na sincronizacao.",
    detail: message || "Erro desconhecido.",
    tone: "error",
  });
}

function initSyncButtons() {
  const btnOrders = $("#btn-sync-orders");
  const btnProducts = $("#btn-sync-products");

  if (btnOrders) {
    btnOrders.addEventListener("click", async () => {
      setText("orders-sync-status", "Sincronizando pedidos...");
      ORDERS_SYNC_IN_PROGRESS = true;
      btnOrders.disabled = true;
      try {
        const res = await syncShopOrders();
        setText(
          "orders-sync-status",
          `OK • Processados: ${res?.summary?.processed ?? "—"}`,
        );
        await loadOrders();
      } catch (e) {
        setText("orders-sync-status", `Erro: ${e.message}`);
      } finally {
        ORDERS_SYNC_IN_PROGRESS = false;
        btnOrders.disabled = false;
      }
    });
  }

  if (btnProducts) {
    btnProducts.addEventListener("click", async () => {
      setText("products-sync-status", "Sincronizando produtos...");
      PRODUCTS_SYNC_IN_PROGRESS = true;
      btnProducts.disabled = true;
      startProductsSyncProgress();
      try {
        const res = await apiPost(
          `/shops/${SHOP_PATH_PLACEHOLDER}/products/sync`,
        );
        setText(
          "products-sync-status",
          `OK - ${buildProductsSyncSummary(res?.summary || {})}`,
        );
        finishProductsSyncProgress(res?.summary || {});
        await loadProducts();
      } catch (e) {
        setText("products-sync-status", `Erro: ${e.message}`);
        failProductsSyncProgress(e.message);
      } finally {
        PRODUCTS_SYNC_IN_PROGRESS = false;
        btnProducts.disabled = false;
      }
    });
  }
}

function initProductsToolbar() {
  bindProductsEditorBackButton();
  const pageSizeSel = $("#products-page-size");
  const sortBySel = $("#products-sort-by");
  const sortDirSel = $("#products-sort-dir");
  const statusSel = $("#products-status");

  const qInput = $("#products-q");
  const skuInput = $("#products-skus");
  const btnSearch = $("#products-search");
  const btnClear = $("#products-clear");
  const btnExport = $("#products-export");

  const first = $("#products-first");
  const prev = $("#products-prev");
  const next = $("#products-next");
  const last = $("#products-last");

  if (pageSizeSel) {
    pageSizeSel.value = String(PRODUCTS_PAGE_SIZE);
    pageSizeSel.addEventListener("change", async () => {
      PRODUCTS_PAGE_SIZE = Number(pageSizeSel.value);
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (sortBySel) {
    sortBySel.value = PRODUCTS_SORT_BY;
    sortBySel.addEventListener("change", async () => {
      PRODUCTS_SORT_BY = String(sortBySel.value || "updatedAt");
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (sortDirSel) {
    sortDirSel.value = PRODUCTS_SORT_DIR;
    sortDirSel.addEventListener("change", async () => {
      PRODUCTS_SORT_DIR = String(sortDirSel.value || "desc");
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (statusSel) {
    statusSel.value = PRODUCTS_STATUS_VALUE;
    statusSel.addEventListener("change", async () => {
      PRODUCTS_STATUS_VALUE = String(statusSel.value || "");
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (qInput) {
    qInput.value = PRODUCTS_Q;
  }

  if (skuInput) {
    skuInput.value = PRODUCTS_SKUS;
  }

  const doSearch = async () => {
    PRODUCTS_Q = String(qInput?.value || "").trim();
    PRODUCTS_SKUS = String(skuInput?.value || "").trim();
    PRODUCTS_PAGE = 1;
    await loadProducts();
  };

  if (btnSearch) btnSearch.addEventListener("click", doSearch);

  if (qInput) {
    qInput.addEventListener("keydown", async (e) => {
      if (e.key === "Enter") await doSearch();
    });
  }

  if (skuInput) {
    skuInput.addEventListener("keydown", async (e) => {
      if (e.key === "Enter") await doSearch();
    });
  }

  if (btnClear) {
    btnClear.addEventListener("click", async () => {
      if (qInput) qInput.value = "";
      if (skuInput) skuInput.value = "";
      if (statusSel) statusSel.value = "";
      PRODUCTS_Q = "";
      PRODUCTS_SKUS = "";
      PRODUCTS_STATUS_VALUE = "";
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (btnExport) {
    btnExport.addEventListener("click", async () => {
      PRODUCTS_Q = String(qInput?.value || "").trim();
      PRODUCTS_SKUS = String(skuInput?.value || "").trim();
      PRODUCTS_STATUS_VALUE = String(statusSel?.value || PRODUCTS_STATUS_VALUE || "");
      await exportProductsFilteredReport(btnExport);
    });
  }

  if (first) {
    first.addEventListener("click", async () => {
      PRODUCTS_PAGE = 1;
      await loadProducts();
    });
  }

  if (prev) {
    prev.addEventListener("click", async () => {
      PRODUCTS_PAGE = Math.max(1, PRODUCTS_PAGE - 1);
      await loadProducts();
    });
  }

  if (next) {
    next.addEventListener("click", async () => {
      PRODUCTS_PAGE = Math.min(PRODUCTS_TOTAL_PAGES, PRODUCTS_PAGE + 1);
      await loadProducts();
    });
  }

  if (last) {
    last.addEventListener("click", async () => {
      PRODUCTS_PAGE = PRODUCTS_TOTAL_PAGES;
      await loadProducts();
    });
  }
}
function initHeaderButtons() {
  const btnSwitch = document.getElementById("btn-switch-shop");
  const btnSidebarSwitch = document.getElementById("btn-sidebar-shop-toggle");
  const btnCreditWallet = document.getElementById("btn-credit-wallet");
  const btnLogout = document.getElementById("btn-logout");

  const openShopSwitcher = async () => {
    try {
      await loadMe();
      const shops = Array.isArray(ME?.shops) ? ME.shops : [];
      const role = String(ME?.user?.role || "");
      const activeShopId = ME?.activeShopId ?? null;

      openShopSwitcherModal({ shops, role, activeShopId });
    } catch (e) {
      openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
    }
  };

  if (btnSwitch) {
    btnSwitch.addEventListener("click", openShopSwitcher);
  }

  if (btnSidebarSwitch) {
    btnSidebarSwitch.addEventListener("click", openShopSwitcher);
  }

  if (btnCreditWallet) {
    btnCreditWallet.addEventListener("click", async () => {
      await showTab("billing-credits");
    });
  }

  document.getElementById("btnBillingCreditsRefresh")?.addEventListener("click", async () => {
    BILLING_CREDITS_POLICY = null;
    await loadBillingCreditsTab();
  });

  if (btnLogout) {
    btnLogout.addEventListener("click", async () => {
      try {
        await apiPost("/auth/logout");
      } catch (_) {}
      window.location.href = "/selecao-plataforma";
    });
  }
}

function openShopSwitcherModal({ shops, role, activeShopId }) {
  const canAddShop = role === "ADMIN" || role === "SUPER_ADMIN";
  const limitReached = shops.length >= 2;

  const shopsHtml = shops.length
    ? shops
        .map((s) => {
          const isActive =
            activeShopId != null && Number(s.id) === Number(activeShopId);

          const title = s.shopId
            ? `ShopId Shopee: ${escapeHtml(String(s.shopId))}`
            : "Loja";
          const region = s.region ? ` • ${escapeHtml(String(s.region))}` : "";
          const status = s.status ? ` • ${escapeHtml(String(s.status))}` : "";

          return `
            <button class="btn btn-primary" data-select-shop="${escapeHtml(
              String(s.id),
            )}" style="width:100%; margin-top:10px;">
              ${title}${region}${status}${isActive ? ` • (ATIVA)` : ""}
            </button>
          `;
        })
        .join("")
    : `<div class="muted" style="margin-top:10px;">Nenhuma loja vinculada.</div>`;

  const left = `
    <div style="flex:1; min-width:280px;">
      <div class="card-title">Lojas desta conta</div>
      <div class="muted" style="margin-top:6px;">Selecione qual deseja usar.</div>
      <div style="margin-top:10px;">${shopsHtml}</div>
    </div>
  `;

  const right = canAddShop
    ? `
      <div style="flex:1; min-width:280px;">
        <div class="card-title">Adicionar nova loja</div>
        <div class="muted" style="margin-top:6px;">
          ${
            limitReached
              ? "Limite de 2 lojas por conta atingido."
              : "Você pode adicionar mais 1 loja (limite 2)."
          }
        </div>
        <div style="margin-top:10px;">
          <button id="btn-add-shop" class="btn btn-primary" ${
            limitReached ? "disabled" : ""
          }>+ Adicionar nova loja</button>
        </div>
      </div>
    `
    : `
      <div style="flex:1; min-width:280px;">
        <div class="card-title">Adicionar nova loja</div>
        <div class="muted" style="margin-top:6px;">Somente usuários Admin podem adicionar lojas.</div>
      </div>
    `;

  openModal(
    "Trocar loja",
    `<div style="display:flex; gap:12px; flex-wrap:wrap; align-items:flex-start;">${left}${right}</div>`,
  );

  // selecionar loja (qualquer usuário pode)
  $all("[data-select-shop]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const shopId = Number(btn.getAttribute("data-select-shop"));
      try {
        await apiPost("/auth/select-shop", { shopId });
        closeModal();
        await loadMe();
        if (document.getElementById("tab-billing-credits")?.classList.contains("active")) {
          await loadBillingCreditsTab();
        }
      } catch (e) {
        openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
      }
    });
  });

  // adicionar loja (admin)
  const btnAdd = document.getElementById("btn-add-shop");
  if (btnAdd && !btnAdd.disabled) {
    btnAdd.addEventListener("click", async () => {
      try {
        const data = await apiGet("/auth/url?mode=add_shop");
        const url = data?.auth_url || null;
        if (url) window.location.href = url;
        else
          openModal(
            "Erro",
            `<div class="muted">Não foi possível gerar o link.</div>`,
          );
      } catch (e) {
        openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
      }
    });
  }
}

function getQueryParam(name) {
  const u = new URL(window.location.href);
  return u.searchParams.get(name);
}

function activateTab(tab) {
  const tabs = $all(".tab");
  const panels = $all(".tab-panel");

  tabs.forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  panels.forEach((p) => p.classList.toggle("active", p.id === `tab-${tab}`));
}

