function initControlPanel() {
  const reloadBtn = document.getElementById("btnControlPanelReload");
  const syncBtn = document.getElementById("btnControlPanelSyncShop");

  reloadBtn?.addEventListener("click", async () => {
    await loadControlPanel({ force: true });
  });

  syncBtn?.addEventListener("click", async () => {
    await runControlPanelShopSync({ origin: "manual" });
  });

  if (!CONTROL_PANEL_AUTO_SYNC_HANDLE) {
    CONTROL_PANEL_AUTO_SYNC_HANDLE = setInterval(() => {
      runControlPanelShopSync({ origin: "auto" });
    }, CONTROL_PANEL_AUTO_SYNC_MS);
  }
}

async function runControlPanelShopSync({ origin = "manual" } = {}) {
  if (CONTROL_PANEL_SYNC_IN_PROGRESS) return;

  const reloadBtn = document.getElementById("btnControlPanelReload");
  const syncBtn = document.getElementById("btnControlPanelSyncShop");
  const metaEl = document.getElementById("controlPanelAccountMeta");
  const originalSyncLabel = syncBtn?.textContent || "Sincronizar loja";
  const previousMetaText = metaEl?.textContent || "";
  const isAuto = origin === "auto";

  CONTROL_PANEL_SYNC_IN_PROGRESS = true;

  if (syncBtn) {
    syncBtn.disabled = true;
    syncBtn.textContent = isAuto
      ? "Sincronizando loja (auto)..."
      : "Sincronizando loja...";
  }
  if (reloadBtn) reloadBtn.disabled = true;
  if (metaEl) {
    metaEl.textContent = isAuto
      ? "Sincronizacao automatica em andamento (ciclo de 12 horas)..."
      : "Sincronizando pedidos e atualizando metricas de SAC e score de atividade...";
  }

  try {
    await ensureShopSelected();
    await syncShopOrders();
    await loadControlPanel({ force: true });
    await refreshOrdersAddressAlertsBadge();
    if (metaEl) {
      metaEl.textContent =
        "Sincronizacao concluida. Pedidos, SAC e score de atividade atualizados.";
    }
    if (isAuto && typeof window.shopeeNotify === "function") {
      window.shopeeNotify({
        title: "Sincronizacao automatica concluida",
        message: "A loja foi sincronizada automaticamente pelo ciclo de 12 horas.",
      });
    }
  } catch (e) {
    if (metaEl) {
      metaEl.textContent = `Erro na sincronizacao da loja: ${e.message}`;
    }
    if (isAuto && typeof window.shopeeNotify === "function") {
      window.shopeeNotify({
        title: "Falha na sincronizacao automatica",
        message: String(e?.message || "Erro desconhecido."),
        type: "error",
      });
    }
  } finally {
    if (syncBtn) {
      syncBtn.disabled = false;
      syncBtn.textContent = originalSyncLabel;
    }
    if (reloadBtn) reloadBtn.disabled = false;
    CONTROL_PANEL_SYNC_IN_PROGRESS = false;

    if (metaEl && previousMetaText && !metaEl.textContent?.startsWith("Erro")) {
      setTimeout(() => {
        if (
          metaEl.textContent ===
          "Sincronizacao concluida. Pedidos, SAC e score de atividade atualizados."
        ) {
          metaEl.textContent = previousMetaText;
        }
      }, 6000);
    }
  }
}

async function startAdsOauthFlow() {
  const btn = document.getElementById("btnAdsIntegrate");
  const msg = document.getElementById("cpcCampaignMsg");
  const originalLabel = btn?.textContent || "Integrar Ads";

  if (btn) {
    btn.disabled = true;
    btn.textContent = "Redirecionando...";
  }
  if (msg) {
    msg.textContent = "Gerando link de autorizacao do app de Ads...";
  }

  try {
    const data = await apiGet("/auth/ads/url");
    const url = data?.auth_url || data?.authUrl || data?.url || null;

    if (!url) {
      throw new Error("Nao foi possivel gerar o link de integracao de Ads.");
    }

    window.location.href = url;
  } catch (e) {
    if (msg) {
      msg.textContent = `Nao foi possivel iniciar a integracao de Ads: ${e.message}`;
    }
    if (btn) {
      btn.disabled = false;
      btn.textContent = originalLabel;
    }
  }
}

window.startAdsOauthFlow = startAdsOauthFlow;

async function startShopeeOauthFlowIfRequested() {
  const tab = getQueryParam("tab");
  const startOauth = getQueryParam("startOauth");

  if (tab && document.getElementById(`tab-${tab}`)) {
    await showTab(tab);
    const url = new URL(window.location.href);
    url.searchParams.delete("tab");
    url.searchParams.delete("startOauth");
    window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
  } else if (tab === "auth") {
    activateTab("auth");
  }
  if (startOauth !== "1") return;

  try {
    const data = await apiGet("/auth/url");
    const url = data?.auth_url || data?.authUrl || data?.url || null;

    const preview = document.getElementById("auth-url-preview");
    if (preview)
      preview.textContent = url ? url : "Não foi possível gerar o link.";

    if (url) window.location.href = url;
  } catch (e) {
    const preview = document.getElementById("auth-url-preview");
    if (preview) preview.textContent = `Erro ao gerar link: ${e.message}`;
  }
}

