function masterMirrorFormatDateTime(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return date.toLocaleString("pt-BR");
}

function masterMirrorHumanizeEventName(value) {
  return String(value || "")
    .trim()
    .replace(/_/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function masterMirrorSparkline(
  values,
  { stroke = "#2f69ff", fill = "rgba(47,105,255,0.16)", width = 240, height = 52 } = {},
) {
  const numeric = (Array.isArray(values) ? values : []).map((value) => Number(value || 0));
  const points = numeric.length ? numeric : [0];
  const max = Math.max(1, ...points);
  const step = points.length > 1 ? width / (points.length - 1) : 0;
  const coords = points.map((value, index) => {
    const x = points.length > 1 ? index * step : width / 2;
    const y = height - 4 - (value / max) * (height - 10);
    return { x, y };
  });
  const linePath = coords
    .map((point, index) => `${index === 0 ? "M" : "L"}${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
    .join(" ");
  const areaPath = `M0 ${height} ${coords
    .map((point) => `L${point.x.toFixed(2)} ${point.y.toFixed(2)}`)
    .join(" ")} L${width} ${height} Z`;

  return `
    <svg viewBox="0 0 ${width} ${height}" class="admin-master-sparkline" preserveAspectRatio="none" aria-hidden="true">
      <path d="${areaPath}" fill="${fill}"></path>
      <path d="${linePath}" fill="none" stroke="${stroke}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"></path>
    </svg>
  `;
}

function masterMirrorFormatDuration(durationMs) {
  const value = Number(durationMs);
  if (!Number.isFinite(value) || value < 0) return "—";
  if (value < 1000) return `${value} ms`;
  const seconds = value / 1000;
  if (seconds < 60) return `${seconds.toFixed(2)} s`;
  const minutes = Math.floor(seconds / 60);
  const remainingSec = Math.round(seconds % 60);
  return `${minutes}m ${remainingSec}s`;
}

