function destroyDashAdsCompareChart() {
  if (DASH_ADS_COMPARE_CHART) {
    DASH_ADS_COMPARE_CHART.destroy();
    DASH_ADS_COMPARE_CHART = null;
  }
}

function setDashAdsCompareBarWidth(id, ratioPct) {
  const el = document.getElementById(id);
  if (!el) return;
  const safe = Number.isFinite(Number(ratioPct))
    ? Math.max(0, Math.min(100, Number(ratioPct)))
    : 0;
  el.style.width = `${safe}%`;
}

function setDashAdsCompareCard({
  currentValue,
  previousValue,
  prevValueId,
  currentBarId,
  prevBarId,
  formatValue,
}) {
  const currentNumber = Number(currentValue);
  const previousNumber = Number(previousValue);

  const safeCurrent =
    Number.isFinite(currentNumber) && currentNumber > 0 ? currentNumber : 0;
  const safePrevious =
    Number.isFinite(previousNumber) && previousNumber > 0 ? previousNumber : 0;
  const peak = Math.max(safeCurrent, safePrevious, 0);

  const currentPct = peak > 0 ? (safeCurrent / peak) * 100 : 0;
  const previousPct = peak > 0 ? (safePrevious / peak) * 100 : 0;

  setText(prevValueId, formatValue(previousValue));
  setDashAdsCompareBarWidth(currentBarId, currentPct);
  setDashAdsCompareBarWidth(prevBarId, previousPct);
}

function formatDashAdsCompareCurrency(valueInCents) {
  const n = Number(valueInCents);
  if (!Number.isFinite(n)) return "-";
  return formatBRLCents(n);
}

function formatDashAdsComparePercent(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "-";
  return `${n.toFixed(2)}%`;
}

function formatDashAdsCompareCount(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "-";
  return n.toLocaleString("pt-BR");
}

function renderDashAdsComparisonChart({ current, previous }) {
  const canvas = document.getElementById("dashAdsCompareChart");
  const ctx = canvas?.getContext?.("2d");

  if (!ctx || !window.Chart) {
    destroyDashAdsCompareChart();
    return;
  }

  const chartTheme = getUiChartThemeColors();
  const isLight = document.body.classList.contains("theme-light");

  const rows = [
    {
      label: "Gasto Ads",
      current: Number(current?.metrics?.spendCents || 0),
      previous: Number(previous?.metrics?.spendCents || 0),
      format: formatDashAdsCompareCurrency,
    },
    {
      label: "TACOS",
      current: Number(current?.metrics?.tacosPct || 0),
      previous: Number(previous?.metrics?.tacosPct || 0),
      format: formatDashAdsComparePercent,
    },
    {
      label: "Pedidos Ads",
      current: Number(current?.counts?.ordersMatched || 0),
      previous: Number(previous?.counts?.ordersMatched || 0),
      format: formatDashAdsCompareCount,
    },
    {
      label: "Share Ads",
      current: Number(current?.metrics?.adsRevenueSharePct || 0),
      previous: Number(previous?.metrics?.adsRevenueSharePct || 0),
      format: formatDashAdsComparePercent,
    },
  ];

  const computeDeltaPct = (currentValue, previousValue) => {
    const curr = Number(currentValue);
    const prev = Number(previousValue);
    if (!Number.isFinite(curr) || !Number.isFinite(prev) || prev <= 0) return null;
    return Number((((curr - prev) / prev) * 100).toFixed(2));
  };

  const deltas = rows.map((row) => computeDeltaPct(row.current, row.previous));
  const finiteDeltas = deltas.filter((value) => Number.isFinite(value));
  const maxAbs = finiteDeltas.length
    ? Math.max(...finiteDeltas.map((value) => Math.abs(value)), 5)
    : 5;
  const axisPadding = Math.max(5, Math.ceil(maxAbs * 0.15));
  const axisLimit = Math.ceil(maxAbs + axisPadding);

  destroyDashAdsCompareChart();

  DASH_ADS_COMPARE_CHART = new Chart(ctx, {
    type: "bar",
    data: {
      labels: rows.map((row) => row.label),
      datasets: [
        {
          label: "Variação MTD vs mês anterior (%)",
          data: deltas,
          borderRadius: 8,
          borderSkipped: false,
          backgroundColor: (context) => {
            const value = Number(context?.raw);
            const isPositive = !Number.isFinite(value) || value >= 0;
            if (isPositive) {
              return isLight ? "rgba(34,197,94,0.58)" : "rgba(34,197,94,0.52)";
            }
            return isLight ? "rgba(239,68,68,0.56)" : "rgba(248,113,113,0.50)";
          },
          borderColor: (context) => {
            const value = Number(context?.raw);
            const isPositive = !Number.isFinite(value) || value >= 0;
            if (isPositive) {
              return isLight ? "rgba(22,163,74,0.92)" : "rgba(74,222,128,0.92)";
            }
            return isLight ? "rgba(220,38,38,0.92)" : "rgba(252,165,165,0.92)";
          },
          borderWidth: 1,
        },
      ],
    },
    options: {
      indexAxis: "y",
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "nearest", intersect: false },
      plugins: {
        legend: {
          display: true,
          labels: { color: chartTheme.legend },
        },
        tooltip: {
          displayColors: true,
          backgroundColor: chartTheme.tooltipBg,
          borderColor: chartTheme.tooltipBorder,
          borderWidth: 1,
          titleColor: chartTheme.tooltipTitle,
          bodyColor: chartTheme.tooltipBody,
          callbacks: {
            title(context) {
              const point = Array.isArray(context) ? context[0] : null;
              const idx = Number(point?.dataIndex || 0);
              return rows[idx]?.label || "Métrica";
            },
            label(context) {
              const idx = Number(context?.dataIndex || 0);
              const row = rows[idx];
              if (!row) return "";
              const value = Number(context?.parsed?.x);
              if (!Number.isFinite(value)) return "Variação: sem base comparativa";
              return `Variação: ${value > 0 ? "+" : ""}${value.toFixed(2)}%`;
            },
            afterBody(context) {
              const point = Array.isArray(context) ? context[0] : null;
              const idx = Number(point?.dataIndex || 0);
              const row = rows[idx];
              if (!row) return [];
              return [
                `Atual: ${row.format(row.current)}`,
                `Anterior: ${row.format(row.previous)}`,
              ];
            },
          },
        },
      },
      scales: {
        x: {
          min: -axisLimit,
          max: axisLimit,
          grid: { color: chartTheme.grid },
          ticks: {
            color: chartTheme.axis,
            callback(value) {
              const n = Number(value);
              if (!Number.isFinite(n)) return value;
              return `${n > 0 ? "+" : ""}${n}%`;
            },
          },
        },
        y: {
          grid: { display: false },
          ticks: { color: chartTheme.axis },
        },
      },
    },
  });
}

function renderDashAdsComparisonWidgets(data) {
  if (!data?.metrics || !data?.counts) {
    const emptyValueIds = [
      "dashAdsSpendPrev",
      "dashAdsTacosPrev",
      "dashAdsOrdersPrev",
      "dashAdsSharePrev",
    ];

    emptyValueIds.forEach((id) => setText(id, "-"));

    const emptyBarIds = [
      "dashAdsSpendBarCurrent",
      "dashAdsSpendBarPrev",
      "dashAdsTacosBarCurrent",
      "dashAdsTacosBarPrev",
      "dashAdsOrdersBarCurrent",
      "dashAdsOrdersBarPrev",
      "dashAdsShareBarCurrent",
      "dashAdsShareBarPrev",
    ];

    emptyBarIds.forEach((id) => setDashAdsCompareBarWidth(id, 0));
    setText("dashAdsCompareHint", "Indice por metrica (0 a 100)");
    destroyDashAdsCompareChart();
    return;
  }

  const previous = data?.mom?.previous || {};

  setDashAdsCompareCard({
    currentValue: data?.metrics?.spendCents,
    previousValue: previous?.metrics?.spendCents,
    prevValueId: "dashAdsSpendPrev",
    currentBarId: "dashAdsSpendBarCurrent",
    prevBarId: "dashAdsSpendBarPrev",
    formatValue: formatDashAdsCompareCurrency,
  });

  setDashAdsCompareCard({
    currentValue: data?.metrics?.tacosPct,
    previousValue: previous?.metrics?.tacosPct,
    prevValueId: "dashAdsTacosPrev",
    currentBarId: "dashAdsTacosBarCurrent",
    prevBarId: "dashAdsTacosBarPrev",
    formatValue: formatDashAdsComparePercent,
  });

  setDashAdsCompareCard({
    currentValue: data?.counts?.ordersMatched,
    previousValue: previous?.counts?.ordersMatched,
    prevValueId: "dashAdsOrdersPrev",
    currentBarId: "dashAdsOrdersBarCurrent",
    prevBarId: "dashAdsOrdersBarPrev",
    formatValue: formatDashAdsCompareCount,
  });

  setDashAdsCompareCard({
    currentValue: data?.metrics?.adsRevenueSharePct,
    previousValue: previous?.metrics?.adsRevenueSharePct,
    prevValueId: "dashAdsSharePrev",
    currentBarId: "dashAdsShareBarCurrent",
    prevBarId: "dashAdsShareBarPrev",
    formatValue: formatDashAdsComparePercent,
  });

  const req = data?.request || {};
  const cmp = req?.compare || {};
  const hint = req?.dateFrom && req?.dateTo && cmp?.previousDateFrom && cmp?.previousDateTo
    ? `Atual ${req.dateFrom} -> ${req.dateTo} | Anterior ${cmp.previousDateFrom} -> ${cmp.previousDateTo}`
    : "Variacao percentual por metrica (MTD vs mes anterior)";
  setText("dashAdsCompareHint", hint);

  renderDashAdsComparisonChart({
    current: {
      metrics: data?.metrics || {},
      counts: data?.counts || {},
    },
    previous,
  });
}

function renderDashboardAdsMtdKpis(data, { label } = {}) {
  const hasPayload = Boolean(data?.metrics && data?.counts);

  if (!hasPayload) {
    setText("dashAdsSpend", "-");
    setText("dashAdsTacos", "-");
    setText("dashAdsOrders", "-");
    setText("dashAdsShare", "-");
    setKpiMoMText("dashAdsSpendMoM", "MoM: -", 0);
    setKpiMoMText("dashAdsTacosMoM", "MoM: -", 0);
    setKpiMoMText("dashAdsOrdersMoM", "MoM: -", 0);
    setKpiMoMText("dashAdsShareMoM", "MoM: -", 0);

    const badgeUnavailable = document.getElementById("dashAdsBadge");
    if (badgeUnavailable) {
      badgeUnavailable.className = "badge badge--gray";
      badgeUnavailable.textContent = "Indisponivel";
    }

    renderDashAdsComparisonWidgets(null);
    setText("dashAdsMeta", label || "-");
    return;
  }

  const spendCents = Number(data?.metrics?.spendCents || 0);
  const tacosPct = data?.metrics?.tacosPct;
  const adsRevenueSharePct = data?.metrics?.adsRevenueSharePct;
  const ordersMatched = Number(data?.counts?.ordersMatched || 0);

  setText("dashAdsSpend", formatBRLCents(spendCents));
  setText(
    "dashAdsTacos",
    tacosPct == null ? "-" : `${Number(tacosPct).toFixed(2)}%`,
  );
  setText("dashAdsOrders", String(ordersMatched));
  setText(
    "dashAdsShare",
    adsRevenueSharePct == null ? "-" : `${Number(adsRevenueSharePct).toFixed(2)}%`,
  );

  const momDelta = data?.mom?.delta || {};
  setKpiMoMText(
    "dashAdsSpendMoM",
    formatMoMPercentTextClean(momDelta?.spendPct),
    momDelta?.spendPct,
  );
  setKpiMoMText(
    "dashAdsTacosMoM",
    formatMoMPpTextClean(momDelta?.tacosPp),
    momDelta?.tacosPp,
  );
  setKpiMoMText(
    "dashAdsOrdersMoM",
    formatMoMPercentTextClean(momDelta?.ordersMatchedPct),
    momDelta?.ordersMatchedPct,
  );
  setKpiMoMText(
    "dashAdsShareMoM",
    formatMoMPpTextClean(momDelta?.adsRevenueSharePp),
    momDelta?.adsRevenueSharePp,
  );

  const badge = document.getElementById("dashAdsBadge");
  if (badge) {
    badge.className =
      "badge " + (spendCents > 0 ? "badge--top" : "badge--gray");
    badge.textContent = spendCents > 0 ? "MTD ativo" : "Sem gasto";
  }

  renderDashAdsComparisonWidgets(data);

  const req = data?.request || {};
  const cmp = req?.compare || {};
  const generatedLabel =
    req?.dateFrom && req?.dateTo && cmp?.previousDateFrom && cmp?.previousDateTo
      ? `Periodo MTD: ${req.dateFrom} -> ${req.dateTo} | MoM: ${cmp.previousDateFrom} -> ${cmp.previousDateTo}`
      : req?.dateFrom && req?.dateTo
        ? `Periodo MTD: ${req.dateFrom} -> ${req.dateTo}`
        : "-";

  setText("dashAdsMeta", label || generatedLabel);
}

async function apiPatch(path, body) {
  path = normalizeApiPath(path);
  const r = await fetch(path, {
    method: "PATCH",
    credentials: "include",
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await r.text();
  if (!r.ok) throw new Error(text || `HTTP ${r.status}`);
  return text ? JSON.parse(text) : null;
}

function getLogisticsProcessUi() {
  const panel = document.getElementById("logisticsProcessPanel");
  if (!panel) return null;

  return {
    panel,
    title: panel.querySelector("#logisticsProcessTitle"),
    meta: panel.querySelector("#logisticsProcessMeta"),
    badge: panel.querySelector("#logisticsProcessBadge"),
    bar: panel.querySelector("#logisticsProcessBar"),
    counter: panel.querySelector("#logisticsProcessCounter"),
    percent: panel.querySelector("#logisticsProcessPercent"),
    logs: panel.querySelector("#logisticsProcessLogs"),
    exportBtn: panel.querySelector("#btnLogisticsProcessExport"),
    closeBtn: panel.querySelector("#btnLogisticsProcessClose"),
  };
}

function updateLogisticsProcessProgress(done, total, success, failed) {
  const ui = getLogisticsProcessUi();
  if (!ui) return;
  const safeTotal = Math.max(0, Number(total || 0));
  const safeDone = Math.max(0, Number(done || 0));
  const pct = safeTotal > 0 ? Math.round((safeDone / safeTotal) * 100) : 0;

  if (ui.counter) ui.counter.textContent = `${safeDone}/${safeTotal}`;
  if (ui.percent) ui.percent.textContent = `${pct}%`;
  if (ui.bar) ui.bar.style.width = `${pct}%`;
  if (ui.meta) {
    ui.meta.textContent =
      `Concluidos ${safeDone}/${safeTotal} - sucesso ${Number(success || 0)} - falhas ${Number(failed || 0)}`;
  }
  syncGlobalTrackedProcessProgress(LOGISTICS_PROCESS_STATE?.globalProcessId, {
    done: safeDone,
    total: safeTotal,
    success: Number(success || 0),
    failed: Number(failed || 0),
  });
}

function appendLogisticsProcessLog(message, tone = "info") {
  if (!LOGISTICS_PROCESS_STATE) return;
  const ui = getLogisticsProcessUi();
  if (!ui) return;

  const stamp = new Date().toLocaleTimeString("pt-BR", { hour12: false });
  const line = `[${stamp}] ${String(message || "")}`;
  LOGISTICS_PROCESS_STATE.logs.push(line);
  appendGlobalTrackedProcessLog(LOGISTICS_PROCESS_STATE.globalProcessId, line, tone);

  if (!ui.logs) return;
  const row = document.createElement("div");
  row.className = `logistics-process-log logistics-process-log--${tone}`;
  row.textContent = line;
  ui.logs.appendChild(row);
  ui.logs.scrollTop = ui.logs.scrollHeight;
}

function startLogisticsProcess(actionLabel, total) {
  const processId = beginGlobalTrackedProcess("Central Logística", actionLabel, total);
  LOGISTICS_PROCESS_STATE = {
    actionLabel: String(actionLabel || "Processo"),
    startedAt: new Date().toLocaleString("pt-BR"),
    total: Number(total || 0),
    done: 0,
    success: 0,
    failed: 0,
    logs: [],
    finished: false,
    globalProcessId: processId,
  };

  const ui = getLogisticsProcessUi();
  if (!ui) return;

  ui.panel.classList.remove("is-hidden");
  if (ui.title) ui.title.textContent = LOGISTICS_PROCESS_STATE.actionLabel;
  if (ui.badge) {
    ui.badge.textContent = "Em andamento";
    ui.badge.classList.remove("is-success", "is-warning");
    ui.badge.classList.add("is-running");
  }
  if (ui.logs) ui.logs.innerHTML = "";
  if (ui.exportBtn) ui.exportBtn.disabled = true;
  updateLogisticsProcessProgress(0, LOGISTICS_PROCESS_STATE.total, 0, 0);
  appendLogisticsProcessLog(
    `Processo iniciado para ${LOGISTICS_PROCESS_STATE.total} produto(s).`,
    "info",
  );
}

function finishLogisticsProcess(summaryMessage) {
  if (!LOGISTICS_PROCESS_STATE) return;
  LOGISTICS_PROCESS_STATE.finished = true;
  appendLogisticsProcessLog(summaryMessage, "info");

  const ui = getLogisticsProcessUi();
  if (!ui) return;

  if (ui.exportBtn) ui.exportBtn.disabled = false;
  if (ui.badge) {
    const hasFailure = Number(LOGISTICS_PROCESS_STATE.failed || 0) > 0;
    ui.badge.textContent = hasFailure ? "Concluido com alertas" : "Concluido";
    ui.badge.classList.remove("is-running");
    ui.badge.classList.toggle("is-warning", hasFailure);
    ui.badge.classList.toggle("is-success", !hasFailure);
  }
  finishGlobalTrackedProcess(LOGISTICS_PROCESS_STATE.globalProcessId, {
    summaryMessage: String(summaryMessage || ""),
    hasWarning: Number(LOGISTICS_PROCESS_STATE.failed || 0) > 0,
  });
}

function closeLogisticsProcessPanel() {
  const ui = getLogisticsProcessUi();
  if (!ui?.panel) return;
  ui.panel.classList.add("is-hidden");
}

function downloadLogisticsProcessLogs() {
  if (!LOGISTICS_PROCESS_STATE) return;
  const lines = [
    `Processo: ${LOGISTICS_PROCESS_STATE.actionLabel || "Logistica"}`,
    `Inicio: ${LOGISTICS_PROCESS_STATE.startedAt || "-"}`,
    `Total: ${Number(LOGISTICS_PROCESS_STATE.total || 0)}`,
    `Concluidos: ${Number(LOGISTICS_PROCESS_STATE.done || 0)}`,
    `Sucesso: ${Number(LOGISTICS_PROCESS_STATE.success || 0)}`,
    `Falhas: ${Number(LOGISTICS_PROCESS_STATE.failed || 0)}`,
    "",
    ...(Array.isArray(LOGISTICS_PROCESS_STATE.logs) ? LOGISTICS_PROCESS_STATE.logs : []),
  ];
  const blob = new Blob([lines.join("\n")], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `logistica-processo-${new Date().toISOString().replace(/[:.]/g, "-")}.txt`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function bindLogisticsProcessPanelActions() {
  const ui = getLogisticsProcessUi();
  if (!ui?.panel || ui.panel.dataset.bound === "1") return;
  ui.panel.dataset.bound = "1";
  ui.closeBtn?.addEventListener("click", closeLogisticsProcessPanel);
  ui.exportBtn?.addEventListener("click", downloadLogisticsProcessLogs);
}

function inferLogisticsResultSuccess(row) {
  if (typeof row?.ok === "boolean") return row.ok;
  if (typeof row?.success === "boolean") return row.success;

  const status = String(row?.status || row?.result || "")
    .trim()
    .toLowerCase();
  if (status) {
    if (["erro", "error", "falha", "failed"].includes(status)) return false;
    if (["ok", "success", "sucesso", "enabled", "habilitado"].includes(status))
      return true;
  }

  const message = String(row?.message || "").toLowerCase();
  if (/(erro|falha|não foi possível|nao foi possivel|inválido|invalido|rejeitado|não permitido|nao permitido)/i.test(message)) {
    return false;
  }
  return true;
}

function processLogisticsResultRows(rows, expectedItemIds = [], actionLabel = "Logistica") {
  if (!LOGISTICS_PROCESS_STATE) return;

  const byId = new Map();
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const key = String(row?.itemId || "").trim();
    if (key) byId.set(key, row);
  });

  expectedItemIds.forEach((itemId) => {
    const row = byId.get(itemId);
    const title =
      row?.title || row?.name || row?.productName || `Item ${itemId || "sem id"}`;
    const message = String(row?.message || "").trim();
    const ok = inferLogisticsResultSuccess(row || {});

    LOGISTICS_PROCESS_STATE.done += 1;
    if (ok) {
      LOGISTICS_PROCESS_STATE.success += 1;
    } else {
      LOGISTICS_PROCESS_STATE.failed += 1;
    }

    appendLogisticsProcessLog(
      `${ok ? "Sucesso" : "Falha"} ao ${actionLabel.toLowerCase()} ${title}${message ? ` - ${message}` : ""}.`,
      ok ? "success" : "error",
    );
    updateLogisticsProcessProgress(
      LOGISTICS_PROCESS_STATE.done,
      LOGISTICS_PROCESS_STATE.total,
      LOGISTICS_PROCESS_STATE.success,
      LOGISTICS_PROCESS_STATE.failed,
    );
  });
}

function formatShopStatus(status) {
  const normalized = String(status || "").trim();
  return normalized || "—";
}

function renderLogisticsChannelBadges(shop) {
  const channels = Array.isArray(shop?.logistics) ? shop.logistics : [];
  const visibleChannels = channels.filter((channel) => channel.kind !== "other");

  if (!visibleChannels.length) {
    return '<span class="badge badge--gray">Sem canais</span>';
  }

  return visibleChannels
    .map((channel) => {
      const tone = channel.enabled ? "badge--green" : "badge--gray";
      return `<span class="badge ${tone}" style="margin-right:6px;margin-bottom:6px;">${escapeHtml(channel.name || channel.label || "Canal")}</span>`;
    })
    .join("");
}

function getHeavyLogisticsItems() {
  const enabled = Array.isArray(LOGISTICS_DATA?.heavy?.enabled)
    ? LOGISTICS_DATA.heavy.enabled
    : [];
  const eligible = Array.isArray(LOGISTICS_DATA?.heavy?.eligible)
    ? LOGISTICS_DATA.heavy.eligible
    : [];
  const byId = new Map();

  enabled.forEach((item) => {
    const itemId = String(item?.itemId || "").trim();
    if (itemId) byId.set(itemId, { ...item, heavyEnabled: true });
  });
  eligible.forEach((item) => {
    const itemId = String(item?.itemId || "").trim();
    if (!itemId || byId.has(itemId)) return;
    byId.set(itemId, { ...item, heavyEnabled: false });
  });
  return Array.from(byId.values());
}

function updateHeavyLogisticsSelection() {
  const count = LOGISTICS_SELECTED_HEAVY_IDS.size;
  setText(
    "logisticsHeavyCount",
    count
      ? `${count} selecionado${count === 1 ? "" : "s"}`
      : "Selecione produtos para liberar as acoes",
  );

  const toggle = document.getElementById("logisticsHeavySelectAll");
  const visibleIds = $all(".logistics-heavy-checkbox")
    .map((input) => String(input.value || "").trim())
    .filter(Boolean);
  if (toggle) {
    toggle.checked =
      visibleIds.length > 0 &&
      visibleIds.every((itemId) => LOGISTICS_SELECTED_HEAVY_IDS.has(itemId));
  }

  ["btnEnableSelectedHeavy", "btnDisableSelectedHeavy"].forEach((id) => {
    const button = document.getElementById(id);
    if (!button) return;
    button.disabled = count === 0;
    button.title = count === 0 ? "Selecione ao menos um produto primeiro" : "";
  });
}

function renderHeavyLogisticsPanel() {
  const body = document.getElementById("logisticsHeavyBody");
  if (!body) return;

  const allItems = getHeavyLogisticsItems();
  const filteredItems = filterLogisticsItems(allItems, LOGISTICS_HEAVY_QUERY);
  const allIds = new Set(
    allItems.map((item) => String(item?.itemId || "").trim()),
  );
  LOGISTICS_SELECTED_HEAVY_IDS = new Set(
    Array.from(LOGISTICS_SELECTED_HEAVY_IDS).filter((itemId) => allIds.has(itemId)),
  );
  body.innerHTML = filteredItems.length
    ? filteredItems
        .map((item) => {
          const itemId = String(item?.itemId || "").trim();
          const checked = LOGISTICS_SELECTED_HEAVY_IDS.has(itemId) ? "checked" : "";
          const state = item.heavyEnabled ? "Habilitada" : "Disponivel";
          const tone = item.heavyEnabled ? "badge--green" : "badge--gray";
          return `
            <tr class="logistics-row" data-logistics-item-id="${escapeHtml(itemId)}">
              <td><input class="logistics-heavy-checkbox" type="checkbox" value="${escapeHtml(itemId)}" ${checked} /></td>
              <td>${escapeHtml(itemId || "-")}</td>
              <td>${escapeHtml(item.title || "-")}</td>
              <td><span class="badge ${tone}">${state}</span></td>
              <td>${renderLogisticsChannelBadges(item)}</td>
            </tr>`;
        })
        .join("")
    : `<tr><td colspan="5"><div class="muted ui-state ui-state--empty">Nenhum produto com Entrega de Item Grande/Pesado disponivel nesta loja.</div></td></tr>`;

  setText(
    "logisticsHeavySummary",
    `${filteredItems.length} de ${allItems.length} produto(s) com o canal de pesados disponivel.`,
  );
  $all(".logistics-heavy-checkbox").forEach((input) => {
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;
      if (input.checked) LOGISTICS_SELECTED_HEAVY_IDS.add(itemId);
      else LOGISTICS_SELECTED_HEAVY_IDS.delete(itemId);
      updateHeavyLogisticsSelection();
    });
  });
  $all("#logisticsHeavyBody [data-logistics-item-id]").forEach((row) => {
    row.addEventListener("click", async (event) => {
      if (event.target.closest("input, button, label, a")) return;
      const itemId = String(row.dataset.logisticsItemId || "").trim();
      if (itemId) await openProductDetail(itemId);
    });
  });
  updateHeavyLogisticsSelection();
}

async function configureHeavyLogistics(itemIds, enable) {
  const validItemIds = Array.from(
    new Set(
      (Array.isArray(itemIds) ? itemIds : [])
        .map((itemId) => String(itemId || "").trim())
        .filter((itemId) => /^\\d+$/.test(itemId)),
    ),
  );
  if (!validItemIds.length) {
    openModal("Atencao", '<div class="muted">Selecione ao menos um produto.</div>');
    return;
  }

  const actionLabel = enable
    ? "Ativacao de Entrega de Item Grande/Pesado"
    : "Desativacao de Entrega de Item Grande/Pesado";
  const targetKinds = enable ? ["seller", "heavy"] : ["seller"];
  const confirmation = enable
    ? "Ativar Entrega de Item Grande/Pesado e Logistica do vendedor? SPX e Expresso Aereo serao desativados nesses anuncios."
    : "Desativar Entrega de Item Grande/Pesado e manter Logistica do vendedor nos anuncios selecionados?";
  if (!window.confirm(confirmation)) return;

  startLogisticsProcess(actionLabel, validItemIds.length);
  appendLogisticsProcessLog("Enviando configuracao para a fila assincrona...", "info");
  try {
    const enqueueResult = await enqueueAsyncProcessJob("logistics.configure", {
      itemIds: validItemIds,
      targetKinds,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );
    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) =>
        appendLogisticsProcessLog(
          `Status do job: ${String(snapshot?.status || "waiting").toUpperCase()}`,
          "info",
        ),
    });
    const result = extractAsyncProcessPayload(status);
    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(
      rows,
      validItemIds,
      enable ? "ativar entrega pesada" : "desativar entrega pesada",
    );
    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );
    await loadLogistics();
  } catch (error) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = validItemIds.length;
      LOGISTICS_PROCESS_STATE.failed = validItemIds.length;
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral: ${String(error?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        validItemIds.length,
        validItemIds.length,
        0,
        validItemIds.length,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(error.message)}</div>`);
  }
}

