function bindLogisticsTableInteractions() {
  $all("[data-logistics-item-id]").forEach((row) => {
    row.addEventListener("click", async (event) => {
      if (event.target.closest("button, input, label, a")) return;

      const itemId = String(row.dataset.logisticsItemId || "").trim();
      if (itemId) await openProductDetail(itemId);
    });
  });

  $all(".logistics-eligible-checkbox").forEach((input) => {
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;

      if (input.checked) {
        LOGISTICS_SELECTED_ELIGIBLE_IDS.add(itemId);
      } else {
        LOGISTICS_SELECTED_ELIGIBLE_IDS.delete(itemId);
      }

      updateLogisticsEligibleCount();
      updateLogisticsSelectAllState();
    });
  });

  $all(".logistics-enabled-checkbox").forEach((input) => {
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;

      if (input.checked) {
        LOGISTICS_SELECTED_ENABLED_IDS.add(itemId);
      } else {
        LOGISTICS_SELECTED_ENABLED_IDS.delete(itemId);
      }

      updateLogisticsEnabledCount();
      updateLogisticsEnabledSelectAllState();
    });
  });

  $all(".logistics-seller-checkbox").forEach((input) => {
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;

      if (input.checked) {
        LOGISTICS_SELECTED_SELLER_IDS.add(itemId);
      } else {
        LOGISTICS_SELECTED_SELLER_IDS.delete(itemId);
      }

      updateLogisticsSellerEligibleCount();
      updateLogisticsSellerSelectAllState();
    });
  });

  $all(".logistics-seller-enabled-checkbox").forEach((input) => {
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;

      if (input.checked) {
        LOGISTICS_SELECTED_SELLER_ENABLED_IDS.add(itemId);
      } else {
        LOGISTICS_SELECTED_SELLER_ENABLED_IDS.delete(itemId);
      }

      updateLogisticsSellerEnabledCount();
      updateLogisticsSellerEnabledSelectAllState();
    });
  });

  $all(".btn-enable-single-spx").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const itemId = String(btn.dataset.itemId || "").trim();
      await enableSelectedSpx([itemId]);
    });
  });

  $all(".btn-enable-single-seller").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const itemId = String(btn.dataset.itemId || "").trim();
      await enableSelectedSellerLogistics([itemId]);
    });
  });

  $all(".btn-disable-single-spx").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const itemId = String(btn.dataset.itemId || "").trim();
      await disableSelectedSpx([itemId]);
    });
  });

  $all(".btn-disable-single-seller").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const itemId = String(btn.dataset.itemId || "").trim();
      await disableSelectedSellerLogistics([itemId]);
    });
  });
}

function renderLogisticsTables(data) {
  LOGISTICS_DATA = data || {
    shops: [],
    spx: { enabled: [], eligible: [] },
    seller: { enabled: [], eligible: [] },
  };
  const enabledBody = document.getElementById("logisticsEnabledBody");
  const eligibleBody = document.getElementById("logisticsEligibleBody");
  const sellerEnabledBody = document.getElementById("logisticsSellerEnabledBody");
  const sellerEligibleBody = document.getElementById("logisticsSellerEligibleBody");
  const enabledAll = Array.isArray(LOGISTICS_DATA?.spx?.enabled)
    ? LOGISTICS_DATA.spx.enabled
    : [];
  const eligibleAll = Array.isArray(LOGISTICS_DATA?.spx?.eligible)
    ? LOGISTICS_DATA.spx.eligible
    : [];
  const sellerEnabledAll = Array.isArray(LOGISTICS_DATA?.seller?.enabled)
    ? LOGISTICS_DATA.seller.enabled
    : [];
  const sellerEligibleAll = Array.isArray(LOGISTICS_DATA?.seller?.eligible)
    ? LOGISTICS_DATA.seller.eligible
    : [];
  const enabledFiltered = filterLogisticsItems(enabledAll, LOGISTICS_SPX_QUERY);
  const eligibleFiltered = filterLogisticsItems(eligibleAll, LOGISTICS_SPX_QUERY);
  const sellerEnabledFiltered = filterLogisticsItems(
    sellerEnabledAll,
    LOGISTICS_SELLER_QUERY,
  );
  const sellerEligibleFiltered = filterLogisticsItems(
    sellerEligibleAll.filter(
      (item) =>
        !Boolean(item?.spxEnabled) &&
        !hasSellerChannelEnabledForLogisticsItem(item),
    ),
    LOGISTICS_SELLER_QUERY,
  );
  LOGISTICS_FILTERED_ELIGIBLE_IDS = eligibleFiltered.map((item) =>
    String(item.itemId || "").trim(),
  );
  LOGISTICS_FILTERED_ENABLED_IDS = enabledFiltered.map((item) =>
    String(item.itemId || "").trim(),
  );
  LOGISTICS_FILTERED_SELLER_IDS = sellerEligibleFiltered.map((item) =>
    String(item.itemId || "").trim(),
  );
  LOGISTICS_FILTERED_SELLER_ENABLED_IDS = sellerEnabledFiltered.map((item) =>
    String(item.itemId || "").trim(),
  );

  const allEnabledIds = enabledAll.map((item) => String(item?.itemId || "").trim());
  const allEligibleIds = eligibleAll.map((item) => String(item?.itemId || "").trim());
  const allSellerEnabledIds = sellerEnabledAll.map((item) =>
    String(item?.itemId || "").trim(),
  );
  const allSellerEligibleIds = sellerEligibleAll
    .filter(
      (item) =>
        !Boolean(item?.spxEnabled) &&
        !hasSellerChannelEnabledForLogisticsItem(item),
    )
    .map((item) => String(item?.itemId || "").trim());

  LOGISTICS_SELECTED_ENABLED_IDS = new Set(
    Array.from(LOGISTICS_SELECTED_ENABLED_IDS).filter((itemId) =>
      allEnabledIds.includes(itemId),
    ),
  );
  LOGISTICS_SELECTED_ELIGIBLE_IDS = new Set(
    Array.from(LOGISTICS_SELECTED_ELIGIBLE_IDS).filter((itemId) =>
      allEligibleIds.includes(itemId),
    ),
  );
  LOGISTICS_SELECTED_SELLER_ENABLED_IDS = new Set(
    Array.from(LOGISTICS_SELECTED_SELLER_ENABLED_IDS).filter((itemId) =>
      allSellerEnabledIds.includes(itemId),
    ),
  );
  LOGISTICS_SELECTED_SELLER_IDS = new Set(
    Array.from(LOGISTICS_SELECTED_SELLER_IDS).filter((itemId) =>
      allSellerEligibleIds.includes(itemId),
    ),
  );

  const enabledPage = paginateLogisticsItems(
    enabledFiltered,
    LOGISTICS_ENABLED_PAGE,
    LOGISTICS_ENABLED_PAGE_SIZE,
  );
  LOGISTICS_ENABLED_PAGE = enabledPage.page;
  LOGISTICS_ENABLED_TOTAL_PAGES = enabledPage.totalPages;

  const eligiblePage = paginateLogisticsItems(
    eligibleFiltered,
    LOGISTICS_ELIGIBLE_PAGE,
    LOGISTICS_ELIGIBLE_PAGE_SIZE,
  );
  LOGISTICS_ELIGIBLE_PAGE = eligiblePage.page;
  LOGISTICS_ELIGIBLE_TOTAL_PAGES = eligiblePage.totalPages;

  const sellerEnabledPage = paginateLogisticsItems(
    sellerEnabledFiltered,
    LOGISTICS_SELLER_ENABLED_PAGE,
    LOGISTICS_SELLER_ENABLED_PAGE_SIZE,
  );
  LOGISTICS_SELLER_ENABLED_PAGE = sellerEnabledPage.page;
  LOGISTICS_SELLER_ENABLED_TOTAL_PAGES = sellerEnabledPage.totalPages;

  const sellerEligiblePage = paginateLogisticsItems(
    sellerEligibleFiltered,
    LOGISTICS_SELLER_ELIGIBLE_PAGE,
    LOGISTICS_SELLER_ELIGIBLE_PAGE_SIZE,
  );
  LOGISTICS_SELLER_ELIGIBLE_PAGE = sellerEligiblePage.page;
  LOGISTICS_SELLER_ELIGIBLE_TOTAL_PAGES = sellerEligiblePage.totalPages;

  if (enabledBody) {
    enabledBody.innerHTML = enabledPage.items.length
      ? enabledPage.items
          .map((shop) => {
            const itemId = String(shop.itemId || "").trim();
            const checked = LOGISTICS_SELECTED_ENABLED_IDS.has(itemId)
              ? "checked"
              : "";

            return `
              <tr class="logistics-row" data-logistics-item-id="${escapeHtml(itemId)}">
                <td><input class="logistics-enabled-checkbox" type="checkbox" value="${escapeHtml(itemId)}" ${checked} /></td>
                <td>${escapeHtml(String(shop.itemId || "—"))}</td>
                <td>${escapeHtml(shop.title || "—")}</td>
                <td>${escapeHtml(formatShopStatus(shop.status))}</td>
                <td>${renderLogisticsChannelBadges(shop)}</td>
                <td>
                  <button class="btn btn-ghost btn-disable-single-spx" type="button" data-item-id="${escapeHtml(itemId)}">
                    Desativar SPX + Expresso A&eacute;reo
                  </button>
                </td>
              </tr>
            `;
          })
          .join("")
      : `<tr><td colspan="6"><div class="muted ui-state ui-state--empty">Nenhum produto com SPX ou Expresso A&eacute;reo ativo.</div></td></tr>`;
  }

  if (eligibleBody) {
    eligibleBody.innerHTML = eligiblePage.items.length
      ? eligiblePage.items
          .map((shop) => {
            const itemId = String(shop.itemId || "").trim();
            const checked = LOGISTICS_SELECTED_ELIGIBLE_IDS.has(itemId)
              ? "checked"
              : "";

            return `
              <tr class="logistics-row" data-logistics-item-id="${escapeHtml(itemId)}">
                <td><input class="logistics-eligible-checkbox" type="checkbox" value="${escapeHtml(itemId)}" ${checked} /></td>
                <td>${escapeHtml(String(shop.itemId || "—"))}</td>
                <td>${escapeHtml(shop.title || "—")}</td>
                <td>${escapeHtml(formatShopStatus(shop.status))}</td>
                <td>
                  <button
                    class="btn btn-primary btn-enable-single-spx"
                    type="button"
                    data-item-id="${escapeHtml(itemId)}"
                  >
                    Ativar SPX + Expresso A&eacute;reo
                  </button>
                </td>
              </tr>
            `;
          })
          .join("")
      : `<tr><td colspan="5"><div class="muted ui-state ui-state--empty">Nenhum produto eleg&iacute;vel ao SPX ou Expresso A&eacute;reo encontrado.</div></td></tr>`;
  }

  if (sellerEnabledBody) {
    sellerEnabledBody.innerHTML = sellerEnabledPage.items.length
      ? sellerEnabledPage.items
          .map((shop) => {
            const itemId = String(shop.itemId || "").trim();
            const checked = LOGISTICS_SELECTED_SELLER_ENABLED_IDS.has(itemId)
              ? "checked"
              : "";

            return `
              <tr class="logistics-row" data-logistics-item-id="${escapeHtml(itemId)}">
                <td><input class="logistics-seller-enabled-checkbox" type="checkbox" value="${escapeHtml(itemId)}" ${checked} /></td>
                <td>${escapeHtml(String(shop.itemId || "—"))}</td>
                <td>${escapeHtml(shop.title || "—")}</td>
                <td>${escapeHtml(formatShopStatus(shop.status))}</td>
                <td>${renderLogisticsChannelBadges(shop)}</td>
                <td>
                  <button class="btn btn-ghost btn-disable-single-seller" type="button" data-item-id="${escapeHtml(itemId)}">
                    Desabilitar logística
                  </button>
                </td>
              </tr>
            `;
          })
          .join("")
      : `<tr><td colspan="6"><div class="muted ui-state ui-state--empty">Nenhum produto com logistica do vendedor ativa.</div></td></tr>`;
  }

  if (sellerEligibleBody) {
    sellerEligibleBody.innerHTML = sellerEligiblePage.items.length
      ? sellerEligiblePage.items
          .map((shop) => {
            const itemId = String(shop.itemId || "").trim();
            const checked = LOGISTICS_SELECTED_SELLER_IDS.has(itemId)
              ? "checked"
              : "";

            return `
              <tr class="logistics-row" data-logistics-item-id="${escapeHtml(itemId)}">
                <td><input class="logistics-seller-checkbox" type="checkbox" value="${escapeHtml(itemId)}" ${checked} /></td>
                <td>${escapeHtml(String(shop.itemId || "—"))}</td>
                <td>${escapeHtml(shop.title || "—")}</td>
                <td>${escapeHtml(formatShopStatus(shop.status))}</td>
                <td>
                  <button
                    class="btn btn-primary btn-enable-single-seller"
                    type="button"
                    data-item-id="${escapeHtml(itemId)}"
                  >
                    Habilitar logistica
                  </button>
                </td>
              </tr>
            `;
          })
          .join("")
      : `<tr><td colspan="5"><div class="muted ui-state ui-state--empty">Nenhum produto disponivel para habilitar logistica do vendedor.</div></td></tr>`;
  }

  setLogisticsPagerState(
    "logisticsEnabled",
    enabledPage.page,
    enabledPage.totalPages,
    enabledPage.total,
  );
  setLogisticsPagerState(
    "logisticsEligible",
    eligiblePage.page,
    eligiblePage.totalPages,
    eligiblePage.total,
  );
  setLogisticsPagerState(
    "logisticsSellerEnabled",
    sellerEnabledPage.page,
    sellerEnabledPage.totalPages,
    sellerEnabledPage.total,
  );
  setLogisticsPagerState(
    "logisticsSellerEligible",
    sellerEligiblePage.page,
    sellerEligiblePage.totalPages,
    sellerEligiblePage.total,
  );

  bindLogisticsTableInteractions();
  updateLogisticsEnabledCount();
  updateLogisticsEnabledSelectAllState();
  updateLogisticsEligibleCount();
  updateLogisticsSelectAllState();
  updateLogisticsSellerEnabledCount();
  updateLogisticsSellerEnabledSelectAllState();
  updateLogisticsSellerEligibleCount();
  updateLogisticsSellerSelectAllState();
  renderHeavyLogisticsPanel();
  enhanceUiStates(document.getElementById("tab-logistics") || document);
}

function csvEscapeCell(value) {
  const text = String(value ?? "");
  if (
    text.includes('"') ||
    text.includes(";") ||
    text.includes(",") ||
    text.includes("\n") ||
    text.includes("\r")
  ) {
    return `"${text.replace(/"/g, '""')}"`;
  }
  return text;
}

function downloadLogisticsCsvUtf8(filename, headers, rows) {
  const lines = [headers.map(csvEscapeCell).join(";")];
  rows.forEach((row) => {
    lines.push(row.map(csvEscapeCell).join(";"));
  });

  const blob = new Blob([`\uFEFF${lines.join("\r\n")}`], {
    type: "text/csv;charset=utf-8;",
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function downloadLogisticsXlsx(filename, headers, rows) {
  const worksheet = window.XLSX.utils.aoa_to_sheet([headers, ...rows]);
  worksheet["!cols"] = headers.map((header, index) => {
    if (index === 1) return { wch: 56 };
    return { wch: Math.max(String(header || "").length + 2, 16) };
  });

  const workbook = window.XLSX.utils.book_new();
  window.XLSX.utils.book_append_sheet(workbook, worksheet, "SPX");
  window.XLSX.writeFile(workbook, filename, { compression: true });
}

function getLogisticsPackageMetrics(product) {
  const metrics = product?.spxEligibilityMetrics || {};
  const dimension = product?.dimension || {};

  return {
    length:
      metrics?.packageLength ??
      dimension?.package_length ??
      dimension?.length ??
      "",
    width:
      metrics?.packageWidth ??
      dimension?.package_width ??
      dimension?.width ??
      "",
    height:
      metrics?.packageHeight ??
      dimension?.package_height ??
      dimension?.height ??
      "",
    weight: metrics?.weight ?? product?.weight ?? "",
    cubicWeight: metrics?.cubicWeight ?? "",
    chargeableWeight: metrics?.chargeableWeight ?? "",
    cubicFormula:
      metrics?.cubicWeight != null
        ? `${metrics.packageLength} x ${metrics.packageWidth} x ${metrics.packageHeight} / ${(metrics.cubicWeightDivisor || 6000)}`
        : "",
  };
}

function exportLogisticsSpxXlsx() {
  const enabled = Array.isArray(LOGISTICS_DATA?.spx?.enabled)
    ? LOGISTICS_DATA.spx.enabled
    : [];
  const eligible = Array.isArray(LOGISTICS_DATA?.spx?.eligible)
    ? LOGISTICS_DATA.spx.eligible
    : [];

  const unionMap = new Map();
  [...enabled, ...eligible].forEach((product) => {
    const itemId = String(product?.itemId || "").trim();
    if (!itemId) return;

    const previous = unionMap.get(itemId) || {};
    unionMap.set(itemId, {
      ...previous,
      ...product,
      spxEnabled:
        typeof product?.spxEnabled === "boolean"
          ? product.spxEnabled
          : previous?.spxEnabled,
      spxEligible:
        typeof product?.spxEligible === "boolean"
          ? product.spxEligible
          : previous?.spxEligible,
    });
  });

  const rows = Array.from(unionMap.values())
    .sort((a, b) => String(a?.title || "").localeCompare(String(b?.title || ""), "pt-BR"))
    .map((product) => {
      const pack = getLogisticsPackageMetrics(product);
      return [
        String(product?.itemId || ""),
        product?.title || "",
        product?.spxEnabled ? "Sim" : "Nao",
        product?.spxEligible ? "Sim" : "Nao",
        pack.length,
        pack.width,
        pack.height,
        pack.weight,
        pack.cubicWeight,
        pack.chargeableWeight,
        pack.cubicFormula,
      ];
    });

  if (!rows.length) {
    openModal(
      "Exportar XLSX SPX",
      '<div class="muted">Nao ha produtos habilitados ou elegiveis para exportar.</div>',
    );
    return;
  }

  const headers = [
    "item_id",
    "nome_produto",
    "spx_habilitado",
    "spx_elegivel",
    "comprimento_cm",
    "largura_cm",
    "altura_cm",
    "peso_kg",
    "peso_cubico_kg",
    "peso_faturavel_kg",
    "formula_peso_cubico",
  ];

  if (window.XLSX?.utils?.aoa_to_sheet) {
    downloadLogisticsXlsx(
      `central-logistica-spx-${new Date().toISOString().slice(0, 10)}.xlsx`,
      headers,
      rows,
    );
    return;
  }

  downloadLogisticsCsvUtf8(
    `central-logistica-spx-${new Date().toISOString().slice(0, 10)}.csv`,
    headers,
    rows,
  );
  openModal(
    "Exportar SPX",
    '<div class="muted">A biblioteca XLSX nao carregou no navegador. O sistema exportou automaticamente um CSV UTF-8 compativel com acentuacao.</div>',
  );
}

function normalizeLogisticsMappingText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function parseLogisticsMappingKinds(rawValue) {
  const tokens = String(rawValue || "")
    .split(",")
    .map((token) => normalizeLogisticsMappingText(token))
    .filter(Boolean);
  const kinds = new Set();
  const invalid = [];

  tokens.forEach((token) => {
    if (
      token === "logistica do vendedor" ||
      token === "seller" ||
      token === "seller logistics" ||
      token === "central logistica"
    ) {
      kinds.add("seller");
      return;
    }
    if (
      token === "shopee xpress" ||
      token === "spx" ||
      token === "expresso aereo"
    ) {
      kinds.add("spx");
      return;
    }
    if (
      token === "retire perto de voce" ||
      token === "retire perto de voce." ||
      token === "retire perto de você" ||
      token === "pickup" ||
      token === "retire"
    ) {
      kinds.add("pickup");
      return;
    }
    invalid.push(token);
  });

  return {
    kinds: Array.from(kinds),
    invalid,
  };
}

function formatLogisticsKindsForDisplay(kinds = []) {
  const labels = [];
  if (Array.isArray(kinds) && kinds.includes("seller")) {
    labels.push("Logística do vendedor");
  }
  if (Array.isArray(kinds) && kinds.includes("spx")) {
    labels.push("Shopee Xpress / Expresso A\u00e9reo");
  }
  if (Array.isArray(kinds) && kinds.includes("pickup")) {
    labels.push("Retire perto de você");
  }
  return labels.join(", ");
}

function renderLogisticsMappingPreview() {
  const fileEl = document.getElementById("logisticsMappingFileName");
  const summaryEl = document.getElementById("logisticsMappingSummary");
  const bodyEl = document.getElementById("logisticsMappingPreviewBody");
  if (!fileEl || !summaryEl || !bodyEl) return;

  const validRows = Array.isArray(LOGISTICS_MAPPING_STATE?.validRows)
    ? LOGISTICS_MAPPING_STATE.validRows
    : [];
  const invalidRows = Array.isArray(LOGISTICS_MAPPING_STATE?.invalidRows)
    ? LOGISTICS_MAPPING_STATE.invalidRows
    : [];
  fileEl.textContent = LOGISTICS_MAPPING_STATE.fileName
    ? `Arquivo: ${LOGISTICS_MAPPING_STATE.fileName}`
    : "Nenhum arquivo selecionado.";
  summaryEl.textContent =
    `${validRows.length} linha(s) válida(s)` +
    (invalidRows.length ? ` • ${invalidRows.length} linha(s) com erro` : "");

  const previewRows = [...validRows.slice(0, 50), ...invalidRows.slice(0, 20)];
  if (!previewRows.length) {
    bodyEl.innerHTML = `<tr><td colspan="4"><div class="muted">Envie uma planilha para visualizar o preview.</div></td></tr>`;
    return;
  }

  bodyEl.innerHTML = previewRows
    .map((row) => {
      const statusLabel = row.ok
        ? '<span class="badge badge--green">Válido</span>'
        : '<span class="badge badge--red">Erro</span>';
      const logisticsText = row.ok
        ? formatLogisticsKindsForDisplay(row.kinds)
        : String(row.logisticsRaw || "");
      return `
        <tr>
          <td>${escapeHtml(String(row.rowNumber || "-"))}</td>
          <td>${escapeHtml(String(row.itemId || ""))}</td>
          <td>${escapeHtml(logisticsText || "-")}</td>
          <td>${statusLabel}<div class="muted">${escapeHtml(String(row.message || ""))}</div></td>
        </tr>
      `;
    })
    .join("");
}

function downloadLogisticsMappingTemplate() {
  const headers = ["ID do anúncio", "Tipo de Logística"];
  const rows = [
    ["1861418518", "Logística do vendedor"],
    ["1861418519", "Shopee Xpress, Retire perto de você"],
    ["1861418520", "Shopee Xpress, Logística do vendedor"],
  ];
  if (window.XLSX?.utils?.aoa_to_sheet) {
    const worksheet = window.XLSX.utils.aoa_to_sheet([headers, ...rows]);
    worksheet["!cols"] = [{ wch: 20 }, { wch: 52 }];
    const workbook = window.XLSX.utils.book_new();
    window.XLSX.utils.book_append_sheet(workbook, worksheet, "Modelo");
    window.XLSX.writeFile(workbook, "modelo_mapeamento_logistica.xlsx", {
      compression: true,
    });
    return;
  }

  downloadLogisticsCsvUtf8("modelo_mapeamento_logistica.csv", headers, rows);
}

async function parseLogisticsMappingFile(file) {
  if (!file) return;
  const isCsv = String(file.name || "")
    .toLowerCase()
    .endsWith(".csv");

  const arrayBuffer = await file.arrayBuffer();
  const workbook = window.XLSX.read(arrayBuffer, {
    type: "array",
    raw: false,
    codepage: isCsv ? 65001 : undefined,
  });
  const sheetName = workbook.SheetNames[0];
  const sheet = sheetName ? workbook.Sheets[sheetName] : null;
  if (!sheet) {
    throw new Error("Não foi possível ler a primeira aba da planilha.");
  }

  const matrix = window.XLSX.utils.sheet_to_json(sheet, {
    header: 1,
    defval: "",
    blankrows: false,
  });
  if (!Array.isArray(matrix) || matrix.length < 2) {
    throw new Error("A planilha está vazia ou sem linhas de dados.");
  }

  const validRows = [];
  const invalidRows = [];

  for (let i = 1; i < matrix.length; i += 1) {
    const row = Array.isArray(matrix[i]) ? matrix[i] : [];
    const rowNumber = i + 1;
    const itemId = String(row[0] || "").trim();
    const logisticsRaw = String(row[1] || "").trim();

    if (!itemId && !logisticsRaw) continue;
    if (!/^\d+$/.test(itemId)) {
      invalidRows.push({
        ok: false,
        rowNumber,
        itemId,
        logisticsRaw,
        message: "ID do anúncio inválido.",
      });
      continue;
    }

    const parsed = parseLogisticsMappingKinds(logisticsRaw);
    if (!parsed.kinds.length || parsed.invalid.length) {
      invalidRows.push({
        ok: false,
        rowNumber,
        itemId,
        logisticsRaw,
        message: !parsed.kinds.length
          ? "Tipo de Logística vazio/inválido."
          : `Valor inválido: ${parsed.invalid.join(", ")}`,
      });
      continue;
    }

    validRows.push({
      ok: true,
      rowNumber,
      itemId,
      logisticsRaw,
      kinds: parsed.kinds,
      message: "Pronto para processar.",
    });
  }

  LOGISTICS_MAPPING_STATE = {
    fileName: String(file.name || ""),
    validRows,
    invalidRows,
  };
  renderLogisticsMappingPreview();
}

async function runAutomaticLogisticsMapping() {
  const validRows = Array.isArray(LOGISTICS_MAPPING_STATE?.validRows)
    ? LOGISTICS_MAPPING_STATE.validRows
    : [];
  if (!validRows.length) {
    openModal(
      "Mapeamento automático",
      '<div class="muted">Envie uma planilha válida para iniciar o processamento.</div>',
    );
    return;
  }

  const uniqueIds = Array.from(new Set(validRows.map((row) => String(row.itemId))));
  const confirmed = window.confirm(
    `Processar mapeamento automático para ${uniqueIds.length} anúncio(s)?`,
  );
  if (!confirmed) return;

  startLogisticsProcess("Andamento do mapeamento automático", uniqueIds.length);
  appendLogisticsProcessLog("Enviando mapeamento para fila assíncrona...", "info");

  try {
    const mappings = validRows.map((row) => ({
      itemId: row.itemId,
      logisticsRaw: row.logisticsRaw,
    }));
    const enqueueResult = await enqueueAsyncProcessJob("logistics.mapping.apply", {
      mappings,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );
    const startStatus = await waitForAsyncProcessJobStart(jobId);
    let result = null;
    if (!startStatus) {
      appendLogisticsProcessLog(
        "Job ficou em WAITING por mais de 15s. Executando fallback direto (sem fila).",
        "warning",
      );
      try {
        const cancelStatus = await cancelAsyncProcessJob(jobId);
        if (cancelStatus?.cancelled) {
          appendLogisticsProcessLog(
            `Job em fila removido com sucesso (${jobId}).`,
            "info",
          );
        } else {
          appendLogisticsProcessLog(
            `Job não removido (${jobId}) - estado atual: ${String(cancelStatus?.state || "desconhecido")}.`,
            "warning",
          );
        }
      } catch (cancelError) {
        appendLogisticsProcessLog(
          `Não foi possível remover job da fila: ${String(cancelError?.message || "erro desconhecido")}`,
          "warning",
        );
      }
      const directResult = await apiPost("/shops/active/logistics/mapping/apply", {
        mappings,
      });
      result = directResult && typeof directResult === "object" ? directResult : {};
    } else {
      const status = await waitForAsyncProcessJob(jobId, {
        onUpdate: (snapshot) => {
          const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
          appendLogisticsProcessLog(`Status do job: ${stateLabel}`, "info");
        },
      });
      result = extractAsyncProcessPayload(status);
    }

    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(rows, uniqueIds, "aplicar mapeamento");
    const summaryLines = Array.isArray(result?.summaryLines)
      ? result.summaryLines
      : [];
    summaryLines.forEach((line) => appendLogisticsProcessLog(String(line || ""), "info"));

    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );

    openModal(
      "Resultado do mapeamento automático",
      `
        <div class="muted">${escapeHtml(summaryLines[0] || "Processo concluído.")}</div>
        <div class="muted" style="margin-top:8px;">${escapeHtml(summaryLines[1] || "")}</div>
      `,
    );
    await loadLogistics();
  } catch (error) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = Number(LOGISTICS_PROCESS_STATE.total || uniqueIds.length);
      LOGISTICS_PROCESS_STATE.failed = Number(LOGISTICS_PROCESS_STATE.total || uniqueIds.length);
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral no mapeamento automático: ${String(error?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        LOGISTICS_PROCESS_STATE.done,
        LOGISTICS_PROCESS_STATE.total,
        LOGISTICS_PROCESS_STATE.success,
        LOGISTICS_PROCESS_STATE.failed,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(error.message)}</div>`);
  }
}

async function loadLogistics({ forceSync = true } = {}) {
  if (!forceSync && LOGISTICS_DATA) {
    renderLogisticsTables(LOGISTICS_DATA);
    return LOGISTICS_DATA;
  }

  const enabledBody = document.getElementById("logisticsEnabledBody");
  const eligibleBody = document.getElementById("logisticsEligibleBody");
  const sellerEnabledBody = document.getElementById("logisticsSellerEnabledBody");
  const sellerEligibleBody = document.getElementById("logisticsSellerEligibleBody");
  LOGISTICS_SELECTED_ENABLED_IDS = new Set();
  LOGISTICS_SELECTED_ELIGIBLE_IDS = new Set();
  LOGISTICS_SELECTED_SELLER_ENABLED_IDS = new Set();
  LOGISTICS_SELECTED_SELLER_IDS = new Set();

  if (enabledBody) {
    enabledBody.innerHTML = `<tr><td colspan="6"><div class="muted ui-state ui-state--loading">Carregando logistica...</div></td></tr>`;
  }
  if (eligibleBody) {
    eligibleBody.innerHTML = `<tr><td colspan="5"><div class="muted ui-state ui-state--loading">Carregando logistica...</div></td></tr>`;
  }
  if (sellerEnabledBody) {
    sellerEnabledBody.innerHTML = `<tr><td colspan="6"><div class="muted ui-state ui-state--loading">Carregando logistica...</div></td></tr>`;
  }
  if (sellerEligibleBody) {
    sellerEligibleBody.innerHTML = `<tr><td colspan="5"><div class="muted ui-state ui-state--loading">Carregando logistica...</div></td></tr>`;
  }

  const data = await apiGet("/shops/active/logistics/products");
  renderLogisticsTables(data);
  return data;
}

async function enableSelectedSpx(shopIds, options = {}) {
  const validShopIds = Array.from(
    new Set(
      (Array.isArray(shopIds) ? shopIds : [])
        .map((value) => String(value || "").trim())
        .filter((value) => /^\d+$/.test(value)),
    ),
  );

  if (!validShopIds.length) {
    openModal(
      "Atenção",
      `<div class="muted">Selecione ao menos um produto elegível.</div>`,
    );
    return;
  }

  const disableSellerLogistics =
    typeof options.disableSellerLogistics === "boolean"
      ? options.disableSellerLogistics
      : document.getElementById("logisticsDisableSellerLogistics")?.checked !== false;
  const confirmationMessage = disableSellerLogistics
    ? "Ativar Shopee Xpress e Expresso A\u00e9reo, ativar Retire Perto de Voc\u00ea e desativar Log\u00edstica do vendedor?"
    : "Ativar Shopee Xpress, Expresso A\u00e9reo e Retire Perto de Voc\u00ea sem desativar a Log\u00edstica do vendedor?";
  const confirmed = window.confirm(confirmationMessage);
  if (!confirmed) return;

  startLogisticsProcess("Ativa\u00e7\u00e3o SPX + Expresso A\u00e9reo", validShopIds.length);
  appendLogisticsProcessLog(
    "Enviando solicita\u00e7\u00e3o para ativar SPX e Expresso A\u00e9reo...",
    "info",
  );

  try {
    const enqueueResult = await enqueueAsyncProcessJob("logistics.spx.enable", {
      itemIds: validShopIds,
      disableSellerLogistics,
    });
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendLogisticsProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const result = extractAsyncProcessPayload(status);
    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(rows, validShopIds, "ativar SPX + Expresso A\u00e9reo");
    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );
    openModal(
      "Resultado da atualização",
      rows.length
        ? rows
            .map(
              (row) => `<div class="card"><strong>${escapeHtml(String(row.itemId || "—"))}</strong><div class="muted" style="margin-top:6px;">${escapeHtml(row.title || "Produto sem título")}</div><div class="muted" style="margin-top:6px;">${escapeHtml(row.message || "")}</div></div>`,
            )
            .join("")
        : `<div class="muted">Nenhum produto foi atualizado.</div>`,
    );
    await loadLogistics();
  } catch (e) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = Number(LOGISTICS_PROCESS_STATE.total || validShopIds.length);
      LOGISTICS_PROCESS_STATE.failed = Number(LOGISTICS_PROCESS_STATE.total || validShopIds.length);
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral ao ativar SPX + Expresso A\u00e9reo: ${String(e?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        LOGISTICS_PROCESS_STATE.done,
        LOGISTICS_PROCESS_STATE.total,
        LOGISTICS_PROCESS_STATE.success,
        LOGISTICS_PROCESS_STATE.failed,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
  }
}

