function initLogisticsTab() {
  const tabButtons = $all("[data-logistics-tab]");
  const panels = $all(".logistics-tab-content");
  const sellerLegacyMuted = document.querySelector(
    "#logistics-tab-seller .section-card .section-card__body > .muted",
  );
  if (
    sellerLegacyMuted &&
    String(sellerLegacyMuted.textContent || "")
      .toUpperCase()
      .includes("FULL SHOPEE")
  ) {
    const legacyCard = sellerLegacyMuted.closest(".section-card");
    if (legacyCard) legacyCard.style.display = "none";
  }

  tabButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const tab = btn.dataset.logisticsTab;
      tabButtons.forEach((item) => item.classList.toggle("active", item === btn));
      panels.forEach((panel) => {
        const active = panel.id === `logistics-tab-${tab}`;
        panel.classList.toggle("active", active);
        panel.style.display = active ? "" : "none";
      });
    });
  });

  document
    .getElementById("btnLogisticsReload")
    ?.addEventListener("click", () => loadLogistics({ forceSync: true }));
  document.getElementById("btnLogisticsHeavySearch")?.addEventListener("click", () => {
    LOGISTICS_HEAVY_QUERY = String(
      document.getElementById("logisticsHeavySearch")?.value || "",
    ).trim();
    renderHeavyLogisticsPanel();
  });
  document.getElementById("btnLogisticsHeavyClear")?.addEventListener("click", () => {
    LOGISTICS_HEAVY_QUERY = "";
    const input = document.getElementById("logisticsHeavySearch");
    if (input) input.value = "";
    renderHeavyLogisticsPanel();
  });
  document.getElementById("logisticsHeavySelectAll")?.addEventListener("change", (event) => {
    $all(".logistics-heavy-checkbox").forEach((input) => {
      const itemId = String(input.value || "").trim();
      if (!itemId) return;
      input.checked = Boolean(event.target.checked);
      if (input.checked) LOGISTICS_SELECTED_HEAVY_IDS.add(itemId);
      else LOGISTICS_SELECTED_HEAVY_IDS.delete(itemId);
    });
    updateHeavyLogisticsSelection();
  });
  document
    .getElementById("btnEnableSelectedHeavy")
    ?.addEventListener("click", () =>
      configureHeavyLogistics(Array.from(LOGISTICS_SELECTED_HEAVY_IDS), true),
    );
  document
    .getElementById("btnDisableSelectedHeavy")
    ?.addEventListener("click", () =>
      configureHeavyLogistics(Array.from(LOGISTICS_SELECTED_HEAVY_IDS), false),
    );
  bindLogisticsProcessPanelActions();
  syncLogisticsBulkActionState();

  document
    .getElementById("btnEnableSelectedSpxChannels")
    ?.addEventListener("click", async () => {
      await enableSelectedSpx(getSelectedEnabledLogisticsIds(), {
        disableSellerLogistics: false,
      });
    });
  document
    .getElementById("btnEnableSelectedSpx")
    ?.addEventListener("click", async () => {
      await enableSelectedSpx(getSelectedEligibleLogisticsIds());
    });
  document
    .getElementById("btnDisableSelectedSpx")
    ?.addEventListener("click", async () => {
      await disableSelectedSpx(getSelectedEnabledLogisticsIds());
    });
  document
    .getElementById("btnDisableAllEnabledSpx")
    ?.addEventListener("click", async () => {
      await disableSelectedSpx(getAllEnabledSpxIds());
    });
  document
    .getElementById("btnLogisticsKeepOnlySpx")
    ?.addEventListener("click", async () => {
      await resolveLogisticsConflicts(
        "spx",
        getSelectedConflictIdsFromCurrentSelection("spx"),
      );
    });
  document
    .getElementById("btnEnableSelectedSellerLogistics")
    ?.addEventListener("click", async () => {
      await enableSelectedSellerLogistics(getSelectedSellerLogisticsIds());
    });
  document
    .getElementById("btnDisableSelectedSellerLogistics")
    ?.addEventListener("click", async () => {
      await disableSelectedSellerLogistics(getSelectedSellerEnabledLogisticsIds());
    });
  document
    .getElementById("btnDisableAllEnabledSellerLogistics")
    ?.addEventListener("click", async () => {
      await disableSelectedSellerLogistics(getAllEnabledSellerLogisticsIds());
    });
  document
    .getElementById("btnLogisticsKeepOnlySeller")
    ?.addEventListener("click", async () => {
      await resolveLogisticsConflicts(
        "seller",
        getSelectedConflictIdsFromCurrentSelection("seller"),
      );
    });

  const logisticsSearchInput = document.getElementById("logisticsSearch");
  const logisticsSellerSearchInput = document.getElementById("logisticsSellerSearch");
  const applySpxSearch = () => {
    LOGISTICS_SPX_QUERY = String(logisticsSearchInput?.value || "").trim();
    LOGISTICS_ENABLED_PAGE = 1;
    LOGISTICS_ELIGIBLE_PAGE = 1;
    renderLogisticsTables(LOGISTICS_DATA);
  };
  const applySellerSearch = () => {
    LOGISTICS_SELLER_QUERY = String(logisticsSellerSearchInput?.value || "").trim();
    LOGISTICS_SELLER_ENABLED_PAGE = 1;
    LOGISTICS_SELLER_ELIGIBLE_PAGE = 1;
    renderLogisticsTables(LOGISTICS_DATA);
  };

  document
    .getElementById("btnLogisticsSearch")
    ?.addEventListener("click", applySpxSearch);
  document
    .getElementById("btnLogisticsSelectIdsSpx")
    ?.addEventListener("click", () => applyLogisticsSelectionByIds("spx"));
  document
    .getElementById("btnLogisticsSellerSearch")
    ?.addEventListener("click", applySellerSearch);
  document
    .getElementById("btnLogisticsSelectIdsSeller")
    ?.addEventListener("click", () => applyLogisticsSelectionByIds("seller"));

  logisticsSearchInput?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") applySpxSearch();
  });
  logisticsSellerSearchInput?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") applySellerSearch();
  });

  document
    .getElementById("btnLogisticsClear")
    ?.addEventListener("click", () => {
      LOGISTICS_SPX_QUERY = "";
      if (logisticsSearchInput) logisticsSearchInput.value = "";
      LOGISTICS_ENABLED_PAGE = 1;
      LOGISTICS_ELIGIBLE_PAGE = 1;
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("btnLogisticsSellerClear")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_QUERY = "";
      if (logisticsSellerSearchInput) logisticsSellerSearchInput.value = "";
      LOGISTICS_SELLER_ENABLED_PAGE = 1;
      LOGISTICS_SELLER_ELIGIBLE_PAGE = 1;
      renderLogisticsTables(LOGISTICS_DATA);
    });

  document
    .getElementById("btnLogisticsExportXlsx")
    ?.addEventListener("click", exportLogisticsSpxXlsx);
  document
    .getElementById("btnLogisticsMappingTemplate")
    ?.addEventListener("click", downloadLogisticsMappingTemplate);
  document
    .getElementById("btnLogisticsMappingApply")
    ?.addEventListener("click", async (event) => {
      event.preventDefault();
      const applyBtn = event.currentTarget;
      if (!(applyBtn instanceof HTMLButtonElement)) {
        await runAutomaticLogisticsMapping();
        return;
      }
      if (applyBtn.dataset.processing === "1") return;
      applyBtn.dataset.processing = "1";
      applyBtn.disabled = true;
      const originalText = applyBtn.textContent || "Processar mapeamento";
      applyBtn.textContent = "Processando...";
      try {
        await runAutomaticLogisticsMapping();
      } finally {
        applyBtn.dataset.processing = "0";
        applyBtn.disabled = false;
        applyBtn.textContent = originalText;
      }
    });
  document
    .getElementById("logisticsMappingFile")
    ?.addEventListener("change", async (event) => {
      const file = event?.target?.files?.[0];
      if (!file) return;
      try {
        await parseLogisticsMappingFile(file);
      } catch (error) {
        LOGISTICS_MAPPING_STATE = {
          fileName: String(file?.name || ""),
          validRows: [],
          invalidRows: [],
        };
        renderLogisticsMappingPreview();
        openModal(
          "Erro ao ler planilha",
          `<div class="muted">${escapeHtml(String(error?.message || error))}</div>`,
        );
      }
    });
  renderLogisticsMappingPreview();

  document.getElementById("logisticsEnabledFirst")?.addEventListener("click", () => {
    LOGISTICS_ENABLED_PAGE = 1;
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEnabledPrev")?.addEventListener("click", () => {
    LOGISTICS_ENABLED_PAGE = Math.max(1, LOGISTICS_ENABLED_PAGE - 1);
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEnabledNext")?.addEventListener("click", () => {
    LOGISTICS_ENABLED_PAGE = Math.min(
      LOGISTICS_ENABLED_TOTAL_PAGES,
      LOGISTICS_ENABLED_PAGE + 1,
    );
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEnabledLast")?.addEventListener("click", () => {
    LOGISTICS_ENABLED_PAGE = LOGISTICS_ENABLED_TOTAL_PAGES;
    renderLogisticsTables(LOGISTICS_DATA);
  });

  document.getElementById("logisticsEligibleFirst")?.addEventListener("click", () => {
    LOGISTICS_ELIGIBLE_PAGE = 1;
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEligiblePrev")?.addEventListener("click", () => {
    LOGISTICS_ELIGIBLE_PAGE = Math.max(1, LOGISTICS_ELIGIBLE_PAGE - 1);
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEligibleNext")?.addEventListener("click", () => {
    LOGISTICS_ELIGIBLE_PAGE = Math.min(
      LOGISTICS_ELIGIBLE_TOTAL_PAGES,
      LOGISTICS_ELIGIBLE_PAGE + 1,
    );
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document.getElementById("logisticsEligibleLast")?.addEventListener("click", () => {
    LOGISTICS_ELIGIBLE_PAGE = LOGISTICS_ELIGIBLE_TOTAL_PAGES;
    renderLogisticsTables(LOGISTICS_DATA);
  });
  document
    .getElementById("logisticsSellerEnabledFirst")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ENABLED_PAGE = 1;
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEnabledPrev")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ENABLED_PAGE = Math.max(1, LOGISTICS_SELLER_ENABLED_PAGE - 1);
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEnabledNext")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ENABLED_PAGE = Math.min(
        LOGISTICS_SELLER_ENABLED_TOTAL_PAGES,
        LOGISTICS_SELLER_ENABLED_PAGE + 1,
      );
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEnabledLast")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ENABLED_PAGE = LOGISTICS_SELLER_ENABLED_TOTAL_PAGES;
      renderLogisticsTables(LOGISTICS_DATA);
    });

  document
    .getElementById("logisticsSellerEligibleFirst")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ELIGIBLE_PAGE = 1;
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEligiblePrev")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ELIGIBLE_PAGE = Math.max(1, LOGISTICS_SELLER_ELIGIBLE_PAGE - 1);
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEligibleNext")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ELIGIBLE_PAGE = Math.min(
        LOGISTICS_SELLER_ELIGIBLE_TOTAL_PAGES,
        LOGISTICS_SELLER_ELIGIBLE_PAGE + 1,
      );
      renderLogisticsTables(LOGISTICS_DATA);
    });
  document
    .getElementById("logisticsSellerEligibleLast")
    ?.addEventListener("click", () => {
      LOGISTICS_SELLER_ELIGIBLE_PAGE = LOGISTICS_SELLER_ELIGIBLE_TOTAL_PAGES;
      renderLogisticsTables(LOGISTICS_DATA);
    });

  document
    .getElementById("logisticsSelectAllEligible")
    ?.addEventListener("change", (event) => {
      const checked = Boolean(event.target.checked);
      LOGISTICS_FILTERED_ELIGIBLE_IDS.forEach((itemId) => {
        if (checked) {
          LOGISTICS_SELECTED_ELIGIBLE_IDS.add(itemId);
        } else {
          LOGISTICS_SELECTED_ELIGIBLE_IDS.delete(itemId);
        }
      });
      $all(".logistics-eligible-checkbox").forEach((input) => {
        const itemId = String(input.value || "").trim();
        if (!itemId) return;
        input.checked = LOGISTICS_SELECTED_ELIGIBLE_IDS.has(itemId);
      });
      updateLogisticsEligibleCount();
      updateLogisticsSelectAllState();
    });
  document
    .getElementById("logisticsSelectAllEnabled")
    ?.addEventListener("change", (event) => {
      const checked = Boolean(event.target.checked);
      LOGISTICS_FILTERED_ENABLED_IDS.forEach((itemId) => {
        if (checked) {
          LOGISTICS_SELECTED_ENABLED_IDS.add(itemId);
        } else {
          LOGISTICS_SELECTED_ENABLED_IDS.delete(itemId);
        }
      });
      $all(".logistics-enabled-checkbox").forEach((input) => {
        const itemId = String(input.value || "").trim();
        if (!itemId) return;
        input.checked = LOGISTICS_SELECTED_ENABLED_IDS.has(itemId);
      });
      updateLogisticsEnabledCount();
      updateLogisticsEnabledSelectAllState();
    });
  document
    .getElementById("logisticsSelectAllSellerEligible")
    ?.addEventListener("change", (event) => {
      const checked = Boolean(event.target.checked);
      LOGISTICS_FILTERED_SELLER_IDS.forEach((itemId) => {
        if (checked) {
          LOGISTICS_SELECTED_SELLER_IDS.add(itemId);
        } else {
          LOGISTICS_SELECTED_SELLER_IDS.delete(itemId);
        }
      });
      $all(".logistics-seller-checkbox").forEach((input) => {
        const itemId = String(input.value || "").trim();
        if (!itemId) return;
        input.checked = LOGISTICS_SELECTED_SELLER_IDS.has(itemId);
      });
      updateLogisticsSellerEligibleCount();
      updateLogisticsSellerSelectAllState();
    });
  document
    .getElementById("logisticsSelectAllSellerEnabled")
    ?.addEventListener("change", (event) => {
      const checked = Boolean(event.target.checked);
      LOGISTICS_FILTERED_SELLER_ENABLED_IDS.forEach((itemId) => {
        if (checked) {
          LOGISTICS_SELECTED_SELLER_ENABLED_IDS.add(itemId);
        } else {
          LOGISTICS_SELECTED_SELLER_ENABLED_IDS.delete(itemId);
        }
      });
      $all(".logistics-seller-enabled-checkbox").forEach((input) => {
        const itemId = String(input.value || "").trim();
        if (!itemId) return;
        input.checked = LOGISTICS_SELECTED_SELLER_ENABLED_IDS.has(itemId);
      });
      updateLogisticsSellerEnabledCount();
      updateLogisticsSellerEnabledSelectAllState();
    });
}

function initAuthTab() {
  const btn = document.getElementById("btn-auth-url");
  if (!btn) return;

  btn.addEventListener("click", async () => {
    const preview = document.getElementById("auth-url-preview");
    if (preview) preview.textContent = "Gerando link...";

    try {
      const data = await apiGet("/auth/url");
      const url = data?.auth_url || data?.authUrl || data?.url || null;
      if (preview)
        preview.textContent = url ? url : "Não foi possível gerar o link.";
      if (url) window.location.href = url;
    } catch (e) {
      if (preview) preview.textContent = `Erro: ${e.message}`;
    }
  });
}

async function apiDelete(path) {
  path = normalizeApiPath(path);
  const r = await fetch(path, { method: "DELETE", credentials: "include" });
  const text = await r.text();
  if (!r.ok) throw new Error(text || `HTTP ${r.status}`);
  return text ? JSON.parse(text) : null;
}

// ---------------- MARGEM DE CONTRIBUICAO ----------------
let MARGIN_ORDERS_DATA = [];
let MARGIN_SUMMARY_DATA = null;
let MARGIN_ORDERS_PAGE = 1;
let MARGIN_ORDERS_PAGE_SIZE = 25;
let MARGIN_TAX_BASE = "products";

function getMarginFilters() {
  const dateFrom = document.getElementById("marginDateFrom")?.value;
  const dateTo = document.getElementById("marginDateTo")?.value;
  const taxInput = document.getElementById("marginTaxRate");
  const rawTaxRate = taxInput?.value?.trim() || "";
  const taxRate = rawTaxRate === "" ? null : Number(rawTaxRate);

  if (!dateFrom || !dateTo) throw new Error("Selecione o período.");
  if (dateFrom > dateTo) throw new Error("A data inicial deve ser anterior à final.");
  if (taxRate != null && (!Number.isFinite(taxRate) || taxRate < 0 || taxRate > 100)) {
    throw new Error("A alíquota deve estar entre 0 e 100%.");
  }

  const query = new URLSearchParams({ dateFrom, dateTo });
  if (taxRate != null) query.set("taxRate", String(taxRate));
  query.set("taxBase", MARGIN_TAX_BASE);
  return { dateFrom, dateTo, taxRate, taxBase: MARGIN_TAX_BASE, query: query.toString() };
}

function renderMarginAccountTacos(tacos) {
  const targets = [
    ["marginSummaryTacos", "marginSummaryTacosMeta"],
    ["marginOrdersTacos", "marginOrdersTacosMeta"],
  ].map(([valueId, metaId]) => ({
    value: document.getElementById(valueId),
    meta: document.getElementById(metaId),
  })).filter(({ value, meta }) => value && meta);
  if (!targets.length) return;

  const spend = Number(tacos?.spend || 0);
  const gmv = Number(tacos?.gmv || 0);
  const percent = tacos?.percent == null ? null : Number(tacos.percent);
  const metaText = gmv > 0
    ? `${formatBRL(spend)} em Ads / ${formatBRL(gmv)} de receita de produtos (${tacos.periodStart || ""} a ${tacos.periodEnd || ""})${tacos.source === "official_daily_performance" ? " · Dados oficiais Shopee Ads" : " · Base local de Ads"}`
    : "Sem receita de produtos no periodo selecionado.";
  targets.forEach(({ value, meta }) => {
    value.textContent = percent == null ? "-" : `${percent.toFixed(2)}%`;
    meta.textContent = metaText;
  });
}
function initMargin() {
  document.getElementById("btnLoadMargin")?.addEventListener("click", loadMargin);
  document.getElementById("btnExportMargin")?.addEventListener("click", exportMarginReport);
  document.querySelectorAll("[data-margin-tax-base]").forEach((button) => {
    button.addEventListener("click", () => {
      MARGIN_TAX_BASE = button.dataset.marginTaxBase === "full_order" ? "full_order" : "products";
      document.querySelectorAll("[data-margin-tax-base]").forEach((candidate) => {
        const isActive = candidate.dataset.marginTaxBase === MARGIN_TAX_BASE;
        candidate.classList.toggle("active", isActive);
        candidate.setAttribute("aria-pressed", String(isActive));
      });
    });
  });
  document.getElementById("btnSaveMarginTaxRate")?.addEventListener("click", async () => {
    try {
      const { taxRate } = getMarginFilters();
      if (taxRate == null) throw new Error("Informe a alíquota.");
      await apiPatch("/shops/active/tax-rate", { taxRate });
      const costsTaxRate = document.getElementById("shopTaxRate");
      if (costsTaxRate) costsTaxRate.value = String(taxRate);
      alert("Alíquota salva.");
      await loadMargin();
    } catch (error) {
      alert(error.message);
    }
  });

  const marginOrdersBody = document.getElementById("margin-orders-body");
  if (marginOrdersBody && marginOrdersBody.dataset.bound !== "1") {
    marginOrdersBody.dataset.bound = "1";
    marginOrdersBody.addEventListener("click", async (event) => {
      const costButton = event.target.closest("[data-margin-cost-order-sn]");
      if (costButton) {
        event.stopPropagation();
        await openMarginMissingCostsModal(
          costButton.getAttribute("data-margin-cost-order-sn"),
        );
        return;
      }
      const row = event.target.closest("[data-margin-order-sn]");
      const orderSn = row?.getAttribute("data-margin-order-sn");
      if (orderSn) await openOrderDetail(orderSn);
    });
  }

  document.getElementById("btnMarginOrdersPrev")?.addEventListener("click", () => {
    if (MARGIN_ORDERS_PAGE <= 1) return;
    MARGIN_ORDERS_PAGE -= 1;
    renderMarginOrdersTable();
  });
  document.getElementById("btnMarginOrdersNext")?.addEventListener("click", () => {
    MARGIN_ORDERS_PAGE += 1;
    renderMarginOrdersTable();
  });
  document.getElementById("margin-orders-page-size")?.addEventListener("change", (event) => {
    MARGIN_ORDERS_PAGE_SIZE = Math.max(1, Number(event.target.value || 25));
    MARGIN_ORDERS_PAGE = 1;
    renderMarginOrdersTable();
  });

  initMarginSubTabs();
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  document.getElementById("marginDateFrom").value = isoLocalDate(start);
  document.getElementById("marginDateTo").value = isoLocalDate(now);
}

function initMarginSubTabs() {
  const tabs = $all(".margin-sub-tab");
  const contents = $all(".margin-tab-content");
  const filterSelect = document.getElementById("margin-filter-profitability");

  filterSelect?.addEventListener("change", () => {
    MARGIN_ORDERS_PAGE = 1;
    renderMarginOrdersTable();
  });

  tabs.forEach((button) => {
    button.addEventListener("click", async () => {
      const tab = button.dataset.marginTab;
      tabs.forEach((item) => item.classList.toggle("active", item === button));
      contents.forEach((content) => {
        content.style.display = content.id === `margin-tab-${tab}` ? "block" : "none";
      });
      if (tab === "pedidos" && !MARGIN_ORDERS_DATA.length) {
        await loadMarginOrderDetails();
      }
    });
  });
}

async function loadMarginOrderDetails() {
  const tbody = document.getElementById("margin-orders-body");
  const loading = document.getElementById("margin-orders-loading");
  const filterSelect = document.getElementById("margin-filter-profitability");
  const exportButton = document.getElementById("btnExportMargin");
  let filters;

  try {
    filters = getMarginFilters();
  } catch (error) {
    alert(error.message);
    return false;
  }

  if (loading) loading.style.display = "inline";
  if (tbody) tbody.innerHTML = "";
  if (exportButton) exportButton.disabled = true;

  try {
    const data = await apiGet(`/dashboard/margin/orders?${filters.query}`);
    MARGIN_ORDERS_DATA = data.orders || [];
    renderMarginAccountTacos(data.accountTacos);
    if (filterSelect) filterSelect.value = "all";
    MARGIN_ORDERS_PAGE = 1;
    renderMarginOrdersTable();
    if (exportButton) exportButton.disabled = MARGIN_ORDERS_DATA.length === 0;
    return true;
  } catch (error) {
    console.error(error);
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="19"><div class="muted ui-state ui-state--error">Erro ao carregar: ${escapeHtml(error.message)}</div></td></tr>`;
    }
    return false;
  } finally {
    if (loading) loading.style.display = "none";
  }
}

function getFilteredMarginOrders() {
  const filter = document.getElementById("margin-filter-profitability")?.value || "all";
  if (filter === "loss") {
    return MARGIN_ORDERS_DATA.filter((order) => order.profit < 0);
  }
  if (filter === "profit") {
    return MARGIN_ORDERS_DATA.filter((order) => order.profit > 0);
  }
  if (filter === "low-margin") {
    return MARGIN_ORDERS_DATA.filter(
      (order) => order.profit > 0 && order.profitMargin < 15,
    );
  }
  if (filter === "missing-cost") {
    return MARGIN_ORDERS_DATA.filter((order) => Number(order.missingCostItems || 0) > 0);
  }
  if (filter === "financial-review") {
    return MARGIN_ORDERS_DATA.filter((order) => Boolean(order.financialReview?.requiresReview));
  }
  return MARGIN_ORDERS_DATA;
}

function renderMarginOrdersTable() {
  const tbody = document.getElementById("margin-orders-body");
  const countEl = document.getElementById("margin-orders-count");
  const pageInfo = document.getElementById("margin-orders-page-info");
  const previousButton = document.getElementById("btnMarginOrdersPrev");
  const nextButton = document.getElementById("btnMarginOrdersNext");
  const scrollContainer = document.getElementById("margin-orders-scroll");
  if (!tbody || !countEl) return;

  const orders = getFilteredMarginOrders();
  const totalPages = Math.max(1, Math.ceil(orders.length / MARGIN_ORDERS_PAGE_SIZE));
  MARGIN_ORDERS_PAGE = Math.min(Math.max(1, MARGIN_ORDERS_PAGE), totalPages);

  if (!orders.length) {
    countEl.textContent = "Nenhum pedido encontrado";
    if (pageInfo) pageInfo.textContent = "P\u00e1gina 0 de 0";
    if (previousButton) previousButton.disabled = true;
    if (nextButton) nextButton.disabled = true;
    tbody.innerHTML = '<tr><td colspan="19"><div class="muted ui-state ui-state--empty">Nenhum pedido encontrado neste per&iacute;odo.</div></td></tr>';
    return;
  }

  const startIndex = (MARGIN_ORDERS_PAGE - 1) * MARGIN_ORDERS_PAGE_SIZE;
  const endIndex = Math.min(startIndex + MARGIN_ORDERS_PAGE_SIZE, orders.length);
  const pageOrders = orders.slice(startIndex, endIndex);

  countEl.textContent = `Exibindo ${startIndex + 1}-${endIndex} de ${orders.length} pedido${orders.length === 1 ? "" : "s"}`;
  if (pageInfo) pageInfo.textContent = `P\u00e1gina ${MARGIN_ORDERS_PAGE} de ${totalPages}`;
  if (previousButton) previousButton.disabled = MARGIN_ORDERS_PAGE <= 1;
  if (nextButton) nextButton.disabled = MARGIN_ORDERS_PAGE >= totalPages;
  if (scrollContainer) scrollContainer.scrollTop = 0;

  tbody.innerHTML = pageOrders.map((order) => {
    const date = new Date(order.shopeeCreateTime).toLocaleDateString("pt-BR");
    const profitColor = order.profit >= 0 ? "var(--up)" : "var(--down)";
    const costWarning = order.missingCostItems > 0
      ? ` title="${order.missingCostItems} item(ns) sem custo configurado"`
      : "";
    const financialReview = order.financialReview || {};
    const reconciliationCell = financialReview.requiresReview
      ? '<span class="badge" title="Requer revisao antes de calibrar o motor.">Revisar financeiro</span>' : '<span class="muted">Conciliado</span>';
    const shippingCost = order.shippingCost || {};
    const ownLogisticsShipping = Number(order.costs?.ownLogisticsShipping || order.ownLogisticsShipping || 0);
    const freightPassThrough = Number(order.costs?.shippingPassThrough || order.shippingCost?.freightPassThrough || order.freightPassThrough || 0);
    const shippingNotes = [
      shippingCost.source === "seller_logistics_reserve" ? "" : shippingCost.isProvisional ? "Provisao pelo frete estimado do canal" : "",
      Number(shippingCost.shopeeRebate || 0) > 0 ? `Rebate de frete Shopee (fora da margem): ${formatBRL(shippingCost.shopeeRebate)}` : "",
      freightPassThrough > 0 ? `${order.isOwnLogistics ? "Reserva de frete proprio a repassar" : "Frete do canal a repassar"}: ${formatBRL(freightPassThrough)}` : "",
    ].filter(Boolean);
    const shippingCell = `${formatBRL(order.costs.shipping)}${shippingNotes.length ? `<span class="pricing-v6-muted-line">${shippingNotes.map(escapeHtml).join(" | ")}</span>` : ""}`;
    const payoutAdjustment = Number(order.otherShopeeAdjustments || 0);
    const payoutAdjustmentCell = `${payoutAdjustment > 0 ? "+" : payoutAdjustment < 0 ? "-" : ""}${formatBRL(Math.abs(payoutAdjustment))}`;
    return `
      <tr class="margin-order-row" data-margin-order-sn="${escapeHtml(order.orderSn || "")}"${costWarning}>
        <td><button type="button" class="margin-order-link">${escapeHtml(order.orderSn || "?")}</button></td>
        <td class="muted">${date}</td>
        <td>${escapeHtml(formatOrderStatusLabel(order.orderStatus || ""))}</td>
        <td>${reconciliationCell}</td>
        <td>${formatBRL(order.revenue)}</td>
        <td style="font-weight: 500;">${formatBRL(order.netReceived)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.products)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.commissions)}</td>
        <td style="color: var(--down);">${shippingCell}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.voucher)}</td>
        <td style="color: var(--up);">${formatBRL(order.rebatesShopee || 0)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.orderTaxes || 0)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.configuredTaxes || 0)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.ads)}</td>
        <td style="color: var(--down);">${formatBRL(order.costs.returns)}</td>
        <td>${payoutAdjustmentCell}</td>
        <td style="font-weight: 600; color: ${profitColor};">${formatBRL(order.profit)}</td>
        <td style="font-weight: 600; color: ${profitColor};">${Number(order.profitMargin || 0).toFixed(1)}%</td>
        <td>
          ${Number(order.missingCostItems || 0) > 0
            ? `<button type="button" class="btn btn-ghost btn-sm margin-cost-action" data-margin-cost-order-sn="${escapeHtml(order.orderSn || "")}">Adicionar CMV (${Number(order.missingCostItems || 0)})</button>`
            : '<span class="muted">&mdash;</span>'}
        </td>
      </tr>`;
  }).join("");
}

function getMarginOrderBySn(orderSn) {
  const normalizedOrderSn = String(orderSn || "").trim();
  return MARGIN_ORDERS_DATA.find(
    (order) => String(order?.orderSn || "").trim() === normalizedOrderSn,
  );
}

function getMarginMissingCostProducts(order) {
  const productsByItemId = new Map();
  (Array.isArray(order?.items) ? order.items : [])
    .filter((item) => !item?.hasConfiguredCost)
    .forEach((item) => {
      const itemId = String(item?.itemId || "").trim();
      if (!itemId) return;
      const existing = productsByItemId.get(itemId) || {
        itemId,
        name: String(item?.name || "Produto sem nome").trim(),
        quantity: 0,
        skus: new Set(),
      };
      existing.quantity += Number(item?.quantity || 0);
      if (item?.sku) existing.skus.add(String(item.sku).trim());
      productsByItemId.set(itemId, existing);
    });

  return Array.from(productsByItemId.values()).map((item) => ({
    ...item,
    skus: Array.from(item.skus),
  }));
}

async function openMarginMissingCostsModal(orderSn) {
  const order = getMarginOrderBySn(orderSn);
  if (!order) {
    alert("Pedido nao encontrado no relatorio atual.");
    return;
  }

  const missingProducts = getMarginMissingCostProducts(order);
  if (!missingProducts.length) {
    alert("Este pedido nao possui produtos sem custo configurado.");
    return;
  }

  openModal(
    `Cadastrar CMV - Pedido ${escapeHtml(order.orderSn || "")}`,
    '<div class="muted">Carregando produtos sem custo...</div>',
  );

  try {
    const itemIds = missingProducts.map((item) => item.itemId).join(",");
    const data = await apiGet(
      `/shops/active/costs/pricing-items?itemIds=${encodeURIComponent(itemIds)}`,
    );
    const productsByItemId = new Map(
      (Array.isArray(data?.items) ? data.items : []).map((product) => [
        String(product?.itemId || "").trim(),
        product,
      ]),
    );
    const editableProducts = missingProducts
      .map((item) => ({ ...item, product: productsByItemId.get(item.itemId) }))
      .filter((item) => Number(item.product?.id || 0) > 0);

    if (!editableProducts.length) {
      openModal(
        `Cadastrar CMV - Pedido ${escapeHtml(order.orderSn || "")}`,
        '<div class="muted">Os produtos deste pedido nao estao disponiveis na tabela de custos da loja.</div>',
      );
      return;
    }

    const unavailableCount = missingProducts.length - editableProducts.length;
    openModal(
      `Cadastrar CMV - Pedido ${escapeHtml(order.orderSn || "")}`,
      `
        <div class="margin-cost-editor">
          <div class="muted">Informe o custo unitario de cada produto. Ao salvar, o CMV sera gravado na tabela de custos da loja e a margem sera recalculada.</div>
          ${unavailableCount > 0 ? `<div class="ui-state ui-state--warning">${unavailableCount} produto(s) nao puderam ser localizados na tabela de custos.</div>` : ""}
          <div class="margin-cost-editor__list">
            ${editableProducts.map((item) => `
              <label class="margin-cost-editor__item">
                <span class="margin-cost-editor__identity">
                  <strong>${escapeHtml(item.name)}</strong>
                  <small>ID ${escapeHtml(item.itemId)}${item.skus.length ? ` · SKU ${escapeHtml(item.skus.join(" | "))}` : ""} · ${Number(item.quantity || 0)} unidade(s) neste pedido</small>
                </span>
                <span class="margin-cost-editor__field">
                  <small>CMV unitario (R$)</small>
                  <input class="input margin-cost-editor__input" type="number" min="0.01" step="0.01" inputmode="decimal" data-product-id="${escapeHtml(item.product.id)}" value="" placeholder="0,00" required />
                </span>
              </label>
            `).join("")}
          </div>
          <div id="margin-cost-editor-feedback" class="muted"></div>
          <div class="toolbar" style="justify-content:flex-end; gap:8px; margin-top:4px;">
            <button id="btnCancelMarginCosts" type="button" class="btn btn-ghost">Cancelar</button>
            <button id="btnSaveMarginCosts" type="button" class="btn btn-primary">Salvar custos e recalcular</button>
          </div>
        </div>
      `,
    );

    document.getElementById("btnCancelMarginCosts")?.addEventListener("click", closeModal);
    document.getElementById("btnSaveMarginCosts")?.addEventListener("click", async (event) => {
      const saveButton = event.currentTarget;
      const feedback = document.getElementById("margin-cost-editor-feedback");
      const inputs = Array.from(
        document.querySelectorAll(".margin-cost-editor__input"),
      );
      const invalidInput = inputs.find((input) => Number(input.value) <= 0);
      if (invalidInput) {
        if (feedback) feedback.textContent = "Informe um CMV maior que R$ 0,00 para todos os produtos.";
        invalidInput.focus();
        return;
      }

      saveButton.disabled = true;
      saveButton.textContent = "Salvando...";
      if (feedback) feedback.textContent = "Salvando custos na tabela de produtos...";
      try {
        for (const input of inputs) {
          await apiPatch(`/shops/active/products/${input.dataset.productId}/cost`, {
            cost: Number(input.value),
          });
        }
        await loadMargin();
        const profitabilityFilter = document.getElementById("margin-filter-profitability");
        if (profitabilityFilter) {
          profitabilityFilter.value = "missing-cost";
          MARGIN_ORDERS_PAGE = 1;
          renderMarginOrdersTable();
        }
        closeModal();
      } catch (error) {
        if (feedback) feedback.textContent = `Erro ao salvar: ${error.message}`;
        saveButton.disabled = false;
        saveButton.textContent = "Salvar custos e recalcular";
      }
    });
  } catch (error) {
    openModal(
      `Cadastrar CMV - Pedido ${escapeHtml(order.orderSn || "")}`,
      `<div class="muted">Erro ao carregar produtos: ${escapeHtml(error.message)}</div>`,
    );
  }
}

async function loadMargin() {
  let filters;
  try {
    filters = getMarginFilters();
  } catch (error) {
    alert(error.message);
    return;
  }

  const button = document.getElementById("btnLoadMargin");
  if (button) button.disabled = true;
  try {
    const data = await apiGet(`/dashboard/margin?${filters.query}`);
    MARGIN_SUMMARY_DATA = data;
    renderMarginAccountTacos(data.accountTacos);
    setText(
      "marginDataMeta",
      `Período ${filters.dateFrom} a ${filters.dateTo} · Alíquota ${Number(data.taxRate ?? filters.taxRate ?? 0).toFixed(2)}% · Imposto sobre ${data.taxBase === "full_order" ? "pedido completo" : "produtos sem frete"} · Calculado em ${new Date().toLocaleString("pt-BR")}`,
    );
    const taxInput = document.getElementById("marginTaxRate");
    if (taxInput && filters.taxRate == null) taxInput.value = String(data.taxRate || 0);

    setText("marginRevenue", formatBRLFixed90(data.productRevenue ?? data.revenue));
    setText("marginNetReceived", formatBRLFixed90(data.productNetReceived ?? data.netReceived));
    setText("marginTotalCosts", formatBRLFixed90(data.costs.total));
    setText("marginProfit", formatBRLFixed90(data.profit));
    setText("marginProfitPercent", (Number(data.profitMargin) || 0).toFixed(2) + "%");
    setText("marginCommissions", formatBRLFixed90(data.costs?.commissions ?? 0));
    setText("marginProductCosts", formatBRLFixed90(data.costs?.products ?? 0));
    setText("marginReturns", formatBRLFixed90(data.costs?.returns ?? 0));
    setText("marginTaxes", formatBRLFixed90(data.costs?.taxes ?? 0));
    setText("marginOrderTaxes", formatBRLFixed90(data.costs?.orderTaxes ?? 0));
    setText("marginConfiguredTaxes", formatBRLFixed90(data.costs?.configuredTaxes ?? 0));
    const ads = data.ads || {};
    const adsTotal = ads.total ?? data.costs?.ads ?? 0;
    const adsAdjustment = Number(ads.notAllocatedToOrders || 0);
    setText("marginAds", formatBRLFixed90(adsTotal));
    setText(
      "marginAdsDetail",
      `Alocado aos pedidos: ${formatBRLFixed90(ads.allocatedToOrders ?? 0)} | Ajuste do periodo: ${adsAdjustment > 0 ? "+" : ""}${formatBRLFixed90(adsAdjustment)}`,
    );
    const returns = data.returns || {};
    setText(
      "marginReturnsDetail",
      `Reembolsos: ${formatBRLFixed90(returns.productRefunds ?? 0)} | DRC: ${formatBRLFixed90(returns.disputeAdjustments ?? 0)}`,
    );
    setText("marginShipping", formatBRLFixed90(data.costs?.shipping ?? 0));
    const ownLogisticsShipping = Number(data.costs?.ownLogisticsShipping || 0);
    setText(
      "marginShippingDetail",
      ownLogisticsShipping > 0
        ? `Fora da margem. Inclui a reserva de ${formatBRLFixed90(ownLogisticsShipping)} para frete proprio a repassar.`
        : "Fora da margem: valor mantido apenas para conciliacao logistica.",
    );
    setText("marginVouchers", formatBRLFixed90(data.costs?.vouchers ?? 0));
    setText("marginShopeeRebates", formatBRLFixed90(data.credits?.shopeeRebates ?? 0));
    setText("marginSpxCost", formatBRLFixed90(data.spx?.totalCents ?? 0));
    setText("marginSpxCount", (data.spx?.count || 0) + " pedidos");

    const warning = document.getElementById("marginCostWarning");
    const missingItems = Number(data.missingCosts?.items || 0);
    if (warning) {
      warning.style.display = missingItems > 0 ? "block" : "none";
      warning.textContent = missingItems > 0
        ? `Atenção: ${missingItems} item(ns) em ${data.missingCosts.orders} pedido(s) estão sem custo configurado. A margem desses pedidos está superestimada.`
        : "";
    }

    MARGIN_ORDERS_DATA = [];
    MARGIN_ORDERS_PAGE = 1;
    const exportButton = document.getElementById("btnExportMargin");
    if (exportButton) exportButton.disabled = true;
    const pedidosTab = document.getElementById("margin-tab-pedidos");
    if (pedidosTab && pedidosTab.style.display !== "none") {
      await loadMarginOrderDetails();
    }
  } catch (error) {
    console.error(error);
    alert("Erro ao calcular margem: " + error.message);
  } finally {
    if (button) button.disabled = false;
  }
}

const MARGIN_CURRENCY_FORMAT = '"R$" #,##0.00;[Red]-"R$" #,##0.00';
const MARGIN_PERCENT_FORMAT = "0.00%";
const MARGIN_DATE_FORMAT = "dd/mm/yyyy";

function applyMarginColumnFormats(
  sheet,
  rows,
  { percentHeaders = [], dateHeaders = [], integerHeaders = [] } = {},
) {
  if (!sheet?.["!ref"] || !rows?.length) return;

  const range = XLSX.utils.decode_range(sheet["!ref"]);
  const headers = Object.keys(rows[0]);
  const percentSet = new Set(percentHeaders);
  const dateSet = new Set(dateHeaders);
  const integerSet = new Set(integerHeaders);

  headers.forEach((header, columnIndex) => {
    const format = percentSet.has(header)
      ? MARGIN_PERCENT_FORMAT
      : dateSet.has(header)
        ? MARGIN_DATE_FORMAT
        : integerSet.has(header)
          ? "0"
          : MARGIN_CURRENCY_FORMAT;

    for (let rowIndex = 1; rowIndex <= range.e.r; rowIndex += 1) {
      const address = XLSX.utils.encode_cell({ r: rowIndex, c: columnIndex });
      const cell = sheet[address];
      if (!cell) continue;
      if (dateSet.has(header) || cell.t === "n" || cell.t === "d") {
        cell.z = format;
      }
    }
  });
}

function normalizeMarginPercentValue(value) {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric)) return 0;
  return Math.abs(numeric) > 1 ? numeric / 100 : numeric;
}

function applyMarginRawFinancialFormats(sheet, rows) {
  if (!sheet?.["!ref"] || !rows?.length) return;

  const headers = Object.keys(rows[0]);
  const valueColumn = headers.indexOf("Valor");
  if (valueColumn < 0) return;

  rows.forEach((row, index) => {
    const cell = sheet[
      XLSX.utils.encode_cell({ r: index + 1, c: valueColumn })
    ];
    if (!cell || cell.t !== "n") return;
    cell.z = row.Tipo === "%" ? MARGIN_PERCENT_FORMAT : MARGIN_CURRENCY_FORMAT;
  });
}

function applyMarginSummaryFormats(sheet, rows) {
  if (!sheet?.["!ref"] || !rows?.length) return;

  const percentIndicators = new Set(["Aliquota", "Margem percentual"]);
  const integerIndicators = new Set(["Itens sem custo"]);

  rows.forEach((row, index) => {
    const cell = sheet[XLSX.utils.encode_cell({ r: index + 1, c: 1 })];
    if (!cell || cell.t !== "n") return;
    cell.z = percentIndicators.has(row.Indicador)
      ? MARGIN_PERCENT_FORMAT
      : integerIndicators.has(row.Indicador)
        ? "0"
        : MARGIN_CURRENCY_FORMAT;
  });
}

function exportMarginReport() {
  const run = async () => {
    if (!MARGIN_ORDERS_DATA.length) {
      const loaded = await loadMarginOrderDetails();
      if (!loaded || !MARGIN_ORDERS_DATA.length) return;
    }
    if (!window.XLSX) throw new Error("Biblioteca de planilhas indisponível.");

    const filters = getMarginFilters();
    const getOrderItemIdentity = (order) => {
      const items = Array.isArray(order?.items) ? order.items : [];
      const distinctValues = (field) => Array.from(
        new Set(
          items
            .map((item) => String(item?.[field] || "").trim())
            .filter(Boolean),
        ),
      );
      return {
        products: distinctValues("name").join(" | "),
        skus: distinctValues("sku").join(" | "),
      };
    };
    const ordersRows = MARGIN_ORDERS_DATA.map((order) => {
      const itemIdentity = getOrderItemIdentity(order);
      return {
      "Pedido": order.orderSn,
      "Data": new Date(order.shopeeCreateTime),
      "Status": order.orderStatus,
      "Situacao financeira": order.financialReview?.requiresReview ? "Revisar financeiro" : "Conciliado",
      "Motivos da revisao": Array.isArray(order.financialReview?.reasons) ? order.financialReview.reasons.join(", ") : "",
      "Produtos": itemIdentity.products,
      "SKUs": itemIdentity.skus,
      "GMV pago": Number(order.revenue || 0),
      "Receita produtos": Number(order.itemsRevenue || 0),
      "Receita frete": Number(order.shippingRevenue || 0),
      "Frete proprio a repassar": Number(order.ownLogisticsShipping || order.costs?.ownLogisticsShipping || 0),
      "Repasse liquido Shopee": Number(order.netReceived || 0),
      "Repasse esperado por campos confirmados": Number(order.reconciliation?.expectedPayout || 0),
      "Ajuste de repasse nao detalhado": Number(order.reconciliation?.adjustment || 0),
      "Fonte do repasse": order.netReceivedSource === "shopee" ? "Shopee" : "Calculado",
      "Custo do produto (CMV)": Number(order.costs?.products || 0),
      "Comissoes e taxas": Number(order.costs?.commissions || 0),
      "Frete descontado": Number(order.costs?.shipping || 0),
      "Fonte do frete descontado": order.shippingCost?.source || "unavailable",
      "Rebate de frete Shopee": Number(order.shippingCost?.shopeeRebate || 0),
      "Rebate de frete fora da margem": Number(order.freightRebateExcluded || 0),
      "Frete em provisao": order.shippingCost?.isProvisional ? "Sim" : "Nao",
      "Cupom vendedor": Number(order.costs?.voucher || 0),
      "Rebates Shopee": Number(order.rebatesShopee || 0),
      "Impostos no pedido": Number(order.costs?.orderTaxes || 0),
      "Imposto da aliquota": Number(order.costs?.configuredTaxes || 0),
      "Ads": Number(order.costs?.ads || 0),
      "Devolucoes": Number(order.costs?.returns || 0),
      "Sobra final (R$)": Number(order.profit || 0),
      "Margem percentual": Number(order.profitMargin || 0) / 100,
      "Itens sem custo": Number(order.missingCostItems || 0),
      };
    });
    const detailRows = MARGIN_ORDERS_DATA.map((order) => {
      const details = order.financialDetails || {};
      const products = details.products || {};
      const discounts = details.discounts || {};
      const shipping = details.shipping || {};
      const fees = details.fees || {};
      const taxes = details.taxes || {};
      const returns = details.returns || {};
      const money = (value) => Number(value || 0);
      const itemIdentity = getOrderItemIdentity(order);

      return {
        "Pedido": order.orderSn,
        "Data": new Date(order.shopeeCreateTime),
        "Status": order.orderStatus,
        "Produtos": itemIdentity.products,
        "SKUs": itemIdentity.skus,
        "Preco original produtos": money(products.originalPrice),
        "Subtotal produtos com descontos": money(products.discountedSubtotal),
        "Total pago pelo comprador": money(products.buyerTotal),
        "Subtotal no checkout": money(products.checkoutSubtotal),
        "Ajuste PIX": money(discounts.pix),
        "Cupom do vendedor": money(discounts.sellerVoucher),
        "Desconto do vendedor": money(discounts.sellerDiscount),
        "Cupom Shopee": money(discounts.shopeeVoucher),
        "Desconto Shopee": money(discounts.shopeeDiscount),
        "Moedas Shopee": money(discounts.coins),
        "Promocao de pagamento": money(discounts.paymentPromotion),
        "Cashback moedas vendedor": money(discounts.sellerCoinCashback),
        "Trade-in vendedor": money(discounts.tradeInSeller),
        "Rebate produto vendedor": money(discounts.sellerProductRebate),
        "Frete estimado": money(shipping.estimated),
        "Frete pago comprador": money(shipping.buyerPaid),
        "Frete real parceiro logistico": money(shipping.actual),
        "Desconto frete 3PL": money(shipping.discount3pl),
        "Desconto frete vendedor": money(shipping.sellerDiscount),
        "Rebate frete Shopee": money(shipping.shopeeRebate),
        "Frete reverso": money(shipping.reverse),
        "Retorno ao vendedor": money(shipping.returnToSeller),
        "Protecao frete vendedor": money(shipping.sellerProtection),
        "Premio protecao entrega": money(shipping.deliveryProtection),
        "Reembolso protecao RSF": money(shipping.protectionClaimRsf),
        "Reembolso protecao FSF": money(shipping.protectionClaimFsf),
        "Comissao bruta": money(fees.commissionGross),
        "Comissao liquida": money(fees.commissionNet),
        "Ajuste comercial comissao": money(fees.commissionCommercialAdjustment),
        "Servico bruto": money(fees.serviceGross),
        "Servico liquido": money(fees.serviceNet),
        "Servico adicional": money(fees.additionalService),
        "Taxa transacao": money(fees.transaction),
        "Taxa por item vendido": money(fees.soldItem),
        "Ajuste comercial servico": money(fees.serviceCommercialAdjustment),
        "Comissao afiliados": money(fees.affiliateCommission),
        "Ads ou suporte tecnico Shopee": money(fees.adsTechnicalSupport),
        "FBS fee": money(fees.fbs),
        "Servico devolucao internacional": money(fees.overseasReturnService),
        "Retencao tributaria": money(taxes.withholding),
        "Retencao VAT": money(taxes.withholdingVat),
        "Retencao PIT": money(taxes.withholdingPit),
        "Escrow tax": money(taxes.escrow),
        "Sales tax LVG": money(taxes.salesLvg),
        "VAT produto": money(taxes.productVat),
        "VAT frete": money(taxes.shippingVat),
        "GST produto": money(taxes.productGst),
        "GST frete": money(taxes.shippingGst),
        "VAT importacao": money(taxes.importedGoodsVat),
        "Imposto importacao": money(taxes.importDuty),
        "Reembolso ao comprador": money(returns.sellerRefund),
        "Ajuste por disputa": money(returns.disputeAdjustment),
        "Compensacao perda vendedor": money(returns.sellerLostCompensation),
        "Total comissoes e taxas usado": money(order.costs?.commissions),
        "Total frete descontado usado": money(order.costs?.shipping),
        "Fonte do frete descontado": order.shippingCost?.source || "unavailable",
        "Frete em provisao": order.shippingCost?.isProvisional ? "Sim" : "Nao",
        "Total impostos pedido usado": money(order.costs?.orderTaxes),
        "Repasse liquido Shopee": money(order.netReceived),
        "Repasse esperado por campos confirmados": money(order.reconciliation?.expectedPayout),
        "Ajuste de repasse nao detalhado": money(order.reconciliation?.adjustment),
        "Situacao financeira": order.financialReview?.requiresReview ? "Revisar financeiro" : "Conciliado",
        "Motivos da revisao": Array.isArray(order.financialReview?.reasons) ? order.financialReview.reasons.join(", ") : "",
        "Custo do produto (CMV)": money(order.costs?.products),
        "Imposto da aliquota": money(order.costs?.configuredTaxes),
        "Ads atribuido": money(order.costs?.ads),
        "Sobra final (R$)": money(order.profit),
        "Margem percentual": money(order.profitMargin) / 100,
      };
    });
    const adjustmentRows = MARGIN_ORDERS_DATA.flatMap((order) =>
      (order.financialDetails?.accountingAdjustments || []).map((adjustment) => ({
        "Pedido": order.orderSn,
        "Data do pedido": new Date(order.shopeeCreateTime),
        "Motivo": adjustment.reason || "",
        "Data do ajuste": adjustment.date || "",
        "Valor": Number(adjustment.amountCents || 0),
      }))
    );
    const rawFinancialRows = MARGIN_ORDERS_DATA.flatMap((order) =>
      (order.rawFinancialFields || []).map((field) => {
        const isPercent = /(rate|percent|percentage|ratio)/i.test(
          String(field.field || ""),
        );
        return {
          "Pedido": order.orderSn,
          "Data": new Date(order.shopeeCreateTime),
          "Campo API Shopee": field.field,
          "Tipo": isPercent ? "%" : "R$",
          "Valor": isPercent
            ? normalizeMarginPercentValue(field.value)
            : Number(field.value || 0),
        };
      })
    );
    const itemRows = MARGIN_ORDERS_DATA.flatMap((order) =>
      (order.items || []).map((item) => ({
        "Pedido": order.orderSn,
        "Data": new Date(order.shopeeCreateTime),
        "ID produto": item.itemId || "",
        "ID variacao": item.modelId || "",
        "SKU": item.sku || "",
        "Produto": item.name || "",
        "Variacao": item.variation || "",
        "Quantidade": Number(item.quantity || 0),
        "Preco unitario": Number(item.unitPrice || 0),
        "Custo unitario": Number(item.unitCost || 0),
        "Custo total do produto": Number(item.totalCost || 0),
        "Custo configurado": item.hasConfiguredCost ? "Sim" : "Nao",
      }))
    );
    const summary = MARGIN_SUMMARY_DATA || {};
    const summaryRows = [
      { "Indicador": "Periodo", "Valor": `${filters.dateFrom} a ${filters.dateTo}` },
      { "Indicador": "Aliquota", "Valor": Number(summary.taxRate ?? filters.taxRate ?? 0) / 100 },
      { "Indicador": "Base do imposto", "Valor": summary.taxBase === "full_order" ? "Pedido completo (frete + produtos)" : "Apenas produtos (sem frete)" },
      { "Indicador": "Receita de produtos (sem frete)", "Valor": Number((summary.productRevenue ?? summary.revenue) || 0) },
      { "Indicador": "Repasse liquido de produtos (sem frete e rebate de frete)", "Valor": Number((summary.productNetReceived ?? summary.netReceived) || 0) },
      { "Indicador": "Custo do produto (CMV)", "Valor": Number(summary.costs?.products || 0) },
      { "Indicador": "Descontos e custos", "Valor": Number(summary.costs?.total || 0) },
      { "Indicador": "Frete em conciliacao (fora da margem)", "Valor": Number(summary.costs?.shipping || 0) },
      { "Indicador": "Rebate de frete (fora da margem)", "Valor": Number(summary.credits?.freightRebateExcluded || 0) },
      { "Indicador": "Sobra final (R$)", "Valor": Number(summary.profit || 0) },
      { "Indicador": "Margem percentual", "Valor": Number(summary.profitMargin || 0) / 100 },
      { "Indicador": "Itens sem custo", "Valor": Number(summary.missingCosts?.items || 0) },
    ];

    const workbook = XLSX.utils.book_new();
    const summarySheet = XLSX.utils.json_to_sheet(summaryRows);
    const ordersSheet = XLSX.utils.json_to_sheet(ordersRows);
    const itemsSheet = XLSX.utils.json_to_sheet(itemRows);
    const detailsSheet = XLSX.utils.json_to_sheet(detailRows);
    const adjustmentsSheet = XLSX.utils.json_to_sheet(adjustmentRows);
    const rawFinancialSheet = XLSX.utils.json_to_sheet(rawFinancialRows);
    summarySheet["!cols"] = [{ wch: 30 }, { wch: 22 }];
    ordersSheet["!cols"] = ordersRows[0]
      ? Object.keys(ordersRows[0]).map((key) => ({ wch: Math.min(28, Math.max(12, key.length + 2)) }))
      : [];
    itemsSheet["!cols"] = itemRows[0]
      ? Object.keys(itemRows[0]).map((key) => ({ wch: Math.min(42, Math.max(12, key.length + 2)) }))
      : [];
    detailsSheet["!cols"] = detailRows[0]
      ? Object.keys(detailRows[0]).map((key) => ({ wch: Math.min(34, Math.max(14, key.length + 2)) }))
      : [];
    adjustmentsSheet["!cols"] = [{ wch: 22 }, { wch: 18 }, { wch: 42 }, { wch: 22 }, { wch: 16 }];
    rawFinancialSheet["!cols"] = [{ wch: 22 }, { wch: 18 }, { wch: 58 }, { wch: 10 }, { wch: 18 }];
    applyMarginSummaryFormats(summarySheet, summaryRows);
    applyMarginColumnFormats(ordersSheet, ordersRows, {
      percentHeaders: ["Margem percentual"],
      dateHeaders: ["Data"],
      integerHeaders: ["Itens sem custo"],
    });
    applyMarginColumnFormats(detailsSheet, detailRows, {
      percentHeaders: ["Margem percentual"],
      dateHeaders: ["Data"],
    });
    applyMarginColumnFormats(adjustmentsSheet, adjustmentRows, {
      dateHeaders: ["Data do pedido", "Data do ajuste"],
    });
    applyMarginColumnFormats(rawFinancialSheet, rawFinancialRows, {
      dateHeaders: ["Data"],
    });
    applyMarginRawFinancialFormats(rawFinancialSheet, rawFinancialRows);
    applyMarginColumnFormats(itemsSheet, itemRows, {
      dateHeaders: ["Data"],
      integerHeaders: ["Quantidade"],
    });
    XLSX.utils.book_append_sheet(workbook, summarySheet, "Resumo");
    XLSX.utils.book_append_sheet(workbook, ordersSheet, "Pedidos");
    XLSX.utils.book_append_sheet(workbook, detailsSheet, "Taxas detalhadas");
    XLSX.utils.book_append_sheet(workbook, adjustmentsSheet, "Ajustes Shopee");
    XLSX.utils.book_append_sheet(workbook, rawFinancialSheet, "Campos Shopee");
    XLSX.utils.book_append_sheet(workbook, itemsSheet, "Itens");
    XLSX.writeFile(workbook, `margem_contribuicao_${filters.dateFrom}_a_${filters.dateTo}.xlsx`, { compression: true });
  };

  run().catch((error) => {
    console.error(error);
    alert("Erro ao exportar planilha: " + error.message);
  });
}

// ---------------- CUSTOS ----------------
let COSTS_PAGE = 1;
const COSTS_PAGE_SIZE = 50;

function isCostsWithoutCostFilterActive() {
  return Boolean(document.getElementById("costsWithoutCost")?.checked);
}

function normalizeCostSpreadsheetHeader(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .toUpperCase();
}

function getCostSpreadsheetValue(row, headers) {
  const expected = new Set(headers.map(normalizeCostSpreadsheetHeader));
  const entry = Object.entries(row || {}).find(([key]) => expected.has(normalizeCostSpreadsheetHeader(key)));
  return entry ? entry[1] : undefined;
}
function initCosts() {
  document
    .getElementById("btnCostsPrev")
    ?.addEventListener("click", () => changeCostsPage(-1));
  document
    .getElementById("btnCostsNext")
    ?.addEventListener("click", () => changeCostsPage(1));
  document.getElementById("costsSearch")?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      COSTS_PAGE = 1;
      loadCosts();
    }
  });
  document.getElementById("costsWithoutCost")?.addEventListener("change", () => {
    COSTS_PAGE = 1;
    loadCosts();
  });

  document
    .getElementById("btnSaveTaxRate")
    ?.addEventListener("click", async () => {
      const taxRate = document.getElementById("shopTaxRate").value;
      try {
        await apiPatch("/shops/active/tax-rate", { taxRate });
        alert("Alíquota salva!");
      } catch (e) {
        alert("Erro ao salvar alíquota: " + e.message);
      }
    });

  // Export XLSX por padrão
  document.getElementById("btnExportCosts")?.addEventListener("click", () => {
    window.open("/shopee/shops/active/costs/export?format=xlsx", "_blank");
  });

  document.getElementById("btnImportCosts")?.addEventListener("click", () => {
    document.getElementById("fileImportCosts").click();
  });

  document
    .getElementById("fileImportCosts")
    ?.addEventListener("change", async (e) => {
      const file = e.target.files[0];
      if (!file) return;

      const fileName = file.name.toLowerCase();
      let items = [];

      try {
        if (fileName.endsWith(".xlsx") || fileName.endsWith(".xls")) {
          // Ler XLSX usando FileReader
          const reader = new FileReader();
          reader.onload = async (event) => {
            try {
              const data = new Uint8Array(event.target.result);
              const workbook = XLSX.read(data, { type: "array" });
              const sheet = workbook.Sheets[workbook.SheetNames[0]];
              const jsonData = XLSX.utils.sheet_to_json(sheet);

              const items = jsonData
                .map((row) => {
                  // Tenta encontrar colunas por nome (case-insensitive)
                  const itemId = getCostSpreadsheetValue(row, ["ID", "ITEM ID", "ITEMID"]);
                  const cost = getCostSpreadsheetValue(row, ["PREÇO", "PRECO", "CUSTO", "COST", "PRICE"]);

                  if (!itemId || cost === undefined) return null;

                  return {
                    itemId: String(itemId).trim(),
                    cost: parseFloat(
                      String(cost)
                        .replace(/[R$\s]/g, "")
                        .replace(",", "."),
                    ),
                  };
                })
                .filter(Boolean);

              if (items.length === 0) {
                alert(
                  "Nenhum item válido encontrado no XLSX. Verifique as colunas: ID, NOME, SKU, PREÇO",
                );
                e.target.value = "";
                return;
              }

              await enviarImportacao(items);
            } catch (err) {
              alert("Erro ao ler XLSX: " + err.message);
              e.target.value = "";
            }
          };
          reader.readAsArrayBuffer(file);
        } else if (fileName.endsWith(".csv")) {
          // Ler CSV (mantém compatibilidade)
          const text = await file.text();
          const lines = text.split(/\r?\n/).filter((l) => l.trim());

          for (let i = 0; i < lines.length; i++) {
            let line = lines[i].trim();
            if (!line) continue;

            // Ignorar header
            if (i === 0 && line.toLowerCase().startsWith("id")) continue;

            // Detectar separador
            const countSemi = (line.match(/;/g) || []).length;
            const countComma = (line.match(/,/g) || []).length;
            const sep = countSemi > countComma ? ";" : ",";

            // Parser simples que respeita aspas
            const cols = [];
            let current = "";
            let inQuotes = false;

            for (let j = 0; j < line.length; j++) {
              const char = line[j];

              if (char === '"') {
                inQuotes = !inQuotes;
              } else if (char === sep && !inQuotes) {
                cols.push(current.replace(/^"|"$/g, "").trim());
                current = "";
              } else {
                current += char;
              }
            }
            cols.push(current.replace(/^"|"$/g, "").trim());

            if (cols.length < 2) continue;

            // Col 0: ID (extrair só números)
            let itemIdRaw = cols[0];
            if (itemIdRaw.toUpperCase().includes("E+")) {
              itemIdRaw = itemIdRaw.replace(",", ".");
              const f = parseFloat(itemIdRaw);
              if (!isNaN(f)) {
                itemIdRaw = f.toLocaleString("fullwide", {
                  useGrouping: false,
                });
              }
            }
            // Remove tudo que não é número
            const itemId = itemIdRaw.replace(/[^0-9]/g, "");

            // Col 3 ou último com valor numérico: PREÇO
            let costStr = "";
            if (cols.length >= 4) {
              costStr = cols[3];
            } else if (cols.length >= 2) {
              // Se tiver menos colunas, tenta usar a última
              costStr = cols[cols.length - 1];
            }

            costStr = costStr.replace("R$", "").trim();

            if (costStr.includes(",") && costStr.includes(".")) {
              costStr = costStr.replace(/\./g, "").replace(",", ".");
            } else if (costStr.includes(",")) {
              costStr = costStr.replace(",", ".");
            }

            const cost = parseFloat(costStr);

            if (itemId && !isNaN(cost)) {
              items.push({ itemId, cost });
            }
          }

          if (items.length === 0) {
            alert("Nenhum item válido encontrado no CSV.");
            e.target.value = "";
            return;
          }

          await enviarImportacao(items);
        } else {
          alert("Formato inválido. Use XLSX ou CSV.");
          e.target.value = "";
        }
      } catch (err) {
        alert("Erro ao processar arquivo: " + err.message);
        e.target.value = "";
      }
    });

  async function enviarImportacao(items) {
    try {
      const res = await apiPost("/shops/active/costs/import", { items });
      alert(`Importação concluída! ${res.updated} itens atualizados.`);
      loadCosts();
    } catch (err) {
      alert("Erro na importação: " + err.message);
    }
  }
}

async function changeCostsPage(delta) {
  COSTS_PAGE += delta;
  if (COSTS_PAGE < 1) COSTS_PAGE = 1;
  await loadCosts();
}

async function loadCosts() {
  const search = document.getElementById("costsSearch").value;
  const withoutCost = isCostsWithoutCostFilterActive();
  const tbody = document.querySelector("#tblCosts tbody");
  if (!tbody) return;
  tbody.innerHTML = `<tr><td colspan="5"><div class="muted ui-state ui-state--loading">Carregando...</div></td></tr>`;

  try {
    const data = await apiGet(
      `/shops/active/costs?page=${COSTS_PAGE}&pageSize=${COSTS_PAGE_SIZE}&q=${encodeURIComponent(search)}&withoutCost=${withoutCost ? "1" : "0"}`,
    );

    // Atualiza Tax Rate se vier (vem no list)
    if (data.taxRate !== undefined) {
      document.getElementById("shopTaxRate").value = data.taxRate;
    }

    tbody.innerHTML = "";
    if (!data.items || data.items.length === 0) {
      tbody.innerHTML = `<tr><td colspan="5"><div class="muted ui-state ui-state--empty">Nenhum produto encontrado.</div></td></tr>`;
      return;
    }

    data.items.forEach((it) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
            <td>${it.itemId}</td>
            <td>
                <div style="display:flex; align-items:center; gap:8px;">
                    ${it.imageUrl ? `<img src="${it.imageUrl}" style="width:32px;height:32px;object-fit:cover;">` : ""}
                    <span>${it.title}</span>
                </div>
            </td>
            <td>${it.itemSku || "-"}</td>
            <td>
                <input type="number" step="0.01" class="input input-sm cost-input" data-id="${it.id}" value="${Number(it.cost).toFixed(2)}" style="width: 80px;">
            </td>
            <td>
                <button class="btn btn-ghost btn-sm btn-save-cost" data-id="${it.id}">Salvar</button>
            </td>
        `;
      tbody.appendChild(tr);
    });

    // Eventos de salvar
    tbody.querySelectorAll(".btn-save-cost").forEach((btn) => {
      btn.addEventListener("click", async (e) => {
        const id = e.target.dataset.id;
        const input = tbody.querySelector(`.cost-input[data-id="${id}"]`);
        const cost = input.value;
        try {
          await apiPatch(`/shops/active/products/${id}/cost`, { cost });
          // feedback visual?
          e.target.textContent = "Salvo!";
          setTimeout(() => (e.target.textContent = "Salvar"), 1000);
          if (withoutCost && Number(cost) > 0) {
            COSTS_PAGE = 1;
            await loadCosts();
          }
        } catch (err) {
          alert("Erro ao salvar: " + err.message);
        }
      });
    });

    // Salvar ao dar Enter no input
    tbody.querySelectorAll(".cost-input").forEach((input) => {
      input.addEventListener("keydown", async (e) => {
        if (e.key === "Enter") {
          const id = e.target.dataset.id;
          const cost = e.target.value;
          try {
            await apiPatch(`/shops/active/products/${id}/cost`, { cost });
            input.blur();
            // feedback visual
            input.style.borderColor = "var(--up)";
            setTimeout(() => (input.style.borderColor = ""), 1000);
            if (withoutCost && Number(cost) > 0) {
              COSTS_PAGE = 1;
              await loadCosts();
            }
          } catch (err) {
            alert("Erro ao salvar: " + err.message);
          }
        }
      });
    });

    setText(
      "costsPageInfo",
      `Página ${data.page} de ${data.totalPages} (${data.total} itens)`,
    );
  } catch (e) {
    console.error(e);
    tbody.innerHTML = `<tr><td colspan="5"><div class="muted ui-state ui-state--error">Erro: ${escapeHtml(e.message)}</div></td></tr>`;
  }
}

function parseIntelligentPricingIdsInput(value) {
  return Array.from(
    new Set(
      String(value || "")
        .split(/[\s,;\n\r\t]+/)
        .map((token) => token.replace(/[^0-9]/g, "").trim())
        .filter(Boolean),
    ),
  ).slice(0, INTELLIGENT_PRICING_MAX_IDS);
}

function toMoneyNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function toNonNegativeMoney(value, fallback = 0) {
  return Math.max(0, toMoneyNumber(value, fallback));
}

function resolveCommissionRule(unitPrice) {
  const price = toNonNegativeMoney(unitPrice, 0);
  if (price < 8) {
    return {
      pct: 0.2,
      fixedPerItem: price / 2,
      label: "20% + taxa reduzida (50% do preco)",
      lowPriceProtection: true,
    };
  }
  if (price <= 79.99) {
    return {
      pct: 0.2,
      fixedPerItem: 4,
      label: "20% + R$4/item",
    };
  }
  if (price <= 99.99) {
    return {
      pct: 0.14,
      fixedPerItem: 16,
      label: "14% + R$16/item",
    };
  }
  if (price <= 199.99) {
    return {
      pct: 0.14,
      fixedPerItem: 20,
      label: "14% + R$20/item",
    };
  }
  return {
    pct: 0.14,
    fixedPerItem: 26,
    label: "14% + R$26/item (faixa >= R$200)",
  };
}

function calculateShopeeFees(unitPrice, quantity = 1) {
  const normalizedPrice = toNonNegativeMoney(unitPrice, 0);
  const normalizedQuantity = Math.max(1, Math.floor(toMoneyNumber(quantity, 1)));
  const commissionRule = resolveCommissionRule(normalizedPrice);
  const commissionValue = normalizedPrice * normalizedQuantity * commissionRule.pct;
  const fixedFeeValue = commissionRule.fixedPerItem * normalizedQuantity;
  const totalFees = commissionValue + fixedFeeValue;

  return {
    commissionRule,
    commissionValue,
    fixedFeeValue,
    totalFees,
    payoutBeforeCostsAndTaxes: normalizedPrice * normalizedQuantity - totalFees,
  };
}

function resolveFreightCouponCap(unitPrice) {
  const price = toNonNegativeMoney(unitPrice, 0);
  if (price <= 79.99) return 20;
  if (price <= 199.99) return 30;
  return 40;
}

function resolvePixDiscountPct(baseValue) {
  const value = toNonNegativeMoney(baseValue, 0);
  if (value >= 500) return 0.08;
  if (value >= 80) return 0.05;
  return 0;
}

function resolveVoucherDiscountValue(voucher, baseAmount) {
  const base = toNonNegativeMoney(baseAmount, 0);
  if (!(base > 0)) return 0;

  const minSpend = toNonNegativeMoney(voucher?.minSpendAmount, 0);
  if (minSpend > 0 && base < minSpend) return 0;

  const rewardType = Number(voucher?.rewardType || 0);
  let discountValue = 0;

  if (rewardType === 1) {
    discountValue = toNonNegativeMoney(voucher?.discountAmount, 0);
  } else if (rewardType === 2 || rewardType === 3) {
    const percentage = Math.max(0, Math.min(100, toMoneyNumber(voucher?.percentage, 0)));
    discountValue = (base * percentage) / 100;
  }

  const maxDiscount = toNonNegativeMoney(voucher?.maxDiscountAmount, 0);
  if (maxDiscount > 0) discountValue = Math.min(discountValue, maxDiscount);
  return Math.min(base, Math.max(0, discountValue));
}

function resolveVoucherCandidatesForItem(_item, unitPrice, quantity) {
  const activeVouchers = (Array.isArray(INTELLIGENT_PRICING_STATE.voucherList)
    ? INTELLIGENT_PRICING_STATE.voucherList
    : []
  ).filter((voucher) => Boolean(voucher?.isActiveNow));
  if (!activeVouchers.length) return [];

  const baseQty = Math.max(1, Math.floor(toMoneyNumber(quantity, 1)));
  const baseValue = toNonNegativeMoney(unitPrice, 0) * baseQty;

  return activeVouchers
    .map((voucher) => {
      const voucherId = String(voucher?.voucherId || "").trim();
      if (!voucherId) return null;
      const discountValue = resolveVoucherDiscountValue(voucher, baseValue);
      if (!(discountValue > 0)) return null;
      const voucherName = String(
        voucher?.voucherName || voucher?.voucherCode || "Voucher",
      ).trim();
      return {
        voucherId,
        voucherName,
        discountValue,
      };
    })
    .filter(Boolean);
}

function resolveSellerCouponSelection(item, unitPrice, quantity) {
  const mode = String(INTELLIGENT_PRICING_STATE.couponMode || "selected")
    .trim()
    .toLowerCase();
  if (mode === "none") return null;

  const candidates = resolveVoucherCandidatesForItem(item, unitPrice, quantity);
  if (!candidates.length) return null;

  if (mode === "max") {
    return candidates.reduce((best, current) =>
      current.discountValue > (best?.discountValue || 0) ? current : best,
    );
  }
  if (mode === "min") {
    return candidates.reduce((best, current) =>
      current.discountValue < (best?.discountValue || Number.POSITIVE_INFINITY)
        ? current
        : best,
    );
  }

  const selectedId = String(INTELLIGENT_PRICING_STATE.selectedCouponId || "").trim();
  const selected = selectedId
    ? candidates.find((entry) => String(entry.voucherId) === selectedId) || null
    : null;
  return selected || candidates[0];
}

function computeIntelligentPricingForItem(item, state) {
  const quantity = Math.max(1, Math.floor(toMoneyNumber(item?.quantity, 1)));
  const unitPrice = toNonNegativeMoney(item?.price, 0);
  const grossValue = unitPrice * quantity;
  const shippingEstimate = toNonNegativeMoney(state?.shippingEstimate, 0);
  const taxRate = Math.max(0, toMoneyNumber(state?.taxRate, 0));
  const effectiveCost = toNonNegativeMoney(
    item?.costCustom != null ? item.costCustom : item?.costBase,
    0,
  );
  const costTotal = effectiveCost * quantity;

  const commissionRule = resolveCommissionRule(unitPrice);
  const couponSelection = resolveSellerCouponSelection(item, unitPrice, quantity);
  let sellerCouponDiscount = toNonNegativeMoney(couponSelection?.discountValue, 0);
  sellerCouponDiscount = Math.min(grossValue, Math.max(0, sellerCouponDiscount));

  const subtotalAfterSellerCoupon = Math.max(0, grossValue - sellerCouponDiscount);
  const freightCouponCap = resolveFreightCouponCap(unitPrice) * quantity;
  const freightCouponApplied = Math.min(shippingEstimate, freightCouponCap);
  const customerShipping = Math.max(0, shippingEstimate - freightCouponApplied);

  const pixDiscountPct = resolvePixDiscountPct(subtotalAfterSellerCoupon);
  const pixDiscountValue = subtotalAfterSellerCoupon * pixDiscountPct;

  const customerInstallmentTotal = subtotalAfterSellerCoupon + customerShipping;
  const customerPixTotal = Math.max(0, customerInstallmentTotal - pixDiscountValue);
  const shopeeRebates = pixDiscountValue + freightCouponApplied;

  const commissionsValue =
    subtotalAfterSellerCoupon * commissionRule.pct +
    commissionRule.fixedPerItem * quantity;
  const taxesValue = subtotalAfterSellerCoupon * (taxRate / 100);
  const netReceivable =
    subtotalAfterSellerCoupon - commissionsValue - taxesValue - costTotal;

  return {
    quantity,
    unitPrice,
    grossValue,
    sellerCouponDiscount,
    subtotalAfterSellerCoupon,
    shippingEstimate,
    freightCouponCap,
    freightCouponApplied,
    customerShipping,
    pixDiscountPct,
    pixDiscountValue,
    customerInstallmentTotal,
    customerPixTotal,
    shopeeRebates,
    commissionsValue,
    taxesValue,
    costTotal,
    netReceivable,
    commissionRule,
    appliedCoupon: couponSelection,
  };
}

function renderIntelligentPricingLowPriceGuidance() {
  const guidanceEl = document.getElementById("intelligentPricingLowPriceGuidance");
  if (!guidanceEl) return;

  const lowPriceItems = (Array.isArray(INTELLIGENT_PRICING_STATE.items)
    ? INTELLIGENT_PRICING_STATE.items
    : [])
    .map((item) => ({ item, price: toNonNegativeMoney(item?.price, 0) }))
    .filter(({ price }) => price > 0 && price < 8);

  if (!lowPriceItems.length) {
    guidanceEl.hidden = true;
    guidanceEl.innerHTML = "";
    return;
  }

  const examples = lowPriceItems.slice(0, 3).map(({ item, price }) => {
    const individual = calculateShopeeFees(price);
    const kitPrice = price * 4;
    const kit = calculateShopeeFees(kitPrice);
    const title = String(item?.title || item?.itemId || "Produto").trim();
    const feePct = price > 0 ? (individual.totalFees / price) * 100 : 0;

    return `
      <article class="ip-low-price-item">
        <strong>${escapeHtml(title)}</strong>
        <span>Preco de venda: ${formatBRL(price)}</span>
        <span>Comissao (20%): ${formatBRL(individual.commissionValue)}</span>
        <span>Taxa fixa reduzida (50% do preco): ${formatBRL(individual.fixedFeeValue)}</span>
        <span>Total de taxas Shopee: ${formatBRL(individual.totalFees)} (${feePct.toFixed(0)}% do faturamento)</span>
        <span class="ip-low-price-item__result">Repasse antes de custo e impostos: ${formatBRL(individual.payoutBeforeCostsAndTaxes)}</span>
        <div class="ip-kit-comparison">
          <strong>Kit recomendado: 4 unidades por ${formatBRL(kitPrice)}</strong>
          <span>Taxas do kit: ${formatBRL(kit.totalFees)} | Repasse: ${formatBRL(kit.payoutBeforeCostsAndTaxes)} (${formatBRL(kit.payoutBeforeCostsAndTaxes / 4)} por unidade)</span>
        </div>
      </article>
    `;
  });

  const extraItems = lowPriceItems.length - examples.length;
  guidanceEl.hidden = false;
  guidanceEl.innerHTML = `
    <div class="ip-low-price-guidance__title">Protecao para itens abaixo de R$ 8,00</div>
    <p>A taxa fixa de R$ 4,00 e substituida por 50% do preco do anuncio. O repasse abaixo nao inclui custo do produto, imposto da loja ou cupons.</p>
    <div class="ip-low-price-guidance__grid">${examples.join("")}</div>
    ${extraItems > 0 ? `<div class="muted">Mais ${extraItems} item(ns) abaixo de R$ 8,00 seguem esta mesma regra.</div>` : ""}
    <div class="ip-low-price-guidance__warning"><strong>Atencao para CPF:</strong> caso a conta tenha ultrapassado 450 pedidos nos ultimos 90 dias, a Shopee pode aplicar uma taxa adicional em itens abaixo de R$ 12,00. Essa taxa nao esta incluida nesta simulacao.</div>
  `;
}

