async function loadSalesControl() {
  const statusEl = document.getElementById("salesControlStatus");
  const summaryEl = document.getElementById("salesControlSummary");
  const bodyEl = document.getElementById("salesControlBody");
  const insightsEl = document.getElementById("salesControlInsights");
  if (!statusEl || !summaryEl || !bodyEl || !insightsEl) return;

  setDefaultRangeInputs("salesControlDateFrom", "salesControlDateTo", 30);
  statusEl.textContent = "Carregando tráfego orgânico...";
  summaryEl.innerHTML = "";
  bodyEl.innerHTML = '<tr><td colspan="5"><div class="muted">Carregando...</div></td></tr>';
  insightsEl.innerHTML = '<div class="muted">Processando insights...</div>';

  const limit = String(document.getElementById("salesControlLimit")?.value || "20").trim();
  const filterMode = String(
    document.getElementById("salesControlFilterMode")?.value || "low_conversion",
  ).trim();
  const maxConversionPct = String(
    document.getElementById("salesControlMaxConversionPct")?.value || "2",
  ).trim();
  const itemId = String(
    document.getElementById("salesControlItemId")?.value || "",
  ).trim();
  const qs = buildDateRangeQuery("salesControlDateFrom", "salesControlDateTo");
  qs.set("limit", limit);
  qs.set("filterMode", filterMode);
  qs.set("maxConversionPct", maxConversionPct);
  if (itemId) qs.set("itemId", itemId);

  try {
    await ensureShopSelected();
    const data = await apiGet(
      `/shops/${SHOP_PATH_PLACEHOLDER}/products/sales-control?${qs.toString()}`,
    );
    SALES_CONTROL_LAST_DATA = data;
    renderSalesControlSummary(data);
    renderSalesControlTable(data?.items || []);
    renderSalesControlInsights(data?.insights || []);
    statusEl.textContent = `Top ${formatInt(
      data?.summary?.selectedRows || 0,
    )} carregado(s) para revisão de conversão.`;
  } catch (error) {
    statusEl.textContent = `Erro ao carregar Controle de Vendas: ${error.message}`;
    renderSalesControlTable([]);
    renderSalesControlInsights([]);
  }
}

