function toProductRankingNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function getProductRankingMode() {
  return String(
    document.getElementById("productRankingMode")?.value || "revenue",
  );
}

function getProductRankingLimit() {
  const n = Number(document.getElementById("productRankingLimit")?.value || 20);
  return Number.isFinite(n) && n > 0 ? n : 20;
}

function getProductRankingScore(row) {
  const growth = toProductRankingNumber(row.growthRevenuePct, 0);
  const orders = toProductRankingNumber(row.orders, 0);
  const share = toProductRankingNumber(row.shareRevenuePct, 0);
  let score = 55;
  score += Math.max(-20, Math.min(20, growth * 0.35));
  score += Math.max(0, Math.min(15, Math.log10(Math.max(orders, 1)) * 8));
  score += Math.max(0, Math.min(15, share * 0.8));
  return Math.max(0, Math.min(100, Math.round(score)));
}

function getProductRankingRecommendation(row) {
  const growth = toProductRankingNumber(row.growthRevenuePct, 0);
  const orders = toProductRankingNumber(row.orders, 0);
  const score = getProductRankingScore(row);
  if (growth <= -15) return "Revisar preço e conteúdo";
  if (orders <= 2) return "Aumentar tráfego e vitrine";
  if (score >= 80 && growth >= 10) return "Escalar investimento";
  if (score < 50) return "Ação corretiva imediata";
  return "Manter e monitorar";
}

function getProductRankingMetricValue(row, mode = "revenue") {
  const source = row && typeof row === "object" ? row : {};
  const revenue = toProductRankingNumber(source.revenue, 0);
  const orders = toProductRankingNumber(source.orders, 0);
  const growth = toProductRankingNumber(source.growthRevenuePct, 0);
  const ticket = orders > 0 ? revenue / orders : 0;
  const participation = toProductRankingNumber(source.shareRevenuePct, 0);
  const stability = getProductRankingScore(source);

  switch (String(mode || "revenue")) {
    case "orders":
      return orders;
    case "growth":
      return growth;
    case "ticket":
      return ticket;
    case "stability":
      return stability;
    case "participation":
      return participation;
    case "revenue":
    default:
      return revenue;
  }
}

function getProductRankingModeLabel(mode = "revenue") {
  switch (String(mode || "revenue")) {
    case "orders":
      return "Vendas";
    case "growth":
      return "Crescimento";
    case "ticket":
      return "Ticket médio";
    case "stability":
      return "Estabilidade";
    case "participation":
      return "Participação";
    case "revenue":
    default:
      return "Faturamento";
  }
}

function formatProductRankingMetricValue(value, mode = "revenue") {
  const normalized = String(mode || "revenue");
  const n = toProductRankingNumber(value, 0);
  if (normalized === "revenue" || normalized === "ticket") {
    return formatBRL(n);
  }
  if (normalized === "orders") {
    return `${formatInt(Math.round(n))} venda(s)`;
  }
  if (normalized === "stability") {
    return `${Number(n.toFixed(1))} pts`;
  }
  if (normalized === "growth" || normalized === "participation") {
    return `${n >= 0 ? "+" : ""}${Number(n.toFixed(2))}%`;
  }
  return String(Number(n.toFixed(2)));
}

function normalizeProductRankingCategoryId(value) {
  const raw = String(value ?? "").trim();
  return raw && raw !== "0" ? raw : "";
}

function resolveProductRankingCategoryLabel(categoryId) {
  const normalized = normalizeProductRankingCategoryId(categoryId);
  if (!normalized) return "Sem categoria";
  return PRODUCT_RANKING_CATEGORY_LABELS.get(normalized) || `Categoria ${normalized}`;
}

async function ensureProductRankingCategoryLabels() {
  if (PRODUCT_RANKING_CATEGORY_LABELS.size > 0) return;
  if (PRODUCT_RANKING_CATEGORY_LOADING_PROMISE) {
    await PRODUCT_RANKING_CATEGORY_LOADING_PROMISE;
    return;
  }

  PRODUCT_RANKING_CATEGORY_LOADING_PROMISE = (async () => {
    try {
      const payload = await apiGet("/shops/active/listing-clone/categories");
      const categories = Array.isArray(payload?.categories) ? payload.categories : [];
      const map = new Map();
      categories.forEach((entry) => {
        const categoryId = normalizeProductRankingCategoryId(entry?.categoryId);
        if (!categoryId) return;
        const label = String(entry?.displayName || entry?.path || entry?.name || "").trim();
        if (!label) return;
        map.set(categoryId, label);
      });
      if (map.size > 0) {
        PRODUCT_RANKING_CATEGORY_LABELS = map;
      }
    } catch (_error) {
      // fallback para usar categoryId quando o dicionario de categorias nao estiver disponivel
    } finally {
      PRODUCT_RANKING_CATEGORY_LOADING_PROMISE = null;
    }
  })();

  await PRODUCT_RANKING_CATEGORY_LOADING_PROMISE;
}

function formatProductRankingDelta(currentPos, previousPos) {
  if (!previousPos) return '<span class="product-ranking-pill">Novo</span>';
  const diff = previousPos - currentPos;
  if (diff > 0) {
    return `<span class="product-ranking-pill product-ranking-pill--up">↑ +${diff}</span>`;
  }
  if (diff < 0) {
    return `<span class="product-ranking-pill product-ranking-pill--down">↓ ${Math.abs(diff)}</span>`;
  }
  return '<span class="product-ranking-pill">—</span>';
}

function setProductRankingDefaultRanges() {
  const fromEl = document.getElementById("productRankingDateFrom");
  const toEl = document.getElementById("productRankingDateTo");
  const compareFromEl = document.getElementById("productRankingCompareFrom");
  const compareToEl = document.getElementById("productRankingCompareTo");
  if (!fromEl || !toEl || !compareFromEl || !compareToEl) return;

  const today = new Date();
  const currentFrom = new Date(today.getFullYear(), today.getMonth(), 1);
  const currentTo = new Date(today);

  if (!fromEl.value) fromEl.value = isoLocalDate(currentFrom);
  if (!toEl.value) toEl.value = isoLocalDate(currentTo);

  if (!compareFromEl.value || !compareToEl.value) {
    const from = new Date(`${fromEl.value}T00:00:00`);
    const to = new Date(`${toEl.value}T00:00:00`);
    const diffDays = Math.max(
      1,
      Math.floor((to.getTime() - from.getTime()) / 86400000) + 1,
    );
    const compareTo = new Date(from);
    compareTo.setDate(compareTo.getDate() - 1);
    const compareFrom = new Date(compareTo);
    compareFrom.setDate(compareFrom.getDate() - (diffDays - 1));
    compareFromEl.value = isoLocalDate(compareFrom);
    compareToEl.value = isoLocalDate(compareTo);
  }
}

async function fetchProductRankingRange(dateFrom, dateTo) {
  const qs = new URLSearchParams({
    dateFrom: String(dateFrom || ""),
    dateTo: String(dateTo || ""),
  });
  const data = await apiGet(
    `/shops/${SHOP_PATH_PLACEHOLDER}/products/sales-share?${qs.toString()}`,
  );
  const rows = Array.isArray(data?.lists?.withSales) ? data.lists.withSales : [];
  return {
    meta: data?.meta || {},
    summary: data?.summary || {},
    rows,
  };
}

function buildProductRankingView(currentData, compareData, mode, limit) {
  const normalizeRows = (rows) =>
    (Array.isArray(rows) ? rows : []).filter(
      (row) => row && typeof row === "object",
    );

  const currentRows = normalizeRows(currentData?.rows);
  const compareRows = normalizeRows(compareData?.rows);
  const compareMap = new Map(
    compareRows.map((row) => [String(row.itemId || ""), row]),
  );

  const sortByMode = (rows) =>
    [...rows].sort(
      (a, b) =>
        getProductRankingMetricValue(b, mode) -
          getProductRankingMetricValue(a, mode) ||
        toProductRankingNumber(b?.revenue, 0) - toProductRankingNumber(a?.revenue, 0),
    );

  const compareRanking = sortByMode(compareRows);
  const comparePosMap = new Map(
    compareRanking.map((row, index) => [String(row.itemId || ""), index + 1]),
  );

  const ranked = sortByMode(currentRows).map((row, index) => {
    const itemKey = String(row.itemId || "");
    const previous = compareMap.get(itemKey) || null;
    const previousPosition = comparePosMap.get(itemKey) || null;
    const revenue = toProductRankingNumber(row.revenue, 0);
    const orders = toProductRankingNumber(row.orders, 0);
    const ticket = orders > 0 ? revenue / orders : 0;
    return {
      ...row,
      positionCurrent: index + 1,
      positionPrevious: previousPosition,
      revenue,
      orders,
      ticket,
      score: getProductRankingScore(row),
      recommendation: getProductRankingRecommendation(row),
      previousRevenue: toProductRankingNumber(previous?.revenue, 0),
      previousOrders: toProductRankingNumber(previous?.orders, 0),
    };
  });

  const totalRevenue = ranked.reduce((sum, row) => sum + row.revenue, 0);
  const topRows = ranked.slice(0, Math.max(1, limit));
  const topItemIds = new Set(topRows.map((row) => String(row.itemId || "")));
  const top3Revenue = topRows
    .slice(0, 3)
    .reduce((sum, row) => sum + row.revenue, 0);
  const top3Share = totalRevenue > 0 ? (top3Revenue / totalRevenue) * 100 : 0;
  const up = topRows.filter(
    (row) =>
      row.positionPrevious && row.positionCurrent < row.positionPrevious,
  ).length;
  const down = topRows.filter(
    (row) =>
      row.positionPrevious && row.positionCurrent > row.positionPrevious,
  ).length;
  const entered = topRows.filter((row) => !row.positionPrevious).length;
  const avgGrowth =
    topRows.length > 0
      ? topRows.reduce(
          (sum, row) => sum + toProductRankingNumber(row.growthRevenuePct, 0),
          0,
        ) / topRows.length
      : 0;
  const bestUpRow = topRows
    .filter(
      (row) =>
        row.positionPrevious && row.positionCurrent < row.positionPrevious,
    )
    .sort(
      (a, b) =>
        (b.positionPrevious - b.positionCurrent) -
        (a.positionPrevious - a.positionCurrent),
    )[0] || null;
  const bestDownRow = topRows
    .filter(
      (row) =>
        row.positionPrevious && row.positionCurrent > row.positionPrevious,
    )
    .sort(
      (a, b) =>
        (b.positionCurrent - b.positionPrevious) -
        (a.positionCurrent - a.positionPrevious),
    )[0] || null;
  const exitedFromTop = compareRanking
    .slice(0, Math.max(1, limit))
    .filter((row) => !topItemIds.has(String(row.itemId || "")))
    .slice(0, 12)
    .map((row, index) => ({
      ...row,
      positionPrevious: index + 1,
      previousRevenue: toProductRankingNumber(row.revenue, 0),
      previousOrders: toProductRankingNumber(row.orders, 0),
    }));

  return {
    mode,
    limit,
    totalRevenue,
    top3Share,
    up,
    down,
    entered,
    avgGrowth,
    bestUpRow,
    bestDownRow,
    exitedFromTop,
    topRows,
    ranked,
    currentData,
    compareData,
  };
}

function getProductSalesCategory(row) {
  return resolveProductRankingCategoryLabel(row?.categoryId);
}

function destroyProductRankingCharts() {
  if (PRODUCT_RANKING_EVOLUTION_CHART) {
    PRODUCT_RANKING_EVOLUTION_CHART.destroy();
    PRODUCT_RANKING_EVOLUTION_CHART = null;
  }
  if (PRODUCT_RANKING_DISTRIBUTION_CHART) {
    PRODUCT_RANKING_DISTRIBUTION_CHART.destroy();
    PRODUCT_RANKING_DISTRIBUTION_CHART = null;
  }
}

function renderProductRankingCharts(view) {
  const evolutionCanvas = document.getElementById("productRankingEvolutionChart");
  const evolutionExplainEl = document.getElementById("productRankingEvolutionExplain");
  const distributionCanvas = document.getElementById(
    "productRankingDistributionChart",
  );
  const legendEl = document.getElementById("productRankingDistributionLegend");
  if (!evolutionCanvas || !distributionCanvas) {
    return;
  }

  const mode = String(view?.mode || getProductRankingMode());
  const modeLabel = getProductRankingModeLabel(mode);
  const chartTheme = getUiChartThemeColors();
  const currentTop = view.topRows;
  const compareRows = Array.isArray(view.compareData?.rows)
    ? view.compareData.rows.filter((row) => row && typeof row === "object")
    : [];
  compareRows.sort(
    (a, b) =>
      getProductRankingMetricValue(b, mode) -
        getProductRankingMetricValue(a, mode) ||
      toProductRankingNumber(b?.revenue, 0) - toProductRankingNumber(a?.revenue, 0),
  );
  const compareTop = compareRows.slice(0, currentTop.length);

  const metricValueForMode = (row) =>
    toProductRankingNumber(getProductRankingMetricValue(row, mode), 0);
  let accCurrent = 0;
  let accCompare = 0;
  const labels = currentTop.map((_, idx) => `Top ${idx + 1}`);
  const currentSeries = currentTop.map((row) => {
    accCurrent += metricValueForMode(row);
    return Number(accCurrent.toFixed(2));
  });
  const compareSeries = labels.map((_, idx) => {
    accCompare += metricValueForMode(compareTop[idx] || null);
    return Number(accCompare.toFixed(2));
  });

  destroyProductRankingCharts();

  if (typeof Chart !== "undefined") {
    PRODUCT_RANKING_EVOLUTION_CHART = new Chart(evolutionCanvas.getContext("2d"), {
      type: "line",
      data: {
        labels,
        datasets: [
          {
            label: `${modeLabel} acumulado (atual)`,
            data: currentSeries,
            borderColor: "rgba(64, 132, 255, 1)",
            backgroundColor: "rgba(64, 132, 255, 0.15)",
            borderWidth: 2,
            tension: 0.25,
            fill: true,
            pointRadius: 2,
            pointHoverRadius: 5,
            pointHitRadius: 18,
          },
          {
            label: `${modeLabel} acumulado (comparação)`,
            data: compareSeries,
            borderColor: "rgba(120, 128, 144, 1)",
            backgroundColor: "rgba(120, 128, 144, 0.15)",
            borderWidth: 2,
            tension: 0.25,
            fill: true,
            pointRadius: 2,
            pointHoverRadius: 5,
            pointHitRadius: 18,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: "index", intersect: false },
        plugins: {
          legend: { display: true, labels: { color: chartTheme.legend } },
          tooltip: {
            backgroundColor: chartTheme.tooltipBg,
            borderColor: chartTheme.tooltipBorder,
            borderWidth: 1,
            titleColor: chartTheme.tooltipTitle,
            bodyColor: chartTheme.tooltipBody,
            displayColors: true,
            callbacks: {
              title(items) {
                const first = Array.isArray(items) && items.length ? items[0] : null;
                const topPos = toProductRankingNumber(first?.dataIndex, 0) + 1;
                return `Acumulado até Top ${topPos}`;
              },
              label(ctx) {
                const val = toProductRankingNumber(ctx?.raw, 0);
                return `${ctx.dataset?.label || "Série"}: ${formatProductRankingMetricValue(val, mode)}`;
              },
            },
          },
        },
        scales: {
          x: {
            grid: { color: chartTheme.grid },
            ticks: { color: chartTheme.axis, maxTicksLimit: 12 },
          },
          y: {
            grid: { color: chartTheme.grid },
            title: {
              display: true,
              text: `${modeLabel} acumulado`,
              color: chartTheme.axis,
            },
            ticks: {
              color: chartTheme.axis,
              callback(value) {
                return formatProductRankingMetricValue(value, mode);
              },
            },
          },
        },
      },
    });
  }
  renderProductRankingEvolutionExplain({
    view,
    mode,
    modeLabel,
    currentSeries,
    compareSeries,
    currentTop,
    compareTop,
    root: evolutionExplainEl,
  });

  const categoryBuckets = new Map();
  view.topRows.forEach((row) => {
    const key = getProductSalesCategory(row);
    const prev = categoryBuckets.get(key) || {
      revenue: 0,
      orders: 0,
      items: 0,
    };
    prev.revenue += toProductRankingNumber(row.revenue, 0);
    prev.orders += toProductRankingNumber(row.orders, 0);
    prev.items += 1;
    categoryBuckets.set(key, prev);
  });
  const categoryPalette = [
    "#2563eb",
    "#0891b2",
    "#7c3aed",
    "#f59e0b",
    "#f97316",
    "#16a34a",
    "#ef4444",
    "#6b7280",
  ];
  const categoryEntries = [...categoryBuckets.entries()]
    .map(([label, bucket]) => ({
      label,
      ...bucket,
    }))
    .sort((a, b) => b.revenue - a.revenue);
  const chartEntries =
    categoryEntries.length > 0
      ? categoryEntries
      : [
          {
            label: "Sem dados",
            revenue: 0,
            orders: 0,
            items: 0,
          },
        ];

  if (typeof Chart !== "undefined") {
    PRODUCT_RANKING_DISTRIBUTION_CHART = new Chart(
      distributionCanvas.getContext("2d"),
      {
        type: "doughnut",
        data: {
        labels: chartEntries.map((entry) => entry.label),
        datasets: [
          {
            data: chartEntries.map((entry) => Number(entry.revenue.toFixed(2))),
            backgroundColor: chartEntries.map(
              (_entry, index) => categoryPalette[index % categoryPalette.length],
            ),
            borderColor: "rgba(255,255,255,0.08)",
            borderWidth: 1,
            hoverOffset: 10,
          },
        ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: "nearest", intersect: false },
          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: chartTheme.tooltipBg,
              borderColor: chartTheme.tooltipBorder,
              borderWidth: 1,
              titleColor: chartTheme.tooltipTitle,
              bodyColor: chartTheme.tooltipBody,
              callbacks: {
                title(items) {
                  const first = Array.isArray(items) && items.length ? items[0] : null;
                  const idx = toProductRankingNumber(first?.dataIndex, -1);
                  return idx >= 0 && chartEntries[idx] ? chartEntries[idx].label : "Categoria";
                },
                label(ctx) {
                  const idx = toProductRankingNumber(ctx?.dataIndex, -1);
                  const entry = idx >= 0 ? chartEntries[idx] : null;
                  const revenue = toProductRankingNumber(entry?.revenue, 0);
                  return `Faturamento: ${formatBRL(revenue)}`;
                },
                afterLabel(ctx) {
                  const idx = toProductRankingNumber(ctx?.dataIndex, -1);
                  const entry = idx >= 0 ? chartEntries[idx] : null;
                  const orders = toProductRankingNumber(entry?.orders, 0);
                  const items = toProductRankingNumber(entry?.items, 0);
                  const totalRevenue = chartEntries.reduce(
                    (acc, current) => acc + toProductRankingNumber(current?.revenue, 0),
                    0,
                  );
                  const revenue = toProductRankingNumber(entry?.revenue, 0);
                  const sharePct = totalRevenue > 0 ? (revenue / totalRevenue) * 100 : 0;
                  return [
                    `Vendas: ${formatInt(orders)}`,
                    `IDs: ${formatInt(items)}`,
                    `Participação: ${sharePct.toFixed(1)}%`,
                  ];
                },
              },
            },
          },
        },
      },
    );
  }

  if (legendEl) {
    legendEl.innerHTML = chartEntries
      .map(
        (entry, index) =>
          `<div>
            <span class="product-ranking-legend__label"><i style="background:${escapeHtml(categoryPalette[index % categoryPalette.length])}"></i>${escapeHtml(entry.label)}</span>
            <strong>${formatBRL(entry.revenue)} • ${formatInt(entry.orders)} vendas • ${formatInt(entry.items)} IDs</strong>
          </div>`,
      )
      .join("");
  }
}

function renderProductRankingEvolutionExplain({
  view,
  mode,
  modeLabel,
  currentSeries = [],
  compareSeries = [],
  currentTop = [],
  compareTop = [],
  root = null,
} = {}) {
  const explainEl = root || document.getElementById("productRankingEvolutionExplain");
  if (!explainEl) return;

  if (!currentTop.length) {
    explainEl.innerHTML = '<div class="muted">Sem dados suficientes para explicar a curva acumulada.</div>';
    return;
  }

  const lastCurrent = toProductRankingNumber(currentSeries[currentSeries.length - 1], 0);
  const lastCompare = toProductRankingNumber(compareSeries[compareSeries.length - 1], 0);
  const diff = lastCurrent - lastCompare;
  const diffPct = lastCompare > 0 ? Number((((lastCurrent - lastCompare) / lastCompare) * 100).toFixed(1)) : null;
  const firstCurrent = toProductRankingNumber(currentSeries[0], 0);
  const firstCompare = toProductRankingNumber(compareSeries[0], 0);
  const top3Current = toProductRankingNumber(currentSeries[Math.min(2, currentSeries.length - 1)], 0);
  const top3Compare = toProductRankingNumber(compareSeries[Math.min(2, compareSeries.length - 1)], 0);
  const concentrationTop3Pct =
    lastCurrent > 0 ? Number(((top3Current / lastCurrent) * 100).toFixed(1)) : 0;
  const orderingHint = getProductRankingModeLabel(mode);

  explainEl.innerHTML = `
    <div class="product-ranking-evolution-explain__title">Como ler a Evolução acumulada (${escapeHtml(modeLabel)})</div>
    <div class="product-ranking-evolution-explain__text">
      Cada ponto no eixo X representa o acumulado da métrica para os produtos do Top até aquela posição.
      Exemplo: no ponto <strong>Top 3</strong>, o gráfico soma os valores dos itens #1, #2 e #3 do ranking no modo <strong>${escapeHtml(orderingHint)}</strong>.
    </div>
    <div class="product-ranking-evolution-explain__text">
      A linha azul mostra o período atual e a linha cinza mostra o período de comparação, ambas acumulando a mesma métrica selecionada.
      Se a azul está acima da cinza, o período atual está performando melhor naquele trecho do ranking.
    </div>
    <div class="product-ranking-evolution-explain__metrics">
      <span>Top 1 atual: <strong>${escapeHtml(formatProductRankingMetricValue(firstCurrent, mode))}</strong> vs comp.: <strong>${escapeHtml(formatProductRankingMetricValue(firstCompare, mode))}</strong></span>
      <span>Top 3 atual: <strong>${escapeHtml(formatProductRankingMetricValue(top3Current, mode))}</strong> vs comp.: <strong>${escapeHtml(formatProductRankingMetricValue(top3Compare, mode))}</strong></span>
      <span>Top ${formatInt(currentTop.length)} atual: <strong>${escapeHtml(formatProductRankingMetricValue(lastCurrent, mode))}</strong> vs comp.: <strong>${escapeHtml(formatProductRankingMetricValue(lastCompare, mode))}</strong></span>
      <span>Diferença final: <strong>${escapeHtml(`${diff >= 0 ? "+" : "-"}${formatProductRankingMetricValue(Math.abs(diff), mode)}`)}</strong>${diffPct != null ? ` (${escapeHtml(`${diffPct >= 0 ? "+" : ""}${diffPct}%`)})` : ""}</span>
      <span>Concentração no Top 3 (atual): <strong>${escapeHtml(`${concentrationTop3Pct.toFixed(1)}%`)}</strong></span>
    </div>
    <div class="product-ranking-evolution-explain__text">
      Regra prática: quando a distância entre as linhas abre cedo (Top 1 a Top 5), o ganho/perda está concentrado nos líderes.
      Se a abertura acontece mais no fim da curva, a diferença vem do miolo/cauda do Top.
    </div>
  `;
}

function renderProductRankingHistory(view) {
  const historyEl = document.getElementById("productRankingHistory");
  if (!historyEl) return;

  const topRows = Array.isArray(view?.topRows) ? view.topRows : [];
  const exited = Array.isArray(view?.exitedFromTop) ? view.exitedFromTop : [];
  if (!topRows.length && !exited.length) {
    PRODUCT_RANKING_HISTORY_ROWS = [];
    renderProductRankingHistoryRows([]);
    return;
  }

  const movements = topRows
    .map((row) => {
      const previousPos = Number(row.positionPrevious || 0);
      const currentPos = Number(row.positionCurrent || 0);
      const rankDiff = previousPos > 0 ? previousPos - currentPos : 0;
      const revenueDelta =
        toProductRankingNumber(row.revenue, 0) -
        toProductRankingNumber(row.previousRevenue, 0);
      let movementLabel = "Rank estável";
      let movementTone = "neutral";
      if (!previousPos) {
        movementLabel = "Entrou no Top";
        movementTone = "up";
      } else if (rankDiff > 0) {
        movementLabel = `Subiu ${rankDiff} pos.`;
        movementTone = "up";
      } else if (rankDiff < 0) {
        movementLabel = `Caiu ${Math.abs(rankDiff)} pos.`;
        movementTone = "down";
      }
      return {
        id: String(row.itemId || ""),
        title: row.title || "Produto",
        previousPos,
        currentPos,
        movementLabel,
        movementTone,
        revenueDelta,
        growth: toProductRankingNumber(row.growthRevenuePct, 0),
        revenue: toProductRankingNumber(row.revenue, 0),
        previousRevenue: toProductRankingNumber(row.previousRevenue, 0),
      };
    })
    .sort((a, b) => Math.abs(b.revenueDelta) - Math.abs(a.revenueDelta))
    .slice(0, 18);

  const exitedRows = exited.slice(0, 8).map((row) => ({
    id: String(row.itemId || ""),
    title: row.title || "Produto",
    previousPos: Number(row.positionPrevious || 0),
    currentPos: null,
    movementLabel: "Saiu do Top",
    movementTone: "down",
    revenueDelta: -Math.abs(toProductRankingNumber(row.previousRevenue, 0)),
    growth: null,
    revenue: 0,
    previousRevenue: toProductRankingNumber(row.previousRevenue, 0),
  }));

  PRODUCT_RANKING_HISTORY_ROWS = [...movements, ...exitedRows]
    .sort((a, b) => Math.abs(b.revenueDelta) - Math.abs(a.revenueDelta))
    .slice(0, 24);

  renderProductRankingHistoryRows(PRODUCT_RANKING_HISTORY_ROWS);
}

function getFilteredProductRankingHistoryRows(rows = []) {
  const filter = String(PRODUCT_RANKING_HISTORY_FILTER || "all");
  if (filter === "up") {
    return rows.filter((row) => row?.movementTone === "up" && row?.currentPos);
  }
  if (filter === "down") {
    return rows.filter(
      (row) => row?.movementTone === "down" && row?.currentPos,
    );
  }
  if (filter === "exited") {
    return rows.filter((row) => !row?.currentPos);
  }
  return rows;
}

function syncProductRankingHistoryFilterButtons() {
  const buttons = document.querySelectorAll("[data-ranking-history-filter]");
  buttons.forEach((button) => {
    const key = String(button.getAttribute("data-ranking-history-filter") || "all");
    button.classList.toggle("is-active", key === PRODUCT_RANKING_HISTORY_FILTER);
  });
}

function renderProductRankingHistoryRows(rows = []) {
  const historyEl = document.getElementById("productRankingHistory");
  const countEl = document.getElementById("productRankingHistoryCount");
  if (!historyEl) return;

  syncProductRankingHistoryFilterButtons();

  const filteredRows = getFilteredProductRankingHistoryRows(rows);
  if (countEl) {
    countEl.textContent = `${formatInt(filteredRows.length)} de ${formatInt(rows.length)} movimentações`;
  }

  if (!filteredRows.length) {
    historyEl.innerHTML =
      '<div class="muted">Nenhuma movimentação encontrada para este filtro.</div>';
    return;
  }

  historyEl.innerHTML = filteredRows
    .map((row) => {
      const toneClass =
        row.movementTone === "up"
          ? "product-ranking-history__badge--up"
          : row.movementTone === "down"
            ? "product-ranking-history__badge--down"
            : "";
      const revenueDeltaLabel = `${row.revenueDelta >= 0 ? "+" : "-"}${formatBRL(
        Math.abs(row.revenueDelta),
      )}`;
      const posLabel = row.currentPos
        ? `#${row.previousPos || "Novo"} → #${row.currentPos}`
        : `#${row.previousPos || "-"} → Fora do Top`;
      return `
        <article class="product-ranking-history__row">
          <div class="product-ranking-history__main">
            <div class="product-ranking-history__title">${escapeHtml(row.title)}</div>
            <div class="product-ranking-history__meta">ID ${escapeHtml(row.id)} • ${escapeHtml(posLabel)}</div>
          </div>
          <div class="product-ranking-history__stats">
            <span class="product-ranking-history__badge ${toneClass}">${escapeHtml(row.movementLabel)}</span>
            <strong>${escapeHtml(revenueDeltaLabel)}</strong>
          </div>
        </article>
      `;
    })
    .join("");
}

function renderProductRankingPanels(view) {
  const kpiEl = document.getElementById("productRankingKpis");
  const healthEl = document.getElementById("productRankingHealth");
  const movesEl = document.getElementById("productRankingMoves");
  const insightsEl = document.getElementById("productRankingInsights");
  const bodyEl = document.getElementById("productRankingBody");
  const historyEl = document.getElementById("productRankingHistory");
  const statusEl = document.getElementById("productRankingStatus");
  if (!kpiEl || !healthEl || !movesEl || !insightsEl || !bodyEl) return;

  if (!view.topRows.length) {
    const evolutionExplainEl = document.getElementById("productRankingEvolutionExplain");
    kpiEl.innerHTML = "";
    healthEl.innerHTML = '<div class="muted">Sem dados para o período selecionado.</div>';
    movesEl.innerHTML = '<div class="muted">Sem movimentações.</div>';
    insightsEl.innerHTML = '<div class="muted">Sem insights no recorte atual.</div>';
    if (historyEl) {
      PRODUCT_RANKING_HISTORY_ROWS = [];
      renderProductRankingHistoryRows([]);
    }
    bodyEl.innerHTML =
      '<tr><td colspan="11"><div class="muted">Nenhum anúncio com vendas encontrado.</div></td></tr>';
    if (evolutionExplainEl) {
      evolutionExplainEl.innerHTML =
        '<div class="muted">Sem dados suficientes para explicar a curva acumulada.</div>';
    }
    if (statusEl) statusEl.textContent = "Sem dados para exibir.";
    destroyProductRankingCharts();
    return;
  }

  const healthScore = Math.max(
    35,
    Math.min(
      99,
      Math.round(
        88 -
          Math.max(0, view.top3Share - 55) * 0.5 -
          Math.max(0, -view.avgGrowth) * 0.35 +
          Math.max(0, view.up - view.down) * 1.6,
      ),
    ),
  );

  const totalOrders = view.topRows.reduce((sum, row) => sum + row.orders, 0);
  const avgTicket =
    totalOrders > 0
      ? view.topRows.reduce((sum, row) => sum + row.revenue, 0) / totalOrders
      : 0;
  const top1 = view.topRows[0];
  const bestUpLabel = view.bestUpRow
    ? `#${view.bestUpRow.itemId} (+${view.bestUpRow.positionPrevious - view.bestUpRow.positionCurrent})`
    : "Sem subida";
  const bestDownLabel = view.bestDownRow
    ? `#${view.bestDownRow.itemId} (-${view.bestDownRow.positionCurrent - view.bestDownRow.positionPrevious})`
    : "Sem queda";

  kpiEl.innerHTML = `
    <article class="product-ranking-kpi">
      <span>Faturamento do Top ${view.limit}</span>
      <strong>${formatBRL(view.topRows.reduce((sum, row) => sum + row.revenue, 0))}</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Vendas do Top ${view.limit}</span>
      <strong>${formatInt(totalOrders)}</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Ticket médio</span>
      <strong>${formatBRL(avgTicket)}</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Concentração Top 3</span>
      <strong>${view.top3Share.toFixed(1)}%</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Produto líder</span>
      <strong>${escapeHtml(String(top1?.itemId || "-"))}</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Maior subida</span>
      <strong>${escapeHtml(bestUpLabel)}</strong>
    </article>
    <article class="product-ranking-kpi">
      <span>Maior queda</span>
      <strong>${escapeHtml(bestDownLabel)}</strong>
    </article>
  `;

  healthEl.innerHTML = `
    <div class="product-ranking-health-score">${healthScore}<small>/100</small></div>
    <div class="product-ranking-health-list">
      <div>Estabilidade: <strong>${healthScore >= 75 ? "Boa" : healthScore >= 60 ? "Média" : "Crítica"}</strong></div>
      <div>Crescimento médio: <strong>${formatGrowthLabel(view.avgGrowth)}</strong></div>
      <div>Concentração Top 3: <strong>${view.top3Share.toFixed(1)}%</strong></div>
      <div>Movimento líquido: <strong>${view.up - view.down >= 0 ? "+" : ""}${view.up - view.down}</strong></div>
    </div>
  `;

  const stableCount = Math.max(
    0,
    view.topRows.length - view.up - view.down - view.entered,
  );

  movesEl.innerHTML = `
    <div class="product-ranking-move-grid">
      <article><strong>${formatInt(view.up)}</strong><span>Subiram posições</span></article>
      <article><strong>${formatInt(view.down)}</strong><span>Caíram posições</span></article>
      <article><strong>${formatInt(view.entered)}</strong><span>Entraram no Top</span></article>
      <article><strong>${formatInt(stableCount)}</strong><span>Mantiveram posição</span></article>
    </div>
  `;

  const calcDeltaPct = (current, previous) => {
    const cur = toProductRankingNumber(current, 0);
    const prev = toProductRankingNumber(previous, 0);
    if (prev <= 0) return null;
    return Number((((cur - prev) / prev) * 100).toFixed(1));
  };
  const topRevenueCurrent = view.topRows.reduce(
    (sum, row) => sum + toProductRankingNumber(row.revenue, 0),
    0,
  );
  const topOrdersCurrent = view.topRows.reduce(
    (sum, row) => sum + toProductRankingNumber(row.orders, 0),
    0,
  );
  const topTicketCurrent = topOrdersCurrent > 0 ? topRevenueCurrent / topOrdersCurrent : 0;
  const compareRows = Array.isArray(view.compareData?.rows)
    ? [...view.compareData.rows]
    : [];
  compareRows.sort(
    (a, b) =>
      getProductRankingMetricValue(b, view.mode) -
        getProductRankingMetricValue(a, view.mode) ||
      toProductRankingNumber(b.revenue, 0) - toProductRankingNumber(a.revenue, 0),
  );
  const compareTopRows = compareRows.slice(0, view.topRows.length);
  const topRevenueCompare = compareTopRows.reduce(
    (sum, row) => sum + toProductRankingNumber(row.revenue, 0),
    0,
  );
  const topOrdersCompare = compareTopRows.reduce(
    (sum, row) => sum + toProductRankingNumber(row.orders, 0),
    0,
  );
  const topTicketCompare = topOrdersCompare > 0 ? topRevenueCompare / topOrdersCompare : 0;
  const topRevenueDeltaPct = calcDeltaPct(topRevenueCurrent, topRevenueCompare);
  const topOrdersDeltaPct = calcDeltaPct(topOrdersCurrent, topOrdersCompare);
  const topTicketDeltaPct = calcDeltaPct(topTicketCurrent, topTicketCompare);

  const insights = [];
  const pushInsight = ({ icon, tone, title, message }) => {
    insights.push({
      icon: icon || "i",
      tone: tone || "info",
      title: title || "Insight",
      message: message || "",
    });
  };

  if (topRevenueDeltaPct != null) {
    pushInsight({
      icon: topRevenueDeltaPct >= 0 ? "▲" : "▼",
      tone: topRevenueDeltaPct >= 0 ? "positive" : "negative",
      title: "Faturamento do Top no comparativo",
      message: `${topRevenueDeltaPct >= 0 ? "+" : ""}${topRevenueDeltaPct}% vs período de comparação (${formatBRL(topRevenueCurrent)} vs ${formatBRL(topRevenueCompare)}).`,
    });
  }
  if (topOrdersDeltaPct != null) {
    pushInsight({
      icon: topOrdersDeltaPct >= 0 ? "⇅" : "⇅",
      tone: topOrdersDeltaPct >= 0 ? "info" : "warning",
      title: "Volume de vendas do Top",
      message: `${topOrdersDeltaPct >= 0 ? "+" : ""}${topOrdersDeltaPct}% em pedidos (${formatInt(topOrdersCurrent)} vs ${formatInt(topOrdersCompare)}).`,
    });
  }
  if (topTicketDeltaPct != null) {
    pushInsight({
      icon: topTicketDeltaPct >= 0 ? "$" : "$",
      tone: topTicketDeltaPct >= 0 ? "positive" : "warning",
      title: "Ticket médio do Top",
      message: `${topTicketDeltaPct >= 0 ? "+" : ""}${topTicketDeltaPct}% no ticket médio (${formatBRL(topTicketCurrent)} vs ${formatBRL(topTicketCompare)}).`,
    });
  }

  const highGrowth = view.topRows.filter(
    (row) => toProductRankingNumber(row.growthRevenuePct, 0) >= 20,
  ).length;
  const sharpDrop = view.topRows.filter(
    (row) => toProductRankingNumber(row.growthRevenuePct, 0) <= -15,
  ).length;
  const top1Revenue = toProductRankingNumber(top1?.revenue, 0);
  const top1ShareOnTop = topRevenueCurrent > 0
    ? Number(((top1Revenue / topRevenueCurrent) * 100).toFixed(1))
    : 0;
  const scoreAvg =
    view.topRows.length > 0
      ? Number(
          (
            view.topRows.reduce(
              (sum, row) => sum + toProductRankingNumber(row.score, 0),
              0,
            ) / view.topRows.length
          ).toFixed(1),
        )
      : 0;
  const lowScore = view.topRows.filter((row) => toProductRankingNumber(row.score, 0) < 50).length;
  const categoryMix = new Map();
  view.topRows.forEach((row) => {
    const label = getProductSalesCategory(row);
    categoryMix.set(label, (categoryMix.get(label) || 0) + 1);
  });
  const categoryLead = [...categoryMix.entries()].sort((a, b) => b[1] - a[1])[0] || null;

  if (highGrowth > 0) {
    pushInsight({
      icon: "▲",
      tone: "positive",
      title: "Anúncios em aceleração",
      message: `${formatInt(highGrowth)} anúncio(s) cresceram acima de 20% em faturamento.`,
    });
  }
  if (view.top3Share >= 60) {
    pushInsight({
      icon: "!",
      tone: "warning",
      title: "Concentração elevada",
      message: `Top 3 concentram ${view.top3Share.toFixed(1)}% do faturamento. Vale diversificar para reduzir risco.`,
    });
  } else {
    pushInsight({
      icon: "✓",
      tone: "positive",
      title: "Concentração saudável",
      message: `Top 3 em ${view.top3Share.toFixed(1)}% do faturamento, com melhor distribuição de receita.`,
    });
  }
  if (sharpDrop > 0) {
    pushInsight({
      icon: "▼",
      tone: "negative",
      title: "Quedas relevantes no Top",
      message: `${formatInt(sharpDrop)} anúncio(s) tiveram retração de 15% ou mais no faturamento.`,
    });
  }
  if (lowScore > 0) {
    pushInsight({
      icon: "!",
      tone: "negative",
      title: "Score crítico",
      message: `${formatInt(lowScore)} anúncio(s) com score abaixo de 50 pedem ação corretiva imediata.`,
    });
  }
  if (view.exitedFromTop.length > 0) {
    pushInsight({
      icon: "↘",
      tone: "warning",
      title: "Saídas do ranking",
      message: `${formatInt(view.exitedFromTop.length)} anúncio(s) saíram do Top no comparativo e merecem revisão.`,
    });
  }
  if (view.bestUpRow) {
    pushInsight({
      icon: "↗",
      tone: "positive",
      title: "Maior avanço de posição",
      message: `ID ${view.bestUpRow.itemId} ganhou ${
        view.bestUpRow.positionPrevious - view.bestUpRow.positionCurrent
      } posições com ${formatGrowthLabel(view.bestUpRow.growthRevenuePct)} de crescimento.`,
    });
  }
  if (view.bestDownRow) {
    pushInsight({
      icon: "↘",
      tone: "negative",
      title: "Maior perda de posição",
      message: `ID ${view.bestDownRow.itemId} perdeu ${
        view.bestDownRow.positionCurrent - view.bestDownRow.positionPrevious
      } posições e pede revisão de preço, mídia e estoque.`,
    });
  }
  if (top1?.itemId) {
    pushInsight({
      icon: "★",
      tone: "info",
      title: "Peso do líder no Top",
      message: `ID ${top1.itemId} representa ${top1ShareOnTop.toFixed(1)}% do faturamento do Top ${view.limit}.`,
    });
  }
  if (stableCount > 0) {
    pushInsight({
      icon: "•",
      tone: "info",
      title: "Base estável",
      message: `${formatInt(stableCount)} anúncio(s) mantiveram posição no ranking, sustentando previsibilidade.`,
    });
  }
  pushInsight({
    icon: "Σ",
    tone: scoreAvg >= 70 ? "positive" : scoreAvg >= 55 ? "warning" : "negative",
    title: "Qualidade média do Top",
    message: `Score médio de ${scoreAvg}/100 no recorte atual.`,
  });
  if (categoryLead) {
    pushInsight({
      icon: "◔",
      tone: "info",
      title: "Categoria de produto dominante",
      message: `${categoryLead[0]} lidera com ${formatInt(categoryLead[1])} anúncio(s) entre os mais vendidos.`,
    });
  }
  if (!insights.length) {
    pushInsight({
      icon: "i",
      tone: "info",
      title: "Leitura geral",
      message: "Ranking estável no recorte atual, sem alertas críticos.",
    });
  }

  insightsEl.innerHTML = insights
    .map(
      (item) =>
        `<article class="product-ranking-insight product-ranking-insight--${escapeHtml(item.tone)}">
          <span class="product-ranking-insight__icon">${escapeHtml(item.icon)}</span>
          <div class="product-ranking-insight__body">
            <strong>${escapeHtml(item.title)}</strong>
            <div>${escapeHtml(item.message)}</div>
          </div>
        </article>`,
    )
    .join("");

  bodyEl.innerHTML = view.topRows
    .map((row) => {
      const img = row.images?.[0]?.url
        ? `<img class="product-ranking-thumb" src="${escapeHtml(row.images[0].url)}" alt="" />`
        : '<div class="product-ranking-thumb"></div>';
      const growth = toProductRankingNumber(row.growthRevenuePct, 0);
      const growthCls = growth >= 0 ? "up" : "down";
      return `
        <tr class="strategy-table-row" data-item-id="${escapeHtml(String(row.itemId || ""))}">
          <td>#${row.positionCurrent}</td>
          <td>
            <div class="product-ranking-product">
              ${img}
              <div>
                <div class="product-ranking-product__id">${escapeHtml(String(row.itemId || "-"))}</div>
                <div class="product-ranking-product__title">${escapeHtml(row.title || "Sem título")}</div>
                <div class="product-ranking-product__sku">SKU: ${escapeHtml(row.itemSku || "-")}</div>
              </div>
            </div>
          </td>
          <td>${formatBRL(row.revenue)}</td>
          <td>${formatInt(row.orders)}</td>
          <td>${formatBRL(row.ticket)}</td>
          <td>${toProductRankingNumber(row.shareRevenuePct, 0).toFixed(2)}%</td>
          <td><span class="product-ranking-growth product-ranking-growth--${growthCls}">${escapeHtml(formatGrowthLabel(growth))}</span></td>
          <td>${row.positionPrevious ? `#${row.positionPrevious}` : "Novo"}</td>
          <td>${formatProductRankingDelta(row.positionCurrent, row.positionPrevious)}</td>
          <td>${row.score}</td>
          <td>${escapeHtml(row.recommendation)}</td>
        </tr>
      `;
    })
    .join("");

  bodyEl.querySelectorAll(".strategy-table-row").forEach((row) => {
    row.addEventListener("click", async () => {
      const itemId = String(row.getAttribute("data-item-id") || "");
      if (!itemId) return;
      await openProductDetail(itemId);
    });
  });

  if (statusEl) {
    statusEl.textContent = `Período: ${String(
      view.currentData?.meta?.periodLabel || "-",
    )} • Comparação: ${String(
      view.compareData?.meta?.periodLabel || "-",
    )} • Modo: ${String(getProductRankingMode())}`;
  }

  renderProductRankingHistory(view);
  renderProductRankingCharts(view);
}

function exportProductRankingCsv() {
  const rows = Array.isArray(PRODUCT_RANKING_VIEW_DATA?.topRows)
    ? PRODUCT_RANKING_VIEW_DATA.topRows
    : [];
  if (!rows.length) return;

  const headers = [
    "posicao",
    "item_id",
    "titulo",
    "faturamento",
    "vendas",
    "ticket_medio",
    "participacao_pct",
    "crescimento_pct",
    "posicao_anterior",
    "score",
    "acao_recomendada",
    "sku",
  ];
  const csvRows = rows.map((row) => [
    row.positionCurrent,
    row.itemId || "",
    row.title || "",
    Number(row.revenue || 0).toFixed(2),
    row.orders || 0,
    Number(row.ticket || 0).toFixed(2),
    Number(row.shareRevenuePct || 0).toFixed(2),
    Number(row.growthRevenuePct || 0).toFixed(2),
    row.positionPrevious || "",
    row.score || 0,
    row.recommendation || "",
    row.itemSku || "",
  ]);
  downloadCsv(
    `ranking-anuncios-shopee-${new Date().toISOString().slice(0, 10)}.csv`,
    headers,
    csvRows,
  );
}

function bindProductRankingEvents() {
  if (PRODUCT_RANKING_BOUND) return;
  const btnLoad = document.getElementById("btnProductRankingLoad");
  const btnExport = document.getElementById("btnProductRankingExport");
  const modeEl = document.getElementById("productRankingMode");
  const limitEl = document.getElementById("productRankingLimit");
  const historyFilterButtons = document.querySelectorAll(
    "[data-ranking-history-filter]",
  );

  btnLoad?.addEventListener("click", () => {
    loadProductsRanking();
  });
  btnExport?.addEventListener("click", () => {
    exportProductRankingCsv();
  });
  modeEl?.addEventListener("change", () => {
    if (!PRODUCT_RANKING_RAW_DATA) return;
    const view = buildProductRankingView(
      PRODUCT_RANKING_RAW_DATA.currentData,
      PRODUCT_RANKING_RAW_DATA.compareData,
      getProductRankingMode(),
      getProductRankingLimit(),
    );
    PRODUCT_RANKING_VIEW_DATA = view;
    renderProductRankingPanels(view);
  });
  limitEl?.addEventListener("change", () => {
    if (!PRODUCT_RANKING_RAW_DATA) return;
    const view = buildProductRankingView(
      PRODUCT_RANKING_RAW_DATA.currentData,
      PRODUCT_RANKING_RAW_DATA.compareData,
      getProductRankingMode(),
      getProductRankingLimit(),
    );
    PRODUCT_RANKING_VIEW_DATA = view;
    renderProductRankingPanels(view);
  });
  historyFilterButtons.forEach((button) => {
    button.addEventListener("click", () => {
      PRODUCT_RANKING_HISTORY_FILTER = String(
        button.getAttribute("data-ranking-history-filter") || "all",
      );
      renderProductRankingHistoryRows(PRODUCT_RANKING_HISTORY_ROWS);
    });
  });
  syncProductRankingHistoryFilterButtons();
  PRODUCT_RANKING_BOUND = true;
}

async function loadProductsRanking() {
  bindProductRankingEvents();
  setProductRankingDefaultRanges();

  const statusEl = document.getElementById("productRankingStatus");
  const dateFrom = String(
    document.getElementById("productRankingDateFrom")?.value || "",
  ).trim();
  const dateTo = String(
    document.getElementById("productRankingDateTo")?.value || "",
  ).trim();
  const compareFrom = String(
    document.getElementById("productRankingCompareFrom")?.value || "",
  ).trim();
  const compareTo = String(
    document.getElementById("productRankingCompareTo")?.value || "",
  ).trim();

  if (!dateFrom || !dateTo || !compareFrom || !compareTo) {
    if (statusEl) statusEl.textContent = "Preencha os períodos para carregar.";
    return;
  }

  if (statusEl) statusEl.textContent = "Carregando ranking de anúncios...";

  try {
    await ensureShopSelected();
    const [currentData, compareData] = await Promise.all([
      fetchProductRankingRange(dateFrom, dateTo),
      fetchProductRankingRange(compareFrom, compareTo),
    ]);
    await ensureProductRankingCategoryLabels();

    PRODUCT_RANKING_RAW_DATA = { currentData, compareData };
    const view = buildProductRankingView(
      currentData,
      compareData,
      getProductRankingMode(),
      getProductRankingLimit(),
    );
    PRODUCT_RANKING_VIEW_DATA = view;
    renderProductRankingPanels(view);
  } catch (error) {
    if (statusEl) {
      statusEl.textContent = `Erro ao carregar ranking: ${error.message}`;
    }
  }
}

function launchQualityTone(score) {
  const n = Number(score || 0);
  if (n >= 80) return "Boa";
  if (n >= 60) return "Media";
  return "Critica";
}

function renderLaunchesChart(items = []) {
  const canvas = document.getElementById("launchesChart");
  if (!canvas || typeof Chart === "undefined") return;

  if (LAUNCHES_CHART) {
    LAUNCHES_CHART.destroy();
    LAUNCHES_CHART = null;
  }

  const rows = [...items]
    .slice(0, 10)
    .sort(
      (a, b) =>
        new Date(a.launchDate || 0).getTime() -
        new Date(b.launchDate || 0).getTime(),
    );

  LAUNCHES_CHART = new Chart(canvas.getContext("2d"), {
    type: "bar",
    data: {
      labels: rows.map((row) =>
        new Date(row.launchDate || Date.now()).toLocaleDateString("pt-BR", {
          day: "2-digit",
          month: "2-digit",
        }),
      ),
      datasets: [
        {
          label: "Faturamento",
          data: rows.map((row) => Number(row.revenue || 0)),
          backgroundColor: "rgba(88, 132, 255, 0.55)",
          borderColor: "rgba(88, 132, 255, 1)",
          borderWidth: 1,
          borderRadius: 10,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { display: false } },
      scales: {
        y: {
          ticks: {
            callback(value) {
              return formatBRL(Number(value || 0));
            },
          },
        },
      },
    },
  });
}

async function renderLaunchSelection(itemId) {
  const detailRoot = document.getElementById("launchesDetail");
  if (!detailRoot) return;
  if (!itemId) {
    detailRoot.innerHTML = `<div class="muted">Selecione um lançamento na tabela para abrir os detalhes.</div>`;
    return;
  }

  const launch =
    LAUNCHES_LAST_DATA?.items?.find(
      (row) => String(row.itemId || "") === String(itemId),
    ) || null;
  if (!launch) return;

  detailRoot.innerHTML = `
    <div class="strategy-kpi-grid">
      <article class="strategy-kpi-card">
        <div class="strategy-kpi-card__label">Produto</div>
        <div class="strategy-kpi-card__value strategy-kpi-card__value--sm">${escapeHtml(launch.title || "Sem titulo")}</div>
        <div class="strategy-kpi-card__meta">Item ID ${escapeHtml(String(launch.itemId || "-"))}</div>
      </article>
      <article class="strategy-kpi-card">
        <div class="strategy-kpi-card__label">Criado em</div>
        <div class="strategy-kpi-card__value strategy-kpi-card__value--sm">${escapeHtml(fmtDateTime(launch.launchDate))}</div>
        <div class="strategy-kpi-card__meta">SKU ${escapeHtml(launch.itemSku || "-")}</div>
      </article>
      <article class="strategy-kpi-card">
        <div class="strategy-kpi-card__label">Crescimento</div>
        <div class="strategy-kpi-card__value">${escapeHtml(formatGrowthLabel(launch.growthRevenuePct))}</div>
        <div class="strategy-kpi-card__meta">${launch.isGrowing ? "Lancamento em crescimento" : "Lancamento precisa de acao"}</div>
      </article>
      <article class="strategy-kpi-card">
        <div class="strategy-kpi-card__label">Qualidade do lançamento</div>
        <div class="strategy-kpi-card__value">${Number(launch.launchQuality?.score || 0)}</div>
        <div class="strategy-kpi-card__meta">${escapeHtml(launchQualityTone(launch.launchQuality?.score))}</div>
      </article>
    </div>
  `;

  detailRoot.insertAdjacentHTML(
    "beforeend",
    `<div style="display:flex;justify-content:flex-end;margin-top:12px;"><button id="btnLaunchOpenAnalyticsAi" class="btn btn-ghost">Abrir no Analytics IA</button></div>`,
  );
  document
    .getElementById("btnLaunchOpenAnalyticsAi")
    ?.addEventListener("click", async () => {
      ANALYTICS_AI_SELECTED_ITEM_ID = String(itemId);
      ANALYTICS_AI_QUERY = String(itemId);
      ANALYTICS_AI_PRODUCTS_PAGE = 1;
      const searchInput = document.getElementById("analyticsAiSearch");
      if (searchInput) searchInput.value = String(itemId);
      await showTab("analytics-ai");
      await runAnalyticsAiForItem(itemId, { titleFallback: launch.title || "" });
    });
}

function buildAnalyticsAiOptionLabel(product) {
  const itemId = String(product?.itemId || "");
  const title = String(product?.title || product?.item_name || "Sem titulo");
  const compactTitle = title.length > 80 ? `${title.slice(0, 80)}...` : title;
  return `${itemId} - ${compactTitle}`;
}

function renderAnalyticsAiPicker(items = [], meta = {}) {
  const select = document.getElementById("analyticsAiItemSelect");
  const metaEl = document.getElementById("analyticsAiMeta");
  if (!select || !metaEl) return;

  if (!items.length) {
    select.innerHTML = `<option value="">Nenhum ID encontrado</option>`;
    metaEl.textContent = "Nenhum ID encontrado com o filtro atual.";
    return;
  }

  select.innerHTML = items
    .map((product) => {
      const itemId = String(product?.itemId || "");
      return `<option value="${escapeHtml(itemId)}">${escapeHtml(buildAnalyticsAiOptionLabel(product))}</option>`;
    })
    .join("");

  const page = Math.max(1, Number(meta?.page || 1));
  const totalPages = Math.max(1, Number(meta?.totalPages || 1));
  const total = Math.max(0, Number(meta?.total || items.length || 0));

  metaEl.innerHTML = `
    Mostrando ${formatInt(items.length)} IDs desta pagina • Pagina ${formatInt(page)} de ${formatInt(totalPages)} • Total ${formatInt(total)} IDs
    <span style="display:inline-flex;gap:8px;margin-left:10px;">
      <button id="btnAnalyticsAiPrevPage" class="btn btn-ghost" ${page <= 1 ? "disabled" : ""}>Anterior</button>
      <button id="btnAnalyticsAiNextPage" class="btn btn-ghost" ${page >= totalPages ? "disabled" : ""}>Proxima</button>
    </span>
  `;

  document.getElementById("btnAnalyticsAiPrevPage")?.addEventListener("click", () => {
    ANALYTICS_AI_PRODUCTS_PAGE = Math.max(1, ANALYTICS_AI_PRODUCTS_PAGE - 1);
    loadAnalyticsAi({ autoAnalyze: false });
  });
  document.getElementById("btnAnalyticsAiNextPage")?.addEventListener("click", () => {
    ANALYTICS_AI_PRODUCTS_PAGE = ANALYTICS_AI_PRODUCTS_PAGE + 1;
    loadAnalyticsAi({ autoAnalyze: false });
  });
}

async function runAnalyticsAiForItem(itemId, options = {}) {
  const root = document.getElementById(options.resultRootId || "analyticsAiResult");
  if (!root) return;

  const targetItemId = String(itemId || "").trim();
  if (!targetItemId) {
    root.innerHTML = `<div class="muted">Selecione um ID e clique em "Analisar ID".</div>`;
    return;
  }

  root.innerHTML = `<div class="muted">Analisando palavras do titulo e descricao...</div>`;
  try {
    const detail = await apiGet(
      `/shops/${SHOP_PATH_PLACEHOLDER}/products/${encodeURIComponent(targetItemId)}/full`,
    );
    const product = detail?.product || {};
    const extra = detail?.extra || {};
    const title = String(
      product.title || options.titleFallback || "Produto sem titulo",
    ).trim();
    const description = String(extra.description || "").trim();
    const query = title
      .split(/\s+/)
      .slice(0, 6)
      .join(" ");

    const trends = await apiGet(
      `/shops/${SHOP_PATH_PLACEHOLDER}/seo/shopee-recommended-keywords?itemId=${encodeURIComponent(targetItemId)}&q=${encodeURIComponent(query || "")}`,
    );
    const topTerms = Array.isArray(trends?.response?.suggested_keywords)
      ? trends.response.suggested_keywords.slice(0, 12)
      : [];
    const corpus = `${title} ${description}`.toLowerCase();
    const rows = topTerms.map((term) => {
      const keyword =
        String(term.keyword || term.term || term.text || term.query || "").trim();
      const contains = keyword ? corpus.includes(keyword.toLowerCase()) : false;
      return {
        keyword,
        searchVolume: term.search_volume ?? term.volume ?? null,
        qualityScore: term.quality_score ?? term.score ?? null,
        suggestedBid: term.suggested_bid ?? null,
        contains,
      };
    });

    root.innerHTML = `
      <div class="strategy-kpi-grid">
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Item analisado</div>
          <div class="strategy-kpi-card__value strategy-kpi-card__value--sm">${escapeHtml(targetItemId)}</div>
          <div class="strategy-kpi-card__meta">${escapeHtml(title || "-")}</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Consulta base (Shopee Ads)</div>
          <div class="strategy-kpi-card__value strategy-kpi-card__value--sm">${escapeHtml(query || title || "-")}</div>
          <div class="strategy-kpi-card__meta">Endpoint v2.ads.get_recommended_keyword_list</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Cobertura das palavras fortes</div>
          <div class="strategy-kpi-card__value">${formatInt(rows.filter((row) => row.contains).length)}</div>
          <div class="strategy-kpi-card__meta">de ${formatInt(rows.length)} termos relevantes</div>
        </article>
      </div>
      <div class="table-wrap">
        <table class="table">
          <thead>
            <tr>
              <th>Palavra</th>
              <th>Esta no titulo/descricao?</th>
              <th>Volume</th>
              <th>Qualidade</th>
              <th>Bid sugerido</th>
            </tr>
          </thead>
          <tbody>
            ${
              rows.length
                ? rows
                    .map(
                      (row) => `
                        <tr>
                          <td>${escapeHtml(row.keyword || "-")}</td>
                          <td>${row.contains ? "Sim" : "Nao"}</td>
                          <td>${row.searchVolume == null ? "-" : escapeHtml(formatInt(row.searchVolume))}</td>
                          <td>${row.qualityScore == null ? "-" : escapeHtml(String(row.qualityScore))}</td>
                          <td>${row.suggestedBid == null ? "-" : escapeHtml(formatBRL(row.suggestedBid))}</td>
                        </tr>
                      `,
                    )
                    .join("")
                : `<tr><td colspan="5"><div class="muted">Sem palavras retornadas pelo endpoint de recomendadas da Shopee para este ID.</div></td></tr>`
            }
          </tbody>
        </table>
      </div>
    `;
  } catch (error) {
    root.innerHTML = `<div class="muted">Erro ao analisar ID: ${escapeHtml(error.message)}</div>`;
  }
}

async function loadAnalyticsAi(options = {}) {
  const queryInput = document.getElementById("analyticsAiSearch");
  const select = document.getElementById("analyticsAiItemSelect");
  const resultRoot = document.getElementById("analyticsAiResult");
  const metaEl = document.getElementById("analyticsAiMeta");
  if (!queryInput || !select || !resultRoot || !metaEl) return;

  if (typeof options.query === "string") {
    ANALYTICS_AI_QUERY = options.query.trim();
  } else {
    ANALYTICS_AI_QUERY = queryInput.value.trim();
  }

  metaEl.textContent = "Carregando IDs...";
  if (!ANALYTICS_AI_SELECTED_ITEM_ID) {
    resultRoot.innerHTML = `<div class="muted">Selecione um ID e clique em "Analisar ID".</div>`;
  }

  try {
    await ensureShopSelected();

    const qs = new URLSearchParams({
      page: String(Math.max(1, ANALYTICS_AI_PRODUCTS_PAGE)),
      pageSize: String(ANALYTICS_AI_PRODUCTS_PAGE_SIZE),
      q: ANALYTICS_AI_QUERY || "",
      sortBy: "updatedAt",
      sortDir: "desc",
    });
    const data = await apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/products?${qs.toString()}`);
    const items = Array.isArray(data?.items)
      ? data.items
      : Array.isArray(data?.products)
        ? data.products
        : [];
    const meta = data?.meta || {};

    ANALYTICS_AI_PRODUCTS_PAGE = Math.max(1, Number(meta.page || ANALYTICS_AI_PRODUCTS_PAGE));
    ANALYTICS_AI_PRODUCTS_TOTAL_PAGES = Math.max(1, Number(meta.totalPages || 1));

    renderAnalyticsAiPicker(items, {
      page: ANALYTICS_AI_PRODUCTS_PAGE,
      totalPages: ANALYTICS_AI_PRODUCTS_TOTAL_PAGES,
      total: Number(meta.total || items.length || 0),
    });

    const preferredItemId =
      options.preferredItemId != null
        ? String(options.preferredItemId)
        : ANALYTICS_AI_SELECTED_ITEM_ID;
    let selectedItemId = preferredItemId;

    if (!selectedItemId || !items.some((row) => String(row.itemId || "") === selectedItemId)) {
      selectedItemId = items[0]?.itemId ? String(items[0].itemId) : "";
    }

    ANALYTICS_AI_SELECTED_ITEM_ID = selectedItemId || null;
    select.value = selectedItemId || "";

    if (options.autoAnalyze && selectedItemId) {
      const selectedProduct =
        items.find((row) => String(row.itemId || "") === String(selectedItemId)) || null;
      await runAnalyticsAiForItem(selectedItemId, {
        titleFallback: selectedProduct?.title || "",
      });
    }
  } catch (error) {
    select.innerHTML = `<option value="">Erro ao carregar IDs</option>`;
    metaEl.textContent = `Erro ao carregar IDs: ${error.message}`;
    resultRoot.innerHTML = `<div class="muted">Erro ao carregar base para Analytics IA.</div>`;
  }
}

function renderLaunchesTable() {
  const body = document.getElementById("launchesBody");
  const pagination = document.getElementById("launchesPagination");
  if (!body || !pagination) return;

  const items = Array.isArray(LAUNCHES_LAST_DATA?.items) ? LAUNCHES_LAST_DATA.items : [];
  const total = items.length;
  const totalPages = Math.max(1, Math.ceil(total / LAUNCHES_PAGE_SIZE));
  LAUNCHES_PAGE = Math.min(Math.max(1, LAUNCHES_PAGE), totalPages);

  const startIndex = (LAUNCHES_PAGE - 1) * LAUNCHES_PAGE_SIZE;
  const pageItems = items.slice(startIndex, startIndex + LAUNCHES_PAGE_SIZE);
  const from = total ? startIndex + 1 : 0;
  const to = total ? startIndex + pageItems.length : 0;

  if (!pageItems.length) {
    body.innerHTML = `<tr><td colspan="6"><div class="muted">Nenhum lançamento encontrado na janela atual.</div></td></tr>`;
  } else {
    body.innerHTML = pageItems
      .map(
        (row) => `
          <tr class="strategy-table-row ${String(SELECTED_LAUNCH_ITEM_ID || "") === String(row.itemId || "") ? "is-active" : ""}" data-launch-item-id="${escapeHtml(String(row.itemId || ""))}">
            <td>${escapeHtml(String(row.itemId || "-"))}</td>
            <td>${escapeHtml(row.title || "Sem titulo")}</td>
            <td>${escapeHtml(fmtDateTime(row.launchDate))}</td>
            <td>${formatBRL(row.revenue || 0)}</td>
            <td>${formatInt(row.quantity || 0)}</td>
            <td>${formatInt(row.launchQuality?.score || 0)}</td>
          </tr>
        `,
      )
      .join("");
  }

  pagination.innerHTML = `
    <div class="strategy-pagination__meta">Mostrando ${from}-${to} de ${formatInt(total)} lançamentos</div>
    <div class="strategy-pagination__actions">
      <button id="launchesPaginationPrev" class="btn btn-ghost" ${LAUNCHES_PAGE <= 1 ? "disabled" : ""}>Anterior</button>
      <span class="muted">Pagina ${LAUNCHES_PAGE}/${totalPages}</span>
      <button id="launchesPaginationNext" class="btn btn-ghost" ${LAUNCHES_PAGE >= totalPages ? "disabled" : ""}>Proxima</button>
    </div>
  `;

  document.getElementById("launchesPaginationPrev")?.addEventListener("click", () => {
    LAUNCHES_PAGE = Math.max(1, LAUNCHES_PAGE - 1);
    renderLaunchesTable();
  });
  document.getElementById("launchesPaginationNext")?.addEventListener("click", () => {
    LAUNCHES_PAGE = LAUNCHES_PAGE + 1;
    renderLaunchesTable();
  });

  body.querySelectorAll("[data-launch-item-id]").forEach((row) => {
    row.addEventListener("click", async () => {
      SELECTED_LAUNCH_ITEM_ID = row.getAttribute("data-launch-item-id");
      renderLaunchesTable();
      await renderLaunchSelection(SELECTED_LAUNCH_ITEM_ID);
    });
  });
}

function renderLaunchesMoMChart(rows = []) {
  const canvas = document.getElementById("launchesMoMChart");
  if (!canvas || typeof Chart === "undefined") return;

  if (LAUNCHES_MOM_CHART) {
    LAUNCHES_MOM_CHART.destroy();
    LAUNCHES_MOM_CHART = null;
  }

  const chartTheme = getUiChartThemeColors();

  LAUNCHES_MOM_CHART = new Chart(canvas.getContext("2d"), {
    data: {
      labels: rows.map((row) => row.label),
      datasets: [
        {
          type: "line",
          label: "Share no faturamento (%)",
          data: rows.map((row) => Number(row.launchRevenueSharePct || 0)),
          borderColor: "rgba(14,165,233,0.95)",
          backgroundColor: "rgba(14,165,233,0.20)",
          pointBackgroundColor: "rgba(14,165,233,1)",
          pointRadius: 4,
          pointHoverRadius: 5,
          tension: 0.32,
          fill: true,
          yAxisID: "yShare",
        },
        {
          type: "bar",
          label: "Quantidade de lançamentos",
          data: rows.map((row) => Number(row.totalLaunches || 0)),
          backgroundColor: "rgba(167,139,250,0.32)",
          borderColor: "rgba(167,139,250,0.95)",
          borderWidth: 1,
          borderRadius: 8,
          yAxisID: "yCount",
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: { color: chartTheme.legend },
        },
        tooltip: {
          backgroundColor: chartTheme.tooltipBg,
          borderColor: chartTheme.tooltipBorder,
          borderWidth: 1,
          titleColor: chartTheme.tooltipTitle,
          bodyColor: chartTheme.tooltipBody,
        },
      },
      scales: {
        x: {
          ticks: { color: chartTheme.axis },
          grid: { color: chartTheme.grid },
        },
        yShare: {
          type: "linear",
          position: "left",
          beginAtZero: true,
          ticks: {
            color: chartTheme.axis,
            callback(value) {
              return `${Number(value || 0).toFixed(0)}%`;
            },
          },
          grid: { color: chartTheme.grid },
        },
        yCount: {
          type: "linear",
          position: "right",
          beginAtZero: true,
          ticks: { color: chartTheme.axis },
          grid: { display: false },
        },
      },
    },
  });
}

async function loadLaunchesMoM() {
  const statusEl = document.getElementById("launchesMoMStatus");
  const shareCurrentEl = document.getElementById("launchesMoMShareCurrent");
  const shareDeltaEl = document.getElementById("launchesMoMShareDelta");
  const countCurrentEl = document.getElementById("launchesMoMCountCurrent");
  const countDeltaEl = document.getElementById("launchesMoMCountDelta");
  if (
    !statusEl ||
    !shareCurrentEl ||
    !shareDeltaEl ||
    !countCurrentEl ||
    !countDeltaEl
  ) {
    return;
  }

  const dateToValue = LAUNCHES_LAST_DATA?.meta?.dateTo || isoLocalDate(new Date());
  const ranges = buildTrailingMonthRanges(dateToValue, LAUNCHES_MOM_MONTHS);
  statusEl.textContent = "Carregando MoM...";

  const series = await Promise.all(
    ranges.map(async (range) => {
      try {
        const qs = new URLSearchParams({
          dateFrom: range.dateFrom,
          dateTo: range.dateTo,
          summaryOnly: "true",
        });
        const data = await apiGet(
          `/shops/${SHOP_PATH_PLACEHOLDER}/products/launches?${qs.toString()}`,
        );
        return {
          ...range,
          ok: true,
          launchRevenueSharePct: Number(data?.summary?.launchRevenueSharePct || 0),
          totalLaunches: Number(data?.summary?.totalLaunches || 0),
        };
      } catch (_error) {
        return {
          ...range,
          ok: false,
          launchRevenueSharePct: null,
          totalLaunches: null,
        };
      }
    }),
  );

  const okRows = series.filter((row) => row.ok);
  if (!okRows.length) {
    statusEl.textContent = "Nao foi possivel carregar o MoM de lançamentos.";
    shareCurrentEl.textContent = "—";
    shareDeltaEl.textContent = "—";
    countCurrentEl.textContent = "—";
    countDeltaEl.textContent = "—";
    if (LAUNCHES_MOM_CHART) {
      LAUNCHES_MOM_CHART.destroy();
      LAUNCHES_MOM_CHART = null;
    }
    return;
  }

  renderLaunchesMoMChart(series);

  const latest = okRows[okRows.length - 1];
  const previous = okRows.length > 1 ? okRows[okRows.length - 2] : null;
  const shareDelta =
    previous != null
      ? Number(latest.launchRevenueSharePct || 0) -
        Number(previous.launchRevenueSharePct || 0)
      : null;
  const countDelta =
    previous != null
      ? Number(latest.totalLaunches || 0) - Number(previous.totalLaunches || 0)
      : null;

  shareCurrentEl.textContent = `${Number(latest.launchRevenueSharePct || 0).toFixed(2)}%`;
  shareDeltaEl.textContent =
    shareDelta == null
      ? "—"
      : `${shareDelta > 0 ? "+" : ""}${Number(shareDelta).toFixed(2)} p.p.`;
  countCurrentEl.textContent = formatInt(latest.totalLaunches || 0);
  countDeltaEl.textContent =
    countDelta == null
      ? "—"
      : `${countDelta > 0 ? "+" : ""}${formatInt(countDelta)}`;
  statusEl.textContent =
    okRows.length === series.length
      ? "Serie mensal atualizada."
      : "Serie mensal atualizada parcialmente.";
}

async function loadLaunches() {
  const summary = document.getElementById("launchesSummary");
  const loading = document.getElementById("launchesLoading");
  const body = document.getElementById("launchesBody");
  const pagination = document.getElementById("launchesPagination");
  if (!summary || !loading || !body || !pagination) return;

  const recentDays = String(
    document.getElementById("launchesRecentDays")?.value || "30",
  );
  loading.textContent = "Carregando dados...";
  body.innerHTML = `<tr><td colspan="6"><div class="muted">Carregando...</div></td></tr>`;
  pagination.innerHTML = "";
  summary.innerHTML = `<div class="muted">Carregando resumo...</div>`;
  LAUNCHES_LAST_DATA = null;
  LAUNCHES_PAGE = 1;

  try {
    await ensureShopSelected();
    const qs = new URLSearchParams({ recentDays });
    const data = await apiGet(
      `/shops/${SHOP_PATH_PLACEHOLDER}/products/launches?${qs.toString()}`,
    );
    LAUNCHES_LAST_DATA = data;
    loading.textContent = "Selecione um lançamento na lista.";

    summary.innerHTML = `
      <div class="strategy-kpi-grid">
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Janela</div>
          <div class="strategy-kpi-card__value strategy-kpi-card__value--sm">Ultimos ${escapeHtml(recentDays)} dias</div>
          <div class="strategy-kpi-card__meta">${escapeHtml(data?.meta?.periodLabel || "-")}</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Lançamentos</div>
          <div class="strategy-kpi-card__value">${formatInt(data?.summary?.totalLaunches || 0)}</div>
          <div class="strategy-kpi-card__meta">MoM ${escapeHtml(formatGrowthLabel(data?.summary?.launchesCountMoMPct))}</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Em crescimento</div>
          <div class="strategy-kpi-card__value">${formatInt(data?.summary?.growingCount || 0)}</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Qualidade média</div>
          <div class="strategy-kpi-card__value">${formatInt(data?.summary?.averageQuality || 0)}</div>
          <div class="strategy-kpi-card__meta">Faturamento ${formatBRL(data?.summary?.revenue || 0)}</div>
        </article>
        <article class="strategy-kpi-card">
          <div class="strategy-kpi-card__label">Share dos lançamentos no faturamento</div>
          <div class="strategy-kpi-card__value">${Number(data?.summary?.launchRevenueSharePct || 0).toFixed(2)}%</div>
          <div class="strategy-kpi-card__meta">MoM ${Number(data?.summary?.launchRevenueShareMoMPct || 0).toFixed(2)} p.p.</div>
        </article>
      </div>
      <article class="launches-mom-card">
        <div class="launches-mom-card__header">
          <div class="launches-mom-card__title">MoM de lançamentos</div>
          <div class="launches-mom-card__subtitle">Participação no faturamento e quantidade de novos IDs (últimos ${LAUNCHES_MOM_MONTHS} meses)</div>
        </div>
        <div class="launches-mom-card__body">
          <div class="launches-mom-chart-wrap">
            <canvas id="launchesMoMChart"></canvas>
          </div>
          <div id="launchesMoMStatus" class="muted" style="margin-top:10px">Carregando MoM...</div>
          <div class="launches-mom-kpis">
            <div class="launches-mom-kpi">
              <div class="launches-mom-kpi__label">Share atual</div>
              <div id="launchesMoMShareCurrent" class="launches-mom-kpi__value">—</div>
            </div>
            <div class="launches-mom-kpi">
              <div class="launches-mom-kpi__label">Variação share MoM</div>
              <div id="launchesMoMShareDelta" class="launches-mom-kpi__value">—</div>
            </div>
            <div class="launches-mom-kpi">
              <div class="launches-mom-kpi__label">Lançamentos atuais</div>
              <div id="launchesMoMCountCurrent" class="launches-mom-kpi__value">—</div>
            </div>
            <div class="launches-mom-kpi">
              <div class="launches-mom-kpi__label">Variação de lançamentos</div>
              <div id="launchesMoMCountDelta" class="launches-mom-kpi__value">—</div>
            </div>
          </div>
        </div>
      </article>
    `;

    const items = Array.isArray(data?.items) ? data.items : [];
    if (!SELECTED_LAUNCH_ITEM_ID && items[0]?.itemId) {
      SELECTED_LAUNCH_ITEM_ID = String(items[0].itemId);
    }
    if (
      SELECTED_LAUNCH_ITEM_ID &&
      !items.some((row) => String(row.itemId || "") === String(SELECTED_LAUNCH_ITEM_ID))
    ) {
      SELECTED_LAUNCH_ITEM_ID = items[0]?.itemId ? String(items[0].itemId) : null;
    }

    renderLaunchesTable();
    renderLaunchesChart(items);
    await loadLaunchesMoM();
    await renderLaunchSelection(SELECTED_LAUNCH_ITEM_ID);
  } catch (error) {
    loading.textContent = "Erro ao carregar dados.";
    summary.innerHTML = `<div class="muted">Erro ao carregar lançamentos: ${escapeHtml(error.message)}</div>`;
    body.innerHTML = `<tr><td colspan="6"><div class="muted">Erro ao carregar.</div></td></tr>`;
    pagination.innerHTML = "";
  }
}

function setPanelStatus(elementId, text, type = "") {
  const el = document.getElementById(elementId);
  if (!el) return;
  el.className = type ? `muted ui-state ui-state--${type}` : "muted";
  el.textContent = String(text || "");
}

async function resolveItemIdsBySkus(skus = []) {
  const normalized = Array.from(
    new Set((Array.isArray(skus) ? skus : []).map((sku) => String(sku || "").trim()).filter(Boolean)),
  );
  if (!normalized.length) return [];
  const qs = new URLSearchParams({
    includeInactive: "1",
    skus: normalized.join(","),
  });
  const data = await apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/products/export?${qs.toString()}`);
  const items = Array.isArray(data?.items) ? data.items : [];
  return Array.from(
    new Set(
      items
        .map((item) => String(item?.id || "").trim())
        .filter((value) => /^\d+$/.test(value)),
    ),
  );
}

async function fetchAllActiveItemIdsForBulkSpecs() {
  const ids = [];
  const pageSize = 100;
  let page = 1;
  let totalPages = 1;

  while (page <= totalPages) {
    const params = new URLSearchParams({
      page: String(page),
      pageSize: String(pageSize),
      includeInactive: "0",
      status: "NORMAL",
    });
    const data = await apiGet(`/shops/${SHOP_PATH_PLACEHOLDER}/products?${params.toString()}`);
    const items = Array.isArray(data?.items) ? data.items : [];
    const metaTotalPages = Number(data?.meta?.totalPages || 1);
    totalPages = Number.isFinite(metaTotalPages) && metaTotalPages > 0 ? metaTotalPages : 1;

    for (const item of items) {
      const itemId = String(item?.itemId || "").trim();
      if (/^\d+$/.test(itemId)) ids.push(itemId);
    }

    page += 1;
    if (page > 100) break;
  }

  return Array.from(new Set(ids));
}

async function runBulkSpecsLoadAllActive() {
  const itemIdsInput = document.getElementById("bulkSpecsItemIds");
  const skusInput = document.getElementById("bulkSpecsSkus");
  if (!itemIdsInput) return;

  setPanelStatus("bulkSpecsStatus", "Buscando todos os IDs ativos da loja...", "loading");
  try {
    const ids = await fetchAllActiveItemIdsForBulkSpecs();
    if (!ids.length) {
      setPanelStatus("bulkSpecsStatus", "Nenhum ID ativo encontrado na loja.", "warning");
      return;
    }
    itemIdsInput.value = ids.join(", ");
    if (skusInput) skusInput.value = "";
    setPanelStatus(
      "bulkSpecsStatus",
      `${ids.length} ID(s) ativo(s) carregado(s). Agora clique em "Carregar itens".`,
    );
  } catch (error) {
    setPanelStatus("bulkSpecsStatus", `Falha ao buscar IDs ativos: ${error.message}`, "error");
  }
}

async function enableSelectedSellerLogistics(shopIds) {
  const validShopIds = Array.from(
    new Set(
      (Array.isArray(shopIds) ? shopIds : [])
        .map((value) => String(value || "").trim())
        .filter((value) => /^\d+$/.test(value)),
    ),
  );

  if (!validShopIds.length) {
    openModal(
      "Atenção",
      `<div class="muted">Selecione ao menos um produto para habilitar logistica do vendedor.</div>`,
    );
    return;
  }

  const confirmed = window.confirm(
    "Habilitar Logistica do vendedor para os produtos selecionados?",
  );
  if (!confirmed) return;

  startLogisticsProcess(
    "Andamento da habilitacao da logistica do vendedor",
    validShopIds.length,
  );
  appendLogisticsProcessLog(
    "Enviando solicitacao para habilitar logistica do vendedor...",
    "info",
  );

  try {
    const enqueueResult = await enqueueAsyncProcessJob(
      "logistics.seller.enable",
      {
        itemIds: validShopIds,
      },
    );
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendLogisticsProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const result = extractAsyncProcessPayload(status);
    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(
      rows,
      validShopIds,
      "habilitar logistica do vendedor",
    );
    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );
    openModal(
      "Resultado da atualização",
      rows.length
        ? rows
            .map(
              (row) => `<div class="card"><strong>${escapeHtml(String(row.itemId || "—"))}</strong><div class="muted" style="margin-top:6px;">${escapeHtml(row.title || "Produto sem título")}</div><div class="muted" style="margin-top:6px;">${escapeHtml(row.message || "")}</div></div>`,
            )
            .join("")
        : `<div class="muted">Nenhum produto foi atualizado.</div>`,
    );
    await loadLogistics();
  } catch (e) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = Number(LOGISTICS_PROCESS_STATE.total || validShopIds.length);
      LOGISTICS_PROCESS_STATE.failed = Number(LOGISTICS_PROCESS_STATE.total || validShopIds.length);
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral ao habilitar logistica do vendedor: ${String(e?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        LOGISTICS_PROCESS_STATE.done,
        LOGISTICS_PROCESS_STATE.total,
        LOGISTICS_PROCESS_STATE.success,
        LOGISTICS_PROCESS_STATE.failed,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
  }
}

async function disableSelectedSellerLogistics(shopIds) {
  const validShopIds = Array.from(
    new Set(
      (Array.isArray(shopIds) ? shopIds : [])
        .map((value) => String(value || "").trim())
        .filter((value) => /^\d+$/.test(value)),
    ),
  );

  if (!validShopIds.length) {
    openModal(
      "Atenção",
      `<div class="muted">Selecione ao menos um produto habilitado para desabilitar logistica do vendedor.</div>`,
    );
    return;
  }

  const confirmed = window.confirm(
    "Desabilitar Logistica do vendedor para os produtos selecionados?",
  );
  if (!confirmed) return;

  startLogisticsProcess(
    "Andamento da desabilitacao da logistica do vendedor",
    validShopIds.length,
  );
  appendLogisticsProcessLog(
    "Enviando solicitacao para desabilitar logistica do vendedor...",
    "info",
  );

  try {
    const enqueueResult = await enqueueAsyncProcessJob(
      "logistics.seller.disable",
      {
        itemIds: validShopIds,
      },
    );
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendLogisticsProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const result = extractAsyncProcessPayload(status);
    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(
      rows,
      validShopIds,
      "desabilitar logistica do vendedor",
    );
    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );
    openModal(
      "Resultado da atualização",
      rows.length
        ? rows
            .map(
              (row) => `<div class="card"><strong>${escapeHtml(String(row.itemId || "—"))}</strong><div class="muted" style="margin-top:6px;">${escapeHtml(row.title || "Produto sem título")}</div><div class="muted" style="margin-top:6px;">${escapeHtml(row.message || "")}</div></div>`,
            )
            .join("")
        : `<div class="muted">Nenhum produto foi atualizado.</div>`,
    );
    await loadLogistics();
  } catch (e) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = Number(
        LOGISTICS_PROCESS_STATE.total || validShopIds.length,
      );
      LOGISTICS_PROCESS_STATE.failed = Number(
        LOGISTICS_PROCESS_STATE.total || validShopIds.length,
      );
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral ao desabilitar logistica do vendedor: ${String(e?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        LOGISTICS_PROCESS_STATE.done,
        LOGISTICS_PROCESS_STATE.total,
        LOGISTICS_PROCESS_STATE.success,
        LOGISTICS_PROCESS_STATE.failed,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(e.message)}</div>`);
  }
}

async function resolveLogisticsConflicts(mode = "spx", explicitItemIds = []) {
  const keepMode = mode === "seller" ? "seller" : "spx";
  const defaultPool =
    keepMode === "seller"
      ? Array.isArray(LOGISTICS_DATA?.seller?.enabled)
        ? LOGISTICS_DATA.seller.enabled
        : []
      : Array.isArray(LOGISTICS_DATA?.spx?.enabled)
        ? LOGISTICS_DATA.spx.enabled
        : [];
  const itemIds = Array.from(
    new Set(
      (Array.isArray(explicitItemIds) && explicitItemIds.length
        ? explicitItemIds
        : collectConflictItemIds(defaultPool)
      )
        .map((value) => String(value || "").trim())
        .filter((value) => /^\d+$/.test(value)),
    ),
  );

  if (!itemIds.length) {
    openModal(
      "Conflitos de logística",
      '<div class="muted">Nenhum conflito SPX + Logistica do vendedor encontrado para corrigir.</div>',
    );
    return;
  }

  const confirmation = window.confirm(
    keepMode === "seller"
      ? "Corrigir conflitos mantendo apenas Logistica do vendedor nos produtos com conflito?"
      : "Corrigir conflitos mantendo apenas SPX nos produtos com conflito?",
  );
  if (!confirmation) return;

  const action =
    keepMode === "seller"
      ? "logistics.conflicts.keep_seller"
      : "logistics.conflicts.keep_spx";
  startLogisticsProcess(
    keepMode === "seller"
      ? "Andamento da correção de conflito (manter logística do vendedor)"
      : "Andamento da correção de conflito (manter SPX)",
    itemIds.length,
  );
  appendLogisticsProcessLog("Enviando solicitação de correção de conflitos...", "info");

  try {
    const enqueueResult = await enqueueAsyncProcessJob(action, { itemIds });
    const jobId = String(enqueueResult?.jobId || "");
    appendLogisticsProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );

    const status = await waitForAsyncProcessJob(jobId, {
      onUpdate: (snapshot) => {
        const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
        appendLogisticsProcessLog(`Status do job: ${stateLabel}`, "info");
      },
    });
    const result = extractAsyncProcessPayload(status);
    const rows = Array.isArray(result?.results) ? result.results : [];
    processLogisticsResultRows(rows, itemIds, "corrigir conflito");
    finishLogisticsProcess(
      `Resumo final: ${LOGISTICS_PROCESS_STATE?.success || 0} sucesso(s) e ${LOGISTICS_PROCESS_STATE?.failed || 0} falha(s).`,
    );
    openModal(
      "Resultado da correção",
      rows.length
        ? rows
            .map(
              (row) => `<div class="card"><strong>${escapeHtml(String(row.itemId || "—"))}</strong><div class="muted" style="margin-top:6px;">${escapeHtml(row.title || "Produto sem título")}</div><div class="muted" style="margin-top:6px;">${escapeHtml(row.message || "")}</div></div>`,
            )
            .join("")
        : '<div class="muted">Nenhum item processado.</div>',
    );
    await loadLogistics();
  } catch (error) {
    if (LOGISTICS_PROCESS_STATE) {
      LOGISTICS_PROCESS_STATE.done = Number(LOGISTICS_PROCESS_STATE.total || itemIds.length);
      LOGISTICS_PROCESS_STATE.failed = Number(LOGISTICS_PROCESS_STATE.total || itemIds.length);
      LOGISTICS_PROCESS_STATE.success = 0;
      appendLogisticsProcessLog(
        `Falha geral na correção de conflitos: ${String(error?.message || "erro desconhecido")}`,
        "error",
      );
      updateLogisticsProcessProgress(
        LOGISTICS_PROCESS_STATE.done,
        LOGISTICS_PROCESS_STATE.total,
        LOGISTICS_PROCESS_STATE.success,
        LOGISTICS_PROCESS_STATE.failed,
      );
      finishLogisticsProcess("Resumo final: processo encerrado com erro.");
    }
    openModal("Erro", `<div class="muted">${escapeHtml(error.message)}</div>`);
  }
}

function parseDeadlineValues(raw) {
  return Array.from(
    new Set(
      String(raw || "")
        .split(/[\n,;]+/g)
        .map((token) => String(token || "").trim())
        .filter(Boolean),
    ),
  );
}

let DEADLINE_SPREADSHEET_MAPPINGS = [];

function normalizeDeadlineSpreadsheetHeader(value) {
  const normalized = String(value || "").normalize("NFD");
  return normalized
    .split("")
    .filter((char) => char.charCodeAt(0) < 768 || char.charCodeAt(0) > 879)
    .join("")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  /*
  return String(value || "")
    .normalize("NFD")
    .replace(/[\\u0300-\\u036f]/g, "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
  */
}

function updateDeadlineSpreadsheetSummary(message, tone = "") {
  const summary = document.getElementById("deadlineSpreadsheetSummary");
  if (!summary) return;
  summary.className = tone ? `muted ui-state ui-state--${tone}` : "muted";
  summary.textContent = message;
}

function downloadDeadlineSpreadsheetTemplate() {
  if (!window.XLSX) {
    openModal("Planilha de prazos", '<div class="muted">A biblioteca de planilhas ainda nao foi carregada.</div>');
    return;
  }
  const worksheet = XLSX.utils.json_to_sheet([
    { "ID do anuncio": "123456789", Prazo: 7 },
    { "ID do anuncio": "987654321", Prazo: 15 },
  ]);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Prazos");
  XLSX.writeFile(workbook, "modelo-controle-de-prazo.xlsx");
}

async function parseDeadlineSpreadsheet(file) {
  if (!window.XLSX) throw new Error("Biblioteca de planilhas indisponivel.");
  const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
  const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });
  const mappings = [];
  const invalidRows = [];

  rows.forEach((row, index) => {
    const normalized = Object.fromEntries(
      Object.entries(row || {}).map(([key, value]) => [normalizeDeadlineSpreadsheetHeader(key), value]),
    );
    const itemId = String(normalized["id do anuncio"] ?? normalized["id anuncio"] ?? normalized["item id"] ?? "").trim();
    const daysToShip = Number(normalized.prazo ?? normalized["prazo dias"] ?? normalized.dias);
    if (!/^\\d+$/.test(itemId) || !Number.isInteger(daysToShip) || daysToShip < 3 || daysToShip > 15) {
      invalidRows.push(index + 2);
      return;
    }
    mappings.push({ itemId, daysToShip });
  });

  if (!mappings.length) {
    throw new Error("Nenhuma linha valida. Informe ID do anuncio e Prazo inteiro entre 3 e 15 dias.");
  }

  DEADLINE_SPREADSHEET_MAPPINGS = Array.from(
    new Map(mappings.map((mapping) => [mapping.itemId, mapping])).values(),
  );
  const idsInput = document.getElementById("deadlineItemIds");
  if (idsInput) idsInput.value = DEADLINE_SPREADSHEET_MAPPINGS.map((mapping) => mapping.itemId).join(", ");
  updateDeadlineSpreadsheetSummary(
    `${DEADLINE_SPREADSHEET_MAPPINGS.length} anuncio(s) pronto(s) para aplicar por planilha${invalidRows.length ? `; ${invalidRows.length} linha(s) ignorada(s) por prazo fora de 3-15 dias ou ID invalido.` : "."}`,
    invalidRows.length ? "warning" : "success",
  );
}

function collectDeadlineControlPayload() {
  return {
    itemIds: String(document.getElementById("deadlineItemIds")?.value || "").trim(),
    skuList: String(document.getElementById("deadlineSkus")?.value || "").trim(),
    idSkuList: String(document.getElementById("deadlineIdSkuList")?.value || "").trim(),
    nameQuery: String(document.getElementById("deadlineNameQuery")?.value || "").trim(),
    selectAllActive: Boolean(document.getElementById("deadlineSelectAllActive")?.checked),
    shippingFilter: String(
      document.getElementById("deadlineShippingFilter")?.value || "all",
    ).trim(),
    deadlineMappings: DEADLINE_SPREADSHEET_MAPPINGS,
  };
}

function buildDeadlinePayloadSignature(payload = {}) {
  return JSON.stringify({
    itemIds: String(payload.itemIds || ""),
    skuList: String(payload.skuList || ""),
    idSkuList: String(payload.idSkuList || ""),
    nameQuery: String(payload.nameQuery || ""),
    selectAllActive: Boolean(payload.selectAllActive),
    shippingFilter: String(payload.shippingFilter || "all"),
    deadlineMappings: Array.isArray(payload.deadlineMappings) ? payload.deadlineMappings : [],
  });
}

function setDeadlineStatus(message, tone = "") {
  const el = document.getElementById("deadlineStatus");
  if (!el) return;
  el.className = tone ? `muted ui-state ui-state--${tone}` : "muted";
  el.textContent = String(message || "");
}

function renderDeadlineTargetsTable(targets = []) {
  const body = document.getElementById("deadlineTargetsBody");
  if (!body) return;

  if (!targets.length) {
    body.innerHTML = `
      <tr>
        <td colspan="6">
          <div class="muted ui-state ui-state--empty">Nenhum item carregado.</div>
        </td>
      </tr>
    `;
    return;
  }

  body.innerHTML = targets
    .map((row) => {
      const days = Number(row?.daysToShip);
      const deadline =
        Number.isFinite(days) && days > 0
          ? `Sob encomenda (${days} dia${days === 1 ? "" : "s"})`
          : "Desabilitado";
      return `
        <tr>
          <td>${escapeHtml(String(row?.itemId || "—"))}</td>
          <td>${escapeHtml(String(row?.itemSku || "—"))}</td>
          <td>${escapeHtml(String(row?.title || "Sem titulo"))}</td>
          <td>${escapeHtml(String(row?.status || "—"))}</td>
          <td>${escapeHtml(deadline)}</td>
          <td>${escapeHtml(String(row?.shippingMode || "—"))}</td>
        </tr>
      `;
    })
    .join("");
}

function getDeadlineProcessUi() {
  const panel = document.getElementById("deadlineProcessPanel");
  if (!panel) return null;

  return {
    panel,
    title: panel.querySelector("#deadlineProcessTitle"),
    meta: panel.querySelector("#deadlineProcessMeta"),
    badge: panel.querySelector("#deadlineProcessBadge"),
    bar: panel.querySelector("#deadlineProcessBar"),
    counter: panel.querySelector("#deadlineProcessCounter"),
    percent: panel.querySelector("#deadlineProcessPercent"),
    logs: panel.querySelector("#deadlineProcessLogs"),
    exportBtn: panel.querySelector("#btnDeadlineProcessExport"),
    closeBtn: panel.querySelector("#btnDeadlineProcessClose"),
  };
}

function updateDeadlineProcessProgress(done, total, success, failed) {
  const ui = getDeadlineProcessUi();
  if (!ui) return;
  const safeTotal = Math.max(0, Number(total || 0));
  const safeDone = Math.max(0, Number(done || 0));
  const pct = safeTotal > 0 ? Math.round((safeDone / safeTotal) * 100) : 0;

  if (ui.counter) ui.counter.textContent = `${safeDone}/${safeTotal}`;
  if (ui.percent) ui.percent.textContent = `${pct}%`;
  if (ui.bar) ui.bar.style.width = `${pct}%`;
  if (ui.meta) {
    ui.meta.textContent =
      `Concluidos ${safeDone}/${safeTotal} - sucesso ${Number(success || 0)} - falhas ${Number(failed || 0)}`;
  }
  syncGlobalTrackedProcessProgress(DEADLINE_PROCESS_STATE?.globalProcessId, {
    done: safeDone,
    total: safeTotal,
    success: Number(success || 0),
    failed: Number(failed || 0),
  });
}

function appendDeadlineProcessLog(message, tone = "info") {
  if (!DEADLINE_PROCESS_STATE) return;
  const ui = getDeadlineProcessUi();
  if (!ui) return;

  const stamp = new Date().toLocaleTimeString("pt-BR", { hour12: false });
  const line = `[${stamp}] ${String(message || "")}`;
  DEADLINE_PROCESS_STATE.logs.push(line);
  appendGlobalTrackedProcessLog(DEADLINE_PROCESS_STATE.globalProcessId, line, tone);

  if (!ui.logs) return;
  const row = document.createElement("div");
  row.className = `logistics-process-log logistics-process-log--${tone}`;
  row.textContent = line;
  ui.logs.appendChild(row);
  ui.logs.scrollTop = ui.logs.scrollHeight;
}

function startDeadlineProcess(actionLabel, total) {
  const processId = beginGlobalTrackedProcess("Controle de Prazo", actionLabel, total);
  DEADLINE_PROCESS_STATE = {
    actionLabel: String(actionLabel || "Controle de Prazo"),
    startedAt: new Date().toLocaleString("pt-BR"),
    total: Number(total || 0),
    done: 0,
    success: 0,
    failed: 0,
    logs: [],
    finished: false,
    globalProcessId: processId,
  };

  const ui = getDeadlineProcessUi();
  if (!ui) return;

  ui.panel.classList.remove("is-hidden");
  if (ui.title) ui.title.textContent = DEADLINE_PROCESS_STATE.actionLabel;
  if (ui.badge) {
    ui.badge.textContent = "Em andamento";
    ui.badge.classList.remove("is-success", "is-warning");
    ui.badge.classList.add("is-running");
  }
  if (ui.logs) ui.logs.innerHTML = "";
  if (ui.exportBtn) ui.exportBtn.disabled = true;
  updateDeadlineProcessProgress(0, DEADLINE_PROCESS_STATE.total, 0, 0);
  appendDeadlineProcessLog(
    `Processo iniciado para ${DEADLINE_PROCESS_STATE.total} produto(s).`,
    "info",
  );
}

function finishDeadlineProcess(summaryMessage) {
  if (!DEADLINE_PROCESS_STATE) return;
  DEADLINE_PROCESS_STATE.finished = true;
  appendDeadlineProcessLog(summaryMessage, "info");

  const ui = getDeadlineProcessUi();
  if (!ui) return;
  if (ui.exportBtn) ui.exportBtn.disabled = false;
  if (ui.badge) {
    const hasFailure = Number(DEADLINE_PROCESS_STATE.failed || 0) > 0;
    ui.badge.textContent = hasFailure ? "Concluido com alertas" : "Concluido";
    ui.badge.classList.remove("is-running");
    ui.badge.classList.toggle("is-warning", hasFailure);
    ui.badge.classList.toggle("is-success", !hasFailure);
  }
  finishGlobalTrackedProcess(DEADLINE_PROCESS_STATE.globalProcessId, {
    summaryMessage: String(summaryMessage || ""),
    hasWarning: Number(DEADLINE_PROCESS_STATE.failed || 0) > 0,
  });
}

function closeDeadlineProcessPanel() {
  const ui = getDeadlineProcessUi();
  if (!ui?.panel) return;
  ui.panel.classList.add("is-hidden");
}

function downloadDeadlineProcessLogs() {
  if (!DEADLINE_PROCESS_STATE) return;
  const lines = [
    `Processo: ${DEADLINE_PROCESS_STATE.actionLabel || "Controle de Prazo"}`,
    `Inicio: ${DEADLINE_PROCESS_STATE.startedAt || "-"}`,
    `Total: ${Number(DEADLINE_PROCESS_STATE.total || 0)}`,
    `Concluidos: ${Number(DEADLINE_PROCESS_STATE.done || 0)}`,
    `Sucesso: ${Number(DEADLINE_PROCESS_STATE.success || 0)}`,
    `Falhas: ${Number(DEADLINE_PROCESS_STATE.failed || 0)}`,
    "",
    ...(Array.isArray(DEADLINE_PROCESS_STATE.logs)
      ? DEADLINE_PROCESS_STATE.logs
      : []),
  ];
  const blob = new Blob([lines.join("\n")], {
    type: "text/plain;charset=utf-8",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `controle-prazo-${new Date().toISOString().replace(/[:.]/g, "-")}.txt`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function bindDeadlineProcessPanelActions() {
  const ui = getDeadlineProcessUi();
  if (!ui?.panel || ui.panel.dataset.bound === "1") return;
  ui.panel.dataset.bound = "1";
  ui.closeBtn?.addEventListener("click", closeDeadlineProcessPanel);
  ui.exportBtn?.addEventListener("click", downloadDeadlineProcessLogs);
}

function inferDeadlineResultSuccess(row) {
  if (typeof row?.ok === "boolean") return row.ok;
  const code = String(row?.code || "").toLowerCase();
  if (!code) return true;
  if (code === "updated" || code === "ok" || code === "success") return true;
  return false;
}

function renderDeadlineSummary(data = {}) {
  const summaryEl = document.getElementById("deadlineSummary");
  if (!summaryEl) return;
  const total = Number(data?.total || 0);
  const shown = Number(data?.shown || 0);
  summaryEl.textContent = `Total encontrado: ${fmtInt(total)} • Exibidos: ${fmtInt(shown)}`;
}

function validateDeadlinePayloadBeforePreview(payload = {}) {
  const hasIds = parseDeadlineValues(payload.itemIds).length > 0;
  const hasSkus = parseDeadlineValues(payload.skuList).length > 0;
  const hasMixed = parseDeadlineValues(payload.idSkuList).length > 0;
  const hasName = String(payload.nameQuery || "").trim().length > 0;
  const allActive = Boolean(payload.selectAllActive);
  return allActive || hasIds || hasSkus || hasMixed || hasName;
}

async function runDeadlineControlPreview({ silent = false } = {}) {
  const payload = collectDeadlineControlPayload();
  if (!validateDeadlinePayloadBeforePreview(payload)) {
    renderDeadlineTargetsTable([]);
    renderDeadlineSummary({ total: 0, shown: 0 });
    setDeadlineStatus(
      "Informe ao menos um filtro (IDs, SKUs, nome, lista mista) ou marque todos os ativos.",
      "warning",
    );
    return null;
  }

  if (!silent) setDeadlineStatus("Buscando produtos alvo...", "loading");
  const data = await apiPost(
    "/shops/active/products/deadline-control/preview",
    payload,
  );
  const targets = Array.isArray(data?.targets) ? data.targets : [];
  DEADLINE_CONTROL_LAST_PREVIEW = {
    signature: buildDeadlinePayloadSignature(payload),
    payload,
    data,
    loadedAt: Date.now(),
  };
  renderDeadlineTargetsTable(targets);
  renderDeadlineSummary(data || {});
  setDeadlineStatus(
    `Preview concluido: ${fmtInt(Number(data?.total || 0))} produto(s) encontrado(s).`,
  );
  return data;
}

function syncDeadlineDaysInputState() {
  const action = String(
    document.getElementById("deadlineAction")?.value || "enable",
  ).trim();
  const daysInput = document.getElementById("deadlineDaysToShip");
  if (!daysInput) return;
  daysInput.disabled = action !== "enable";
}

function applyDeadlineProcessResult(result, totalFallback) {
  const resultPayload = result && typeof result === "object" ? result : {};
  const logs = Array.isArray(resultPayload?.logs) ? resultPayload.logs : [];
  const totalFromResult = Number(resultPayload?.total || totalFallback);
  if (DEADLINE_PROCESS_STATE) DEADLINE_PROCESS_STATE.total = totalFromResult;

  for (const row of logs) {
    const ok = inferDeadlineResultSuccess(row);
    if (DEADLINE_PROCESS_STATE) {
      DEADLINE_PROCESS_STATE.done += 1;
      if (ok) DEADLINE_PROCESS_STATE.success += 1;
      else DEADLINE_PROCESS_STATE.failed += 1;
    }
    appendDeadlineProcessLog(
      `${ok ? "Sucesso" : "Falha"} • ID ${row?.itemId || "—"} • ${row?.message || ""}`,
      ok ? "success" : "error",
    );
    updateDeadlineProcessProgress(
      DEADLINE_PROCESS_STATE?.done || 0,
      DEADLINE_PROCESS_STATE?.total || totalFromResult,
      DEADLINE_PROCESS_STATE?.success || 0,
      DEADLINE_PROCESS_STATE?.failed || 0,
    );
  }

  const success = Number(resultPayload?.success || 0);
  const failed = Number(resultPayload?.failed || 0);
  if (DEADLINE_PROCESS_STATE) {
    DEADLINE_PROCESS_STATE.total = totalFromResult;
    DEADLINE_PROCESS_STATE.done = totalFromResult;
    DEADLINE_PROCESS_STATE.success = success;
    DEADLINE_PROCESS_STATE.failed = failed;
  }
  updateDeadlineProcessProgress(
    DEADLINE_PROCESS_STATE?.done || totalFromResult,
    DEADLINE_PROCESS_STATE?.total || totalFromResult,
    DEADLINE_PROCESS_STATE?.success || success,
    DEADLINE_PROCESS_STATE?.failed || failed,
  );
  finishDeadlineProcess(
    `Resumo final: ${success} sucesso(s) e ${failed} falha(s).`,
  );
  setDeadlineStatus(
    `Processo concluido: ${success} sucesso(s) e ${failed} falha(s).`,
    failed > 0 ? "warning" : "",
  );
}

async function runDeadlineControlApply() {
  const payload = collectDeadlineControlPayload();
  const action = String(document.getElementById("deadlineAction")?.value || "")
    .trim()
    .toLowerCase();
  const daysToShip = Number(
    document.getElementById("deadlineDaysToShip")?.value || 0,
  );

  if (!["enable", "disable"].includes(action)) {
    setDeadlineStatus("Selecione uma acao valida.", "error");
    return;
  }

  const hasSpreadsheetMappings = Array.isArray(payload.deadlineMappings) && payload.deadlineMappings.length > 0;
  if (
    action === "enable" &&
    !hasSpreadsheetMappings &&
    (!Number.isInteger(daysToShip) || daysToShip < 3 || daysToShip > 15)
  ) {
    setDeadlineStatus("Para habilitar, informe um prazo entre 3 e 15 dias.", "error");
    return;
  }

  if (!validateDeadlinePayloadBeforePreview(payload)) {
    setDeadlineStatus(
      "Informe ao menos um filtro (IDs, SKUs, nome, lista mista) ou marque todos os ativos.",
      "warning",
    );
    return;
  }

  let previewData = null;
  const signature = buildDeadlinePayloadSignature(payload);
  if (
    DEADLINE_CONTROL_LAST_PREVIEW &&
    DEADLINE_CONTROL_LAST_PREVIEW.signature === signature
  ) {
    previewData = DEADLINE_CONTROL_LAST_PREVIEW.data;
  } else {
    previewData = await runDeadlineControlPreview({ silent: true });
  }

  const total = Number(previewData?.total || 0);
  if (!Number.isFinite(total) || total <= 0) {
    setDeadlineStatus("Nenhum produto encontrado para aplicar o controle de prazo.", "warning");
    return;
  }

  const confirmed = window.confirm(
    action === "enable"
      ? hasSpreadsheetMappings
        ? `Aplicar os prazos da planilha em ${total} produto(s)?`
        : `Aplicar prazo sob encomenda de ${daysToShip} dia(s) em ${total} produto(s)?`
      : `Desabilitar prazo sob encomenda em ${total} produto(s)?`,
  );
  if (!confirmed) return;

  startDeadlineProcess(
    action === "enable"
      ? hasSpreadsheetMappings
        ? "Andamento: aplicar prazos da planilha"
        : `Andamento: habilitar prazo (${daysToShip} dias)`
      : "Andamento: desabilitar prazo sob encomenda",
    total,
  );
  appendDeadlineProcessLog("Enviando requisicao para Shopee...", "info");
  setDeadlineStatus("Processando atualizacao em massa...", "loading");

  const body = {
    ...payload,
    action,
    daysToShip: action === "enable" && !hasSpreadsheetMappings ? daysToShip : undefined,
    concurrency: 4,
  };

  try {
    const enqueueResult = await enqueueAsyncProcessJob("products.deadline.apply", body);
    const jobId = String(enqueueResult?.jobId || "");
    appendDeadlineProcessLog(
      `Job enfileirado com sucesso (jobId: ${jobId || "-"})`,
      "info",
    );
    const startStatus = await waitForAsyncProcessJobStart(jobId);
    let result = null;
    if (!startStatus) {
      appendDeadlineProcessLog(
        "Job ficou em WAITING por mais de 15s. Executando fallback direto (sem fila).",
        "warning",
      );
      try {
        const cancelStatus = await cancelAsyncProcessJob(jobId);
        if (cancelStatus?.cancelled) {
          appendDeadlineProcessLog(
            `Job em fila removido com sucesso (${jobId}).`,
            "info",
          );
        } else {
          appendDeadlineProcessLog(
            `Job não removido (${jobId}) - estado atual: ${String(cancelStatus?.state || "desconhecido")}.`,
            "warning",
          );
        }
      } catch (cancelError) {
        appendDeadlineProcessLog(
          `Não foi possível remover job da fila: ${String(cancelError?.message || "erro desconhecido")}`,
          "warning",
        );
      }
      result = await apiPost("/shops/active/products/deadline-control/apply", body);
    } else {
      const status = await waitForAsyncProcessJob(jobId, {
        onUpdate: (snapshot) => {
          const stateLabel = String(snapshot?.status || "waiting").toUpperCase();
          appendDeadlineProcessLog(`Status do job: ${stateLabel}`, "info");
        },
      });
      result = extractAsyncProcessPayload(status);
    }

    applyDeadlineProcessResult(result, total);
    await runDeadlineControlPreview({ silent: true });
  } catch (error) {
    if (DEADLINE_PROCESS_STATE) {
      DEADLINE_PROCESS_STATE.done = Number(DEADLINE_PROCESS_STATE.total || total);
      DEADLINE_PROCESS_STATE.failed = Number(DEADLINE_PROCESS_STATE.total || total);
      DEADLINE_PROCESS_STATE.success = 0;
      appendDeadlineProcessLog(
        `Falha geral no controle de prazo: ${String(error?.message || "erro desconhecido")}`,
        "error",
      );
      updateDeadlineProcessProgress(
        DEADLINE_PROCESS_STATE.done,
        DEADLINE_PROCESS_STATE.total,
        DEADLINE_PROCESS_STATE.success,
        DEADLINE_PROCESS_STATE.failed,
      );
      finishDeadlineProcess("Resumo final: processo encerrado com erro.");
    }
    setDeadlineStatus(
      `Falha ao aplicar controle de prazo: ${String(error?.message || error)}`,
      "error",
    );
  }
}

