    setPanelStatus(
      "bulkClipStatus",
      `${data.itemIds.length} anuncio(s) sem clip encontrados.${unavailable ? ` ${unavailable} nao puderam ser verificados.` : ""}`,
      unavailable ? "warning" : "",
    );
