/* ---------------- Boot ---------------- */
async function boot() {
  setAppBootLoader(true, "Buscando dados iniciais...");
  initInactivityLogout();
  initThemeToggle();
  initTabs();
  initWorkspaceQuickJump();
  applyBetaTags();
  initControlPanel();
  initControlPanelFocus();
  initSupportCenter();
  initModal();
  initSyncButtons();
  initProductsToolbar();
  initSwitchShopShortcut();
  initHeaderButtons();
  initGlobalNotifications();
  startProcessNotificationsPolling();
  initGlobalProcessDock();
  initAuthTab();
  initOrdersAlertsPopover();
  initSeo();
  initMargin();
  initCosts();
  initIntelligentPricing();
  initLogisticsTab();
  initDeadlineControlTab();
  initBulkOperationTabs();
  initProductStrategyTabs();
  enhanceUiStates();
  applyActionHierarchy();
  document
    .getElementById("btnDashReload")
    ?.addEventListener("click", () => loadDashboard({ silent: false }));
  document.getElementById("dashLiveToggle")?.addEventListener("change", (e) => {
    setDashMode(e.target.checked ? "today" : "month");
    loadDashboard({ silent: false });
  });
  setDashMode("month");
  document.body.dataset.appBooted = "1";
  try {
    setAppBootLoader(true, "Validando sessão...");
    await loadMe();
    startPriceIncreaseNotificationsPolling();
    startShopeePushNoticePolling();
    startDailyInsightNotifications();
    startGlobalInformativeBanner();
    initSidebarCategories();
    initSidebarCollapse();
    setAppBootLoader(true, "Conectando com Shopee...");
    await startShopeeOauthFlowIfRequested();
    const controlPanel = document.getElementById("tab-control-panel");
    if (controlPanel && controlPanel.classList.contains("active")) {
      animateTabPanel(controlPanel);
      setAppBootLoader(true, "Carregando painel de controle...");
      await loadControlPanel();
      enhanceUiStates(controlPanel);
    }
    const dashPanel = document.getElementById("tab-dashboard");
    if (dashPanel && dashPanel.classList.contains("active")) {
      animateTabPanel(dashPanel);
      setAppBootLoader(true, "Carregando dashboard...");
      await loadDashboard();
      enhanceUiStates(dashPanel);
    }
  } catch (e) {
    setText("auth-status", "Não autenticado. Recarregue a página.");
  } finally {
    window.setTimeout(() => setAppBootLoader(false), 180);
  }
}

boot();
